def build_parser() -> argparse.ArgumentParser:
    """Build the argument parser."""
    common = argparse.ArgumentParser(add_help=False)
    RUNTIME.add_global_options(common, hidden=True)
    parser = RUNTIME.parser(
        description='Jira Cloud platform REST API documentation',
        epilog="credentials:\n  basic: set JIRA_BASIC_USERNAME and JIRA_BASIC_PASSWORD, JIRA_BASIC_COMMAND, or run 'codapact-jira auth login'\n  session: custom; set JIRA_AUTH_PLUGIN=package.module:factory",
        examples=['codapact-jira app-properties addon-properties-resource-get-addon-properties-get ADDON_KEY'],
    )
    commands = parser.add_subparsers(dest="command", metavar="COMMAND", required=True)
    c = commands.add_parser('list-worklogs-by-issue-id-and-worklog-id', parents=[common], help='Get worklogs by issue id and worklog id', description="Returns worklog details for a list of issue ID and worklog ID pairs.\n\nThis is an internal API for bulk fetching worklogs by their issue and worklog\nIDs. Worklogs that don't exist will be filtered out from the response.\n\nThe returned list of worklogs is limited to 1000 items.\n\n**[Permissions](#permissions) required:** This is an internal service-to-\nservice API that requires ASAP authentication. No user permission checks are\nperformed as this bypasses normal user context.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira list-worklogs-by-issue-id-and-worklog-id --requests @requests.json', 'codapact-jira list-worklogs-by-issue-id-and-worklog-id --requests @requests.json --dry-run']), formatter_class=RAW)
    c.add_argument('--requests', dest='p_requests', type=json_value, metavar="JSON", help='A list of issue and worklog ID pairs. JSON array of objects with issue_id, worklog_id. Schema: codapact-jira describe list-worklogs-by-issue-id-and-worklog-id')
    c.set_defaults(handler=_run_list_worklogs_by_issue_id_and_worklog_id, flags={'body.requests': '--requests'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_worklogs_by_issue_id_and_worklog_id', 'requires_one_of': [['--requests']]})
    g_agents = commands.add_parser('agents', help='start-batch, start-uniform', description="Run 'codapact-jira agents COMMAND --help' for a command's options and examples.")
    g_agents_commands = g_agents.add_subparsers(dest="g_agents", metavar="COMMAND", required=True)
