    c.add_argument('--invocations', dest='p_invocations', type=json_value, metavar="JSON", required=True, help='Between 1 and 50 invocations. Request IDs must be unique within the request. JSON array of objects with agent_id*, issue_id*, request_id*, user_prompt (* required). Schema: codapact-jira describe agents start-batch')
    c.set_defaults(handler=_run_agents_start_batch, flags={'body.client_mutation_id': '--client-mutation-id', 'body.invocations': '--invocations'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'start_batch'})
    c = g_agents_commands.add_parser('start-uniform', parents=[common], help='Bulk start agent sessions (uniform)', description="Starts the same agent on between 1 and 50 issues, with an optional prompt\nshared by every invocation. Supply numeric issue-ID strings, and a Rovo agent\nID. Session-start outcomes are returned inline; the agent's work continues\nasynchronously.\n\n**[Permissions](#permissions) required:**\n\n* Global bulk change [permission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-global-permissions/). * Browse [project\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-permissions/) in all projects that contain\nthe selected issues. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.", usage='%(prog)s --agent-id AGENT_ID --client-mutation-id CLIENT_MUTATION_ID --issue-ids ISSUE_IDS [options]', epilog=RUNTIME.command_epilog(['codapact-jira agents start-uniform --agent-id AGENT_ID --client-mutation-id CLIENT_MUTATION_ID --issue-ids ISSUE_IDS', 'codapact-jira agents start-uniform --agent-id AGENT_ID --client-mutation-id CLIENT_MUTATION_ID --issue-ids ISSUE_IDS --dry-run']), formatter_class=RAW)
