    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True)
    c.set_defaults(handler=_run_app_properties_put, flags={'property_key': '--property-key', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'put_forge_app_property'})
    c = g_app_properties_commands.add_parser('delete', parents=[common], help='Delete app property (Forge)', description="Deletes a Forge app's property.\n\n**[Permissions](#permissions) required:** Only Forge apps can make this\nrequest. This API can only be accessed using\n**[asApp()](https://developer.atlassian.com/platform/forge/apis-\nreference/fetch-api-product.requestjira/#method-signature)** requests from\nForge.\n\nThe new `write:app-data:jira` OAuth scope is 100% optional now, and not using\nit won't break your app. However, we recommend adding it to your app's scope\nlist because we will eventually make it mandatory.", usage='%(prog)s PROPERTY_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira app-properties delete PROPERTY_KEY --dry-run', 'codapact-jira app-properties delete PROPERTY_KEY --yes']), formatter_class=RAW)
