    g_audit_records = commands.add_parser('audit-records', help='list', description="Run 'codapact-jira audit-records COMMAND --help' for a command's options and examples.")
    g_audit_records_commands = g_audit_records.add_subparsers(dest="g_audit_records", metavar="COMMAND", required=True)
    c = g_audit_records_commands.add_parser('list', parents=[common], help='Get audit records', description='Returns a list of audit records. The list can be filtered to include items:\n\n* where each item in `filter` has at least one match in any of these fields: *\n`summary` * `category` * `eventSource` * `objectItem.name` If the object is a\nuser, account ID is available to filter. * `objectItem.parentName` *\n`objectItem.typeName` * `changedValues.changedFrom` *\n`changedValues.changedTo` * `remoteAddress` For example, if `filter` contains\n*man ed*, an audit record containing `summary": "User added to group"` and\n`"category": "group management"` is returned. * created on or after a date and\ntime. * created or or before a date and time.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira audit-records list']), formatter_class=RAW)
    c.add_argument('--offset', dest='p_offset', type=integer, metavar='OFFSET', help='The number of records to skip before returning the first result. (default: 0)')
    c.add_argument('--limit', dest='p_limit', type=integer, metavar='LIMIT', help='The maximum number of results to return. (default: 1000)')
    c.add_argument('--filter', dest='p_filter', metavar='FILTER', help='The strings to match with audit field content, space separated.')
    c.add_argument('--from', dest='p_from', metavar='FROM', help='The date and time on or after which returned audit records must have been created. If `to` is provided `from` must be before `to` or no audit records are returned.')
    c.add_argument('--to', dest='p_to', metavar='TO', help='The date and time on or before which returned audit results must have been created. If `from` is provided `to` must be after `from` or no audit records are returned.')
    c.set_defaults(handler=_run_audit_records_list, flags={'offset': '--offset', 'limit': '--limit', 'filter': '--filter', 'from': '--from', 'to': '--to'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_audit_records'})
