    c.add_argument('--size', dest='p_size', choices=['xsmall', 'small', 'medium', 'large', 'xlarge'], help='The size of the avatar image. If not provided the default size is returned.')
    c.add_argument('--format', dest='p_format', choices=['png', 'svg'], help='The format to return the avatar image in. If not provided the original content format is returned.')
    c.set_defaults(handler=_run_avatars_get_image, flags={'type': '--type', 'id': '--id', 'size': '--size', 'format': '--format'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_avatar_image_by_id'})
    c = g_avatars_commands.add_parser('get-image-by-owner', parents=[common], help='Get avatar image by owner', description='Returns the avatar image for a project, issue type or priority.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* For system avatars, none. * For custom project avatars, *Browse projects*\n[project permission](https://confluence.atlassian.com/x/yodKLg) for the\nproject the avatar belongs to. * For custom issue type avatars, *Browse\nprojects* [project permission](https://confluence.atlassian.com/x/yodKLg) for\nat least one project the issue type is used in. * For priority avatars, none.', usage='%(prog)s TYPE ENTITY_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira avatars get-image-by-owner TYPE ENTITY_ID']), formatter_class=RAW)
    c.add_argument('p_type', metavar='TYPE', nargs='?', default=argparse.SUPPRESS, choices=['issuetype', 'project', 'priority'], help='The icon type of the avatar.')
