    c = g_dashboards_commands.add_parser('create', parents=[common], help='Create dashboard', description='Creates a dashboard.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s --edit-permissions @edit-permissions.json --name NAME --share-permissions @share-permissions.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira dashboards create --edit-permissions @edit-permissions.json --name NAME --share-permissions @share-permissions.json', 'codapact-jira dashboards create --edit-permissions @edit-permissions.json --name NAME --share-permissions @share-permissions.json --dry-run']), formatter_class=RAW)
