    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='The description of the dashboard.')
    c.add_argument('--edit-permissions', dest='p_edit_permissions', type=json_value, metavar="JSON", required=True, help='The edit permissions for the dashboard. JSON array of objects with type*, group, id, project, role, user (* required). Schema: codapact-jira describe dashboards create')
    c.add_argument('--name', dest='p_name', metavar='NAME', required=True, help='The name of the dashboard.')
    c.add_argument('--share-permissions', dest='p_share_permissions', type=json_value, metavar="JSON", required=True, help='The share permissions for the dashboard. JSON array of objects with type*, group, id, project, role, user (* required). Schema: codapact-jira describe dashboards create')
    c.set_defaults(handler=_run_dashboards_create, flags={'extend_admin_permissions': '--extend-admin-permissions', 'body.description': '--description', 'body.edit_permissions': '--edit-permissions', 'body.name': '--name', 'body.share_permissions': '--share-permissions'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_dashboard'})
    c = g_dashboards_commands.add_parser('bulk', parents=[common], help='Bulk edit dashboards', description='Bulk edit dashboards. Maximum number of dashboards to be edited at the same\ntime is 100.\n\n**[Permissions](#permissions) required:** None\n\nThe dashboards to be updated must be owned by the user, or the user must be an\nadministrator.', usage='%(prog)s --action {changeOwner,changePermission,addPermission,removePermission} --entity-ids ENTITY_IDS [options]', epilog=RUNTIME.command_epilog(['codapact-jira dashboards bulk --action changeOwner --entity-ids ENTITY_IDS', 'codapact-jira dashboards bulk --action changeOwner --entity-ids ENTITY_IDS --dry-run']), formatter_class=RAW)
    c.add_argument('--action', dest='p_action', choices=['changeOwner', 'changePermission', 'addPermission', 'removePermission'], required=True, help='Allowed action for bulk edit shareable entity')
    c.add_argument('--change-owner-details', dest='p_change_owner_details', type=json_value, metavar="JSON", help='The details of change owner action. JSON object with autofix_name*, new_owner* (* required). Schema: codapact-jira describe dashboards bulk')
    c.add_argument('--entity-ids', dest='p_entity_ids', action="append", type=integer, metavar='ENTITY_IDS', required=True, help='The id list of shareable entities to be changed.')
    c.add_argument('--extend-admin-permissions', dest='p_extend_admin_permissions', action=argparse.BooleanOptionalAction, help='Whether the actions are executed by users with Administer Jira global permission.')
    c.add_argument('--permission-details', dest='p_permission_details', type=json_value, metavar="JSON", help='The permission details to be changed. JSON object with edit_permissions*, share_permissions* (* required). Schema: codapact-jira describe dashboards bulk')
    c.set_defaults(handler=_run_dashboards_bulk, flags={'body.action': '--action', 'body.change_owner_details': '--change-owner-details', 'body.entity_ids': '--entity-ids', 'body.extend_admin_permissions': '--extend-admin-permissions', 'body.permission_details': '--permission-details'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'bulk_edit_dashboards'})
    c = g_dashboards_commands.add_parser('list-all-available-gadgets', parents=[common], help='Get available gadgets', description='Gets a list of all available gadgets that can be added to all dashboards.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira dashboards list-all-available-gadgets']), formatter_class=RAW)
    c.set_defaults(handler=_run_dashboards_list_all_available_gadgets, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_all_available_dashboard_gadgets'})
    c = g_dashboards_commands.add_parser('get-paginated', parents=[common], help='Search for dashboards', description='Returns a [paginated](#pagination) list of dashboards. This operation is\nsimilar to [Get dashboards](#api-rest-api-3-dashboard-get) except that the\nresults can be refined to include dashboards that have specific attributes.\nFor example, dashboards with a particular name. When multiple attributes are\nspecified only filters matching all attributes are returned.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** The following dashboards that match\nthe query parameters are returned:\n\n* Dashboards owned by the user. Not returned for anonymous users. * Dashboards\nshared with a group that the user is a member of. Not returned for anonymous\nusers. * Dashboards shared with a private project that the user can browse.\nNot returned for anonymous users. * Dashboards shared with a public project. *\nDashboards shared with the public.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira dashboards get-paginated']), formatter_class=RAW)
    c.add_argument('--dashboard-name', dest='p_dashboard_name', metavar='DASHBOARD_NAME', help='String used to perform a case-insensitive partial match with `name`.')
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='User account ID used to return dashboards with the matching `owner.accountId`. This parameter cannot be used with the `owner` parameter.')
    c.add_argument('--owner', dest='p_owner', metavar='OWNER', help='This parameter is deprecated because of privacy changes. Use `accountId` instead. See the [migration guide](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details. User name used to return dashboards with the matching `owner.name`. This parameter cannot be used with the `accountId` parameter.')
    c.add_argument('--groupname', dest='p_groupname', metavar='GROUPNAME', help="As a group's name can change, use of `groupId` is recommended. Group name used to return dashboards that are shared with a group that matches `sharePermissions.group.name`. This parameter cannot be used with the `groupId` parameter.")
    c.add_argument('--group-id', dest='p_group_id', metavar='GROUP_ID', help='Group ID used to return dashboards that are shared with a group that matches `sharePermissions.group.groupId`. This parameter cannot be used with the `groupname` parameter.')
    c.add_argument('--project-id', dest='p_project_id', type=integer, metavar='PROJECT_ID', help='Project ID used to returns dashboards that are shared with a project that matches `sharePermissions.project.id`.')
    c.add_argument('--order-by', dest='p_order_by', choices=['description', '-description', '+description', 'favorite_count', '-favorite_count', '+favorite_count', 'id', '-id', '+id', 'is_favorite', '-is_favorite', '+is_favorite', 'name', '-name', '+name', 'owner', '-owner', '+owner'], help='[Order](#ordering) the results by a field: (default: name)')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.add_argument('--status', dest='p_status', choices=['active', 'archived', 'deleted'], help='The status to filter by. It may be active, archived or deleted. (default: active)')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about dashboard in the response. This parameter accepts a comma-separated list. Expand options include:')
    c.set_defaults(handler=_run_dashboards_get_paginated, flags={'dashboard_name': '--dashboard-name', 'account_id': '--account-id', 'owner': '--owner', 'groupname': '--groupname', 'group_id': '--group-id', 'project_id': '--project-id', 'order_by': '--order-by', 'start_at': '--start-at', 'max_results': '--max-results', 'status': '--status', 'expand': '--expand'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_dashboards_paginated'})
    c = g_dashboards_commands.add_parser('list-all-gadgets', parents=[common], help='Get gadgets', description='Returns a list of dashboard gadgets on a dashboard.\n\nThis operation returns:\n\n* Gadgets from a list of IDs, when `id` is set. * Gadgets with a module key,\nwhen `moduleKey` is set. * Gadgets from a list of URIs, when `uri` is set. *\nAll gadgets, when no other parameters are set.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s DASHBOARD_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira dashboards list-all-gadgets DASHBOARD_ID']), formatter_class=RAW)
    c.add_argument('p_dashboard_id', metavar='DASHBOARD_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the dashboard.')
    c.add_argument('--dashboard-id', dest='p_dashboard_id', default=argparse.SUPPRESS, type=integer, metavar='DASHBOARD_ID', help='same as DASHBOARD_ID')
    c.add_argument('--module-key', dest='p_module_key', action="append", metavar='MODULE_KEY', help='The list of gadgets module keys. To include multiple module keys, separate module keys with ampersand: `moduleKey=key:one&moduleKey=key:two`.')
    c.add_argument('--uri', dest='p_uri', action="append", metavar='URI', help='The list of gadgets URIs. To include multiple URIs, separate URIs with ampersand: `uri=/rest/example/uri/1&uri=/rest/example/uri/2`.')
    c.add_argument('--gadget-id', dest='p_gadget_id', action="append", type=integer, metavar='GADGET_ID', help='The list of gadgets IDs. To include multiple IDs, separate IDs with ampersand: `gadgetId=10000&gadgetId=10001`.')
    c.set_defaults(handler=_run_dashboards_list_all_gadgets, flags={'dashboard_id': '--dashboard-id', 'module_key': '--module-key', 'uri': '--uri', 'gadget_id': '--gadget-id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_all_gadgets'})
    c = g_dashboards_commands.add_parser('add-gadget', parents=[common], help='Add gadget to dashboard', description='Adds a gadget to a dashboard.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s DASHBOARD_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira dashboards add-gadget DASHBOARD_ID --color COLOR', 'codapact-jira dashboards add-gadget DASHBOARD_ID --color COLOR --dry-run']), formatter_class=RAW)
    c.add_argument('p_dashboard_id', metavar='DASHBOARD_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the dashboard.')
    c.add_argument('--dashboard-id', dest='p_dashboard_id', default=argparse.SUPPRESS, type=integer, metavar='DASHBOARD_ID', help='same as DASHBOARD_ID')
    c.add_argument('--color', dest='p_color', metavar='COLOR', help='The color of the gadget. Should be one of `blue`, `red`, `yellow`, `green`, `cyan`, `purple`, `gray`, or `white`.')
    c.add_argument('--ignore-uri-and-module-key-validation', dest='p_ignore_uri_and_module_key_validation', action=argparse.BooleanOptionalAction, help="Whether to ignore the validation of module key and URI. For example, when a gadget is created that is a part of an application that isn't installed.")
    c.add_argument('--module-key', dest='p_module_key', metavar='MODULE_KEY', help="The module key of the gadget type. Can't be provided with `uri`.")
    c.add_argument('--position', dest='p_position', type=json_value, metavar="JSON", help='The position of the gadget. When the gadget is placed into the position, other gadgets in the same column are moved down to accommodate it. JSON object with the_column_position_of_the_gadget*, the_row_position_of_the_gadget* (* required). Schema: codapact-jira describe dashboards add-gadget')
    c.add_argument('--title', dest='p_title', metavar='TITLE', help='The title of the gadget.')
    c.add_argument('--uri', dest='p_uri', metavar='URI', help="The URI of the gadget type. Can't be provided with `moduleKey`.")
    c.set_defaults(handler=_run_dashboards_add_gadget, flags={'dashboard_id': '--dashboard-id', 'body.color': '--color', 'body.ignore_uri_and_module_key_validation': '--ignore-uri-and-module-key-validation', 'body.module_key': '--module-key', 'body.position': '--position', 'body.title': '--title', 'body.uri': '--uri'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'add_gadget', 'requires_one_of': [['--color', '--ignore-uri-and-module-key-validation', '--module-key', '--position', '--title', '--uri']]})
    c = g_dashboards_commands.add_parser('update-gadget', parents=[common], help='Update gadget on dashboard', description='Changes the title, position, and color of the gadget on a dashboard.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s DASHBOARD_ID GADGET_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira dashboards update-gadget DASHBOARD_ID GADGET_ID --color COLOR', 'codapact-jira dashboards update-gadget DASHBOARD_ID GADGET_ID --color COLOR --dry-run']), formatter_class=RAW)
    c.add_argument('p_dashboard_id', metavar='DASHBOARD_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the dashboard.')
    c.add_argument('p_gadget_id', metavar='GADGET_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the gadget.')
    c.add_argument('--dashboard-id', dest='p_dashboard_id', default=argparse.SUPPRESS, type=integer, metavar='DASHBOARD_ID', help='same as DASHBOARD_ID')
    c.add_argument('--gadget-id', dest='p_gadget_id', default=argparse.SUPPRESS, type=integer, metavar='GADGET_ID', help='same as GADGET_ID')
    c.add_argument('--color', dest='p_color', metavar='COLOR', help='The color of the gadget. Should be one of `blue`, `red`, `yellow`, `green`, `cyan`, `purple`, `gray`, or `white`.')
    c.add_argument('--position', dest='p_position', type=json_value, metavar="JSON", help='The position of the gadget. JSON object with the_column_position_of_the_gadget*, the_row_position_of_the_gadget* (* required). Schema: codapact-jira describe dashboards update-gadget')
    c.add_argument('--title', dest='p_title', metavar='TITLE', help='The title of the gadget.')
    c.set_defaults(handler=_run_dashboards_update_gadget, flags={'dashboard_id': '--dashboard-id', 'gadget_id': '--gadget-id', 'body.color': '--color', 'body.position': '--position', 'body.title': '--title'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_gadget', 'requires_one_of': [['--color', '--position', '--title']]})
    c = g_dashboards_commands.add_parser('remove-gadget', parents=[common], help='Remove gadget from dashboard', description='Removes a dashboard gadget from a dashboard.\n\nWhen a gadget is removed from a dashboard, other gadgets in the same column\nare moved up to fill the emptied position.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s DASHBOARD_ID GADGET_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira dashboards remove-gadget DASHBOARD_ID GADGET_ID --dry-run', 'codapact-jira dashboards remove-gadget DASHBOARD_ID GADGET_ID --yes']), formatter_class=RAW)
    c.add_argument('p_dashboard_id', metavar='DASHBOARD_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the dashboard.')
    c.add_argument('p_gadget_id', metavar='GADGET_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the gadget.')
    c.add_argument('--dashboard-id', dest='p_dashboard_id', default=argparse.SUPPRESS, type=integer, metavar='DASHBOARD_ID', help='same as DASHBOARD_ID')
    c.add_argument('--gadget-id', dest='p_gadget_id', default=argparse.SUPPRESS, type=integer, metavar='GADGET_ID', help='same as GADGET_ID')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_dashboards_remove_gadget, flags={'dashboard_id': '--dashboard-id', 'gadget_id': '--gadget-id'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'remove_gadget'})
    c = g_dashboards_commands.add_parser('list-item-property-keys', parents=[common], help='Get dashboard item property keys', description='Returns the keys of all properties for a dashboard item.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** The user must have read permission\nof the dashboard or have the dashboard shared with them.', usage='%(prog)s DASHBOARD_ID ITEM_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira dashboards list-item-property-keys DASHBOARD_ID ITEM_ID']), formatter_class=RAW)
    c.add_argument('p_dashboard_id', metavar='DASHBOARD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the dashboard.')
    c.add_argument('p_item_id', metavar='ITEM_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the dashboard item.')
    c.add_argument('--dashboard-id', dest='p_dashboard_id', default=argparse.SUPPRESS, metavar='DASHBOARD_ID', help='same as DASHBOARD_ID')
    c.add_argument('--item-id', dest='p_item_id', default=argparse.SUPPRESS, metavar='ITEM_ID', help='same as ITEM_ID')
    c.set_defaults(handler=_run_dashboards_list_item_property_keys, flags={'dashboard_id': '--dashboard-id', 'item_id': '--item-id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_dashboard_item_property_keys'})
    c = g_dashboards_commands.add_parser('get-item-property', parents=[common], help='Get dashboard item property', description="Returns the key and value of a dashboard item property.\n\nA dashboard item enables an app to add user-specific information to a user\ndashboard. Dashboard items are exposed to users as gadgets that users can add\nto their dashboards. For more information on how users do this, see [Adding\nand customizing gadgets](https://confluence.atlassian.com/x/7AeiLQ).\n\nWhen an app creates a dashboard item it registers a callback to receive the\ndashboard item ID. The callback fires whenever the item is rendered or, where\nthe item is configurable, the user edits the item. The app then uses this\nresource to store the item's content or configuration details. For more\ninformation on working with dashboard items, see [ Building a dashboard item\nfor a JIRA Connect add-\non](https://developer.atlassian.com/server/jira/platform/guide-building-a-\ndashboard-item-for-a-jira-connect-add-on-33746254/) and the [Dashboard\nItem](https://developer.atlassian.com/cloud/jira/platform/modules/dashboard-\nitem/) documentation.\n\nThere is no resource to set or get dashboard items.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** The user must have read permission\nof the dashboard or have the dashboard shared with them.", usage='%(prog)s DASHBOARD_ID ITEM_ID PROPERTY_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira dashboards get-item-property DASHBOARD_ID ITEM_ID PROPERTY_KEY']), formatter_class=RAW)
    c.add_argument('p_dashboard_id', metavar='DASHBOARD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the dashboard.')
    c.add_argument('p_item_id', metavar='ITEM_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the dashboard item.')
    c.add_argument('p_property_key', metavar='PROPERTY_KEY', nargs='?', default=argparse.SUPPRESS, help='The key of the dashboard item property.')
    c.add_argument('--dashboard-id', dest='p_dashboard_id', default=argparse.SUPPRESS, metavar='DASHBOARD_ID', help='same as DASHBOARD_ID')
    c.add_argument('--item-id', dest='p_item_id', default=argparse.SUPPRESS, metavar='ITEM_ID', help='same as ITEM_ID')
    c.add_argument('--property-key', dest='p_property_key', default=argparse.SUPPRESS, metavar='PROPERTY_KEY', help='same as PROPERTY_KEY')
    c.set_defaults(handler=_run_dashboards_get_item_property, flags={'dashboard_id': '--dashboard-id', 'item_id': '--item-id', 'property_key': '--property-key'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_dashboard_item_property'})
    c = g_dashboards_commands.add_parser('set-item-property', parents=[common], help='Set dashboard item property', description="Sets the value of a dashboard item property. Use this resource in apps to\nstore custom data against a dashboard item.\n\nA dashboard item enables an app to add user-specific information to a user\ndashboard. Dashboard items are exposed to users as gadgets that users can add\nto their dashboards. For more information on how users do this, see [Adding\nand customizing gadgets](https://confluence.atlassian.com/x/7AeiLQ).\n\nWhen an app creates a dashboard item it registers a callback to receive the\ndashboard item ID. The callback fires whenever the item is rendered or, where\nthe item is configurable, the user edits the item. The app then uses this\nresource to store the item's content or configuration details. For more\ninformation on working with dashboard items, see [ Building a dashboard item\nfor a JIRA Connect add-\non](https://developer.atlassian.com/server/jira/platform/guide-building-a-\ndashboard-item-for-a-jira-connect-add-on-33746254/) and the [Dashboard\nItem](https://developer.atlassian.com/cloud/jira/platform/modules/dashboard-\nitem/) documentation.\n\nThere is no resource to set or get dashboard items.\n\nThe value of the request body must be a\n[valid](http://tools.ietf.org/html/rfc4627), non-empty JSON blob. The maximum\nlength is 32768 characters.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** The user must have edit permisson of\nthe dashboard.", usage='%(prog)s DASHBOARD_ID ITEM_ID PROPERTY_KEY --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira dashboards set-item-property DASHBOARD_ID ITEM_ID PROPERTY_KEY --body @body.json', 'codapact-jira dashboards set-item-property DASHBOARD_ID ITEM_ID PROPERTY_KEY --body @body.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_dashboard_id', metavar='DASHBOARD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the dashboard.')
    c.add_argument('p_item_id', metavar='ITEM_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the dashboard item.')
    c.add_argument('p_property_key', metavar='PROPERTY_KEY', nargs='?', default=argparse.SUPPRESS, help='The key of the dashboard item property. The maximum length is 255 characters. For dashboard items with a spec URI and no complete module key, if the provided propertyKey is equal to "config", the request body\'s JSON must be an object with all keys and values as strings.')
    c.add_argument('--dashboard-id', dest='p_dashboard_id', default=argparse.SUPPRESS, metavar='DASHBOARD_ID', help='same as DASHBOARD_ID')
    c.add_argument('--item-id', dest='p_item_id', default=argparse.SUPPRESS, metavar='ITEM_ID', help='same as ITEM_ID')
    c.add_argument('--property-key', dest='p_property_key', default=argparse.SUPPRESS, metavar='PROPERTY_KEY', help='same as PROPERTY_KEY')
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='The value of the property. The value has to be a valid, non-empty [JSON](https://tools.ietf.org/html/rfc4627) value. The maximum length of the property value is 32768 bytes.')
    c.set_defaults(handler=_run_dashboards_set_item_property, flags={'dashboard_id': '--dashboard-id', 'item_id': '--item-id', 'property_key': '--property-key', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'set_dashboard_item_property'})
    c = g_dashboards_commands.add_parser('delete-item-property', parents=[common], help='Delete dashboard item property', description='Deletes a dashboard item property.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** The user must have edit permission\nof the dashboard.', usage='%(prog)s DASHBOARD_ID ITEM_ID PROPERTY_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira dashboards delete-item-property DASHBOARD_ID ITEM_ID PROPERTY_KEY --dry-run', 'codapact-jira dashboards delete-item-property DASHBOARD_ID ITEM_ID PROPERTY_KEY --yes']), formatter_class=RAW)
    c.add_argument('p_dashboard_id', metavar='DASHBOARD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the dashboard.')
    c.add_argument('p_item_id', metavar='ITEM_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the dashboard item.')
    c.add_argument('p_property_key', metavar='PROPERTY_KEY', nargs='?', default=argparse.SUPPRESS, help='The key of the dashboard item property.')
    c.add_argument('--dashboard-id', dest='p_dashboard_id', default=argparse.SUPPRESS, metavar='DASHBOARD_ID', help='same as DASHBOARD_ID')
    c.add_argument('--item-id', dest='p_item_id', default=argparse.SUPPRESS, metavar='ITEM_ID', help='same as ITEM_ID')
    c.add_argument('--property-key', dest='p_property_key', default=argparse.SUPPRESS, metavar='PROPERTY_KEY', help='same as PROPERTY_KEY')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_dashboards_delete_item_property, flags={'dashboard_id': '--dashboard-id', 'item_id': '--item-id', 'property_key': '--property-key'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_dashboard_item_property'})
