    g_field_schemes = commands.add_parser('field-schemes', help='associate-projects-to-field-association-schemes, clone-field-association-scheme, create-field-association-scheme, … (15 commands)', description="Run 'codapact-jira field-schemes COMMAND --help' for a command's options and examples.")
    g_field_schemes_commands = g_field_schemes.add_subparsers(dest="g_field_schemes", metavar="COMMAND", required=True)
    c = g_field_schemes_commands.add_parser('list-field-association-schemes', parents=[common], help='Get field schemes', description='REST endpoint for retrieving a paginated list of field association schemes\nwith optional filtering.\n\nThis endpoint allows clients to fetch field association schemes with optional\nfiltering by project IDs and text queries. The response includes scheme\ndetails with navigation links and filter metadata when applicable.\n\nFiltering Behavior:\n\n* When projectId or query parameters are provided, the response includes\nmatchedFilters metadata showing which filters were applied. * When no filters\nare applied, matchedFilters is omitted from individual scheme objects\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira field-schemes list-field-association-schemes']), formatter_class=RAW)
    c.add_argument('--project-id', dest='p_project_id', action="append", type=integer, metavar='PROJECT_ID', help='(optional) List of project IDs to filter schemes by. If not provided, schemes from all projects are returned.')
    c.add_argument('--arg-query', dest='p_arg_query', metavar='ARG_QUERY', help='(optional) Text filter for scheme name or description matching (case-insensitive). If not provided, no text filtering is applied.')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='Zero-based index of the first item to return (default: 0) (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='Maximum number of items to return per page (default: 50, max: 100) (default: 50)')
    c.set_defaults(handler=_run_field_schemes_list_field_association_schemes, flags={'project_id': '--project-id', 'query': '--arg-query', 'start_at': '--start-at', 'max_results': '--max-results'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_field_association_schemes'})
    c = g_field_schemes_commands.add_parser('create-field-association-scheme', parents=[common], help='Create field scheme', description="Endpoint for creating a new field association scheme.\n\nA new scheme is **not** copied from, or based on, any existing field\nassociation scheme. Instead, it is initialised with a minimal default set of\ncritical fields sourced from the instance's own *system* and *product* fields\n(the fields returned by the product's field API), rather than from a scheme\nyou specify.\n\nTo create a scheme that is based on an existing one, use the *Clone field\nscheme* endpoint instead.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).", usage='%(prog)s --name NAME [options]', epilog=RUNTIME.command_epilog(['codapact-jira field-schemes create-field-association-scheme --name NAME', 'codapact-jira field-schemes create-field-association-scheme --name NAME --dry-run']), formatter_class=RAW)
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='Description of the scheme to be created')
    c.add_argument('--name', dest='p_name', metavar='NAME', required=True, help='The name of the scheme to be created')
    c.set_defaults(handler=_run_field_schemes_create_field_association_scheme, flags={'body.description': '--description', 'body.name': '--name'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_field_association_scheme'})
    c = g_field_schemes_commands.add_parser('update-fields-associated-with-schemes', parents=[common], help='Update fields associated with field schemes', description='Update fields associated with field association schemes.\n\n**Request body limits:** a single request can update associations for at most\n**100 fields** (the top-level field ID keys of the request body), and each\nfield association item may reference at most 50 field schemes. Exceeding a\nlimit returns a 400 response with an error such as "The fieldIds must contain\nno more than 100 items."\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira field-schemes update-fields-associated-with-schemes --body @body.json', 'codapact-jira field-schemes update-fields-associated-with-schemes --body @body.json --dry-run']), formatter_class=RAW)
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='The request containing the schemes and work types to associate each field with.')
    c.set_defaults(handler=_run_field_schemes_update_fields_associated_with_schemes, flags={'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_fields_associated_with_schemes'})
    c = g_field_schemes_commands.add_parser('remove-fields-associated-with-schemes', parents=[common], help='Remove fields associated with field schemes', description='Remove fields associated with field association schemes.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira field-schemes remove-fields-associated-with-schemes --body @body.json --dry-run', 'codapact-jira field-schemes remove-fields-associated-with-schemes --body @body.json --yes']), formatter_class=RAW)
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='The request containing the schemes and fields to be removed.')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_field_schemes_remove_fields_associated_with_schemes, flags={'body': '--body'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'remove_fields_associated_with_schemes'})
    c = g_field_schemes_commands.add_parser('update-field-association-scheme-item-parameters', parents=[common], help='Update field parameters', description='Update field association item parameters in field association schemes.\n\n**Request body limits:** a single request can update parameters for at most\n**100 fields** (the top-level field ID keys of the request body). In addition,\neach field may include at most 50 update items, and each update item may\nreference at most 50 field schemes. Exceeding any of these limits returns a\n400 response with an error such as "The fieldIds must contain no more than 100\nitems."\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira field-schemes update-field-association-scheme-item-parameters --body @body.json', 'codapact-jira field-schemes update-field-association-scheme-item-parameters --body @body.json --dry-run']), formatter_class=RAW)
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='The request containing the field association scheme id and the parameters to update.')
    c.set_defaults(handler=_run_field_schemes_update_field_association_scheme_item_parameters, flags={'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_field_association_scheme_item_parameters'})
    c = g_field_schemes_commands.add_parser('remove-field-association-scheme-item-parameters', parents=[common], help='Remove field parameters', description='Remove field association parameters overrides for work types.\n\n**Request body limits:** a single request can remove at most **100\nparameters**. The number of removals is counted as the sum, across every\nremoval entry, of the number of work types multiplied by the number of\nparameter names in that entry. Exceeding this limit returns a 400 response\nwith the error "Request exceeds maximum number of parameters that can be\nremoved 100".\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira field-schemes remove-field-association-scheme-item-parameters --body @body.json --dry-run', 'codapact-jira field-schemes remove-field-association-scheme-item-parameters --body @body.json --yes']), formatter_class=RAW)
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True)
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_field_schemes_remove_field_association_scheme_item_parameters, flags={'body': '--body'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'remove_field_association_scheme_item_parameters'})
    c = g_field_schemes_commands.add_parser('list', parents=[common], help='Get projects with field schemes', description='Get projects with field association schemes. This will be a temporary API but\nuseful when transitioning from the legacy field configuration APIs to the new\nones.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --project-id PROJECT_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira field-schemes list --project-id PROJECT_ID']), formatter_class=RAW)
