    c = g_field_schemes_commands.add_parser('list-field-association-scheme-item-parameters', parents=[common], help='Get field parameters', description='Retrieve field association parameters on a field association scheme\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID FIELD_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira field-schemes list-field-association-scheme-item-parameters ID FIELD_ID']), formatter_class=RAW)
