    g_filter_sharing = commands.add_parser('filter-sharing', help='add-share-permission, delete-share-permission, get-default-share-scope, … (6 commands)', description="Run 'codapact-jira filter-sharing COMMAND --help' for a command's options and examples.")
    g_filter_sharing_commands = g_filter_sharing.add_subparsers(dest="g_filter_sharing", metavar="COMMAND", required=True)
    c = g_filter_sharing_commands.add_parser('get-default-share-scope', parents=[common], help='Get default share scope', description='Returns the default sharing settings for new filters and dashboards for a\nuser.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira filter-sharing get-default-share-scope']), formatter_class=RAW)
    c.set_defaults(handler=_run_filter_sharing_get_default_share_scope, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_default_share_scope'})
    c = g_filter_sharing_commands.add_parser('set-default-share-scope', parents=[common], help='Set default share scope', description='Sets the default sharing for new filters and dashboards for a user.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s --scope {GLOBAL,AUTHENTICATED,PRIVATE} [options]', epilog=RUNTIME.command_epilog(['codapact-jira filter-sharing set-default-share-scope --scope GLOBAL', 'codapact-jira filter-sharing set-default-share-scope --scope GLOBAL --dry-run']), formatter_class=RAW)
    c.add_argument('--scope', dest='p_scope', choices=['GLOBAL', 'AUTHENTICATED', 'PRIVATE'], required=True, help='The scope of the default sharing for new filters and dashboards:')
    c.set_defaults(handler=_run_filter_sharing_set_default_share_scope, flags={'body.scope': '--scope'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'set_default_share_scope'})
    c = g_filter_sharing_commands.add_parser('list-share-permissions', parents=[common], help='Get share permissions', description='Returns the share permissions for a filter. A filter can be shared with\ngroups, projects, all logged-in users, or the public. Sharing with all logged-\nin users or the public is known as a global share permission.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None, however, share permissions are\nonly returned for:\n\n* filters owned by the user. * filters shared with a group that the user is a\nmember of. * filters shared with a private project that the user has *Browse\nprojects* [project permission](https://confluence.atlassian.com/x/yodKLg) for.\n* filters shared with a public project. * filters shared with the public.', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira filter-sharing list-share-permissions ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the filter.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
    c.set_defaults(handler=_run_filter_sharing_list_share_permissions, flags={'id': '--id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_share_permissions'})
    c = g_filter_sharing_commands.add_parser('add-share-permission', parents=[common], help='Add share permission', description='Add a share permissions to a filter. If you add a global share permission (one\nfor all logged-in users or the public) it will overwrite all share permissions\nfor the filter.\n\nBe aware that this operation uses different objects for updating share\npermissions compared to [Update filter](#api-rest-api-3-filter-id-put).\n\n**[Permissions](#permissions) required:** *Share dashboards and filters*\n[global permission](https://confluence.atlassian.com/x/x4dKLg) and the user\nmust own the filter.', usage='%(prog)s ID --type {user,project,group,projectRole,global,authenticated} [options]', epilog=RUNTIME.command_epilog(['codapact-jira filter-sharing add-share-permission ID --type user', 'codapact-jira filter-sharing add-share-permission ID --type user --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the filter.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='The user account ID that the filter is shared with. For a request, specify the `accountId` property for the user.')
    c.add_argument('--group-id', dest='p_group_id', metavar='GROUP_ID', help='The ID of the group, which uniquely identifies the group across all Atlassian products.For example, *952d12c3-5b5b-4d04-bb32-44d383afc4b2*. Cannot be provided with `groupname`.')
    c.add_argument('--groupname', dest='p_groupname', metavar='GROUPNAME', help='The name of the group to share the filter with. Set `type` to `group`. Please note that the name of a group is mutable, to reliably identify a group use `groupId`.')
    c.add_argument('--project-id', dest='p_project_id', metavar='PROJECT_ID', help='The ID of the project to share the filter with. Set `type` to `project`.')
    c.add_argument('--project-role-id', dest='p_project_role_id', metavar='PROJECT_ROLE_ID', help='The ID of the project role to share the filter with. Set `type` to `projectRole` and the `projectId` for the project that the role is in.')
    c.add_argument('--rights', dest='p_rights', type=integer, metavar='RIGHTS', help='The rights for the share permission.')
    c.add_argument('--type', dest='p_type', choices=['user', 'project', 'group', 'projectRole', 'global', 'authenticated'], required=True, help='The type of the share permission.Specify the type as follows:')
    c.set_defaults(handler=_run_filter_sharing_add_share_permission, flags={'id': '--id', 'body.account_id': '--account-id', 'body.group_id': '--group-id', 'body.groupname': '--groupname', 'body.project_id': '--project-id', 'body.project_role_id': '--project-role-id', 'body.rights': '--rights', 'body.type': '--type'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'add_share_permission'})
    c = g_filter_sharing_commands.add_parser('get-share-permission', parents=[common], help='Get share permission', description='Returns a share permission for a filter. A filter can be shared with groups,\nprojects, all logged-in users, or the public. Sharing with all logged-in users\nor the public is known as a global share permission.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None, however, a share permission is\nonly returned for:\n\n* filters owned by the user. * filters shared with a group that the user is a\nmember of. * filters shared with a private project that the user has *Browse\nprojects* [project permission](https://confluence.atlassian.com/x/yodKLg) for.\n* filters shared with a public project. * filters shared with the public.', usage='%(prog)s ID PERMISSION_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira filter-sharing get-share-permission ID PERMISSION_ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the filter.')
    c.add_argument('p_permission_id', metavar='PERMISSION_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the share permission.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
    c.add_argument('--permission-id', dest='p_permission_id', default=argparse.SUPPRESS, type=integer, metavar='PERMISSION_ID', help='same as PERMISSION_ID')
    c.set_defaults(handler=_run_filter_sharing_get_share_permission, flags={'id': '--id', 'permission_id': '--permission-id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_share_permission'})
    c = g_filter_sharing_commands.add_parser('delete-share-permission', parents=[common], help='Delete share permission', description='Deletes a share permission from a filter.\n\n**[Permissions](#permissions) required:** Permission to access Jira and the\nuser must own the filter.', usage='%(prog)s ID PERMISSION_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira filter-sharing delete-share-permission ID PERMISSION_ID --dry-run', 'codapact-jira filter-sharing delete-share-permission ID PERMISSION_ID --yes']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the filter.')
    c.add_argument('p_permission_id', metavar='PERMISSION_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the share permission.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
    c.add_argument('--permission-id', dest='p_permission_id', default=argparse.SUPPRESS, type=integer, metavar='PERMISSION_ID', help='same as PERMISSION_ID')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_filter_sharing_delete_share_permission, flags={'id': '--id', 'permission_id': '--permission-id'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_share_permission'})
    g_filters = commands.add_parser('filters', help='change-owner, create, delete, … (13 commands)', description="Run 'codapact-jira filters COMMAND --help' for a command's options and examples.")
    g_filters_commands = g_filters.add_subparsers(dest="g_filters", metavar="COMMAND", required=True)
    c = g_filters_commands.add_parser('create', parents=[common], help='Create filter', description='Creates a filter. The filter is shared according to the [default share\nscope](#api-rest-api-3-filter-post). The filter is not selected as a favorite.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s --name NAME [options]', epilog=RUNTIME.command_epilog(['codapact-jira filters create --name NAME', 'codapact-jira filters create --name NAME --dry-run']), formatter_class=RAW)
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about filter in the response. This parameter accepts a comma-separated list. Expand options include:')
    c.add_argument('--override-share-permissions', dest='p_override_share_permissions', action=argparse.BooleanOptionalAction, help='EXPERIMENTAL: Whether share permissions are overridden to enable filters with any share permissions to be created. Available to users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg). (default: False)')
    c.add_argument('--approximate-last-used', dest='p_approximate_last_used', metavar='DATETIME', help="\\[Experimental\\] Approximate last used time. Returns the date and time when the filter was last used. Returns `null` if the filter hasn't been used after tracking was enabled. For performance reasons, timestamps aren't updated in real time and therefore may not be exactly accurate.")
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='A description of the filter.')
    c.add_argument('--edit-permissions', dest='p_edit_permissions', type=json_value, metavar="JSON", help='The groups and projects that can edit the filter. JSON array of objects with type*, group, id, project, role, user (* required). Schema: codapact-jira describe filters create')
    c.add_argument('--favourite', dest='p_favourite', action=argparse.BooleanOptionalAction, help='Whether the filter is selected as a favorite.')
    c.add_argument('--favourited-count', dest='p_favourited_count', type=integer, metavar='FAVOURITED_COUNT', help='The count of how many users have selected this filter as a favorite, including the filter owner.')
    c.add_argument('--id', dest='p_id', metavar='ID', help='The unique identifier for the filter.')
    c.add_argument('--jql', dest='p_jql', metavar='JQL', help='The JQL query for the filter. For example, *project = SSP AND issuetype = Bug*.')
    c.add_argument('--name', dest='p_name', metavar='NAME', required=True, help='The name of the filter. Must be unique.')
    c.add_argument('--owner', dest='p_owner', type=json_value, metavar="JSON", help='The user who owns the filter. This is defaulted to the creator of the filter, however Jira administrators can change the owner of a shared filter in the admin settings. JSON object with account_id, account_type, active, app_type, application_roles, avatar_urls, display_name, email_address, expand, groups, guest, key, ... Schema: codapact-jira describe filters create')
    c.add_argument('--search-url', dest='p_search_url', metavar='SEARCH_URL', help="A URL to view the filter results in Jira, using the [Search for issues using JQL](#api-rest-api-3-filter-search-get) operation with the filter's JQL string to return the filter results. For example, *https://your-domain.atlassian.net/rest/api/3/search?jql=project+%%3D+SSP+AND+issuetype+%%3D+Bug*.")
    c.add_argument('--self', dest='p_self', metavar='SELF', help='The URL of the filter.')
    c.add_argument('--share-permissions', dest='p_share_permissions', type=json_value, metavar="JSON", help='The groups and projects that the filter is shared with. JSON array of objects with type*, group, id, project, role, user (* required). Schema: codapact-jira describe filters create')
    c.add_argument('--shared-users', dest='p_shared_users', type=json_value, metavar="JSON", help='A paginated list of the users that the filter is shared with. This includes users that are members of the groups or can browse the projects that the filter is shared with. JSON object with end_index, items, max_results, size, start_index. Schema: codapact-jira describe filters create')
    c.add_argument('--subscriptions', dest='p_subscriptions', type=json_value, metavar="JSON", help='A paginated list of the users that are subscribed to the filter. JSON object with end_index, items, max_results, size, start_index. Schema: codapact-jira describe filters create')
    c.add_argument('--view-url', dest='p_view_url', metavar='VIEW_URL', help='A URL to view the filter results in Jira, using the ID of the filter. For example, *https://your-domain.atlassian.net/issues/?filter=10100*.')
    c.set_defaults(handler=_run_filters_create, flags={'expand': '--expand', 'override_share_permissions': '--override-share-permissions', 'body.approximate_last_used': '--approximate-last-used', 'body.description': '--description', 'body.edit_permissions': '--edit-permissions', 'body.favourite': '--favourite', 'body.favourited_count': '--favourited-count', 'body.id': '--id', 'body.jql': '--jql', 'body.name': '--name', 'body.owner': '--owner', 'body.search_url': '--search-url', 'body.self': '--self', 'body.share_permissions': '--share-permissions', 'body.shared_users': '--shared-users', 'body.subscriptions': '--subscriptions', 'body.view_url': '--view-url'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_filter'})
    c = g_filters_commands.add_parser('list-favourite', parents=[common], help='Get favorite filters', description='Returns the visible favorite filters of the user.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** A favorite filter is only visible to\nthe user where the filter is:\n\n* owned by the user. * shared with a group that the user is a member of. *\nshared with a private project that the user has *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for. * shared with a\npublic project. * shared with the public.\n\nFor example, if the user favorites a public filter that is subsequently made\nprivate that filter is not returned by this operation.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira filters list-favourite']), formatter_class=RAW)
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about filter in the response. This parameter accepts a comma-separated list. Expand options include:')
    c.set_defaults(handler=_run_filters_list_favourite, flags={'expand': '--expand'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_favourite_filters'})
    c = g_filters_commands.add_parser('list-my', parents=[common], help='Get my filters', description="Returns the filters owned by the user. If `includeFavourites` is `true`, the\nuser's visible favorite filters are also returned.\n\n**[Permissions](#permissions) required:** Permission to access Jira, however,\na favorite filters is only visible to the user where the filter is:\n\n* owned by the user. * shared with a group that the user is a member of. *\nshared with a private project that the user has *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for. * shared with a\npublic project. * shared with the public.\n\nFor example, if the user favorites a public filter that is subsequently made\nprivate that filter is not returned by this operation.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira filters list-my']), formatter_class=RAW)
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about filter in the response. This parameter accepts a comma-separated list. Expand options include:')
    c.add_argument('--include-favourites', dest='p_include_favourites', action=argparse.BooleanOptionalAction, help="Include the user's favorite filters in the response. (default: False)")
    c.set_defaults(handler=_run_filters_list_my, flags={'expand': '--expand', 'include_favourites': '--include-favourites'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_my_filters'})
    c = g_filters_commands.add_parser('get-paginated', parents=[common], help='Search for filters', description='Returns a [paginated](#pagination) list of filters. Use this operation to get:\n\n* specific filters, by defining `id` only. * filters that match all of the\nspecified attributes. For example, all filters for a user with a particular\nword in their name. When multiple attributes are specified only filters\nmatching all attributes are returned.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None, however, only the following\nfilters that match the query parameters are returned:\n\n* filters owned by the user. * filters shared with a group that the user is a\nmember of. * filters shared with a private project that the user has *Browse\nprojects* [project permission](https://confluence.atlassian.com/x/yodKLg) for.\n* filters shared with a public project. * filters shared with the public.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira filters get-paginated']), formatter_class=RAW)
    c.add_argument('--filter-name', dest='p_filter_name', metavar='FILTER_NAME', help='String used to perform a case-insensitive partial match with `name`.')
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='User account ID used to return filters with the matching `owner.accountId`. This parameter cannot be used with `owner`.')
    c.add_argument('--owner', dest='p_owner', metavar='OWNER', help='This parameter is deprecated because of privacy changes. Use `accountId` instead. See the [migration guide](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details. User name used to return filters with the matching `owner.name`. This parameter cannot be used with `accountId`.')
    c.add_argument('--groupname', dest='p_groupname', metavar='GROUPNAME', help="As a group's name can change, use of `groupId` is recommended to identify a group. Group name used to returns filters that are shared with a group that matches `sharePermissions.group.groupname`. This parameter cannot be used with the `groupId` parameter.")
    c.add_argument('--group-id', dest='p_group_id', metavar='GROUP_ID', help='Group ID used to returns filters that are shared with a group that matches `sharePermissions.group.groupId`. This parameter cannot be used with the `groupname` parameter.')
    c.add_argument('--project-id', dest='p_project_id', type=integer, metavar='PROJECT_ID', help='Project ID used to returns filters that are shared with a project that matches `sharePermissions.project.id`.')
    c.add_argument('--id', dest='p_id', action="append", type=integer, metavar='ID', help='The list of filter IDs. To include multiple IDs, provide an ampersand-separated list. For example, `id=10000&id=10001`. Do not exceed 200 filter IDs.')
    c.add_argument('--order-by', dest='p_order_by', choices=['description', '-description', '+description', 'favourite_count', '-favourite_count', '+favourite_count', 'id', '-id', '+id', 'is_favourite', '-is_favourite', '+is_favourite', 'name', '-name', '+name', 'owner', '-owner', '+owner', 'is_shared', '-is_shared', '+is_shared'], help='[Order](#ordering) the results by a field: (default: name)')
