    c.set_defaults(handler=_run_filters_set, flags={'id': '--id', 'expand': '--expand'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'set_favourite_for_filter'})
    c = g_filters_commands.add_parser('delete-favourite-for', parents=[common], help='Remove filter as favorite', description="Removes a filter as a favorite for the user. Note that this operation only\nremoves filters visible to the user from the user's favorites list. For\nexample, if the user favorites a public filter that is subsequently made\nprivate (and is therefore no longer visible on their favorites list) they\ncannot remove it from their favorites list.\n\n**[Permissions](#permissions) required:** Permission to access Jira.", usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira filters delete-favourite-for ID --dry-run', 'codapact-jira filters delete-favourite-for ID --yes']), formatter_class=RAW)
