    g_group_and_user_picker = commands.add_parser('group-and-user-picker', help='find-users-and-groups', description="Run 'codapact-jira group-and-user-picker COMMAND --help' for a command's options and examples.")
    g_group_and_user_picker_commands = g_group_and_user_picker.add_subparsers(dest="g_group_and_user_picker", metavar="COMMAND", required=True)
    c = g_group_and_user_picker_commands.add_parser('find-users-and-groups', parents=[common], help='Find users and groups', description='Returns a list of users and groups matching a string. The string is used:\n\n* for users, to find a case-insensitive match with display name and e-mail\naddress. Note that if a user has hidden their email address in their user\nprofile, partial matches of the email address will not find the user. An exact\nmatch is required. * for groups, to find a case-sensitive match with group\nname.\n\nFor example, if the string *tin* is used, records with the display name\n*Tina*, email address *sarah@tinplatetraining.com*, and the group *accounting*\nwould be returned.\n\nOptionally, the search can be refined to:\n\n* the projects and issue types associated with a custom field, such as a user\npicker. The search can then be further refined to return only users and groups\nthat have permission to view specific: * projects. * issue types. If multiple\nprojects or issue types are specified, they must be a subset of those enabled\nfor the custom field or no results are returned. For example, if a field is\nenabled for projects A, B, and C then the search could be limited to projects\nB and C. However, if the search is limited to projects B and D, nothing is\nreturned. * not return Connect app users and groups. * return groups that have\na case-insensitive match with the query.\n\nThe primary use case for this resource is to populate a picker field\nsuggestion list with users or groups. To this end, the returned object\nincludes an `html` field for each list. This field highlights the matched\nquery term in the item name with the HTML strong tag. Also, each list is\nwrapped in a response object that contains a header for use in a picker,\nspecifically *Showing X of Y matching groups*.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse users and groups* [global\npermission](https://confluence.atlassian.com/x/yodKLg).', usage='%(prog)s --arg-query ARG_QUERY [options]', epilog=RUNTIME.command_epilog(['codapact-jira group-and-user-picker find-users-and-groups --arg-query ARG_QUERY']), formatter_class=RAW)
    c.add_argument('--arg-query', dest='p_arg_query', metavar='ARG_QUERY', required=True, help='The search string.')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return in each list. (default: 50)')
    c.add_argument('--show-avatar', dest='p_show_avatar', action=argparse.BooleanOptionalAction, help='Whether the user avatar should be returned. If an invalid value is provided, the default value is used. (default: False)')
    c.add_argument('--field-id', dest='p_field_id', metavar='FIELD_ID', help='The custom field ID of the field this request is for.')
    c.add_argument('--project-id', dest='p_project_id', action="append", metavar='PROJECT_ID', help='The ID of a project that returned users and groups must have permission to view. To include multiple projects, provide an ampersand-separated list. For example, `projectId=10000&projectId=10001`. This parameter is only used when `fieldId` is present.')
    c.add_argument('--issue-type-id', dest='p_issue_type_id', action="append", metavar='ISSUE_TYPE_ID', help='The ID of an issue type that returned users and groups must have permission to view. To include multiple issue types, provide an ampersand-separated list. For example, `issueTypeId=10000&issueTypeId=10001`. Special values, such as `-1` (all standard issue types) and `-2` (all subtask issue types), are supported. This parameter is only used when `fieldId` is present.')
    c.add_argument('--avatar-size', dest='p_avatar_size', choices=['xsmall', 'xsmall@2x', 'xsmall@3x', 'small', 'small@2x', 'small@3x', 'medium', 'medium@2x', 'medium@3x', 'large', 'large@2x', 'large@3x', 'xlarge', 'xlarge@2x', 'xlarge@3x', 'xxlarge', 'xxlarge@2x', 'xxlarge@3x', 'xxxlarge', 'xxxlarge@2x', 'xxxlarge@3x'], help='The size of the avatar to return. If an invalid value is provided, the default value is used. (default: xsmall)')
    c.add_argument('--case-insensitive', dest='p_case_insensitive', action=argparse.BooleanOptionalAction, help='Whether the search for groups should be case insensitive. (default: False)')
    c.add_argument('--exclude-connect-addons', dest='p_exclude_connect_addons', action=argparse.BooleanOptionalAction, help='Whether Connect app users and groups should be excluded from the search results. If an invalid value is provided, the default value is used. (default: False)')
    c.add_argument('--include-ai-agents', dest='p_include_ai_agents', action=argparse.BooleanOptionalAction, help='Whether AI Agents should be included in the search results. If an invalid value is provided, the default value is used. (default: False)')
    c.set_defaults(handler=_run_group_and_user_picker_find_users_and_groups, flags={'query': '--arg-query', 'max_results': '--max-results', 'show_avatar': '--show-avatar', 'field_id': '--field-id', 'project_id': '--project-id', 'issue_type_id': '--issue-type-id', 'avatar_size': '--avatar-size', 'case_insensitive': '--case-insensitive', 'exclude_connect_addons': '--exclude-connect-addons', 'include_ai_agents': '--include-ai-agents'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'find_users_and_groups'})
