    c = g_groups_commands.add_parser('bulk', parents=[common], help='Bulk get groups', description='Returns a [paginated](#pagination) list of groups.\n\n**[Permissions](#permissions) required:** *Browse users and groups* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira groups bulk']), formatter_class=RAW)
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.add_argument('--group-id', dest='p_group_id', action="append", metavar='GROUP_ID', help='The ID of a group. To specify multiple IDs, pass multiple `groupId` parameters. For example, `groupId=5b10a2844c20165700ede21g&groupId=5b10ac8d82e05b22cc7d4ef5`.')
    c.add_argument('--group-name', dest='p_group_name', action="append", metavar='GROUP_NAME', help='The name of a group. To specify multiple names, pass multiple `groupName` parameters. For example, `groupName=administrators&groupName=jira-software-users`.')
    c.add_argument('--access-type', dest='p_access_type', metavar='ACCESS_TYPE', help="The access level of a group. Valid values: 'site-admin', 'admin', 'user'.")
    c.add_argument('--application-key', dest='p_application_key', metavar='APPLICATION_KEY', help="The application key of the product user groups to search for. Valid values: 'jira-servicedesk', 'jira-software', 'jira-product-discovery', 'jira-core'.")
    c.set_defaults(handler=_run_groups_bulk, flags={'start_at': '--start-at', 'max_results': '--max-results', 'group_id': '--group-id', 'group_name': '--group-name', 'access_type': '--access-type', 'application_key': '--application-key'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'bulk_get_groups'})
    c = g_groups_commands.add_parser('get-users-from', parents=[common], help='Get users from group', description='Returns a [paginated](#pagination) list of all users in a group.\n\nNote that users are ordered by username, however the username is not returned\nin the results due to privacy reasons.\n\n**[Permissions](#permissions) required:** either of:\n\n* *Browse users and groups* [global\npermission](https://confluence.atlassian.com/x/x4dKLg). * *Administer Jira*\n[global permission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira groups get-users-from']), formatter_class=RAW)
    c.add_argument('--groupname', dest='p_groupname', metavar='GROUPNAME', help="As a group's name can change, use of `groupId` is recommended to identify a group.  ")
    c.add_argument('--group-id', dest='p_group_id', metavar='GROUP_ID', help='The ID of the group. This parameter cannot be used with the `groupName` parameter.')
    c.add_argument('--include-inactive-users', dest='p_include_inactive_users', action=argparse.BooleanOptionalAction, help='Include inactive users. (default: False)')
