    c = g_groups_commands.add_parser('add', parents=[common], help='Add user to group', description='Adds a user to a group.\n\n**[Permissions](#permissions) required:** Site administration (that is, member\nof the *site-admin* [group](https://confluence.atlassian.com/x/24xjL)).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira groups add --account-id ACCOUNT_ID', 'codapact-jira groups add --account-id ACCOUNT_ID --dry-run']), formatter_class=RAW)
    c.add_argument('--groupname', dest='p_groupname', metavar='GROUPNAME', help="As a group's name can change, use of `groupId` is recommended to identify a group.  ")
    c.add_argument('--group-id', dest='p_group_id', metavar='GROUP_ID', help='The ID of the group. This parameter cannot be used with the `groupName` parameter.')
