    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', required=True, help='The account ID of the user, which uniquely identifies the user across all Atlassian products. For example, *5b10ac8d82e05b22cc7d4ef5*.')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_groups_remove_user_from, flags={'groupname': '--groupname', 'group_id': '--group-id', 'username': '--username', 'account_id': '--account-id'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'remove_user_from_group'})
    c = g_groups_commands.add_parser('find', parents=[common], help='Find groups', description='Returns a list of groups whose names contain a query string. A list of group\nnames can be provided to exclude groups from the results.\n\nThe primary use case for this resource is to populate a group picker\nsuggestions list. To this end, the returned object includes the `html` field\nwhere the matched query term is highlighted in the group name with the HTML\nstrong tag. Also, the groups list is wrapped in a response object that\ncontains a header for use in the picker, specifically *Showing X of Y matching\ngroups*.\n\nThe list returns with the groups sorted. If no groups match the list criteria,\nan empty list is returned.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg). Anonymous calls and\ncalls by users without the required permission return an empty list.\n\n*Browse users and groups* [global\npermission](https://confluence.atlassian.com/x/x4dKLg). Without this\npermission, calls where query is not an exact match to an existing group will\nreturn an empty list.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira groups find']), formatter_class=RAW)
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='This parameter is deprecated, setting it does not affect the results. To find groups containing a particular user, use [Get user groups](#api-rest-api-3-user-groups-get).')
    c.add_argument('--arg-query', dest='p_arg_query', metavar='ARG_QUERY', help='The string to find in group names.')
    c.add_argument('--exclude', dest='p_exclude', action="append", metavar='EXCLUDE', help="As a group's name can change, use of `excludeGroupIds` is recommended to identify a group.  ")
    c.add_argument('--exclude-id', dest='p_exclude_id', action="append", metavar='EXCLUDE_ID', help='A group ID to exclude from the result. To exclude multiple groups, provide an ampersand-separated list. For example, `excludeId=group1-id&excludeId=group2-id`. This parameter cannot be used with the `excludeGroups` parameter.')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of groups to return. The maximum number of groups that can be returned is limited by the system property `jira.ajax.autocomplete.limit`.')
    c.add_argument('--case-insensitive', dest='p_case_insensitive', action=argparse.BooleanOptionalAction, help='Whether the search for groups should be case insensitive. (default: False)')
    c.add_argument('--user-name', dest='p_user_name', metavar='USER_NAME', help='This parameter is no longer available. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.set_defaults(handler=_run_groups_find, flags={'account_id': '--account-id', 'query': '--arg-query', 'exclude': '--exclude', 'exclude_id': '--exclude-id', 'max_results': '--max-results', 'case_insensitive': '--case-insensitive', 'user_name': '--user-name'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'find_groups'})
    g_issue_attachments = commands.add_parser('issue-attachments', help='add-attachment, expand-attachment-for-humans, expand-attachment-for-machines, … (8 commands)', description="Run 'codapact-jira issue-attachments COMMAND --help' for a command's options and examples.")
    g_issue_attachments_commands = g_issue_attachments.add_subparsers(dest="g_issue_attachments", metavar="COMMAND", required=True)
    c = g_issue_attachments_commands.add_parser('get-attachment-content', parents=[common], help='Get attachment content', description='Returns the contents of an attachment. A `Range` header can be set to define a\nrange of bytes within the attachment to download. See the [HTTP Range header\nstandard](https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Range) for\ndetails.\n\nTo return a thumbnail of the attachment, use [Get attachment thumbnail](#api-\nrest-api-3-attachment-thumbnail-id-get).\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** For the issue containing the\nattachment:\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * If attachments are added in\nprivate comments, the comment-level restriction will be applied.', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-attachments get-attachment-content ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the attachment.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.add_argument('--redirect', dest='p_redirect', action=argparse.BooleanOptionalAction, help='Whether a redirect is provided for the attachment download. Clients that do not automatically follow redirects can set this to `false` to avoid making multiple requests to download the attachment. (default: True)')
    c.set_defaults(handler=_run_issue_attachments_get_attachment_content, flags={'id': '--id', 'redirect': '--redirect'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_attachment_content'})
    c = g_issue_attachments_commands.add_parser('get-attachment-meta', parents=[common], help='Get Jira attachment settings', description='Returns the attachment settings, that is, whether attachments are enabled and\nthe maximum attachment size allowed.\n\nNote that there are also [project\npermissions](https://confluence.atlassian.com/x/yodKLg) that restrict whether\nusers can create and delete attachments.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-attachments get-attachment-meta']), formatter_class=RAW)
    c.set_defaults(handler=_run_issue_attachments_get_attachment_meta, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_attachment_meta'})
    c = g_issue_attachments_commands.add_parser('get-attachment-thumbnail', parents=[common], help='Get attachment thumbnail', description='Returns the thumbnail of an attachment.\n\nTo return the attachment contents, use [Get attachment content](#api-rest-\napi-3-attachment-content-id-get).\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** For the issue containing the\nattachment:\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * If attachments are added in\nprivate comments, the comment-level restriction will be applied.', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-attachments get-attachment-thumbnail ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the attachment.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.add_argument('--redirect', dest='p_redirect', action=argparse.BooleanOptionalAction, help='Whether a redirect is provided for the attachment download. Clients that do not automatically follow redirects can set this to `false` to avoid making multiple requests to download the attachment. (default: True)')
    c.add_argument('--fallback-to-default', dest='p_fallback_to_default', action=argparse.BooleanOptionalAction, help='Whether a default thumbnail is returned when the requested thumbnail is not found. (default: True)')
    c.add_argument('--width', dest='p_width', type=integer, metavar='WIDTH', help='The maximum width to scale the thumbnail to.')
    c.add_argument('--height', dest='p_height', type=integer, metavar='HEIGHT', help='The maximum height to scale the thumbnail to.')
    c.set_defaults(handler=_run_issue_attachments_get_attachment_thumbnail, flags={'id': '--id', 'redirect': '--redirect', 'fallback_to_default': '--fallback-to-default', 'width': '--width', 'height': '--height'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_attachment_thumbnail'})
    c = g_issue_attachments_commands.add_parser('get-attachment', parents=[common], help='Get attachment metadata', description='Returns the metadata for an attachment. Note that the attachment itself is not\nreturned.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * If attachments are added in\nprivate comments, the comment-level restriction will be applied.', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-attachments get-attachment ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the attachment.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.set_defaults(handler=_run_issue_attachments_get_attachment, flags={'id': '--id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_attachment'})
    c = g_issue_attachments_commands.add_parser('remove-attachment', parents=[common], help='Delete attachment', description='Deletes an attachment from an issue.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** For the project holding the issue\ncontaining the attachment:\n\n* *Delete own attachments* [project\npermission](https://confluence.atlassian.com/x/yodKLg) to delete an attachment\ncreated by the calling user. * *Delete all attachments* [project\npermission](https://confluence.atlassian.com/x/yodKLg) to delete an attachment\ncreated by any user.', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-attachments remove-attachment ID --dry-run', 'codapact-jira issue-attachments remove-attachment ID --yes']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the attachment.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_issue_attachments_remove_attachment, flags={'id': '--id'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'remove_attachment'})
    c = g_issue_attachments_commands.add_parser('expand-attachment-for-humans', parents=[common], help='Get all metadata for an expanded attachment', description="Returns the metadata for the contents of an attachment, if it is an archive,\nand metadata for the attachment itself. For example, if the attachment is a\nZIP archive, then information about the files in the archive is returned and\nmetadata for the ZIP archive. Currently, only the ZIP archive format is\nsupported.\n\nUse this operation to retrieve data that is presented to the user, as this\noperation returns the metadata for the attachment itself, such as the\nattachment's ID and name. Otherwise, use [ Get contents metadata for an\nexpanded attachment](#api-rest-api-3-attachment-id-expand-raw-get), which only\nreturns the metadata for the attachment's contents.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** For the issue containing the\nattachment:\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * If attachments are added in\nprivate comments, the comment-level restriction will be applied.", usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-attachments expand-attachment-for-humans ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the attachment.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.set_defaults(handler=_run_issue_attachments_expand_attachment_for_humans, flags={'id': '--id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'expand_attachment_for_humans'})
    c = g_issue_attachments_commands.add_parser('expand-attachment-for-machines', parents=[common], help='Get contents metadata for an expanded attachment', description="Returns the metadata for the contents of an attachment, if it is an archive.\nFor example, if the attachment is a ZIP archive, then information about the\nfiles in the archive is returned. Currently, only the ZIP archive format is\nsupported.\n\nUse this operation if you are processing the data without presenting it to the\nuser, as this operation only returns the metadata for the contents of the\nattachment. Otherwise, to retrieve data to present to the user, use [ Get all\nmetadata for an expanded attachment](#api-rest-api-3-attachment-id-expand-\nhuman-get) which also returns the metadata for the attachment itself, such as\nthe attachment's ID and name.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** For the issue containing the\nattachment:\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * If attachments are added in\nprivate comments, the comment-level restriction will be applied.", usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-attachments expand-attachment-for-machines ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the attachment.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.set_defaults(handler=_run_issue_attachments_expand_attachment_for_machines, flags={'id': '--id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'expand_attachment_for_machines'})
    c = g_issue_attachments_commands.add_parser('add-attachment', parents=[common], help='Add attachment', description='Adds one or more attachments to an issue. Attachments are posted as\nmultipart/form-data ([RFC 1867](https://www.ietf.org/rfc/rfc1867.txt)).\n\nNote that:\n\n* The request must have a `X-Atlassian-Token: no-check` header, if not it is\nblocked. See [Special headers](#special-request-headers) for more information.\n* The name of the multipart/form-data parameter that contains the attachments\nmust be `file`.\n\nThe following examples upload a file called *myfile.txt* to the issue\n*TEST-123*:\n\n#### curl ####\n\ncurl --location --request POST \'https://your-\ndomain.atlassian.net/rest/api/3/issue/TEST-123/attachments\' -u\n\'email@example.com:<api_token>\' -H \'X-Atlassian-Token: no-check\' --form\n\'file=@"myfile.txt"\'\n\n#### Node.js ####\n\n// This code sample uses the \'node-fetch\' and \'form-data\' libraries: //\nhttps://www.npmjs.com/package/node-fetch //\nhttps://www.npmjs.com/package/form-data const fetch = require(\'node-fetch\');\nconst FormData = require(\'form-data\'); const fs = require(\'fs\'); const\nfilePath = \'myfile.txt\'; const form = new FormData(); const stats =\nfs.statSync(filePath); const fileSizeInBytes = stats.size; const fileStream =\nfs.createReadStream(filePath); form.append(\'file\', fileStream, {knownLength:\nfileSizeInBytes}); fetch(\'https://your-\ndomain.atlassian.net/rest/api/3/issue/TEST-123/attachments\', { method: \'POST\',\nbody: form, headers: { \'Authorization\': `Basic ${Buffer.from(\n\'email@example.com:\' ).toString(\'base64\')}`, \'Accept\': \'application/json\',\n\'X-Atlassian-Token\': \'no-check\' } }) .then(response => { console.log(\n`Response: ${response.status} ${response.statusText}` ); return\nresponse.text(); }) .then(text => console.log(text)) .catch(err =>\nconsole.error(err));\n\n#### Java ####\n\n// This code sample uses the \'Unirest\' library: // http://unirest.io/java.html\nHttpResponse response = Unirest.post("https://your-\ndomain.atlassian.net/rest/api/2/issue/{issueIdOrKey}/attachments")\n.basicAuth("email@example.com", "") .header("Accept", "application/json")\n.header("X-Atlassian-Token", "no-check") .field("file", new\nFile("myfile.txt")) .asJson(); System.out.println(response.getBody());\n\n#### Python ####\n\n# This code sample uses the \'requests\' library: # http://docs.python-\nrequests.org import requests from requests.auth import HTTPBasicAuth import\njson url = "https://your-\ndomain.atlassian.net/rest/api/2/issue/{issueIdOrKey}/attachments" auth =\nHTTPBasicAuth("email@example.com", "") headers = { "Accept":\n"application/json", "X-Atlassian-Token": "no-check" } response =\nrequests.request( "POST", url, headers = headers, auth = auth, files = {\n"file": ("myfile.txt", open("myfile.txt","rb"), "application-type") } )\nprint(json.dumps(json.loads(response.text), sort_keys=True, indent=4,\nseparators=(",", ": ")))\n\n#### PHP ####\n\n// This code sample uses the \'Unirest\' library: // http://unirest.io/php.html\nUnirest\\Request::auth(\'email@example.com\', \'\'); $headers = array( \'Accept\' =>\n\'application/json\', \'X-Atlassian-Token\' => \'no-check\' ); $parameters = array(\n\'file\' => File::add(\'myfile.txt\') ); $response = Unirest\\Request::post(\n\'https://your-\ndomain.atlassian.net/rest/api/2/issue/{issueIdOrKey}/attachments\', $headers,\n$parameters ); var_dump($response)\n\n#### Forge ####\n\n// This sample uses Atlassian Forge and the `form-data` library. //\nhttps://developer.atlassian.com/platform/forge/ //\nhttps://www.npmjs.com/package/form-data import api from "@forge/api"; import\nFormData from "form-data"; const form = new FormData(); form.append(\'file\',\nfileStream, {knownLength: fileSizeInBytes}); const response = await\napi.asApp().requestJira(\'/rest/api/2/issue/{issueIdOrKey}/attachments\', {\nmethod: \'POST\', body: form, headers: { \'Accept\': \'application/json\',\n\'X-Atlassian-Token\': \'no-check\' } }); console.log(`Response:\n${response.status} ${response.statusText}`); console.log(await\nresponse.json());\n\nTip: Use a client library. Many client libraries have classes for handling\nmultipart POST operations. For example, in Java, the Apache HTTP Components\nlibrary provides a [MultiPartEntity](http://hc.apache.org/httpcomponents-\nclient-ga/httpmime/apidocs/org/apache/http/entity/mime/MultipartEntity.html)\nclass for multipart POST operations.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse Projects* and *Create attachments* [ project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s ISSUE_ID_OR_KEY --body BODY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-attachments add-attachment ISSUE_ID_OR_KEY --body BODY', 'codapact-jira issue-attachments add-attachment ISSUE_ID_OR_KEY --body BODY --dry-run']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue that attachments are added to.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--body', dest='p_body', action="append", type=binary_value, metavar='BODY', required=True)
    c.set_defaults(handler=_run_issue_attachments_add_attachment, flags={'issue_id_or_key': '--issue-id-or-key', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'add_attachment'})
    g_issue_bulk_operations = commands.add_parser('issue-bulk-operations', help='get-bulk-operation-progress, list-available-transitions, list-bulk-editable-fields, … (9 commands)', description="Run 'codapact-jira issue-bulk-operations COMMAND --help' for a command's options and examples.")
    g_issue_bulk_operations_commands = g_issue_bulk_operations.add_subparsers(dest="g_issue_bulk_operations", metavar="COMMAND", required=True)
    c = g_issue_bulk_operations_commands.add_parser('submit-bulk-delete', parents=[common], help='Bulk delete issues', description='Use this API to submit a bulk delete request. You can delete up to 1,000\nissues in a single operation.\n\n**[Permissions](#permissions) required:**\n\n* Global bulk change [permission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-global-permissions/). * Delete [issues\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/permissions-for-company-managed-projects/#Delete-issues/)\nin all projects that contain the selected issues. * Browse [project\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-permissions/) in all projects that contain\nthe selected issues. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s --selected-issue-ids-or-keys SELECTED_ISSUE_IDS_OR_KEYS [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-bulk-operations submit-bulk-delete --selected-issue-ids-or-keys SELECTED_ISSUE_IDS_OR_KEYS', 'codapact-jira issue-bulk-operations submit-bulk-delete --selected-issue-ids-or-keys SELECTED_ISSUE_IDS_OR_KEYS --dry-run']), formatter_class=RAW)
    c.add_argument('--selected-issue-ids-or-keys', dest='p_selected_issue_ids_or_keys', action="append", metavar='SELECTED_ISSUE_IDS_OR_KEYS', required=True, help='List of issue IDs or keys which are to be bulk deleted. These IDs or keys can be from different projects and issue types.')
    c.add_argument('--send-bulk-notification', dest='p_send_bulk_notification', action=argparse.BooleanOptionalAction, help='A boolean value that indicates whether to send a bulk change notification when the issues are being deleted. (default: True)')
    c.set_defaults(handler=_run_issue_bulk_operations_submit_bulk_delete, flags={'body.selected_issue_ids_or_keys': '--selected-issue-ids-or-keys', 'body.send_bulk_notification': '--send-bulk-notification'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'submit_bulk_delete'})
    c = g_issue_bulk_operations_commands.add_parser('list-bulk-editable-fields', parents=[common], help='Get bulk editable fields', description='Use this API to get a list of fields visible to the user to perform bulk edit\noperations. You can pass single or multiple issues in the query to get\neligible editable fields. This API uses pagination to return responses,\ndelivering 50 fields at a time.\n\n**[Permissions](#permissions) required:**\n\n* Global bulk change [permission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-global-permissions/). * Browse [project\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-permissions/) in all projects that contain\nthe selected issues. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * Depending on the field, any\nfield-specific permissions required to edit it.', usage='%(prog)s --issue-ids-or-keys ISSUE_IDS_OR_KEYS [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-bulk-operations list-bulk-editable-fields --issue-ids-or-keys ISSUE_IDS_OR_KEYS']), formatter_class=RAW)
    c.add_argument('--issue-ids-or-keys', dest='p_issue_ids_or_keys', metavar='ISSUE_IDS_OR_KEYS', required=True, help='The IDs or keys of the issues to get editable fields from.')
    c.add_argument('--search-text', dest='p_search_text', metavar='SEARCH_TEXT', help='(Optional)The text to search for in the editable fields.')
    c.add_argument('--ending-before', dest='p_ending_before', metavar='ENDING_BEFORE', help='(Optional)The end cursor for use in pagination.')
    c.add_argument('--starting-after', dest='p_starting_after', metavar='STARTING_AFTER', help='(Optional)The start cursor for use in pagination.')
    c.set_defaults(handler=_run_issue_bulk_operations_list_bulk_editable_fields, flags={'issue_ids_or_keys': '--issue-ids-or-keys', 'search_text': '--search-text', 'ending_before': '--ending-before', 'starting_after': '--starting-after'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_bulk_editable_fields'})
    c = g_issue_bulk_operations_commands.add_parser('submit-bulk-edit', parents=[common], help='Bulk edit issues', description='Use this API to submit a bulk edit request and simultaneously edit multiple\nissues. There are limits applied to the number of issues and fields that can\nbe edited. A single request can accommodate a maximum of 1000 issues\n(including subtasks) and 200 fields.\n\n**[Permissions](#permissions) required:**\n\n* Global bulk change [permission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-global-permissions/). * Browse [project\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-permissions/) in all projects that contain\nthe selected issues. * Edit [issues\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-permissions/) in all projects that contain\nthe selected issues. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s --edited-fields-input @edited-fields-input.json --selected-actions SELECTED_ACTIONS --selected-issue-ids-or-keys SELECTED_ISSUE_IDS_OR_KEYS [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-bulk-operations submit-bulk-edit --edited-fields-input @edited-fields-input.json --selected-actions SELECTED_ACTIONS --selected-issue-ids-or-keys SELECTED_ISSUE_IDS_OR_KEYS', 'codapact-jira issue-bulk-operations submit-bulk-edit --edited-fields-input @edited-fields-input.json --selected-actions SELECTED_ACTIONS --selected-issue-ids-or-keys SELECTED_ISSUE_IDS_OR_KEYS --dry-run']), formatter_class=RAW)
    c.add_argument('--edited-fields-input', dest='p_edited_fields_input', type=json_value, metavar="JSON", required=True, help='An object that defines the values to be updated in specified fields of an issue. The structure and content of this parameter vary depending on the type of field being edited. Although the order is not significant, ensure that field IDs align with those in selectedActions. JSON object with cascading_select_fields, clearable_number_fields, color_fields, date_picker_fields, date_time_picker_fields, issue_type, labels_fields, multiple_group_picker_fields, multiple_select_clearable_user_picker_fields, multiple_select_fields, multiple_version_picker_fields, multiselect_components, ... Schema: codapact-jira describe issue-bulk-operations submit-bulk-edit')
    c.add_argument('--selected-actions', dest='p_selected_actions', action="append", metavar='SELECTED_ACTIONS', required=True, help='List of all the field IDs that are to be bulk edited. Each field ID in this list corresponds to a specific attribute of an issue that is set to be modified in the bulk edit operation. The relevant field ID can be obtained by calling the Bulk Edit Get Fields REST API (documentation available on this page itself).')
    c.add_argument('--selected-issue-ids-or-keys', dest='p_selected_issue_ids_or_keys', action="append", metavar='SELECTED_ISSUE_IDS_OR_KEYS', required=True, help='List of issue IDs or keys which are to be bulk edited. These IDs or keys can be from different projects and issue types.')
    c.add_argument('--send-bulk-notification', dest='p_send_bulk_notification', action=argparse.BooleanOptionalAction, help='A boolean value that indicates whether to send a bulk change notification when the issues are being edited. (default: True)')
    c.set_defaults(handler=_run_issue_bulk_operations_submit_bulk_edit, flags={'body.edited_fields_input': '--edited-fields-input', 'body.selected_actions': '--selected-actions', 'body.selected_issue_ids_or_keys': '--selected-issue-ids-or-keys', 'body.send_bulk_notification': '--send-bulk-notification'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'submit_bulk_edit'})
    c = g_issue_bulk_operations_commands.add_parser('submit-bulk-move', parents=[common], help='Bulk move issues', description="Use this API to submit a bulk issue move request. You can move multiple issues\nfrom multiple projects in a single request, but they must all be moved to a\nsingle project, issue type, and parent. You can't move more than 1000 issues\n(including subtasks) at once.\n\n#### Scenarios: ####\n\nThis is an early version of the API and it doesn't have full feature parity\nwith the Bulk Move UI experience.\n\n* Moving issue of type A to issue of type B in the same project or a different\nproject: `SUPPORTED` * Moving multiple issues of type A in one or more\nprojects to multiple issues of type B in one of the source projects or a\ndifferent project: `SUPPORTED` * Moving issues of multiple issue types in one\nor more projects to issues of a single issue type in one of the source project\nor a different project: **`SUPPORTED`** E.g. Moving issues of story and task\nissue types in project 1 and project 2 to issues of task issue type in project\n3 * Moving a standard parent issue of type A with its multiple subtask issue\ntypes in one project to standard issue of type B and multiple subtask issue\ntypes in the same project or a different project: `SUPPORTED` * Moving\nstandard issues with their subtasks to a parent issue in the same project or a\ndifferent project without losing their relation: `SUPPORTED` * Moving an epic\nissue with its child issues to a different project without losing their\nrelation: `SUPPORTED` This usecase is **supported using multiple requests**.\nMove the epic in one request and then move the children in a separate request\nwith target parent set to the epic issue id (Alternatively, move them\nindividually and stitch the relationship back with the Bulk Edit API)\n\n#### Limits applied to bulk issue moves: ####\n\nWhen using the bulk move, keep in mind that there are limits on the number of\nissues and fields you can include.\n\n* You can move up to 1,000 issues in a single operation, including any\nsubtasks. * The total combined number of fields across all issues must not\nexceed 1,500,000. For example, if each issue includes 15,000 fields, then the\nmaximum number of issues that can be moved is 100.\n\n**[Permissions](#permissions) required:**\n\n* Global bulk change [permission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-global-permissions/). * Move [issues\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-permissions/) in source projects. * Create\n[issues permission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-permissions/) in destination projects. *\nBrowse [project permission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-permissions/) in destination projects, if\nmoving subtasks only. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-bulk-operations submit-bulk-move --send-bulk-notification SEND_BULK_NOTIFICATION', 'codapact-jira issue-bulk-operations submit-bulk-move --send-bulk-notification SEND_BULK_NOTIFICATION --dry-run']), formatter_class=RAW)
    c.add_argument('--send-bulk-notification', dest='p_send_bulk_notification', action=argparse.BooleanOptionalAction, help='A boolean value that indicates whether to send a bulk change notification when the issues are being moved. (default: True)')
    c.add_argument('--target-to-sources-mapping', dest='p_target_to_sources_mapping', type=json_value, metavar="JSON", help='An object representing the mapping of issues and data related to destination entities, like fields and statuses, that are required during a bulk move.')
    c.set_defaults(handler=_run_issue_bulk_operations_submit_bulk_move, flags={'body.send_bulk_notification': '--send-bulk-notification', 'body.target_to_sources_mapping': '--target-to-sources-mapping'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'submit_bulk_move', 'requires_one_of': [['--send-bulk-notification', '--target-to-sources-mapping']]})
    c = g_issue_bulk_operations_commands.add_parser('list-available-transitions', parents=[common], help='Get available transitions', description='Use this API to retrieve a list of transitions available for the specified\nissues that can be used or bulk transition operations. You can submit either\nsingle or multiple issues in the query to obtain the available transitions.\n\nThe response will provide the available transitions for issues, organized by\ntheir respective workflows. **Only the transitions that are common among the\nissues within that workflow and do not involve any additional field updates\nwill be included.** For bulk transitions that require additional field\nupdates, please utilise the Jira Cloud UI.\n\nYou can request available transitions for up to 1,000 issues in a single\noperation. This API uses pagination to return responses, delivering 50\nworkflows at a time.\n\n**[Permissions](#permissions) required:**\n\n* Global bulk change [permission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-global-permissions/). * Transition [issues\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/permissions-for-company-managed-projects/#Transition-\nissues/) in all projects that contain the selected issues. * Browse [project\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-permissions/) in all projects that contain\nthe selected issues. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s --issue-ids-or-keys ISSUE_IDS_OR_KEYS [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-bulk-operations list-available-transitions --issue-ids-or-keys ISSUE_IDS_OR_KEYS']), formatter_class=RAW)
    c.add_argument('--issue-ids-or-keys', dest='p_issue_ids_or_keys', metavar='ISSUE_IDS_OR_KEYS', required=True, help='Comma (,) separated Ids or keys of the issues to get transitions available for them.')
    c.add_argument('--ending-before', dest='p_ending_before', metavar='ENDING_BEFORE', help='(Optional)The end cursor for use in pagination.')
    c.add_argument('--starting-after', dest='p_starting_after', metavar='STARTING_AFTER', help='(Optional)The start cursor for use in pagination.')
    c.set_defaults(handler=_run_issue_bulk_operations_list_available_transitions, flags={'issue_ids_or_keys': '--issue-ids-or-keys', 'ending_before': '--ending-before', 'starting_after': '--starting-after'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_available_transitions'})
    c = g_issue_bulk_operations_commands.add_parser('submit-bulk-transition', parents=[common], help='Bulk transition issue statuses', description='Use this API to submit a bulk issue status transition request. You can\ntransition multiple issues, alongside with their valid transition Ids. You can\ntransition up to 1,000 issues in a single operation.\n\n**[Permissions](#permissions) required:**\n\n* Global bulk change [permission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-global-permissions/). * Transition [issues\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/permissions-for-company-managed-projects/#Transition-\nissues/) in all projects that contain the selected issues. * Browse [project\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-permissions/) in all projects that contain\nthe selected issues. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s --bulk-transition-inputs @bulk-transition-inputs.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-bulk-operations submit-bulk-transition --bulk-transition-inputs @bulk-transition-inputs.json', 'codapact-jira issue-bulk-operations submit-bulk-transition --bulk-transition-inputs @bulk-transition-inputs.json --dry-run']), formatter_class=RAW)
    c.add_argument('--bulk-transition-inputs', dest='p_bulk_transition_inputs', type=json_value, metavar="JSON", required=True, help='List of objects and each object has two properties: JSON array of objects with selected_issue_ids_or_keys*, transition_id* (* required). Schema: codapact-jira describe issue-bulk-operations submit-bulk-transition')
    c.add_argument('--send-bulk-notification', dest='p_send_bulk_notification', action=argparse.BooleanOptionalAction, help='A boolean value that indicates whether to send a bulk change notification when the issues are being transitioned. (default: True)')
    c.set_defaults(handler=_run_issue_bulk_operations_submit_bulk_transition, flags={'body.bulk_transition_inputs': '--bulk-transition-inputs', 'body.send_bulk_notification': '--send-bulk-notification'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'submit_bulk_transition'})
    c = g_issue_bulk_operations_commands.add_parser('submit-bulk-unwatch', parents=[common], help='Bulk unwatch issues', description='Use this API to submit a bulk unwatch request. You can unwatch up to 1,000\nissues in a single operation.\n\n**[Permissions](#permissions) required:**\n\n* Global bulk change [permission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-global-permissions/). * Browse [project\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-permissions/) in all projects that contain\nthe selected issues. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s --selected-issue-ids-or-keys SELECTED_ISSUE_IDS_OR_KEYS [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-bulk-operations submit-bulk-unwatch --selected-issue-ids-or-keys SELECTED_ISSUE_IDS_OR_KEYS', 'codapact-jira issue-bulk-operations submit-bulk-unwatch --selected-issue-ids-or-keys SELECTED_ISSUE_IDS_OR_KEYS --dry-run']), formatter_class=RAW)
    c.add_argument('--selected-issue-ids-or-keys', dest='p_selected_issue_ids_or_keys', action="append", metavar='SELECTED_ISSUE_IDS_OR_KEYS', required=True, help='List of issue IDs or keys which are to be bulk watched or unwatched. These IDs or keys can be from different projects and issue types.')
    c.set_defaults(handler=_run_issue_bulk_operations_submit_bulk_unwatch, flags={'body.selected_issue_ids_or_keys': '--selected-issue-ids-or-keys'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'submit_bulk_unwatch'})
    c = g_issue_bulk_operations_commands.add_parser('submit-bulk-watch', parents=[common], help='Bulk watch issues', description='Use this API to submit a bulk watch request. You can watch up to 1,000 issues\nin a single operation.\n\n**[Permissions](#permissions) required:**\n\n* Global bulk change [permission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-global-permissions/). * Browse [project\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-permissions/) in all projects that contain\nthe selected issues. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s --selected-issue-ids-or-keys SELECTED_ISSUE_IDS_OR_KEYS [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-bulk-operations submit-bulk-watch --selected-issue-ids-or-keys SELECTED_ISSUE_IDS_OR_KEYS', 'codapact-jira issue-bulk-operations submit-bulk-watch --selected-issue-ids-or-keys SELECTED_ISSUE_IDS_OR_KEYS --dry-run']), formatter_class=RAW)
    c.add_argument('--selected-issue-ids-or-keys', dest='p_selected_issue_ids_or_keys', action="append", metavar='SELECTED_ISSUE_IDS_OR_KEYS', required=True, help='List of issue IDs or keys which are to be bulk watched or unwatched. These IDs or keys can be from different projects and issue types.')
    c.set_defaults(handler=_run_issue_bulk_operations_submit_bulk_watch, flags={'body.selected_issue_ids_or_keys': '--selected-issue-ids-or-keys'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'submit_bulk_watch'})
    c = g_issue_bulk_operations_commands.add_parser('get-bulk-operation-progress', parents=[common], help='Get bulk issue operation progress', description='Use this to get the progress state for the specified bulk operation `taskId`.\n\n**[Permissions](#permissions) required:**\n\n* Global bulk change [permission](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-global-permissions/).\n\nIf the task is running, this resource will return:\n\n{"taskId":"10779","status":"RUNNING","progressPercent":65,"submittedBy":{"acco\nuntId":"5b10a2844c20165700ede21g"},"created":1690180055963,"started":169018005\n6206,"updated":169018005829}\n\nIf the task has completed, then this resource will return:\n\n{"processedAccessibleIssues":[10001,10002],"created":1709189449954,"progressPe\nrcent":100,"started":1709189450154,"status":"COMPLETE","submittedBy":{"account\nId":"5b10a2844c20165700ede21g"},"invalidOrInaccessibleIssueCount":0,"taskId":"\n10000","totalIssueCount":2,"updated":1709189450354}\n\n**Note:** You can view task progress for up to 14 days from creation.', usage='%(prog)s TASK_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-bulk-operations get-bulk-operation-progress TASK_ID']), formatter_class=RAW)
    c.add_argument('p_task_id', metavar='TASK_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the task.')
    c.add_argument('--task-id', dest='p_task_id', default=argparse.SUPPRESS, metavar='TASK_ID', help='same as TASK_ID')
    c.set_defaults(handler=_run_issue_bulk_operations_get_bulk_operation_progress, flags={'task_id': '--task-id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_bulk_operation_progress'})
    g_issue_comment_properties = commands.add_parser('issue-comment-properties', help='delete-comment-property, get-comment-property, list-comment-property-keys, set-comment-property', description="Run 'codapact-jira issue-comment-properties COMMAND --help' for a command's options and examples.")
