    c.set_defaults(handler=_run_issue_comment_properties_list_comment_property_keys, flags={'comment_id': '--comment-id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_comment_property_keys'})
    c = g_issue_comment_properties_commands.add_parser('get-comment-property', parents=[common], help='Get comment property', description='Returns the value of a comment property.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project. * If\n[issue-level security](https://confluence.atlassian.com/x/J4lKLg) is\nconfigured, issue-level security permission to view the issue. * If the\ncomment has visibility restrictions, belongs to the group or has the role\nvisibility is restricted to.', usage='%(prog)s COMMENT_ID PROPERTY_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-comment-properties get-comment-property COMMENT_ID PROPERTY_KEY']), formatter_class=RAW)
    c.add_argument('p_comment_id', metavar='COMMENT_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the comment.')
    c.add_argument('p_property_key', metavar='PROPERTY_KEY', nargs='?', default=argparse.SUPPRESS, help='The key of the property.')
    c.add_argument('--comment-id', dest='p_comment_id', default=argparse.SUPPRESS, metavar='COMMENT_ID', help='same as COMMENT_ID')
    c.add_argument('--property-key', dest='p_property_key', default=argparse.SUPPRESS, metavar='PROPERTY_KEY', help='same as PROPERTY_KEY')
    c.set_defaults(handler=_run_issue_comment_properties_get_comment_property, flags={'comment_id': '--comment-id', 'property_key': '--property-key'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_comment_property'})
    c = g_issue_comment_properties_commands.add_parser('set-comment-property', parents=[common], help='Set comment property', description='Creates or updates the value of a property for a comment. Use this resource to\nstore custom data against a comment.\n\nThe value of the request body must be a\n[valid](http://tools.ietf.org/html/rfc4627), non-empty JSON blob. The maximum\nlength is 32768 characters.\n\n**[Permissions](#permissions) required:** either of:\n\n* *Edit All Comments* [project\npermission](https://confluence.atlassian.com/x/yodKLg) to create or update the\nvalue of a property on any comment. * *Edit Own Comments* [project\npermission](https://confluence.atlassian.com/x/yodKLg) to create or update the\nvalue of a property on a comment created by the user.', usage='%(prog)s COMMENT_ID PROPERTY_KEY --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-comment-properties set-comment-property COMMENT_ID PROPERTY_KEY --body @body.json', 'codapact-jira issue-comment-properties set-comment-property COMMENT_ID PROPERTY_KEY --body @body.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_comment_id', metavar='COMMENT_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the comment.')
    c.add_argument('p_property_key', metavar='PROPERTY_KEY', nargs='?', default=argparse.SUPPRESS, help='The key of the property. The maximum length is 255 characters.')
    c.add_argument('--comment-id', dest='p_comment_id', default=argparse.SUPPRESS, metavar='COMMENT_ID', help='same as COMMENT_ID')
    c.add_argument('--property-key', dest='p_property_key', default=argparse.SUPPRESS, metavar='PROPERTY_KEY', help='same as PROPERTY_KEY')
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='The value of the property. The value has to be a valid, non-empty [JSON](https://tools.ietf.org/html/rfc4627) value. The maximum length of the property value is 32768 bytes.')
    c.set_defaults(handler=_run_issue_comment_properties_set_comment_property, flags={'comment_id': '--comment-id', 'property_key': '--property-key', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'set_comment_property'})
    c = g_issue_comment_properties_commands.add_parser('delete-comment-property', parents=[common], help='Delete comment property', description='Deletes a comment property.\n\n**[Permissions](#permissions) required:** either of:\n\n* *Edit All Comments* [project\npermission](https://confluence.atlassian.com/x/yodKLg) to delete a property\nfrom any comment. * *Edit Own Comments* [project\npermission](https://confluence.atlassian.com/x/yodKLg) to delete a property\nfrom a comment created by the user.', usage='%(prog)s COMMENT_ID PROPERTY_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-comment-properties delete-comment-property COMMENT_ID PROPERTY_KEY --dry-run', 'codapact-jira issue-comment-properties delete-comment-property COMMENT_ID PROPERTY_KEY --yes']), formatter_class=RAW)
    c.add_argument('p_comment_id', metavar='COMMENT_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the comment.')
    c.add_argument('p_property_key', metavar='PROPERTY_KEY', nargs='?', default=argparse.SUPPRESS, help='The key of the property.')
