    c.set_defaults(handler=_run_issue_comments_list_comments, flags={'issue_id_or_key': '--issue-id-or-key', 'start_at': '--start-at', 'max_results': '--max-results', 'order_by': '--order-by', 'expand': '--expand'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_comments'})
    c = g_issue_comments_commands.add_parser('add-comment', parents=[common], help='Add comment', description='Adds a comment to an issue.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* and *Add comments* [ project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue containing the comment is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s ISSUE_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-comments add-comment ISSUE_ID_OR_KEY --author @author.json', 'codapact-jira issue-comments add-comment ISSUE_ID_OR_KEY --author @author.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about comments in the response. This parameter accepts `renderedBody`, which returns the comment body rendered in HTML.')
    c.add_argument('--author', dest='p_author', type=json_value, metavar="JSON", help='The ID of the user who created the comment. JSON object with account_id, account_type, active, avatar_urls, display_name, email_address, key, name, self, time_zone. Schema: codapact-jira describe issue-comments add-comment')
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", help='The comment text in [Atlassian Document Format](https://developer.atlassian.com/cloud/jira/platform/apis/document/structure/).')
    c.add_argument('--created', dest='p_created', metavar='DATETIME', help='The date and time at which the comment was created.')
    c.add_argument('--id', dest='p_id', metavar='ID', help='The ID of the comment.')
    c.add_argument('--jsd-author-can-see-request', dest='p_jsd_author_can_see_request', action=argparse.BooleanOptionalAction, help='Whether the comment was added from an email sent by a person who is not part of the issue. See [Allow external emails to be added as comments on issues](https://support.atlassian.com/jira-service-management-cloud/docs/allow-external-emails-to-be-added-as-comments-on-issues/)for information on setting up this feature.')
    c.add_argument('--jsd-public', dest='p_jsd_public', action=argparse.BooleanOptionalAction, help="Whether the comment is visible in Jira Service Desk. Defaults to true when comments are created in the Jira Cloud Platform. This includes when the site doesn't use Jira Service Desk or the project isn't a Jira Service Desk project and, therefore, there is no Jira Service Desk for the issue to be visible on. To create a comment with its visibility in Jira Service Desk set to false, use the Jira Service Desk REST API [Create request comment](https://developer.atlassian.com/cloud/jira/service-desk/rest/#api-rest-servicedeskapi-request-issueIdOrKey-comment-post) operation.")
    c.add_argument('--properties', dest='p_properties', type=json_value, metavar="JSON", help='A list of comment properties. Optional on create and update. JSON array of objects with key, value. Schema: codapact-jira describe issue-comments add-comment')
    c.add_argument('--rendered-body', dest='p_rendered_body', metavar='RENDERED_BODY', help='The rendered version of the comment.')
    c.add_argument('--self', dest='p_self', metavar='SELF', help='The URL of the comment.')
    c.add_argument('--update-author', dest='p_update_author', type=json_value, metavar="JSON", help='The ID of the user who updated the comment last. JSON object with account_id, account_type, active, avatar_urls, display_name, email_address, key, name, self, time_zone. Schema: codapact-jira describe issue-comments add-comment')
    c.add_argument('--updated', dest='p_updated', metavar='DATETIME', help='The date and time at which the comment was updated last.')
    c.add_argument('--visibility', dest='p_visibility', type=json_value, metavar="JSON", help='The group or role to which this comment is visible. Optional on create and update. JSON object with identifier, type, value. Schema: codapact-jira describe issue-comments add-comment')
