    c = g_issue_comments_commands.add_parser('update-comment', parents=[common], help='Update comment', description="Updates a comment.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue containing the comment is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * *Edit all comments*[ project\npermission](https://confluence.atlassian.com/x/yodKLg) to update any comment\nor *Edit own comments* to update comment created by the user. * If the comment\nhas visibility restrictions, the user belongs to the group or has the role\nvisibility is restricted to.\n\n**WARNING:** Child comments inherit visibility from their parent comment.\nAttempting to update a child comment's visibility will result in a 400 (Bad\nRequest) error.", usage='%(prog)s ISSUE_ID_OR_KEY ID --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-comments update-comment ISSUE_ID_OR_KEY ID --body @body.json', 'codapact-jira issue-comments update-comment ISSUE_ID_OR_KEY ID --body @body.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the comment.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
