    c.add_argument('--override-editable-flag', dest='p_override_editable_flag', action=argparse.BooleanOptionalAction, help='Whether screen security is overridden to enable uneditable fields to be edited. Available to Connect app users with the *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg) and Forge apps acting on behalf of users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg). (default: False)')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about comments in the response. This parameter accepts `renderedBody`, which returns the comment body rendered in HTML.')
