    g_issue_custom_field_associations_commands = g_issue_custom_field_associations.add_subparsers(dest="g_issue_custom_field_associations", metavar="COMMAND", required=True)
    c = g_issue_custom_field_associations_commands.add_parser('create-associations', parents=[common], help='Create associations', description="Associates fields with projects.\n\nFields will be associated with each issue type on the requested projects.\n\nFields will be associated with all projects that share the same field\nconfiguration which the provided projects are using. This means that while the\nfield will be associated with the requested projects, it will also be\nassociated with any other projects that share the same field configuration.\n\nIf a success response is returned it means that the field association has been\ncreated in any applicable contexts where it wasn't already present.\n\nUp to 50 fields and up to 100 projects can be associated in a single request.\nIf more fields or projects are provided a 400 response will be returned.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).", usage='%(prog)s --association-contexts @association-contexts.json --fields @fields.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-associations create-associations --association-contexts @association-contexts.json --fields @fields.json', 'codapact-jira issue-custom-field-associations create-associations --association-contexts @association-contexts.json --fields @fields.json --dry-run']), formatter_class=RAW)
    c.add_argument('--association-contexts', dest='p_association_contexts', type=json_value, metavar="JSON", required=True, help='Contexts to associate/unassociate the fields with. JSON array of objects with type*, identifier (* required). Schema: codapact-jira describe issue-custom-field-associations create-associations')
    c.add_argument('--fields', dest='p_fields', type=json_value, metavar="JSON", required=True, help='Fields to associate/unassociate with projects. JSON array of objects with type*, identifier (* required). Schema: codapact-jira describe issue-custom-field-associations create-associations')
    c.set_defaults(handler=_run_issue_custom_field_associations_create_associations, flags={'body.association_contexts': '--association-contexts', 'body.fields': '--fields'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_associations'})
    c = g_issue_custom_field_associations_commands.add_parser('remove-associations', parents=[common], help='Remove associations', description='Unassociates a set of fields with a project and issue type context.\n\nFields will be unassociated with all projects/issue types that share the same\nfield configuration which the provided project and issue types are using. This\nmeans that while the field will be unassociated with the provided project and\nissue types, it will also be unassociated with any other projects and issue\ntypes that share the same field configuration.\n\nIf a success response is returned it means that the field association has been\nremoved in any applicable contexts where it was present.\n\nUp to 50 fields and up to 100 projects and issue types can be unassociated in\na single request. If more fields or projects are provided a 400 response will\nbe returned.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --association-contexts @association-contexts.json --fields @fields.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-associations remove-associations --association-contexts @association-contexts.json --fields @fields.json --dry-run', 'codapact-jira issue-custom-field-associations remove-associations --association-contexts @association-contexts.json --fields @fields.json --yes']), formatter_class=RAW)
    c.add_argument('--association-contexts', dest='p_association_contexts', type=json_value, metavar="JSON", required=True, help='Contexts to associate/unassociate the fields with. JSON array of objects with type*, identifier (* required). Schema: codapact-jira describe issue-custom-field-associations remove-associations')
    c.add_argument('--fields', dest='p_fields', type=json_value, metavar="JSON", required=True, help='Fields to associate/unassociate with projects. JSON array of objects with type*, identifier (* required). Schema: codapact-jira describe issue-custom-field-associations remove-associations')
    RUNTIME.add_confirm_option(c)
