    c.add_argument('--is-global-context', dest='p_is_global_context', action=argparse.BooleanOptionalAction, help='Whether to return contexts that apply to all projects.')
    c.add_argument('--context-id', dest='p_context_id', action="append", type=integer, metavar='CONTEXT_ID', help='The list of context IDs. To include multiple contexts, separate IDs with ampersand: `contextId=10000&contextId=10001`.')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
