    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.set_defaults(handler=_run_issue_custom_field_contexts_list_default_values, flags={'field_id': '--field-id', 'context_id': '--context-id', 'start_at': '--start-at', 'max_results': '--max-results'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': True, 'operation': 'get_default_values'})
    c = g_issue_custom_field_contexts_commands.add_parser('set-default-values', parents=[common], help='[deprecated] Set custom field contexts default values', description='Sets default for contexts of a custom field. Default are defined using these\nobjects:\n\n* `CustomFieldContextDefaultValueDate` (type `datepicker`) for date fields. *\n`CustomFieldContextDefaultValueDateTime` (type `datetimepicker`) for date-time\nfields. * `CustomFieldContextDefaultValueSingleOption` (type `option.single`)\nfor single choice select lists and radio buttons. *\n`CustomFieldContextDefaultValueMultipleOption` (type `option.multiple`) for\nmultiple choice select lists and checkboxes. *\n`CustomFieldContextDefaultValueCascadingOption` (type `option.cascading`) for\ncascading select lists. * `CustomFieldContextSingleUserPickerDefaults` (type\n`single.user.select`) for single users. *\n`CustomFieldContextDefaultValueMultiUserPicker` (type `multi.user.select`) for\nuser lists. * `CustomFieldContextDefaultValueSingleGroupPicker` (type\n`grouppicker.single`) for single choice group pickers. *\n`CustomFieldContextDefaultValueMultipleGroupPicker` (type\n`grouppicker.multiple`) for multiple choice group pickers. *\n`CustomFieldContextDefaultValueURL` (type `url`) for URLs. *\n`CustomFieldContextDefaultValueProject` (type `project`) for project pickers.\n* `CustomFieldContextDefaultValueFloat` (type `float`) for floats (floating-\npoint numbers). * `CustomFieldContextDefaultValueLabels` (type `labels`) for\nlabels. * `CustomFieldContextDefaultValueTextField` (type `textfield`) for\ntext fields. * `CustomFieldContextDefaultValueTextArea` (type `textarea`) for\ntext area fields. * `CustomFieldContextDefaultValueLongText` (type `longtext`)\nfor plain text paragraph fields. * `CustomFieldContextDefaultValueReadOnly`\n(type `readonly`) for read only (text) fields. *\n`CustomFieldContextDefaultValueMultipleVersion` (type `version.multiple`) for\nsingle choice version pickers. * `CustomFieldContextDefaultValueSingleVersion`\n(type `version.single`) for multiple choice version pickers.\n\nForge custom fields\n[types](https://developer.atlassian.com/platform/forge/manifest-\nreference/modules/jira-custom-field-type/#data-types) are also supported,\nreturning:\n\n* `CustomFieldContextDefaultValueForgeStringFieldBean` (type `forge.string`)\nfor Forge string fields. *\n`CustomFieldContextDefaultValueForgeMultiStringFieldBean` (type\n`forge.string.list`) for Forge string collection fields. *\n`CustomFieldContextDefaultValueForgeObjectFieldBean` (type `forge.object`) for\nForge object fields. * `CustomFieldContextDefaultValueForgeDateTimeFieldBean`\n(type `forge.datetime`) for Forge date-time fields. *\n`CustomFieldContextDefaultValueForgeGroupFieldBean` (type `forge.group`) for\nForge group fields. * `CustomFieldContextDefaultValueForgeMultiGroupFieldBean`\n(type `forge.group.list`) for Forge group collection fields. *\n`CustomFieldContextDefaultValueForgeNumberFieldBean` (type `forge.number`) for\nForge number fields. * `CustomFieldContextDefaultValueForgeUserFieldBean`\n(type `forge.user`) for Forge user fields. *\n`CustomFieldContextDefaultValueForgeMultiUserFieldBean` (type\n`forge.user.list`) for Forge user collection fields.\n\nOnly one type of default object can be included in a request. To remove a\ndefault for a context, set the default parameter to `null`.\n\n**Deprecated:** This API is deprecated and will be removed in October 2026. A\nreplacement API that supports multiple default values per issue type within a\ncontext is coming soon. See the deprecation notice [CHANGE-\n3082](https://developer.atlassian.com/cloud/jira/platform/changelog/#CHANGE-\n3082) for more details.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s FIELD_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-contexts set-default-values FIELD_ID --default-values @default-values.json', 'codapact-jira issue-custom-field-contexts set-default-values FIELD_ID --default-values @default-values.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_field_id', metavar='FIELD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the custom field.')
    c.add_argument('--field-id', dest='p_field_id', default=argparse.SUPPRESS, metavar='FIELD_ID', help='same as FIELD_ID')
    c.add_argument('--default-values', dest='p_default_values', type=json_value, metavar="JSON")
    c.set_defaults(handler=_run_issue_custom_field_contexts_set_default_values, flags={'field_id': '--field-id', 'body.default_values': '--default-values'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': True, 'operation': 'set_default_values', 'requires_one_of': [['--default-values']]})
    c = g_issue_custom_field_contexts_commands.add_parser('list-context-default-values', parents=[common], help='Get default values for a custom field grouped by context and issue type', description='Returns a paginated list of default values grouped by custom field context.\n\nEach returned `ContextDefaultValuesBean` has a `contextId` and a\n`defaultValues` list of `IssueTypeDefaultValueBean` entries - one per issue-\ntype-scoped default value configured for the context. An entry with\n`"isAnyIssueType": true` represents the catch-all default that applies to\nevery issue type covered by the context that is not covered by a more specific\nentry; a non-null `issueTypeId` represents a default that only applies to that\nissue type.\n\nFor contexts that have not been converted to the multiple-contexts data model,\nexactly one entry is returned per context with `isAnyIssueType=true`. For\nconverted contexts, one entry is returned per configured per-issue-type\ndefault.\n\nThe value object on each entry is the same polymorphic\n`CustomFieldContextDefaultValueBean` exposed by the deprecated `GET\n/defaultValue` endpoint - its concrete subtype depends on the custom field\'s\ntype (see the list of supported types on that endpoint).\n\nOnly tenants enrolled in the early access program (EAP) can access this\nresource. See the [EAP\nannouncement](https://ecosystem.atlassian.net/browse/CHANGE-3082) for details.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s FIELD_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-contexts list-context-default-values FIELD_ID']), formatter_class=RAW)
    c.add_argument('p_field_id', metavar='FIELD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the custom field, for example `customfield\\_10000`.')
    c.add_argument('--field-id', dest='p_field_id', default=argparse.SUPPRESS, metavar='FIELD_ID', help='same as FIELD_ID')
    c.add_argument('--context-id', dest='p_context_id', action="append", type=integer, metavar='CONTEXT_ID', help='The IDs of the contexts to return default values for. If omitted, default values for every context the custom field has are returned.')
    c.add_argument('--issue-type-id', dest='p_issue_type_id', action="append", metavar='ISSUE_TYPE_ID', help='The IDs of the issue types to restrict the returned per-issue-type default values to. If omitted, default values for every issue type are returned. This filter never removes the catch-all `isAnyIssueType` entry of a context.')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.set_defaults(handler=_run_issue_custom_field_contexts_list_context_default_values, flags={'field_id': '--field-id', 'context_id': '--context-id', 'issue_type_id': '--issue-type-id', 'start_at': '--start-at', 'max_results': '--max-results'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_context_default_values'})
    c = g_issue_custom_field_contexts_commands.add_parser('set-context-default-values', parents=[common], help='Set default values for a custom field by context and issue type', description='Updates default values for individual issue types in custom field contexts.\n\nOnly tenants enrolled in the early access program (EAP) can access this\nresource. See the [EAP\nannouncement](https://ecosystem.atlassian.net/browse/CHANGE-3082) for details.\n\nEach entry targets either one issue type through \\{@code issueTypeId\\}, or the\ncatch-all configuration through \\{@code isAnyIssueType=true\\}. A null value\nremoves the default for that target. Entries not included in the request are\nleft unchanged.', usage='%(prog)s FIELD_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-contexts set-context-default-values FIELD_ID --default-values @default-values.json', 'codapact-jira issue-custom-field-contexts set-context-default-values FIELD_ID --default-values @default-values.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_field_id', metavar='FIELD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the custom field, for example \\{@code customfield\\_10000\\}.')
    c.add_argument('--field-id', dest='p_field_id', default=argparse.SUPPRESS, metavar='FIELD_ID', help='same as FIELD_ID')
    c.add_argument('--default-values', dest='p_default_values', type=json_value, metavar="JSON", help='The default values to update. JSON array of objects with context_id*, is_any_issue_type, issue_type_id, value (* required). Schema: codapact-jira describe issue-custom-field-contexts set-context-default-values')
    c.set_defaults(handler=_run_issue_custom_field_contexts_set_context_default_values, flags={'field_id': '--field-id', 'body.default_values': '--default-values'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'set_context_default_values', 'requires_one_of': [['--default-values']]})
    c = g_issue_custom_field_contexts_commands.add_parser('list-issue-type-mappings-for-contexts', parents=[common], help='Get issue types for custom field context', description='Returns a [paginated](#pagination) list of context to issue type mappings for\na custom field. Mappings are returned for all contexts or a list of contexts.\nMappings are ordered first by context ID and then by issue type ID.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s FIELD_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-contexts list-issue-type-mappings-for-contexts FIELD_ID']), formatter_class=RAW)
    c.add_argument('p_field_id', metavar='FIELD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the custom field.')
    c.add_argument('--field-id', dest='p_field_id', default=argparse.SUPPRESS, metavar='FIELD_ID', help='same as FIELD_ID')
    c.add_argument('--context-id', dest='p_context_id', action="append", type=integer, metavar='CONTEXT_ID', help='The ID of the context. To include multiple contexts, provide an ampersand-separated list. For example, `contextId=10001&contextId=10002`.')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.set_defaults(handler=_run_issue_custom_field_contexts_list_issue_type_mappings_for_contexts, flags={'field_id': '--field-id', 'context_id': '--context-id', 'start_at': '--start-at', 'max_results': '--max-results'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_issue_type_mappings_for_contexts'})
    c = g_issue_custom_field_contexts_commands.add_parser('list-custom-field-contexts-for-projects-and-issue-types', parents=[common], help='Get custom field contexts for projects and issue types', description='Returns a [paginated](#pagination) list of project and issue type mappings\nand, for each mapping, the ID of a [custom field\ncontext](https://confluence.atlassian.com/x/k44fOw) that applies to the\nproject and issue type.\n\nIf there is no custom field context assigned to the project then, if present,\nthe custom field context that applies to all projects is returned if it also\napplies to the issue type or all issue types. If a custom field context is not\nfound, the returned custom field context ID is `null`.\n\nDuplicate project and issue type mappings cannot be provided in the request.\n\nThe order of the returned values is the same as provided in the request.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s FIELD_ID --mappings @mappings.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-contexts list-custom-field-contexts-for-projects-and-issue-types FIELD_ID --mappings @mappings.json', 'codapact-jira issue-custom-field-contexts list-custom-field-contexts-for-projects-and-issue-types FIELD_ID --mappings @mappings.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_field_id', metavar='FIELD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the custom field.')
    c.add_argument('--field-id', dest='p_field_id', default=argparse.SUPPRESS, metavar='FIELD_ID', help='same as FIELD_ID')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.add_argument('--mappings', dest='p_mappings', type=json_value, metavar="JSON", required=True, help='The project and issue type mappings. JSON array of objects with issue_type_id*, project_id* (* required). Schema: codapact-jira describe issue-custom-field-contexts list-custom-field-contexts-for-projects-and-issue-types')
    c.set_defaults(handler=_run_issue_custom_field_contexts_list_custom_field_contexts_for_projects_and_issue_types, flags={'field_id': '--field-id', 'start_at': '--start-at', 'max_results': '--max-results', 'body.mappings': '--mappings'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_custom_field_contexts_for_projects_and_issue_types'})
    c = g_issue_custom_field_contexts_commands.add_parser('get-project-context-mapping', parents=[common], help='Get project mappings for custom field context', description='Returns a [paginated](#pagination) list of context to project mappings for a\ncustom field. The result can be filtered by `contextId`. Otherwise, all\nmappings are returned. Invalid IDs are ignored.\n\n**Note:** Jira is adding support for multiple field contexts per project. On\nsites where this is enabled, a custom field can have more than one context\nassociated with the same project, so this operation can return several\nmappings that share the same `projectId`, each with a different `contextId`.\nDo not assume that a project appears at most once in the response. See [CHANGE\n-3082](https://developer.atlassian.com/cloud/jira/platform/changelog/#CHANGE-\n3082) for more details.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s FIELD_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-contexts get-project-context-mapping FIELD_ID']), formatter_class=RAW)
    c.add_argument('p_field_id', metavar='FIELD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the custom field, for example `customfield\\_10000`.')
    c.add_argument('--field-id', dest='p_field_id', default=argparse.SUPPRESS, metavar='FIELD_ID', help='same as FIELD_ID')
    c.add_argument('--context-id', dest='p_context_id', action="append", type=integer, metavar='CONTEXT_ID', help='The list of context IDs. To include multiple context, separate IDs with ampersand: `contextId=10000&contextId=10001`.')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.set_defaults(handler=_run_issue_custom_field_contexts_get_project_context_mapping, flags={'field_id': '--field-id', 'context_id': '--context-id', 'start_at': '--start-at', 'max_results': '--max-results'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_project_context_mapping'})
    c = g_issue_custom_field_contexts_commands.add_parser('update-custom-field-context', parents=[common], help='Update custom field context', description='Updates a [ custom field\ncontext](https://confluence.atlassian.com/adminjiracloud/what-are-custom-\nfield-contexts-991923859.html).\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s FIELD_ID CONTEXT_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-contexts update-custom-field-context FIELD_ID CONTEXT_ID --description DESCRIPTION', 'codapact-jira issue-custom-field-contexts update-custom-field-context FIELD_ID CONTEXT_ID --description DESCRIPTION --dry-run']), formatter_class=RAW)
    c.add_argument('p_field_id', metavar='FIELD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the custom field.')
    c.add_argument('p_context_id', metavar='CONTEXT_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the context.')
    c.add_argument('--field-id', dest='p_field_id', default=argparse.SUPPRESS, metavar='FIELD_ID', help='same as FIELD_ID')
    c.add_argument('--context-id', dest='p_context_id', default=argparse.SUPPRESS, type=integer, metavar='CONTEXT_ID', help='same as CONTEXT_ID')
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='The description of the custom field context. The maximum length is 255 characters.')
    c.add_argument('--name', dest='p_name', metavar='NAME', help='The name of the custom field context. The name must be unique. The maximum length is 255 characters.')
    c.set_defaults(handler=_run_issue_custom_field_contexts_update_custom_field_context, flags={'field_id': '--field-id', 'context_id': '--context-id', 'body.description': '--description', 'body.name': '--name'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_custom_field_context', 'requires_one_of': [['--description', '--name']]})
    c = g_issue_custom_field_contexts_commands.add_parser('delete-custom-field-context', parents=[common], help='Delete custom field context', description='Deletes a [ custom field\ncontext](https://confluence.atlassian.com/adminjiracloud/what-are-custom-\nfield-contexts-991923859.html).\n\nThis API will not allow removing the global context from April 2026. Instead,\nan HTTP 400 response will be returned. See\n[CHANGE-3019](https://developer.atlassian.com/changelog/#CHANGE-3019)\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s FIELD_ID CONTEXT_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-contexts delete-custom-field-context FIELD_ID CONTEXT_ID --dry-run', 'codapact-jira issue-custom-field-contexts delete-custom-field-context FIELD_ID CONTEXT_ID --yes']), formatter_class=RAW)
    c.add_argument('p_field_id', metavar='FIELD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the custom field.')
    c.add_argument('p_context_id', metavar='CONTEXT_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the context.')
    c.add_argument('--field-id', dest='p_field_id', default=argparse.SUPPRESS, metavar='FIELD_ID', help='same as FIELD_ID')
    c.add_argument('--context-id', dest='p_context_id', default=argparse.SUPPRESS, type=integer, metavar='CONTEXT_ID', help='same as CONTEXT_ID')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_issue_custom_field_contexts_delete_custom_field_context, flags={'field_id': '--field-id', 'context_id': '--context-id'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_custom_field_context'})
    c = g_issue_custom_field_contexts_commands.add_parser('add-issue-types-to-context', parents=[common], help='Add issue types to context', description='Adds issue types to a custom field context, appending the issue types to the\nissue types list.\n\nA custom field context without any issue types applies to all issue types.\nAdding issue types replaces the any-issue-type mapping unless \\{@code\nisAnyIssueType\\} is true. A supplied \\{@code defaultValue\\} applies to newly\nadded mappings. If omitted, the default value of the first existing issue type\nmapping is copied. Existing mappings retain their defaults.\n\nIf any of the issue types exists in the custom field context, the operation\nfails and no issue types are added.\n\nThis API will not allow adding issue types to the global context from April\n2026. Instead, an HTTP 400 response will be returned. See\n[CHANGE-3019](https://developer.atlassian.com/changelog/#CHANGE-3019)\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s FIELD_ID CONTEXT_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-contexts add-issue-types-to-context FIELD_ID CONTEXT_ID --default-value @default-value.json', 'codapact-jira issue-custom-field-contexts add-issue-types-to-context FIELD_ID CONTEXT_ID --default-value @default-value.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_field_id', metavar='FIELD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the custom field.')
    c.add_argument('p_context_id', metavar='CONTEXT_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the context.')
    c.add_argument('--field-id', dest='p_field_id', default=argparse.SUPPRESS, metavar='FIELD_ID', help='same as FIELD_ID')
    c.add_argument('--context-id', dest='p_context_id', default=argparse.SUPPRESS, type=integer, metavar='CONTEXT_ID', help='same as CONTEXT_ID')
    c.add_argument('--default-value', dest='p_default_value', type=json_value, metavar="JSON")
    c.add_argument('--is-any-issue-type', dest='p_is_any_issue_type', action=argparse.BooleanOptionalAction, help='Whether to add or retain the any-issue-type mapping. At least one of this property or issueTypeIds is required. Defaults to false.')
    c.add_argument('--issue-type-ids', dest='p_issue_type_ids', action="append", metavar='ISSUE_TYPE_IDS', help='The issue type IDs to add. Optional when isAnyIssueType is true.')
    c.set_defaults(handler=_run_issue_custom_field_contexts_add_issue_types_to_context, flags={'field_id': '--field-id', 'context_id': '--context-id', 'body.default_value': '--default-value', 'body.is_any_issue_type': '--is-any-issue-type', 'body.issue_type_ids': '--issue-type-ids'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'add_issue_types_to_context', 'requires_one_of': [['--default-value', '--is-any-issue-type', '--issue-type-ids']]})
    c = g_issue_custom_field_contexts_commands.add_parser('remove-issue-types-from-context', parents=[common], help='Remove issue types from context', description='Removes issue types from a custom field context.\n\nA custom field context without any issue types applies to all issue types.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s FIELD_ID CONTEXT_ID --issue-type-ids ISSUE_TYPE_IDS [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-contexts remove-issue-types-from-context FIELD_ID CONTEXT_ID --issue-type-ids ISSUE_TYPE_IDS --dry-run', 'codapact-jira issue-custom-field-contexts remove-issue-types-from-context FIELD_ID CONTEXT_ID --issue-type-ids ISSUE_TYPE_IDS --yes']), formatter_class=RAW)
    c.add_argument('p_field_id', metavar='FIELD_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the custom field.')
    c.add_argument('p_context_id', metavar='CONTEXT_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the context.')
    c.add_argument('--field-id', dest='p_field_id', default=argparse.SUPPRESS, metavar='FIELD_ID', help='same as FIELD_ID')
    c.add_argument('--context-id', dest='p_context_id', default=argparse.SUPPRESS, type=integer, metavar='CONTEXT_ID', help='same as CONTEXT_ID')
    c.add_argument('--issue-type-ids', dest='p_issue_type_ids', action="append", metavar='ISSUE_TYPE_IDS', required=True, help='The list of issue type IDs.')
    RUNTIME.add_confirm_option(c)
