    c.set_defaults(handler=_run_issue_custom_field_options_update_custom_field_option, flags={'field_id': '--field-id', 'context_id': '--context-id', 'body.options': '--options'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_custom_field_option', 'requires_one_of': [['--options']]})
    c = g_issue_custom_field_options_commands.add_parser('create-custom-field-option', parents=[common], help='Create custom field options (context)', description='Creates options and, where the custom select field is of the type Select List\n(cascading), cascading options for a custom select field. The options are\nadded to a context of the field.\n\nThe maximum number of options that can be created per request is 1000 and each\nfield can have a maximum of 10000 options.\n\nThis operation works for custom field options created in Jira or the\noperations from this resource. **To work with issue field select list options\ncreated for Connect apps use the [Issue custom field options (apps)](#api-\ngroup-issue-custom-field-options--apps-) operations.**\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s FIELD_ID CONTEXT_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-options create-custom-field-option FIELD_ID CONTEXT_ID --options @options.json', 'codapact-jira issue-custom-field-options create-custom-field-option FIELD_ID CONTEXT_ID --options @options.json --dry-run']), formatter_class=RAW)
