    c = g_issue_custom_field_options_apps_commands.add_parser('update-issue-field-option', parents=[common], help='Update issue field option', description='Updates or creates an option for a select list issue field. This operation\nrequires that the option ID is provided when creating an option, therefore,\nthe option ID needs to be specified as a path and body parameter. The option\nID provided in the path and body must be identical.\n\nNote that this operation **only works for issue field select list options\nadded by Connect apps**, it cannot be used with issue field select list\noptions created in Jira or using operations from the [Issue custom field\noptions](#api-group-Issue-custom-field-options) resource.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg). Jira permissions are\nnot required for the app providing the field.', usage='%(prog)s FIELD_KEY OPTION_ID --id ID --value VALUE [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-options-apps update-issue-field-option FIELD_KEY OPTION_ID --id ID --value VALUE', 'codapact-jira issue-custom-field-options-apps update-issue-field-option FIELD_KEY OPTION_ID --id ID --value VALUE --dry-run']), formatter_class=RAW)
    c.add_argument('p_field_key', metavar='FIELD_KEY', nargs='?', default=argparse.SUPPRESS, help='The field key is specified in the following format: **$(app-key)\\_\\_$(field-key)**. For example, *example-add-on\\_\\_example-issue-field*. To determine the `fieldKey` value, do one of the following:')
    c.add_argument('p_option_id', metavar='OPTION_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the option to be updated.')
    c.add_argument('--field-key', dest='p_field_key', default=argparse.SUPPRESS, metavar='FIELD_KEY', help='same as FIELD_KEY')
    c.add_argument('--option-id', dest='p_option_id', default=argparse.SUPPRESS, type=integer, metavar='OPTION_ID', help='same as OPTION_ID')
    c.add_argument('--arg-config', dest='p_arg_config', type=json_value, metavar="JSON", help='JSON object with attributes, scope. Schema: codapact-jira describe issue-custom-field-options-apps update-issue-field-option')
    c.add_argument('--id', dest='p_id', type=integer, metavar='ID', required=True, help="The unique identifier for the option. This is only unique within the select field's set of options.")
    c.add_argument('--properties', dest='p_properties', type=json_value, metavar="JSON", help='The properties of the object, as arbitrary key-value pairs. These properties can be searched using JQL, if the extractions (see [Issue Field Option Property Index](https://developer.atlassian.com/cloud/jira/platform/modules/issue-field-option-property-index/)) are defined in the descriptor for the issue field module.')
