    c = g_issue_custom_field_options_apps_commands.add_parser('delete-issue-field-option', parents=[common], help='Delete issue field option', description='Deletes an option from a select list issue field.\n\nNote that this operation **only works for issue field select list options\nadded by Connect apps**, it cannot be used with issue field select list\noptions created in Jira or using operations from the [Issue custom field\noptions](#api-group-Issue-custom-field-options) resource.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg). Jira permissions are\nnot required for the app providing the field.', usage='%(prog)s FIELD_KEY OPTION_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-options-apps delete-issue-field-option FIELD_KEY OPTION_ID --dry-run', 'codapact-jira issue-custom-field-options-apps delete-issue-field-option FIELD_KEY OPTION_ID --yes']), formatter_class=RAW)
    c.add_argument('p_field_key', metavar='FIELD_KEY', nargs='?', default=argparse.SUPPRESS, help='The field key is specified in the following format: **$(app-key)\\_\\_$(field-key)**. For example, *example-add-on\\_\\_example-issue-field*. To determine the `fieldKey` value, do one of the following:')
