    c = g_issue_custom_field_options_apps_commands.add_parser('replace-issue-field-option', parents=[common], help='Replace issue field option', description='Deselects an issue-field select-list option from all issues where it is\nselected. A different option can be selected to replace the deselected option.\nThe update can also be limited to a smaller set of issues by using a JQL\nquery.\n\nConnect and Forge app users with *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg) can override the screen\nsecurity configuration using `overrideScreenSecurity` and\n`overrideEditableFlag`.\n\nThis is an [asynchronous operation](#async). The response object contains a\nlink to the long-running task.\n\nNote that this operation **only works for issue field select list options\nadded by Connect apps**, it cannot be used with issue field select list\noptions created in Jira or using operations from the [Issue custom field\noptions](#api-group-Issue-custom-field-options) resource.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg). Jira permissions are\nnot required for the app providing the field.', usage='%(prog)s FIELD_KEY OPTION_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-options-apps replace-issue-field-option FIELD_KEY OPTION_ID --dry-run', 'codapact-jira issue-custom-field-options-apps replace-issue-field-option FIELD_KEY OPTION_ID --yes']), formatter_class=RAW)
    c.add_argument('p_field_key', metavar='FIELD_KEY', nargs='?', default=argparse.SUPPRESS, help='The field key is specified in the following format: **$(app-key)\\_\\_$(field-key)**. For example, *example-add-on\\_\\_example-issue-field*. To determine the `fieldKey` value, do one of the following:')
    c.add_argument('p_option_id', metavar='OPTION_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the option to be deselected.')
    c.add_argument('--replace-with', dest='p_replace_with', type=integer, metavar='REPLACE_WITH', help='The ID of the option that will replace the currently selected option.')
    c.add_argument('--jql', dest='p_jql', metavar='JQL', help='A JQL query that specifies the issues to be updated. For example, *project=10000*.')
    c.add_argument('--override-screen-security', dest='p_override_screen_security', action=argparse.BooleanOptionalAction, help='Whether screen security is overridden to enable hidden fields to be edited. Available to Connect and Forge app users with admin permission. (default: False)')
    c.add_argument('--override-editable-flag', dest='p_override_editable_flag', action=argparse.BooleanOptionalAction, help='Whether screen security is overridden to enable uneditable fields to be edited. Available to Connect and Forge app users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg). (default: False)')
    c.add_argument('--field-key', dest='p_field_key', default=argparse.SUPPRESS, metavar='FIELD_KEY', help='same as FIELD_KEY')
    c.add_argument('--option-id', dest='p_option_id', default=argparse.SUPPRESS, type=integer, metavar='OPTION_ID', help='same as OPTION_ID')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_issue_custom_field_options_apps_replace_issue_field_option, flags={'replace_with': '--replace-with', 'jql': '--jql', 'override_screen_security': '--override-screen-security', 'override_editable_flag': '--override-editable-flag', 'field_key': '--field-key', 'option_id': '--option-id'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'replace_issue_field_option'})
    g_issue_custom_field_values_apps = commands.add_parser('issue-custom-field-values-apps', help='update-custom-field-value, update-multiple-custom-field-values', description="Run 'codapact-jira issue-custom-field-values-apps COMMAND --help' for a command's options and examples.")
    g_issue_custom_field_values_apps_commands = g_issue_custom_field_values_apps.add_subparsers(dest="g_issue_custom_field_values_apps", metavar="COMMAND", required=True)
    c = g_issue_custom_field_values_apps_commands.add_parser('update-multiple-custom-field-values', parents=[common], help='Update custom fields', description="Updates the value of one or more custom fields on one or more issues.\nCombinations of custom field and issue should be unique within the request.\n\nApps can only perform this operation on [custom\nfields](https://developer.atlassian.com/platform/forge/manifest-\nreference/modules/jira-custom-field/) and [custom field\ntypes](https://developer.atlassian.com/platform/forge/manifest-\nreference/modules/jira-custom-field-type/) declared in their own manifests.\n\n**[Permissions](#permissions) required:** Only the app that owns the custom\nfield or custom field type can update its values with this operation.\n\nThe new `write:app-data:jira` OAuth scope is 100% optional now, and not using\nit won't break your app. However, we recommend adding it to your app's scope\nlist because we will eventually make it mandatory.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-values-apps update-multiple-custom-field-values --updates @updates.json', 'codapact-jira issue-custom-field-values-apps update-multiple-custom-field-values --updates @updates.json --dry-run']), formatter_class=RAW)
    c.add_argument('--generate-changelog', dest='p_generate_changelog', action=argparse.BooleanOptionalAction, help='Whether to generate a changelog for this update. (default: True)')
    c.add_argument('--generate-app-events', dest='p_generate_app_events', action=argparse.BooleanOptionalAction, help='Whether to generate app events for this update. Suppresses Forge, Connect, OAuth 2.0, and admin-configured webhooks (registered via the Jira admin UI). Note: Suppressing events means that "issue updated" events will not be emitted for your app or any other apps installed in Jira. This may cause other apps to retain stale data for the updated field, resulting in potentially confusing behaviour. We do not recommend using this flag in a Marketplace app as it may result in incompatibilities with other apps that depend on up-to-date issue data. (default: True)')
    c.add_argument('--updates', dest='p_updates', type=json_value, metavar="JSON", help='JSON array of objects with custom_field*, issue_ids*, value* (* required). Schema: codapact-jira describe issue-custom-field-values-apps update-multiple-custom-field-values')
    c.set_defaults(handler=_run_issue_custom_field_values_apps_update_multiple_custom_field_values, flags={'generate_changelog': '--generate-changelog', 'generate_app_events': '--generate-app-events', 'body.updates': '--updates'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_multiple_custom_field_values', 'requires_one_of': [['--updates']]})
    c = g_issue_custom_field_values_apps_commands.add_parser('update-custom-field-value', parents=[common], help='Update custom field value', description="Updates the value of a custom field on one or more issues.\n\nApps can only perform this operation on [custom\nfields](https://developer.atlassian.com/platform/forge/manifest-\nreference/modules/jira-custom-field/) and [custom field\ntypes](https://developer.atlassian.com/platform/forge/manifest-\nreference/modules/jira-custom-field-type/) declared in their own manifests.\n\n**[Permissions](#permissions) required:** Only the app that owns the custom\nfield or custom field type can update its values with this operation.\n\nThe new `write:app-data:jira` OAuth scope is 100% optional now, and not using\nit won't break your app. However, we recommend adding it to your app's scope\nlist because we will eventually make it mandatory.", usage='%(prog)s FIELD_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-custom-field-values-apps update-custom-field-value FIELD_ID_OR_KEY --updates @updates.json', 'codapact-jira issue-custom-field-values-apps update-custom-field-value FIELD_ID_OR_KEY --updates @updates.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_field_id_or_key', metavar='FIELD_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the custom field. For example, `customfield_10010`.')
    c.add_argument('--field-id-or-key', dest='p_field_id_or_key', default=argparse.SUPPRESS, metavar='FIELD_ID_OR_KEY', help='same as FIELD_ID_OR_KEY')
    c.add_argument('--generate-changelog', dest='p_generate_changelog', action=argparse.BooleanOptionalAction, help='Whether to generate a changelog for this update. (default: True)')
    c.add_argument('--generate-app-events', dest='p_generate_app_events', action=argparse.BooleanOptionalAction, help='Whether to generate app events for this update. Suppresses Forge, Connect, OAuth 2.0, and admin-configured webhooks (registered via the Jira admin UI). Note: Suppressing events means that "issue updated" events will not be emitted for your app or any other apps installed in Jira. This may cause other apps to retain stale data for the updated field, resulting in potentially confusing behaviour. We do not recommend using this flag in a Marketplace app as it may result in incompatibilities with other apps that depend on up-to-date issue data. (default: True)')
    c.add_argument('--updates', dest='p_updates', type=json_value, metavar="JSON", help='The list of custom field update details. JSON array of objects with issue_ids*, value* (* required). Schema: codapact-jira describe issue-custom-field-values-apps update-custom-field-value')
    c.set_defaults(handler=_run_issue_custom_field_values_apps_update_custom_field_value, flags={'field_id_or_key': '--field-id-or-key', 'generate_changelog': '--generate-changelog', 'generate_app_events': '--generate-app-events', 'body.updates': '--updates'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_custom_field_value', 'requires_one_of': [['--updates']]})
    g_issue_field_configurations = commands.add_parser('issue-field-configurations', help='assign-field-configuration-scheme-to-project, create-field-configuration, create-field-configuration-scheme, … (15 commands)', description="Run 'codapact-jira issue-field-configurations COMMAND --help' for a command's options and examples.")
    g_issue_field_configurations_commands = g_issue_field_configurations.add_subparsers(dest="g_issue_field_configurations", metavar="COMMAND", required=True)
    c = g_issue_field_configurations_commands.add_parser('list-all-field-configurations', parents=[common], help='[deprecated] Get all field configurations', description='Deprecated, use [ Field\nschemes](https://developer.atlassian.com/cloud/jira/platform/rest/v3/api-\ngroup-field-schemes/#api-group-field-schemes) which supports field association\nschemes.\n\nReturns a [paginated](#pagination) list of field configurations. The list can\nbe for all field configurations or a subset determined by any combination of\nthese criteria:\n\n* a list of field configuration item IDs. * whether the field configuration is\na default. * whether the field configuration name or description contains a\nquery string.\n\nOnly field configurations used in company-managed (classic) projects are\nreturned.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-field-configurations list-all-field-configurations']), formatter_class=RAW)
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.add_argument('--id', dest='p_id', action="append", type=integer, metavar='ID', help='The list of field configuration IDs. To include multiple IDs, provide an ampersand-separated list. For example, `id=10000&id=10001`.')
