    c = g_issue_links_commands.add_parser('link-issues', parents=[common], help='Create issue link', description='Creates a link between two issues. Use this operation to indicate a\nrelationship between two issues and optionally add a comment to the from\n(outward) issue. To use this resource the site must have [Issue\nLinking](https://confluence.atlassian.com/x/yoXKM) enabled.\n\nThis resource returns nothing on the creation of an issue link. To obtain the\nID of the issue link, use `https://your-\ndomain.atlassian.net/rest/api/3/issue/[linked issue key]?fields=issuelinks`.\n\nIf the link request duplicates a link, the response indicates that the issue\nlink was created. If the request included a comment, the comment is added.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse project* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for all the projects\ncontaining the issues to be linked, * *Link issues* [project\npermission](https://confluence.atlassian.com/x/yodKLg) on the project\ncontaining the from (outward) issue, * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * If the comment has visibility\nrestrictions, belongs to the group or has the role visibility is restricted\nto.', usage='%(prog)s --inward-issue @inward-issue.json --outward-issue @outward-issue.json --type @type.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-links link-issues --inward-issue @inward-issue.json --outward-issue @outward-issue.json --type @type.json', 'codapact-jira issue-links link-issues --inward-issue @inward-issue.json --outward-issue @outward-issue.json --type @type.json --dry-run']), formatter_class=RAW)
    c.add_argument('--comment', dest='p_comment', type=json_value, metavar="JSON", help='JSON object with author, body, created, id, jsd_author_can_see_request, jsd_public, properties, rendered_body, self, update_author, updated, visibility. Schema: codapact-jira describe issue-links link-issues')
    c.add_argument('--inward-issue', dest='p_inward_issue', type=json_value, metavar="JSON", required=True, help='JSON object with fields, id, key, self. Schema: codapact-jira describe issue-links link-issues')
    c.add_argument('--outward-issue', dest='p_outward_issue', type=json_value, metavar="JSON", required=True, help='JSON object with fields, id, key, self. Schema: codapact-jira describe issue-links link-issues')
    c.add_argument('--type', dest='p_type', type=json_value, metavar="JSON", required=True, help='JSON object with id, inward, name, outward, self. Schema: codapact-jira describe issue-links link-issues')
    c.set_defaults(handler=_run_issue_links_link_issues, flags={'body.comment': '--comment', 'body.inward_issue': '--inward-issue', 'body.outward_issue': '--outward-issue', 'body.type': '--type'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'link_issues'})
    c = g_issue_links_commands.add_parser('get', parents=[common], help='Get issue link', description='Returns an issue link.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse project* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for all the projects\ncontaining the linked issues. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, permission\nto view both of the issues.', usage='%(prog)s LINK_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-links get LINK_ID']), formatter_class=RAW)
    c.add_argument('p_link_id', metavar='LINK_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the issue link.')
