    c.add_argument('p_link_id', metavar='LINK_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the issue link.')
    c.add_argument('--link-id', dest='p_link_id', default=argparse.SUPPRESS, metavar='LINK_ID', help='same as LINK_ID')
