    c.set_defaults(handler=_run_issue_panels_bulk_pin_unpin_projects_async, flags={'body.module_id': '--module-id', 'body.project_list': '--project-list'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'bulk_pin_unpin_projects_async'})
    c = g_issue_panels_commands.add_parser('get-bulk-pin-status', parents=[common], help='Get issue panel pin status for projects', description='Get the pin status of an issue panel (added by a Forge app) for multiple\nprojects.\n\nThe operation is read-only and runs synchronously. Projects that do not exist,\nor that you do not have permission to access, are returned in the response\nwith the panel reported as not pinned and the reason in the `error` field; the\nrequest itself still succeeds.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --module-id MODULE_ID --project-list PROJECT_LIST [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-panels get-bulk-pin-status --module-id MODULE_ID --project-list PROJECT_LIST', 'codapact-jira issue-panels get-bulk-pin-status --module-id MODULE_ID --project-list PROJECT_LIST --dry-run']), formatter_class=RAW)
    c.add_argument('--module-id', dest='p_module_id', metavar='MODULE_ID', required=True, help='The moduleId of the Forge panel in the format `ari:cloud:ecosystem::extension/{app-id}/{environment-id}/static/{module-key}`')
    c.add_argument('--project-list', dest='p_project_list', action="append", metavar='PROJECT_LIST', required=True, help='The IDs or keys of the projects to check the issue panel pin status for.')
    c.set_defaults(handler=_run_issue_panels_get_bulk_pin_status, flags={'body.module_id': '--module-id', 'body.project_list': '--project-list'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_bulk_pin_status'})
