    c = g_issue_priorities_commands.add_parser('create-priority', parents=[common], help='Create priority', description='Creates an issue priority.\n\n**Deprecation notice:** The `iconUrl` parameter was sunset on 16th Mar 2025,\nand replaced with `avatarId`. See\n[CHANGE-1525](https://developer.atlassian.com/changelog/#CHANGE-1525).\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --name NAME --status-color STATUS_COLOR [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-priorities create-priority --name NAME --status-color STATUS_COLOR', 'codapact-jira issue-priorities create-priority --name NAME --status-color STATUS_COLOR --dry-run']), formatter_class=RAW)
    c.add_argument('--avatar-id', dest='p_avatar_id', type=integer, metavar='AVATAR_ID', help='The ID for the avatar for the priority. Either the iconUrl or avatarId must be defined, but not both. This parameter is nullable and will become mandatory once the iconUrl parameter is deprecated.')
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='The description of the priority.')
    c.add_argument('--icon-url', dest='p_icon_url', choices=['/images/icons/priorities/blocker.png', '/images/icons/priorities/critical.png', '/images/icons/priorities/high.png', '/images/icons/priorities/highest.png', '/images/icons/priorities/low.png', '/images/icons/priorities/lowest.png', '/images/icons/priorities/major.png', '/images/icons/priorities/medium.png', '/images/icons/priorities/minor.png', '/images/icons/priorities/trivial.png', '/images/icons/priorities/blocker_new.png', '/images/icons/priorities/critical_new.png', '/images/icons/priorities/high_new.png', '/images/icons/priorities/highest_new.png', '/images/icons/priorities/low_new.png', '/images/icons/priorities/lowest_new.png', '/images/icons/priorities/major_new.png', '/images/icons/priorities/medium_new.png', '/images/icons/priorities/minor_new.png', '/images/icons/priorities/trivial_new.png'], help='The URL of an icon for the priority. Accepted protocols are HTTP and HTTPS. Built in icons can also be used. Either the iconUrl or avatarId must be defined, but not both.')
    c.add_argument('--name', dest='p_name', metavar='NAME', required=True, help='The name of the priority. Must be unique.')
    c.add_argument('--status-color', dest='p_status_color', metavar='STATUS_COLOR', required=True, help='The status color of the priority in 3-digit or 6-digit hexadecimal format.')
    c.set_defaults(handler=_run_issue_priorities_create_priority, flags={'body.avatar_id': '--avatar-id', 'body.description': '--description', 'body.icon_url': '--icon-url', 'body.name': '--name', 'body.status_color': '--status-color'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_priority'})
    c = g_issue_priorities_commands.add_parser('set-default-priority', parents=[common], help='Set default priority', description='Sets default issue priority.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --id ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-priorities set-default-priority --id ID', 'codapact-jira issue-priorities set-default-priority --id ID --dry-run']), formatter_class=RAW)
