    c = g_issue_priorities_commands.add_parser('move-priorities', parents=[common], help='Move priorities', description='Changes the order of issue priorities.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --ids IDS [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-priorities move-priorities --ids IDS', 'codapact-jira issue-priorities move-priorities --ids IDS --dry-run']), formatter_class=RAW)
