    c = g_issue_priorities_commands.add_parser('search-priorities', parents=[common], help='Search priorities', description='Returns a [paginated](#pagination) list of priorities. The list can contain\nall priorities or a subset determined by any combination of these criteria:\n\n* a list of priority IDs. Any invalid priority IDs are ignored. * a list of\nproject IDs. Only priorities that are available in these projects will be\nreturned. Any invalid project IDs are ignored. * whether the field\nconfiguration is a default. This returns priorities from company-managed\n(classic) projects only, as there is no concept of default priorities in team-\nmanaged projects.\n\n**Deprecation notice:** The `onlyDefault` parameter is deprecated and will be\nremoved at a later date. See [CHANGE-\n1655](https://developer.atlassian.com/cloud/jira/platform/changelog/#CHANGE-\n1655).\n\n**Deprecation notice:** The `isDefault` property of priorities is deprecated\nand will be removed at a later date. See [CHANGE-\n1655](https://developer.atlassian.com/cloud/jira/platform/changelog/#CHANGE-\n1655).\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-priorities search-priorities']), formatter_class=RAW)
    c.add_argument('--start-at', dest='p_start_at', metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.add_argument('--id', dest='p_id', action="append", metavar='ID', help='The list of priority IDs. To include multiple IDs, provide an ampersand-separated list. For example, `id=2&id=3`.')
    c.add_argument('--project-id', dest='p_project_id', action="append", metavar='PROJECT_ID', help='The list of projects IDs. To include multiple IDs, provide an ampersand-separated list. For example, `projectId=10010&projectId=10111`.')
    c.add_argument('--priority-name', dest='p_priority_name', metavar='PRIORITY_NAME', help='The name of priority to search for. (default: )')
    c.add_argument('--only-default', dest='p_only_default', action=argparse.BooleanOptionalAction, help='Whether only the default priority is returned. (default: False)')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use `schemes` to return the associated priority schemes for each priority. Limited to returning first 15 priority schemes per priority. (default: )')
    c.set_defaults(handler=_run_issue_priorities_search_priorities, flags={'start_at': '--start-at', 'max_results': '--max-results', 'id': '--id', 'project_id': '--project-id', 'priority_name': '--priority-name', 'only_default': '--only-default', 'expand': '--expand'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'search_priorities'})
    c = g_issue_priorities_commands.add_parser('get-priority', parents=[common], help='Get priority', description='Returns an issue priority. To fetch multiple priorities at once, use [Search\npriorities](#api-rest-api-3-priority-search-get) instead.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-priorities get-priority ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the issue priority.')
