    c = g_issue_priorities_commands.add_parser('update-priority', parents=[common], help='Update priority', description='Updates an issue priority.\n\nAt least one request body parameter must be defined.\n\n**Deprecation notice:** The `iconUrl` parameter was sunset on 16th Mar 2025,\nand replaced with `avatarId`. See\n[CHANGE-1525](https://developer.atlassian.com/changelog/#CHANGE-1525).\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-priorities update-priority ID --avatar-id AVATAR_ID', 'codapact-jira issue-priorities update-priority ID --avatar-id AVATAR_ID --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the issue priority.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.add_argument('--avatar-id', dest='p_avatar_id', type=integer, metavar='AVATAR_ID', help='The ID for the avatar for the priority. This parameter is nullable and both iconUrl and avatarId cannot be defined.')
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='The description of the priority.')
    c.add_argument('--icon-url', dest='p_icon_url', choices=['/images/icons/priorities/blocker.png', '/images/icons/priorities/critical.png', '/images/icons/priorities/high.png', '/images/icons/priorities/highest.png', '/images/icons/priorities/low.png', '/images/icons/priorities/lowest.png', '/images/icons/priorities/major.png', '/images/icons/priorities/medium.png', '/images/icons/priorities/minor.png', '/images/icons/priorities/trivial.png', '/images/icons/priorities/blocker_new.png', '/images/icons/priorities/critical_new.png', '/images/icons/priorities/high_new.png', '/images/icons/priorities/highest_new.png', '/images/icons/priorities/low_new.png', '/images/icons/priorities/lowest_new.png', '/images/icons/priorities/major_new.png', '/images/icons/priorities/medium_new.png', '/images/icons/priorities/minor_new.png', '/images/icons/priorities/trivial_new.png'], help='The URL of an icon for the priority. Accepted protocols are HTTP and HTTPS. Built in icons can also be used. Both iconUrl and avatarId cannot be defined.')
    c.add_argument('--name', dest='p_name', metavar='NAME', help='The name of the priority. Must be unique.')
    c.add_argument('--status-color', dest='p_status_color', metavar='STATUS_COLOR', help='The status color of the priority in 3-digit or 6-digit hexadecimal format.')
    c.set_defaults(handler=_run_issue_priorities_update_priority, flags={'id': '--id', 'body.avatar_id': '--avatar-id', 'body.description': '--description', 'body.icon_url': '--icon-url', 'body.name': '--name', 'body.status_color': '--status-color'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_priority', 'requires_one_of': [['--avatar-id', '--description', '--icon-url', '--name', '--status-color']]})
    c = g_issue_priorities_commands.add_parser('delete-priority', parents=[common], help='Delete priority', description='Deletes an issue priority.\n\nThis operation is [asynchronous](#async). Follow the `location` link in the\nresponse to determine the status of the task and use [Get task](#api-rest-\napi-3-task-taskId-get) to obtain subsequent updates.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-priorities delete-priority ID --dry-run', 'codapact-jira issue-priorities delete-priority ID --yes']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the issue priority.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_issue_priorities_delete_priority, flags={'id': '--id'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_priority'})
    g_issue_properties = commands.add_parser('issue-properties', help='bulk-by-issue, bulk-delete, bulk-set, … (8 commands)', description="Run 'codapact-jira issue-properties COMMAND --help' for a command's options and examples.")
    g_issue_properties_commands = g_issue_properties.add_subparsers(dest="g_issue_properties", metavar="COMMAND", required=True)
    c = g_issue_properties_commands.add_parser('bulk-set-issues-properties-list', parents=[common], help='Bulk set issues properties by list', description='Sets or updates a list of entity property values on issues. A list of up to 10\nentity properties can be specified along with up to 10,000 issues on which to\nset or update that list of entity properties.\n\nThe value of the request body must be a\n[valid](http://tools.ietf.org/html/rfc4627), non-empty JSON. The maximum\nlength of single issue property value is 32768 characters. This operation can\nbe accessed anonymously.\n\nThis operation is:\n\n* transactional, either all properties are updated in all eligible issues or,\nwhen errors occur, no properties are updated. * [asynchronous](#async). Follow\nthe `location` link in the response to determine the status of the task and\nuse [Get task](#api-rest-api-3-task-taskId-get) to obtain subsequent updates.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* and *Edit issues* [project\npermissions](https://confluence.atlassian.com/x/yodKLg) for the project\ncontaining the issue. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-properties bulk-set-issues-properties-list --entities-ids ENTITIES_IDS', 'codapact-jira issue-properties bulk-set-issues-properties-list --entities-ids ENTITIES_IDS --dry-run']), formatter_class=RAW)
    c.add_argument('--entities-ids', dest='p_entities_ids', action="append", type=integer, metavar='ENTITIES_IDS', help='A list of entity property IDs.')
    c.add_argument('--properties', dest='p_properties', type=json_value, metavar="JSON", help='A list of entity property keys and values.')
    c.set_defaults(handler=_run_issue_properties_bulk_set_issues_properties_list, flags={'body.entities_ids': '--entities-ids', 'body.properties': '--properties'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'bulk_set_issues_properties_list', 'requires_one_of': [['--entities-ids', '--properties']]})
    c = g_issue_properties_commands.add_parser('bulk-by-issue', parents=[common], help='Bulk set issue properties by issue', description='Sets or updates entity property values on issues. Up to 10 entity properties\ncan be specified for each issue and up to 100 issues included in the request.\n\nThe value of the request body must be a\n[valid](http://tools.ietf.org/html/rfc4627), non-empty JSON.\n\nThis operation is:\n\n* [asynchronous](#async). Follow the `location` link in the response to\ndetermine the status of the task and use [Get task](#api-rest-api-3-task-\ntaskId-get) to obtain subsequent updates. * non-transactional. Updating some\nentities may fail. Such information will available in the task result.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* and *Edit issues* [project\npermissions](https://confluence.atlassian.com/x/yodKLg) for the project\ncontaining the issue. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-properties bulk-by-issue --issues @issues.json', 'codapact-jira issue-properties bulk-by-issue --issues @issues.json --dry-run']), formatter_class=RAW)
    c.add_argument('--issues', dest='p_issues', type=json_value, metavar="JSON", help='A list of issue IDs and their respective properties. JSON array of objects with issue_id, properties. Schema: codapact-jira describe issue-properties bulk-by-issue')
    c.set_defaults(handler=_run_issue_properties_bulk_by_issue, flags={'body.issues': '--issues'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'bulk_set_issue_properties_by_issue', 'requires_one_of': [['--issues']]})
    c = g_issue_properties_commands.add_parser('bulk-set', parents=[common], help='Bulk set issue property', description='Sets a property value on multiple issues.\n\nThe value set can be a constant or determined by a [Jira\nexpression](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions/). Expressions must be computable with constant complexity when\napplied to a set of issues. Expressions must also comply with the\n[restrictions](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions/#restrictions) that apply to all Jira expressions.\n\nThe issues to be updated can be specified by a filter.\n\nThe filter identifies issues eligible for update using these criteria:\n\n* `entityIds` Only issues from this list are eligible. * `currentValue` Only\nissues with the property set to this value are eligible. * `hasProperty`: * If\n*true*, only issues with the property are eligible. * If *false*, only issues\nwithout the property are eligible.\n\nIf more than one criteria is specified, they are joined with the logical\n*AND*: only issues that satisfy all criteria are eligible.\n\nIf an invalid combination of criteria is provided, an error is returned. For\nexample, specifying a `currentValue` and `hasProperty` as *false* would not\nmatch any issues (because without the property the property cannot have a\nvalue).\n\nThe filter is optional. Without the filter all the issues visible to the user\nand where the user has the EDIT\\_ISSUES permission for the issue are\nconsidered eligible.\n\nThis operation is:\n\n* transactional, either all eligible issues are updated or, when errors occur,\nnone are updated. * [asynchronous](#async). Follow the `location` link in the\nresponse to determine the status of the task and use [Get task](#api-rest-\napi-3-task-taskId-get) to obtain subsequent updates.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for each project\ncontaining issues. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * *Edit issues* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for each issue.', usage='%(prog)s PROPERTY_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-properties bulk-set PROPERTY_KEY --expression EXPRESSION', 'codapact-jira issue-properties bulk-set PROPERTY_KEY --expression EXPRESSION --dry-run']), formatter_class=RAW)
    c.add_argument('p_property_key', metavar='PROPERTY_KEY', nargs='?', default=argparse.SUPPRESS, help='The key of the property. The maximum length is 255 characters.')
    c.add_argument('--property-key', dest='p_property_key', default=argparse.SUPPRESS, metavar='PROPERTY_KEY', help='same as PROPERTY_KEY')
    c.add_argument('--expression', dest='p_expression', metavar='EXPRESSION', help='EXPERIMENTAL. The Jira expression to calculate the value of the property. The value of the expression must be an object that can be converted to JSON, such as a number, boolean, string, list, or map. The context variables available to the expression are `issue` and `user`. Issues for which the expression returns a value whose JSON representation is longer than 32768 characters are ignored.')
    c.add_argument('--filter', dest='p_filter', type=json_value, metavar="JSON", help='The bulk operation filter. JSON object with current_value, entity_ids, has_property. Schema: codapact-jira describe issue-properties bulk-set')
    c.add_argument('--value', dest='p_value', type=json_value, metavar="JSON", help='The value of the property. The value must be a [valid](https://tools.ietf.org/html/rfc4627), non-empty JSON blob. The maximum length is 32768 characters.')
    c.set_defaults(handler=_run_issue_properties_bulk_set, flags={'property_key': '--property-key', 'body.expression': '--expression', 'body.filter': '--filter', 'body.value': '--value'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'bulk_set_issue_property', 'requires_one_of': [['--expression', '--filter', '--value']]})
    c = g_issue_properties_commands.add_parser('bulk-delete', parents=[common], help='Bulk delete issue property', description='Deletes a property value from multiple issues. The issues to be updated can be\nspecified by filter criteria.\n\nThe criteria the filter used to identify eligible issues are:\n\n* `entityIds` Only issues from this list are eligible. * `currentValue` Only\nissues with the property set to this value are eligible.\n\nIf both criteria is specified, they are joined with the logical *AND*: only\nissues that satisfy both criteria are considered eligible.\n\nIf no filter criteria are specified, all the issues visible to the user and\nwhere the user has the EDIT\\_ISSUES permission for the issue are considered\neligible.\n\nThis operation is:\n\n* transactional, either the property is deleted from all eligible issues or,\nwhen errors occur, no properties are deleted. * [asynchronous](#async). Follow\nthe `location` link in the response to determine the status of the task and\nuse [Get task](#api-rest-api-3-task-taskId-get) to obtain subsequent updates.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [ project\npermission](https://confluence.atlassian.com/x/yodKLg) for each project\ncontaining issues. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * *Edit issues* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for each issue.', usage='%(prog)s PROPERTY_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-properties bulk-delete PROPERTY_KEY --current-value @current-value.json --dry-run', 'codapact-jira issue-properties bulk-delete PROPERTY_KEY --current-value @current-value.json --yes']), formatter_class=RAW)
    c.add_argument('p_property_key', metavar='PROPERTY_KEY', nargs='?', default=argparse.SUPPRESS, help='The key of the property.')
    c.add_argument('--property-key', dest='p_property_key', default=argparse.SUPPRESS, metavar='PROPERTY_KEY', help='same as PROPERTY_KEY')
    c.add_argument('--current-value', dest='p_current_value', type=json_value, metavar="JSON", help='The value of properties to perform the bulk operation on.')
    c.add_argument('--entity-ids', dest='p_entity_ids', action="append", type=integer, metavar='ENTITY_IDS', help='List of issues to perform the bulk delete operation on.')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_issue_properties_bulk_delete, flags={'property_key': '--property-key', 'body.current_value': '--current-value', 'body.entity_ids': '--entity-ids'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'bulk_delete_issue_property', 'requires_one_of': [['--current-value', '--entity-ids']]})
    c = g_issue_properties_commands.add_parser('list-keys', parents=[common], help='Get issue property keys', description="Returns the URLs and keys of an issue's properties.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** Property details are only returned\nwhere the user has:\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project\ncontaining the issue. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.", usage='%(prog)s ISSUE_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-properties list-keys ISSUE_ID_OR_KEY']), formatter_class=RAW)
