    g_issue_redaction = commands.add_parser('issue-redaction', help='get-redaction-status, redact', description="Run 'codapact-jira issue-redaction COMMAND --help' for a command's options and examples.")
    g_issue_redaction_commands = g_issue_redaction.add_subparsers(dest="g_issue_redaction", metavar="COMMAND", required=True)
