    c = g_issue_redaction_commands.add_parser('get-redaction-status', parents=[common], help='Get redaction status', description='Retrieves the current status of a redaction job ID.\n\nThe jobStatus will be one of the following:\n\n* IN\\_PROGRESS - The redaction job is currently in progress * COMPLETED - The\nredaction job has completed successfully. * PENDING - The redaction job has\nnot started yet', usage='%(prog)s JOB_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-redaction get-redaction-status JOB_ID']), formatter_class=RAW)
