    g_issue_remote_links = commands.add_parser('issue-remote-links', help='create-or-update-remote-issue-link, delete-remote-issue-link, delete-remote-issue-link-by-global-id, … (6 commands)', description="Run 'codapact-jira issue-remote-links COMMAND --help' for a command's options and examples.")
