    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--application', dest='p_application', type=json_value, metavar="JSON", help='Details of the remote application the linked item is in. For example, trello. JSON object with name, type. Schema: codapact-jira describe issue-remote-links create-or-update-remote-issue-link')
    c.add_argument('--global-id', dest='p_global_id', metavar='GLOBAL_ID', help='An identifier for the remote item in the remote system. For example, the global ID for a remote item in Confluence would consist of the app ID and page ID, like this: `appId=456&pageId=123`.')
    c.add_argument('--object', dest='p_object', type=json_value, metavar="JSON", required=True, help='Details of the item linked to. JSON object with title*, url*, icon, status, summary (* required). Schema: codapact-jira describe issue-remote-links create-or-update-remote-issue-link')
    c.add_argument('--relationship', dest='p_relationship', metavar='RELATIONSHIP', help='Description of the relationship between the issue and the linked item. If not set, the relationship description "links to" is used in Jira.')
