    c = g_issue_remote_links_commands.add_parser('delete-remote-issue-link-by-global-id', parents=[common], help='Delete remote issue link by global ID', description="Deletes the remote issue link from the issue using the link's global ID. Where\nthe global ID includes reserved URL characters these must be escaped in the\nrequest. For example, pass `system=http://www.mycompany.com/support&id=1` as\n`system%3Dhttp%3A%2F%2Fwww.mycompany.com%2Fsupport%26id%3D1`.\n\nThis operation requires [issue linking to be\nactive](https://confluence.atlassian.com/x/yoXKM).\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* and *Link issues* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is implemented, issue-\nlevel security permission to view the issue.", usage='%(prog)s ISSUE_ID_OR_KEY --global-id GLOBAL_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-remote-links delete-remote-issue-link-by-global-id ISSUE_ID_OR_KEY --global-id GLOBAL_ID --dry-run', 'codapact-jira issue-remote-links delete-remote-issue-link-by-global-id ISSUE_ID_OR_KEY --global-id GLOBAL_ID --yes']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
