    c = g_issue_search_commands.add_parser('search-issues', parents=[common], help='Search for issues using JQL enhanced search (GET)', description='Searches for issues using [JQL](https://confluence.atlassian.com/x/egORLQ).\nRecent updates might not be immediately visible in the returned search\nresults. If you need [read-after-\nwrite](https://developer.atlassian.com/cloud/jira/platform/search-and-\nreconcile/) consistency, you can utilize the `reconcileIssues` parameter to\nensure stronger consistency assurances. This operation can be accessed\nanonymously.\n\nIf the JQL query expression is too large to be encoded as a query parameter,\nuse the [POST](#api-rest-api-3-search-post) version of this resource.\n\n**[Permissions](#permissions) required:** Issues are included in the response\nwhere the user has:\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project\ncontaining the issue. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-search search-issues']), formatter_class=RAW)
    c.add_argument('--jql', dest='p_jql', metavar='JQL', help='A [JQL](https://confluence.atlassian.com/x/egORLQ) expression. For performance reasons, this parameter requires a bounded query. A bounded query is a query with a search restriction.')
    c.add_argument('--next-page-token', dest='p_next_page_token', metavar='NEXT_PAGE_TOKEN', help='The token for a page to fetch that is not the first page. The first page has a `nextPageToken` of `null`. Use the `nextPageToken` to fetch the next page of issues.')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. To manage page size, API may return fewer items per page where a large number of fields or properties are requested. The greatest number of items returned per page is achieved when requesting `id` or `key` only. It returns max 5000 issues. (default: 50)')
    c.add_argument('--fields', dest='p_fields', action="append", metavar='FIELDS', help='A list of fields to return for each issue, use it to retrieve a subset of fields. This parameter accepts a comma-separated list. Expand options include:')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about issues in the response. Note that, unlike the majority of instances where `expand` is specified, `expand` is defined as a comma-delimited string of values. The expand options are:')
    c.add_argument('--properties', dest='p_properties', action="append", metavar='PROPERTIES', help='A list of up to 5 issue properties to include in the results. This parameter accepts a comma-separated list.')
