    c.add_argument('--reconcile-issues', dest='p_reconcile_issues', action="append", type=integer, metavar='RECONCILE_ISSUES', help='Strong consistency issue ids to be reconciled with search results. Accepts max 50 ids. This list of ids should be consistent with each paginated request across different pages.')
    c.add_argument('--include-archived-projects', dest='p_include_archived_projects', action=argparse.BooleanOptionalAction, help='Whether to also return issues that belong to [archived projects](https://support.atlassian.com/jira-cloud-administration/docs/archive-a-project/). Issues in archived projects are excluded by default. Setting this to `true` returns them alongside issues from active projects; the *Browse projects* permission is still required on the archived project. The default is `false`. (default: False)')
    c.set_defaults(handler=_run_issue_search_search_issues, flags={'jql': '--jql', 'next_page_token': '--next-page-token', 'max_results': '--max-results', 'fields': '--fields', 'expand': '--expand', 'properties': '--properties', 'fields_by_keys': '--fields-by-keys', 'fail_fast': '--fail-fast', 'reconcile_issues': '--reconcile-issues', 'include_archived_projects': '--include-archived-projects'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'search_issues'})
