    c.set_defaults(handler=_run_issue_types_create, flags={'body.description': '--description', 'body.hierarchy_level': '--hierarchy-level', 'body.name': '--name', 'body.type': '--type'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_issue_type'})
    c = g_issue_types_commands.add_parser('get-for-project', parents=[common], help='Get issue types for project', description='Returns issue types for a project.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) in the relevant project\nor *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --project-id PROJECT_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-types get-for-project --project-id PROJECT_ID']), formatter_class=RAW)
    c.add_argument('--project-id', dest='p_project_id', type=integer, metavar='PROJECT_ID', required=True, help='The ID of the project.')
    c.add_argument('--level', dest='p_level', type=integer, metavar='LEVEL', help='The level of the issue type to filter by. Use:')
