    c = g_issue_types_commands.add_parser('update', parents=[common], help='Update issue type', description='Updates the issue type.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-types update ID --avatar-id AVATAR_ID', 'codapact-jira issue-types update ID --avatar-id AVATAR_ID --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the issue type.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
