    c.set_defaults(handler=_run_issue_types_delete, flags={'id': '--id', 'alternative_issue_type_id': '--alternative-issue-type-id'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_issue_type'})
    c = g_issue_types_commands.add_parser('list', parents=[common], help='Get alternative issue types', description='Returns a list of issue types that can be used to replace the issue type. The\nalternative issue types are those assigned to the same workflow scheme, field\nconfiguration scheme, and screen scheme.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-types list ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the issue type.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.set_defaults(handler=_run_issue_types_list, flags={'id': '--id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_alternative_issue_types'})
    c = g_issue_types_commands.add_parser('create-avatar', parents=[common], help='Load issue type avatar', description='Loads an avatar for the issue type.\n\nSpecify the avatar\'s local file location in the body of the request. Also,\ninclude the following headers:\n\n* `X-Atlassian-Token: no-check` To prevent XSRF protection blocking the\nrequest, for more information see [Special Headers](#special-request-headers).\n* `Content-Type: image/image type` Valid image types are JPEG, GIF, or PNG.\n\nFor example: `curl --request POST \\ --user email@example.com:<api_token> \\\n--header \'X-Atlassian-Token: no-check\' \\ --header \'Content-Type: image/<\nimage_type>\' \\ --data-binary "<@/path/to/file/with/your/avatar>" \\ --url\n\'https://your-domain.atlassian.net/rest/api/3/issuetype/{issueTypeId}\'This`\n\nThe avatar is cropped to a square. If no crop parameters are specified, the\nsquare originates at the top left of the image. The length of the square\'s\nsides is set to the smaller of the height or width of the image.\n\nThe cropped image is then used to create avatars of 16x16, 24x24, 32x32, and\n48x48 in size.\n\nAfter creating the avatar, use [ Update issue type](#api-rest-api-3-issuetype-\nid-put) to set it as the issue type\'s displayed avatar.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID --size SIZE --body BODY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-types create-avatar ID --size SIZE --body BODY', 'codapact-jira issue-types create-avatar ID --size SIZE --body BODY --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the issue type.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.add_argument('--x', dest='p_x', type=integer, metavar='X', help='The X coordinate of the top-left corner of the crop region. (default: 0)')
    c.add_argument('--y', dest='p_y', type=integer, metavar='Y', help='The Y coordinate of the top-left corner of the crop region. (default: 0)')
    c.add_argument('--size', dest='p_size', type=integer, metavar='SIZE', required=True, help='The length of each side of the crop region.')
    c.add_argument('--body', dest='p_body', type=binary_value, metavar='BODY', required=True)
    c.set_defaults(handler=_run_issue_types_create_avatar, flags={'id': '--id', 'x': '--x', 'y': '--y', 'size': '--size', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_issue_type_avatar'})
