    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.set_defaults(handler=_run_issue_votes_add_vote, flags={'issue_id_or_key': '--issue-id-or-key'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'add_vote'})
    c = g_issue_votes_commands.add_parser('remove-vote', parents=[common], help='Delete vote', description="Deletes a user's vote from an issue. This is the equivalent of the user\nclicking *Unvote* on an issue in Jira.\n\nThis operation requires the **Allow users to vote on issues** option to be\n*ON*. This option is set in General configuration for Jira. See [Configuring\nJira application options](https://confluence.atlassian.com/x/uYXKM) for\ndetails.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.", usage='%(prog)s ISSUE_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-votes remove-vote ISSUE_ID_OR_KEY --dry-run', 'codapact-jira issue-votes remove-vote ISSUE_ID_OR_KEY --yes']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    RUNTIME.add_confirm_option(c)
