    c.add_argument('p_worklog_id', metavar='WORKLOG_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the worklog.')
    c.add_argument('p_property_key', metavar='PROPERTY_KEY', nargs='?', default=argparse.SUPPRESS, help='The key of the issue property. The maximum length is 255 characters.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--worklog-id', dest='p_worklog_id', default=argparse.SUPPRESS, metavar='WORKLOG_ID', help='same as WORKLOG_ID')
    c.add_argument('--property-key', dest='p_property_key', default=argparse.SUPPRESS, metavar='PROPERTY_KEY', help='same as PROPERTY_KEY')
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='The value of the property. The value has to be a valid, non-empty [JSON](https://tools.ietf.org/html/rfc4627) value. The maximum length of the property value is 32768 bytes.')
    c.set_defaults(handler=_run_issue_worklog_properties_set_worklog_property, flags={'issue_id_or_key': '--issue-id-or-key', 'worklog_id': '--worklog-id', 'property_key': '--property-key', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'set_worklog_property'})
    c = g_issue_worklog_properties_commands.add_parser('delete-worklog-property', parents=[common], help='Delete worklog property', description='Deletes a worklog property.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * If the worklog has visibility\nrestrictions, belongs to the group or has the role visibility is restricted\nto.', usage='%(prog)s ISSUE_ID_OR_KEY WORKLOG_ID PROPERTY_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-worklog-properties delete-worklog-property ISSUE_ID_OR_KEY WORKLOG_ID PROPERTY_KEY --dry-run', 'codapact-jira issue-worklog-properties delete-worklog-property ISSUE_ID_OR_KEY WORKLOG_ID PROPERTY_KEY --yes']), formatter_class=RAW)
