    c = g_issue_worklogs_commands.add_parser('add-worklog', parents=[common], help='Add worklog', description='Adds a worklog to an issue.\n\nTime tracking must be enabled in Jira, otherwise this operation returns an\nerror. For more information, see [Configuring time\ntracking](https://confluence.atlassian.com/x/qoXKM).\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* and *Work on issues* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s ISSUE_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-worklogs add-worklog ISSUE_ID_OR_KEY --author @author.json', 'codapact-jira issue-worklogs add-worklog ISSUE_ID_OR_KEY --author @author.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key the issue.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--notify-users', dest='p_notify_users', action=argparse.BooleanOptionalAction, help='Whether users watching the issue are notified by email. (default: True)')
    c.add_argument('--adjust-estimate', dest='p_adjust_estimate', choices=['new', 'leave', 'manual', 'auto'], help="Defines how to update the issue's time estimate, the options are: (default: auto)")
    c.add_argument('--new-estimate', dest='p_new_estimate', metavar='NEW_ESTIMATE', help="The value to set as the issue's remaining time estimate, as days (\\#d), hours (\\#h), or minutes (\\#m or \\#). For example, *2d*. Required when `adjustEstimate` is `new`.")
    c.add_argument('--reduce-by', dest='p_reduce_by', metavar='REDUCE_BY', help="The amount to reduce the issue's remaining estimate by, as days (\\#d), hours (\\#h), or minutes (\\#m). For example, *2d*. Required when `adjustEstimate` is `manual`.")
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about work logs in the response. This parameter accepts `properties`, which returns worklog properties. (default: )')
    c.add_argument('--override-editable-flag', dest='p_override_editable_flag', action=argparse.BooleanOptionalAction, help='Whether the worklog entry should be added to the issue even if the issue is not editable, because jira.issue.editable set to false or missing. For example, the issue is closed. Connect and Forge app users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg) can use this flag. (default: False)')
    c.add_argument('--author', dest='p_author', type=json_value, metavar="JSON", help='Details of the user who created the worklog. JSON object with account_id, account_type, active, avatar_urls, display_name, email_address, key, name, self, time_zone. Schema: codapact-jira describe issue-worklogs add-worklog')
    c.add_argument('--comment', dest='p_comment', type=json_value, metavar="JSON", help='A comment about the worklog in [Atlassian Document Format](https://developer.atlassian.com/cloud/jira/platform/apis/document/structure/). Optional when creating or updating a worklog.')
    c.add_argument('--created', dest='p_created', metavar='DATETIME', help='The datetime on which the worklog was created.')
    c.add_argument('--id', dest='p_id', metavar='ID', help='The ID of the worklog record.')
    c.add_argument('--issue-id', dest='p_issue_id', metavar='ISSUE_ID', help='The ID of the issue this worklog is for.')
    c.add_argument('--properties', dest='p_properties', type=json_value, metavar="JSON", help='Details of properties for the worklog. Optional when creating or updating a worklog. JSON array of objects with key, value. Schema: codapact-jira describe issue-worklogs add-worklog')
    c.add_argument('--self', dest='p_self', metavar='SELF', help='The URL of the worklog item.')
    c.add_argument('--started', dest='p_started', metavar='DATETIME', help='The datetime on which the worklog effort was started. Required when creating a worklog. Optional when updating a worklog.')
    c.add_argument('--time-spent', dest='p_time_spent', metavar='TIME_SPENT', help="The time spent working on the issue as days (\\#d), hours (\\#h), or minutes (\\#m or \\#). Required when creating a worklog if `timeSpentSeconds` isn't provided. Optional when updating a worklog. Cannot be provided if `timeSpentSecond` is provided.")
    c.add_argument('--time-spent-seconds', dest='p_time_spent_seconds', type=integer, metavar='TIME_SPENT_SECONDS', help="The time in seconds spent working on the issue. Required when creating a worklog if `timeSpent` isn't provided. Optional when updating a worklog. Cannot be provided if `timeSpent` is provided.")
    c.add_argument('--update-author', dest='p_update_author', type=json_value, metavar="JSON", help='Details of the user who last updated the worklog. JSON object with account_id, account_type, active, avatar_urls, display_name, email_address, key, name, self, time_zone. Schema: codapact-jira describe issue-worklogs add-worklog')
    c.add_argument('--updated', dest='p_updated', metavar='DATETIME', help='The datetime on which the worklog was last updated.')
    c.add_argument('--visibility', dest='p_visibility', type=json_value, metavar="JSON", help='Details about any restrictions in the visibility of the worklog. Optional when creating or updating a worklog. JSON object with identifier, type, value. Schema: codapact-jira describe issue-worklogs add-worklog')
    c.set_defaults(handler=_run_issue_worklogs_add_worklog, flags={'issue_id_or_key': '--issue-id-or-key', 'notify_users': '--notify-users', 'adjust_estimate': '--adjust-estimate', 'new_estimate': '--new-estimate', 'reduce_by': '--reduce-by', 'expand': '--expand', 'override_editable_flag': '--override-editable-flag', 'body.author': '--author', 'body.comment': '--comment', 'body.created': '--created', 'body.id': '--id', 'body.issue_id': '--issue-id', 'body.properties': '--properties', 'body.self': '--self', 'body.started': '--started', 'body.time_spent': '--time-spent', 'body.time_spent_seconds': '--time-spent-seconds', 'body.update_author': '--update-author', 'body.updated': '--updated', 'body.visibility': '--visibility'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'add_worklog', 'requires_one_of': [['--author', '--comment', '--created', '--id', '--issue-id', '--properties', '--self', '--started', '--time-spent', '--time-spent-seconds', '--update-author', '--updated', '--visibility']]})
    c = g_issue_worklogs_commands.add_parser('bulk-delete-worklogs', parents=[common], help='Bulk delete worklogs', description="Deletes a list of worklogs from an issue. This is an experimental API with\nlimitations:\n\n* You can't delete more than 5000 worklogs at once. * No notifications will be\nsent for deleted worklogs.\n\nTime tracking must be enabled in Jira, otherwise this operation returns an\nerror. For more information, see [Configuring time\ntracking](https://confluence.atlassian.com/x/qoXKM).\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project\ncontaining the issue. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * *Delete all worklogs*[ project\npermission](https://confluence.atlassian.com/x/yodKLg) to delete any worklog.\n* If any worklog has visibility restrictions, belongs to the group or has the\nrole visibility is restricted to.", usage='%(prog)s ISSUE_ID_OR_KEY --ids IDS [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-worklogs bulk-delete-worklogs ISSUE_ID_OR_KEY --ids IDS --dry-run', 'codapact-jira issue-worklogs bulk-delete-worklogs ISSUE_ID_OR_KEY --ids IDS --yes']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--adjust-estimate', dest='p_adjust_estimate', choices=['leave', 'auto'], help="Defines how to update the issue's time estimate, the options are: (default: auto)")
    c.add_argument('--override-editable-flag', dest='p_override_editable_flag', action=argparse.BooleanOptionalAction, help='Whether the work log entries should be removed to the issue even if the issue is not editable, because jira.issue.editable set to false or missing. For example, the issue is closed. Connect and Forge app users with admin permission can use this flag. (default: False)')
    c.add_argument('--ids', dest='p_ids', action="append", type=integer, metavar='IDS', required=True, help='A list of worklog IDs.')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_issue_worklogs_bulk_delete_worklogs, flags={'issue_id_or_key': '--issue-id-or-key', 'adjust_estimate': '--adjust-estimate', 'override_editable_flag': '--override-editable-flag', 'body.ids': '--ids'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'bulk_delete_worklogs'})
    c = g_issue_worklogs_commands.add_parser('bulk-move-worklogs', parents=[common], help='Bulk move worklogs', description="Moves a list of worklogs from one issue to another. This is an experimental\nAPI with several limitations:\n\n* You can't move more than 5000 worklogs at once. * You can't move worklogs\ncontaining an attachment. * You can't move worklogs restricted by project\nroles. * No notifications will be sent for moved worklogs. * No webhooks or\nevents will be sent for moved worklogs. * No issue history will be recorded\nfor moved worklogs.\n\nTime tracking must be enabled in Jira, otherwise this operation returns an\nerror. For more information, see [Configuring time\ntracking](https://confluence.atlassian.com/x/qoXKM).\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the projects\ncontaining the source and destination issues. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * *Delete all worklogs* [project\npermission](https://confluence.atlassian.com/x/yodKLg) * *Work on issues*\n[project permission](https://confluence.atlassian.com/x/yodKLg) to log work on\nan issue, that is to create a worklog entry, if time tracking is enabled. This\npermission is required as a prerequisite for applying the other time-tracking\npermissions * If the worklog has visibility restrictions, belongs to the group\nor has the role visibility is restricted to.", usage='%(prog)s ISSUE_ID_OR_KEY --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-worklogs bulk-move-worklogs ISSUE_ID_OR_KEY --body @body.json', 'codapact-jira issue-worklogs bulk-move-worklogs ISSUE_ID_OR_KEY --body @body.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS)
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--adjust-estimate', dest='p_adjust_estimate', choices=['leave', 'auto'], help="Defines how to update the issues' time estimate, the options are: (default: auto)")
    c.add_argument('--override-editable-flag', dest='p_override_editable_flag', action=argparse.BooleanOptionalAction, help='Whether the work log entry should be moved to and from the issues even if the issues are not editable, because jira.issue.editable set to false or missing. For example, the issue is closed. Connect and Forge app users with admin permission can use this flag. (default: False)')
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='A JSON object containing a list of worklog IDs and the ID or key of the destination issue. JSON object with ids, issue_id_or_key. Schema: codapact-jira describe issue-worklogs bulk-move-worklogs')
    c.set_defaults(handler=_run_issue_worklogs_bulk_move_worklogs, flags={'issue_id_or_key': '--issue-id-or-key', 'adjust_estimate': '--adjust-estimate', 'override_editable_flag': '--override-editable-flag', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'bulk_move_worklogs'})
    c = g_issue_worklogs_commands.add_parser('get-worklog', parents=[common], help='Get worklog', description='Returns a worklog.\n\nTime tracking must be enabled in Jira, otherwise this operation returns an\nerror. For more information, see [Configuring time\ntracking](https://confluence.atlassian.com/x/qoXKM).\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * If the worklog has visibility\nrestrictions, belongs to the group or has the role visibility is restricted\nto.', usage='%(prog)s ISSUE_ID_OR_KEY ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-worklogs get-worklog ISSUE_ID_OR_KEY ID']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
