    c = g_issue_worklogs_commands.add_parser('update-worklog', parents=[common], help='Update worklog', description='Updates a worklog.\n\nTime tracking must be enabled in Jira, otherwise this operation returns an\nerror. For more information, see [Configuring time\ntracking](https://confluence.atlassian.com/x/qoXKM).\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * *Edit all worklogs*[ project\npermission](https://confluence.atlassian.com/x/yodKLg) to update any worklog\nor *Edit own worklogs* to update worklogs created by the user. * If the\nworklog has visibility restrictions, belongs to the group or has the role\nvisibility is restricted to.', usage='%(prog)s ISSUE_ID_OR_KEY ID --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-worklogs update-worklog ISSUE_ID_OR_KEY ID --body @body.json', 'codapact-jira issue-worklogs update-worklog ISSUE_ID_OR_KEY ID --body @body.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key the issue.')
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the worklog.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.add_argument('--notify-users', dest='p_notify_users', action=argparse.BooleanOptionalAction, help='Whether users watching the issue are notified by email. (default: True)')
    c.add_argument('--adjust-estimate', dest='p_adjust_estimate', choices=['new', 'leave', 'manual', 'auto'], help="Defines how to update the issue's time estimate, the options are: (default: auto)")
    c.add_argument('--new-estimate', dest='p_new_estimate', metavar='NEW_ESTIMATE', help="The value to set as the issue's remaining time estimate, as days (\\#d), hours (\\#h), or minutes (\\#m or \\#). For example, *2d*. Required when `adjustEstimate` is `new`.")
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about worklogs in the response. This parameter accepts `properties`, which returns worklog properties. (default: )')
    c.add_argument('--override-editable-flag', dest='p_override_editable_flag', action=argparse.BooleanOptionalAction, help='Whether the worklog should be added to the issue even if the issue is not editable. For example, because the issue is closed. Connect and Forge app users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg) can use this flag. (default: False)')
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='JSON object with author, comment, created, id, issue_id, properties, self, started, time_spent, time_spent_seconds, update_author, updated, ... Schema: codapact-jira describe issue-worklogs update-worklog')
    c.set_defaults(handler=_run_issue_worklogs_update_worklog, flags={'issue_id_or_key': '--issue-id-or-key', 'id': '--id', 'notify_users': '--notify-users', 'adjust_estimate': '--adjust-estimate', 'new_estimate': '--new-estimate', 'expand': '--expand', 'override_editable_flag': '--override-editable-flag', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_worklog'})
    c = g_issue_worklogs_commands.add_parser('delete-worklog', parents=[common], help='Delete worklog', description='Deletes a worklog from an issue.\n\nTime tracking must be enabled in Jira, otherwise this operation returns an\nerror. For more information, see [Configuring time\ntracking](https://confluence.atlassian.com/x/qoXKM).\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue. * *Delete all worklogs*[ project\npermission](https://confluence.atlassian.com/x/yodKLg) to delete any worklog\nor *Delete own worklogs* to delete worklogs created by the user, * If the\nworklog has visibility restrictions, belongs to the group or has the role\nvisibility is restricted to.', usage='%(prog)s ISSUE_ID_OR_KEY ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-worklogs delete-worklog ISSUE_ID_OR_KEY ID --dry-run', 'codapact-jira issue-worklogs delete-worklog ISSUE_ID_OR_KEY ID --yes']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the worklog.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.add_argument('--notify-users', dest='p_notify_users', action=argparse.BooleanOptionalAction, help='Whether users watching the issue are notified by email. (default: True)')
    c.add_argument('--adjust-estimate', dest='p_adjust_estimate', choices=['new', 'leave', 'manual', 'auto'], help="Defines how to update the issue's time estimate, the options are: (default: auto)")
    c.add_argument('--new-estimate', dest='p_new_estimate', metavar='NEW_ESTIMATE', help="The value to set as the issue's remaining time estimate, as days (\\#d), hours (\\#h), or minutes (\\#m or \\#). For example, *2d*. Required when `adjustEstimate` is `new`.")
    c.add_argument('--increase-by', dest='p_increase_by', metavar='INCREASE_BY', help="The amount to increase the issue's remaining estimate by, as days (\\#d), hours (\\#h), or minutes (\\#m or \\#). For example, *2d*. Required when `adjustEstimate` is `manual`.")
    c.add_argument('--override-editable-flag', dest='p_override_editable_flag', action=argparse.BooleanOptionalAction, help='Whether the work log entry should be added to the issue even if the issue is not editable, because jira.issue.editable set to false or missing. For example, the issue is closed. Connect and Forge app users with admin permission can use this flag. (default: False)')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_issue_worklogs_delete_worklog, flags={'issue_id_or_key': '--issue-id-or-key', 'id': '--id', 'notify_users': '--notify-users', 'adjust_estimate': '--adjust-estimate', 'new_estimate': '--new-estimate', 'increase_by': '--increase-by', 'override_editable_flag': '--override-editable-flag'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_worklog'})
    c = g_issue_worklogs_commands.add_parser('get-ids-of-worklogs-deleted-since', parents=[common], help='Get IDs of deleted worklogs', description='Returns a list of IDs and delete timestamps for worklogs deleted after a date\nand time.\n\nThis resource is paginated, with a limit of 1000 worklogs per page. Each page\nlists worklogs from oldest to youngest. If the number of items in the date\nrange exceeds 1000, `until` indicates the timestamp of the youngest item on\nthe page. Also, `nextPage` provides the URL for the next page of worklogs. The\n`lastPage` parameter is set to true on the last page of worklogs.\n\nThis resource does not return worklogs deleted during the minute preceding the\nrequest.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-worklogs get-ids-of-worklogs-deleted-since']), formatter_class=RAW)
    c.add_argument('--since', dest='p_since', type=integer, metavar='SINCE', help='The date and time, as a UNIX timestamp in milliseconds, after which deleted worklogs are returned. (default: 0)')
    c.set_defaults(handler=_run_issue_worklogs_get_ids_of_worklogs_deleted_since, flags={'since': '--since'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_ids_of_worklogs_deleted_since'})
    c = g_issue_worklogs_commands.add_parser('list-worklogs-for-ids', parents=[common], help='Get worklogs', description='Returns worklog details for a list of worklog IDs.\n\nThe returned list of worklogs is limited to 1000 items.\n\n**[Permissions](#permissions) required:** Permission to access Jira, however,\nworklogs are only returned where either of the following is true:\n\n* the worklog is set as *Viewable by All Users*. * the user is a member of a\nproject role or group with permission to view the worklog.', usage='%(prog)s --ids IDS [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-worklogs list-worklogs-for-ids --ids IDS', 'codapact-jira issue-worklogs list-worklogs-for-ids --ids IDS --dry-run']), formatter_class=RAW)
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about worklogs in the response. This parameter accepts `properties` that returns the properties of each worklog. (default: )')
    c.add_argument('--ids', dest='p_ids', action="append", type=integer, metavar='IDS', required=True, help='A list of worklog IDs.')
    c.set_defaults(handler=_run_issue_worklogs_list_worklogs_for_ids, flags={'expand': '--expand', 'body.ids': '--ids'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_worklogs_for_ids'})
    c = g_issue_worklogs_commands.add_parser('get-ids-of-worklogs-modified-since', parents=[common], help='Get IDs of updated worklogs', description='Returns a list of IDs and update timestamps for worklogs updated after a date\nand time.\n\nThis resource is paginated, with a limit of 1000 worklogs per page. Each page\nlists worklogs from oldest to youngest. If the number of items in the date\nrange exceeds 1000, `until` indicates the timestamp of the youngest item on\nthe page. Also, `nextPage` provides the URL for the next page of worklogs. The\n`lastPage` parameter is set to true on the last page of worklogs.\n\nThis resource does not return worklogs updated during the minute preceding the\nrequest.\n\n**[Permissions](#permissions) required:** Permission to access Jira, however,\nworklogs are only returned where either of the following is true:\n\n* the worklog is set as *Viewable by All Users*. * the user is a member of a\nproject role or group with permission to view the worklog.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issue-worklogs get-ids-of-worklogs-modified-since']), formatter_class=RAW)
    c.add_argument('--since', dest='p_since', type=integer, metavar='SINCE', help='The date and time, as a UNIX timestamp in milliseconds, after which updated worklogs are returned. (default: 0)')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about worklogs in the response. This parameter accepts `properties` that returns the properties of each worklog. (default: )')
    c.set_defaults(handler=_run_issue_worklogs_get_ids_of_worklogs_modified_since, flags={'since': '--since', 'expand': '--expand'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_ids_of_worklogs_modified_since'})
