    g_issues_commands = g_issues.add_subparsers(dest="g_issues", metavar="COMMAND", required=True)
    c = g_issues_commands.add_parser('list-bulk-changelogs', parents=[common], help='Bulk fetch changelogs', description='Bulk fetch changelogs for multiple issues and filter by fields\n\nReturns a paginated list of all changelogs for given issues sorted by\nchangelog date and issue IDs, starting from the oldest changelog and smallest\nissue ID.\n\nIssues are identified by their ID or key, and optionally changelogs can be\nfiltered by their field IDs. You can request the changelogs of up to 1000\nissues and can filter them by up to 10 field IDs.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the projects that\nthe issues are in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issues.', usage='%(prog)s --issue-ids-or-keys ISSUE_IDS_OR_KEYS [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues list-bulk-changelogs --issue-ids-or-keys ISSUE_IDS_OR_KEYS', 'codapact-jira issues list-bulk-changelogs --issue-ids-or-keys ISSUE_IDS_OR_KEYS --dry-run']), formatter_class=RAW)
    c.add_argument('--field-ids', dest='p_field_ids', action="append", metavar='FIELD_IDS', help='List of field IDs to filter changelogs')
    c.add_argument('--issue-ids-or-keys', dest='p_issue_ids_or_keys', action="append", metavar='ISSUE_IDS_OR_KEYS', required=True, help='List of issue IDs/keys to fetch changelogs for')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page (default: 1000)')
    c.add_argument('--next-page-token', dest='p_next_page_token', metavar='NEXT_PAGE_TOKEN', help='The cursor for pagination')
    c.set_defaults(handler=_run_issues_list_bulk_changelogs, flags={'body.field_ids': '--field-ids', 'body.issue_ids_or_keys': '--issue-ids-or-keys', 'body.max_results': '--max-results', 'body.next_page_token': '--next-page-token'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_bulk_changelogs'})
    c = g_issues_commands.add_parser('list-events', parents=[common], help='Get events', description='Returns all issue events.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues list-events']), formatter_class=RAW)
    c.set_defaults(handler=_run_issues_list_events, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_events'})
    c = g_issues_commands.add_parser('create', parents=[common], help='Create issue', description="Creates an issue or, where the option to create subtasks is enabled in Jira, a\nsubtask. A transition may be applied, to move the issue or subtask to a\nworkflow step other than the default start step, and issue properties set.\n\nThe content of the issue or subtask is defined using `update` and `fields`.\nThe fields that can be set in the issue or subtask are determined using the [\nGet create issue metadata](#api-rest-api-3-issue-createmeta-get). These are\nthe same fields that appear on the issue's create screen. Note that the\n`description`, `environment`, and any `textarea` type custom fields (multi-\nline text fields) take Atlassian Document Format content. Single line custom\nfields (`textfield`) accept a string and don't handle Atlassian Document\nFormat content.\n\nCreating a subtask differs from creating an issue as follows:\n\n* `issueType` must be set to a subtask issue type (use [ Get create issue\nmetadata](#api-rest-api-3-issue-createmeta-get) to find subtask issue types).\n* `parent` must contain the ID or key of the parent issue.\n\nIn a next-gen project any issue may be made a child providing that the parent\nand child are members of the same project.\n\n**[Permissions](#permissions) required:** *Browse projects* and *Create\nissues* [project permissions](https://confluence.atlassian.com/x/yodKLg) for\nthe project in which the issue or subtask is created.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues create --fields @fields.json', 'codapact-jira issues create --fields @fields.json --dry-run']), formatter_class=RAW)
    c.add_argument('--update-history', dest='p_update_history', action=argparse.BooleanOptionalAction, help="Whether the project in which the issue is created is added to the user's **Recently viewed** project list, as shown under **Projects** in Jira. When provided, the issue type and request type are added to the user's history for a project. These values are then used to provide defaults on the issue create screen. (default: False)")
    c.add_argument('--fields', dest='p_fields', type=json_value, metavar="JSON", help='List of issue screen fields to update, specifying the sub-field to update and its value for each field. This field provides a straightforward option when setting a sub-field. When multiple sub-fields or other operations are required, use `update`. Fields included in here cannot be included in `update`.')
    c.add_argument('--history-metadata', dest='p_history_metadata', type=json_value, metavar="JSON", help='Additional issue history details. JSON object with activity_description, activity_description_key, actor, cause, description, description_key, email_description, email_description_key, extra_data, generator, type. Schema: codapact-jira describe issues create')
    c.add_argument('--properties', dest='p_properties', type=json_value, metavar="JSON", help='Details of issue properties to be add or update. JSON array of objects with key, value. Schema: codapact-jira describe issues create')
    c.add_argument('--transition', dest='p_transition', type=json_value, metavar="JSON", help='Details of a transition. Required when performing a transition, optional when creating or editing an issue. JSON object with expand, fields, has_screen, id, is_available, is_conditional, is_global, is_initial, looped, name, to. Schema: codapact-jira describe issues create')
    c.add_argument('--update', dest='p_update', type=json_value, metavar="JSON", help='A Map containing the field field name and a list of operations to perform on the issue screen field. Note that fields included in here cannot be included in `fields`.')
    c.set_defaults(handler=_run_issues_create, flags={'update_history': '--update-history', 'body.fields': '--fields', 'body.history_metadata': '--history-metadata', 'body.properties': '--properties', 'body.transition': '--transition', 'body.update': '--update'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_issue', 'requires_one_of': [['--fields', '--history-metadata', '--properties', '--transition', '--update']]})
    c = g_issues_commands.add_parser('archive', parents=[common], help='Archive issue(s) by issue ID/key', description="Enables admins to archive up to 1000 issues in a single request using issue\nID/key, returning details of the issue(s) archived in the process and the\nerrors encountered, if any.\n\n**Note that:**\n\n* you can't archive subtasks directly, only through their parent issues * you\ncan only archive issues from software, service management, and business\nprojects\n\n**[Permissions](#permissions) required:** Jira admin or site admin: [global\npermission](https://confluence.atlassian.com/x/x4dKLg)\n\n**License required:** Premium or Enterprise\n\n**Signed-in users only:** This API can't be accessed anonymously.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues archive --issue-ids-or-keys ISSUE_IDS_OR_KEYS', 'codapact-jira issues archive --issue-ids-or-keys ISSUE_IDS_OR_KEYS --dry-run']), formatter_class=RAW)
    c.add_argument('--issue-ids-or-keys', dest='p_issue_ids_or_keys', action="append", metavar='ISSUE_IDS_OR_KEYS')
    c.set_defaults(handler=_run_issues_archive, flags={'body.issue_ids_or_keys': '--issue-ids-or-keys'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'archive_issues', 'requires_one_of': [['--issue-ids-or-keys']]})
    c = g_issues_commands.add_parser('archive-async', parents=[common], help='Archive issue(s) by JQL', description="Enables admins to archive up to 100,000 issues in a single request using JQL,\nreturning the URL to check the status of the submitted request.\n\nYou can use the [get\ntask](https://developer.atlassian.com/cloud/jira/platform/rest/v3/api-group-\ntasks/#api-rest-api-3-task-taskid-get) and [cancel\ntask](https://developer.atlassian.com/cloud/jira/platform/rest/v3/api-group-\ntasks/#api-rest-api-3-task-taskid-cancel-post) APIs to manage the request.\n\n**Note that:**\n\n* you can't archive subtasks directly, only through their parent issues * you\ncan only archive issues from software, service management, and business\nprojects\n\n**[Permissions](#permissions) required:** Jira admin or site admin: [global\npermission](https://confluence.atlassian.com/x/x4dKLg)\n\n**License required:** Premium or Enterprise\n\n**Signed-in users only:** This API can't be accessed anonymously.\n\n**Rate limiting:** Only a single request per jira instance can be active at\nany given time.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues archive-async --jql JQL', 'codapact-jira issues archive-async --jql JQL --dry-run']), formatter_class=RAW)
    c.add_argument('--jql', dest='p_jql', metavar='JQL')
    c.set_defaults(handler=_run_issues_archive_async, flags={'body.jql': '--jql'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'archive_issues_async', 'requires_one_of': [['--jql']]})
    c = g_issues_commands.add_parser('create-many', parents=[common], help='Bulk create issue', description="Creates upto **50** issues and, where the option to create subtasks is enabled\nin Jira, subtasks. Transitions may be applied, to move the issues or subtasks\nto a workflow step other than the default start step, and issue properties\nset.\n\nThe content of each issue or subtask is defined using `update` and `fields`.\nThe fields that can be set in the issue or subtask are determined using the [\nGet create issue metadata](#api-rest-api-3-issue-createmeta-get). These are\nthe same fields that appear on the issues' create screens. Note that the\n`description`, `environment`, and any `textarea` type custom fields (multi-\nline text fields) take Atlassian Document Format content. Single line custom\nfields (`textfield`) accept a string and don't handle Atlassian Document\nFormat content.\n\nCreating a subtask differs from creating an issue as follows:\n\n* `issueType` must be set to a subtask issue type (use [ Get create issue\nmetadata](#api-rest-api-3-issue-createmeta-get) to find subtask issue types).\n* `parent` the must contain the ID or key of the parent issue.\n\n**[Permissions](#permissions) required:** *Browse projects* and *Create\nissues* [project permissions](https://confluence.atlassian.com/x/yodKLg) for\nthe project in which each issue or subtask is created.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues create-many --issue-updates @issue-updates.json', 'codapact-jira issues create-many --issue-updates @issue-updates.json --dry-run']), formatter_class=RAW)
    c.add_argument('--issue-updates', dest='p_issue_updates', type=json_value, metavar="JSON", help='JSON array of objects with fields, history_metadata, properties, transition, update. Schema: codapact-jira describe issues create-many')
    c.set_defaults(handler=_run_issues_create_many, flags={'body.issue_updates': '--issue-updates'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_issues', 'requires_one_of': [['--issue-updates']]})
    c = g_issues_commands.add_parser('bulk', parents=[common], help='Bulk fetch issues', description="Returns the details for a set of requested issues.\n\nBy default you can request up to 100 issues in a single call. You can request\nup to 1000 issues in a single call when the request is shaped so that it can\nbe served efficiently, that is, when *all* of the following are true:\n\n* the `fields` parameter explicitly names at least one field to include — a\nrequest that contains only exclusions is **not** eligible, and neither are the\n`*all` and `*navigable` wildcards or the default navigable field set, because\nthe number of resolved fields depends on the site's configuration; * no more\nthan 100 fields are explicitly included; * none of the included fields returns\nmultiple values (for example `comment`, `worklog`, or `attachment`); and * the\n`expand` parameter does not include `changelog`, `editmeta`, `operations`,\n`renderedFields`, `transitions`, or `versionedRepresentations`.\n\nRequests that do not meet all of these conditions can include at most 100\nissues; larger requests are rejected with a 400 error.\n\nEach issue is identified by its ID or key, however, if the identifier doesn't\nmatch an issue, a case-insensitive search and check for moved issues is\nperformed. If a matching issue is found its details are returned, a 302 or\nother redirect is **not** returned.\n\nIssues will be returned in ascending `id` order. If there are errors, Jira\nwill return a list of issues which couldn't be fetched along with error\nmessages.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** Issues are included in the response\nwhere the user has:\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.", usage='%(prog)s --issue-ids-or-keys ISSUE_IDS_OR_KEYS [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues bulk --issue-ids-or-keys ISSUE_IDS_OR_KEYS', 'codapact-jira issues bulk --issue-ids-or-keys ISSUE_IDS_OR_KEYS --dry-run']), formatter_class=RAW)
    c.add_argument('--expand', dest='p_expand', action="append", metavar='EXPAND', help='Use [expand](#expansion) to include additional information about issues in the response. Note that, unlike the majority of instances where `expand` is specified, `expand` is defined as a list of values. The expand options are:')
    c.add_argument('--fields', dest='p_fields', action="append", metavar='FIELDS', help='A list of fields to return for each issue, use it to retrieve a subset of fields. This parameter accepts a comma-separated list. Expand options include:')
    c.add_argument('--fields-by-keys', dest='p_fields_by_keys', action=argparse.BooleanOptionalAction, help='Reference fields by their key (rather than ID). The default is `false`.')
    c.add_argument('--issue-ids-or-keys', dest='p_issue_ids_or_keys', action="append", metavar='ISSUE_IDS_OR_KEYS', required=True, help='An array of issue IDs or issue keys to fetch. You can mix issue IDs and keys in the same query. You can request up to 100 issues per call. Requests can include up to 1000 issues per call when they meet all of the conditions described for the `fields` and `expand` parameters. Requests that exceed the applicable limit are rejected with a 400 error.')
    c.add_argument('--properties', dest='p_properties', action="append", metavar='PROPERTIES', help='A list of issue property keys of issue properties to be included in the results. A maximum of 5 issue property keys can be specified.')
    c.set_defaults(handler=_run_issues_bulk, flags={'body.expand': '--expand', 'body.fields': '--fields', 'body.fields_by_keys': '--fields-by-keys', 'body.issue_ids_or_keys': '--issue-ids-or-keys', 'body.properties': '--properties'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'bulk_fetch_issues'})
    c = g_issues_commands.add_parser('get-create-meta', parents=[common], help='[deprecated] Get create issue metadata', description='Returns details of projects, issue types within projects, and, when requested,\nthe create screen fields for each issue type for the user. Use the information\nto populate the requests in [ Create issue](#api-rest-api-3-issue-post) and\n[Create issues](#api-rest-api-3-issue-bulk-post).\n\nDeprecated, see [Create Issue Meta Endpoint Deprecation Notice](https://develo\nper.atlassian.com/cloud/jira/platform/changelog/#CHANGE-1304).\n\nThe request can be restricted to specific projects or issue types using the\nquery parameters. The response will contain information for the valid\nprojects, issue types, or project and issue type combinations requested. Note\nthat invalid project, issue type, or project and issue type combinations do\nnot generate errors.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Create issues* [project\npermission](https://confluence.atlassian.com/x/yodKLg) in the requested\nprojects.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues get-create-meta']), formatter_class=RAW)
    c.add_argument('--project-ids', dest='p_project_ids', action="append", metavar='PROJECT_IDS', help='List of project IDs. This parameter accepts a comma-separated list. Multiple project IDs can also be provided using an ampersand-separated list. For example, `projectIds=10000,10001&projectIds=10020,10021`. This parameter may be provided with `projectKeys`.')
    c.add_argument('--project-keys', dest='p_project_keys', action="append", metavar='PROJECT_KEYS', help='List of project keys. This parameter accepts a comma-separated list. Multiple project keys can also be provided using an ampersand-separated list. For example, `projectKeys=proj1,proj2&projectKeys=proj3`. This parameter may be provided with `projectIds`.')
    c.add_argument('--issuetype-ids', dest='p_issuetype_ids', action="append", metavar='ISSUETYPE_IDS', help='List of issue type IDs. This parameter accepts a comma-separated list. Multiple issue type IDs can also be provided using an ampersand-separated list. For example, `issuetypeIds=10000,10001&issuetypeIds=10020,10021`. This parameter may be provided with `issuetypeNames`.')
    c.add_argument('--issuetype-names', dest='p_issuetype_names', action="append", metavar='ISSUETYPE_NAMES', help='List of issue type names. This parameter accepts a comma-separated list. Multiple issue type names can also be provided using an ampersand-separated list. For example, `issuetypeNames=name1,name2&issuetypeNames=name3`. This parameter may be provided with `issuetypeIds`.')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about issue metadata in the response. This parameter accepts `projects.issuetypes.fields`, which returns information about the fields in the issue creation screen for each issue type. Fields hidden from the screen are not returned. Use the information to populate the `fields` and `update` fields in [Create issue](#api-rest-api-3-issue-post) and [Create issues](#api-rest-api-3-issue-bulk-post).')
    c.set_defaults(handler=_run_issues_get_create_meta, flags={'project_ids': '--project-ids', 'project_keys': '--project-keys', 'issuetype_ids': '--issuetype-ids', 'issuetype_names': '--issuetype-names', 'expand': '--expand'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': True, 'operation': 'get_create_issue_meta'})
    c = g_issues_commands.add_parser('list-create-meta-issue-types', parents=[common], help='Get create metadata issue types for a project', description='Returns a page of issue type metadata for a specified project. Use the\ninformation to populate the requests in [ Create issue](#api-rest-api-3-issue-\npost) and [Create issues](#api-rest-api-3-issue-bulk-post).\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Create issues* [project\npermission](https://confluence.atlassian.com/x/yodKLg) in the requested\nprojects.', usage='%(prog)s PROJECT_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues list-create-meta-issue-types PROJECT_ID_OR_KEY']), formatter_class=RAW)
    c.add_argument('p_project_id_or_key', metavar='PROJECT_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the project.')
    c.add_argument('--project-id-or-key', dest='p_project_id_or_key', default=argparse.SUPPRESS, metavar='PROJECT_ID_OR_KEY', help='same as PROJECT_ID_OR_KEY')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.set_defaults(handler=_run_issues_list_create_meta_issue_types, flags={'project_id_or_key': '--project-id-or-key', 'start_at': '--start-at', 'max_results': '--max-results'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_create_issue_meta_issue_types'})
    c = g_issues_commands.add_parser('get-create-meta-issue-type-id', parents=[common], help='Get create field metadata for a project and issue type id', description='Returns a page of field metadata for a specified project and issuetype id. Use\nthe information to populate the requests in [ Create issue](#api-rest-\napi-3-issue-post) and [Create issues](#api-rest-api-3-issue-bulk-post).\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Create issues* [project\npermission](https://confluence.atlassian.com/x/yodKLg) in the requested\nprojects.', usage='%(prog)s PROJECT_ID_OR_KEY ISSUE_TYPE_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues get-create-meta-issue-type-id PROJECT_ID_OR_KEY ISSUE_TYPE_ID']), formatter_class=RAW)
    c.add_argument('p_project_id_or_key', metavar='PROJECT_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the project.')
    c.add_argument('p_issue_type_id', metavar='ISSUE_TYPE_ID', nargs='?', default=argparse.SUPPRESS, help='The issuetype ID.')
    c.add_argument('--project-id-or-key', dest='p_project_id_or_key', default=argparse.SUPPRESS, metavar='PROJECT_ID_OR_KEY', help='same as PROJECT_ID_OR_KEY')
    c.add_argument('--issue-type-id', dest='p_issue_type_id', default=argparse.SUPPRESS, metavar='ISSUE_TYPE_ID', help='same as ISSUE_TYPE_ID')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.set_defaults(handler=_run_issues_get_create_meta_issue_type_id, flags={'project_id_or_key': '--project-id-or-key', 'issue_type_id': '--issue-type-id', 'start_at': '--start-at', 'max_results': '--max-results'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_create_issue_meta_issue_type_id'})
    c = g_issues_commands.add_parser('get-adf-limit-report', parents=[common], help='Get issue adf limit report', description='Returns all issues whose ADF (rich text) field data breaches the universal ADF\nsize limit.\n\nUnlike the issue limit report, which reports issues breaching per-issue entity\n*count* limits, this endpoint reports issues whose ADF field *byte size*\nexceeds that limit. The reported ADF field types are `comment_adf`,\n`worklog_adf`, `customfield_adf`, `description_adf` and `environment_adf`. The\nreported value for each issue is the number of breaching entities for that\nfield (always 1 for the single-value description and environment fields).\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) is required for the\nproject the issues are in. Results may be incomplete otherwise * *Administer\nJira* [global permission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues get-adf-limit-report']), formatter_class=RAW)
    c.add_argument('--is-returning-keys', dest='p_is_returning_keys', action=argparse.BooleanOptionalAction, help='Return issue keys instead of issue ids in the response. (default: False)')
    c.add_argument('--field-type', dest='p_field_type', action="append", metavar='FIELD_TYPE', help='Restrict the report to the given ADF field types. Defaults to every ADF field type.')
    c.set_defaults(handler=_run_issues_get_adf_limit_report, flags={'is_returning_keys': '--is-returning-keys', 'field_type': '--field-type'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_issue_adf_limit_report'})
    c = g_issues_commands.add_parser('get-limit-report', parents=[common], help='Get issue limit report', description='Returns all issues breaching and approaching per-issue limits.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) is required for the\nproject the issues are in. Results may be incomplete otherwise * *Administer\nJira* [global permission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues get-limit-report']), formatter_class=RAW)
    c.add_argument('--is-returning-keys', dest='p_is_returning_keys', action=argparse.BooleanOptionalAction, help='Return issue keys instead of issue ids in the response. (default: False)')
    c.set_defaults(handler=_run_issues_get_limit_report, flags={'is_returning_keys': '--is-returning-keys'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_issue_limit_report'})
    c = g_issues_commands.add_parser('unarchive', parents=[common], help='Unarchive issue(s) by issue keys/ID', description="Enables admins to unarchive up to 1000 issues in a single request using issue\nID/key, returning details of the issue(s) unarchived in the process and the\nerrors encountered, if any.\n\n**Note that:**\n\n* you can't unarchive subtasks directly, only through their parent issues *\nyou can only unarchive issues from software, service management, and business\nprojects\n\n**[Permissions](#permissions) required:** Jira admin or site admin: [global\npermission](https://confluence.atlassian.com/x/x4dKLg)\n\n**License required:** Premium or Enterprise\n\n**Signed-in users only:** This API can't be accessed anonymously.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues unarchive --issue-ids-or-keys ISSUE_IDS_OR_KEYS', 'codapact-jira issues unarchive --issue-ids-or-keys ISSUE_IDS_OR_KEYS --dry-run']), formatter_class=RAW)
    c.add_argument('--issue-ids-or-keys', dest='p_issue_ids_or_keys', action="append", metavar='ISSUE_IDS_OR_KEYS')
    c.set_defaults(handler=_run_issues_unarchive, flags={'body.issue_ids_or_keys': '--issue-ids-or-keys'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'unarchive_issues', 'requires_one_of': [['--issue-ids-or-keys']]})
    c = g_issues_commands.add_parser('get', parents=[common], help='Get issue', description="Returns the details for an issue.\n\nThe issue is identified by its ID or key, however, if the identifier doesn't\nmatch an issue, a case-insensitive search and check for moved issues is\nperformed. If a matching issue is found its details are returned, a 302 or\nother redirect is **not** returned. The issue key returned in the response is\nthe key of the issue found.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.", usage='%(prog)s ISSUE_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues get ISSUE_ID_OR_KEY']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--fields', dest='p_fields', action="append", metavar='FIELDS', help='A list of fields to return for the issue. This parameter accepts a comma-separated list. Use it to retrieve a subset of fields. Allowed values:')
    c.add_argument('--fields-by-keys', dest='p_fields_by_keys', action=argparse.BooleanOptionalAction, help="Whether fields in `fields` are referenced by keys rather than IDs. This parameter is useful where fields have been added by a connect app and a field's key may differ from its ID. (default: False)")
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about the issues in the response. This parameter accepts a comma-separated list. Expand options include:')
    c.add_argument('--properties', dest='p_properties', action="append", metavar='PROPERTIES', help='A list of issue properties to return for the issue. This parameter accepts a comma-separated list. Allowed values:')
    c.add_argument('--update-history', dest='p_update_history', action=argparse.BooleanOptionalAction, help="Whether the project in which the issue is created is added to the user's **Recently viewed** project list, as shown under **Projects** in Jira. This also populates the [JQL issues search](#api-rest-api-3-search-get) `lastViewed` field. (default: False)")
    c.add_argument('--fail-fast', dest='p_fail_fast', action=argparse.BooleanOptionalAction, help='Whether to fail the request quickly in case of an error while loading fields for an issue. For `failFast=true`, if one field fails, the entire operation fails. For `failFast=false`, the operation will continue even if a field fails. It will return a valid response, but without values for the failed field(s). (default: False)')
    c.set_defaults(handler=_run_issues_get, flags={'issue_id_or_key': '--issue-id-or-key', 'fields': '--fields', 'fields_by_keys': '--fields-by-keys', 'expand': '--expand', 'properties': '--properties', 'update_history': '--update-history', 'fail_fast': '--fail-fast'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_issue'})
    c = g_issues_commands.add_parser('edit', parents=[common], help='Edit issue', description="Edits an issue. Issue properties may be updated as part of the edit. Please\nnote that issue transition is not supported and is ignored here. To transition\nan issue, please use [Transition issue](#api-rest-api-3-issue-issueIdOrKey-\ntransitions-post).\n\nThe edits to the issue's fields are defined using `update` and `fields`. The\nfields that can be edited are determined using [ Get edit issue\nmetadata](#api-rest-api-3-issue-issueIdOrKey-editmeta-get).\n\n**Note:** This endpoint doesn't check screen configurations to determine if a\nfield is editable. For more context, see the [Deprecation of override screen\nsecurity](https://community.developer.atlassian.com/t/deprecation-of-override-\nscreen-security/97153) announcement.\n\nThe parent field may be set by key or ID. For standard issue types, the parent\nmay be removed by setting `update.parent.set.none` to *true*. Note that the\n`description`, `environment`, and any `textarea` type custom fields (multi-\nline text fields) take Atlassian Document Format content. Single line custom\nfields (`textfield`) accept a string and don't handle Atlassian Document\nFormat content.\n\nConnect apps having an app user with *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg), and Forge apps acting\non behalf of users with *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg), can override the\nscreen security configuration using `overrideScreenSecurity` and\n`overrideEditableFlag`.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* and *Edit issues* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.", usage='%(prog)s ISSUE_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues edit ISSUE_ID_OR_KEY --fields @fields.json', 'codapact-jira issues edit ISSUE_ID_OR_KEY --fields @fields.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--notify-users', dest='p_notify_users', action=argparse.BooleanOptionalAction, help="Whether a notification email about the issue update is sent to all watchers. To disable the notification, administer Jira or administer project permissions are required. If the user doesn't have the necessary permission the request is ignored. (default: True)")
    c.add_argument('--override-screen-security', dest='p_override_screen_security', action=argparse.BooleanOptionalAction, help='Whether screen security is overridden to enable hidden fields to be edited. Available to Connect and Forge app users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg) and Forge apps acting on behalf of users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg). (default: False)')
    c.add_argument('--override-editable-flag', dest='p_override_editable_flag', action=argparse.BooleanOptionalAction, help='Whether screen security is overridden to enable uneditable fields to be edited. Available to Connect and Forge app users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg) and Forge apps acting on behalf of users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg). (default: False)')
    c.add_argument('--return-issue', dest='p_return_issue', action=argparse.BooleanOptionalAction, help='Whether the response should contain the issue with fields edited in this request. The returned issue will have the same format as in the [Get issue API](#api-rest-api-3-issue-issueidorkey-get). (default: False)')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='The Get issue API expand parameter to use in the response if the `returnIssue` parameter is `true`. (default: )')
    c.add_argument('--fields', dest='p_fields', type=json_value, metavar="JSON", help='List of issue screen fields to update, specifying the sub-field to update and its value for each field. This field provides a straightforward option when setting a sub-field. When multiple sub-fields or other operations are required, use `update`. Fields included in here cannot be included in `update`.')
    c.add_argument('--history-metadata', dest='p_history_metadata', type=json_value, metavar="JSON", help='Additional issue history details. JSON object with activity_description, activity_description_key, actor, cause, description, description_key, email_description, email_description_key, extra_data, generator, type. Schema: codapact-jira describe issues edit')
    c.add_argument('--properties', dest='p_properties', type=json_value, metavar="JSON", help='Details of issue properties to be add or update. JSON array of objects with key, value. Schema: codapact-jira describe issues edit')
    c.add_argument('--transition', dest='p_transition', type=json_value, metavar="JSON", help='Details of a transition. Required when performing a transition, optional when creating or editing an issue. JSON object with expand, fields, has_screen, id, is_available, is_conditional, is_global, is_initial, looped, name, to. Schema: codapact-jira describe issues edit')
    c.add_argument('--update', dest='p_update', type=json_value, metavar="JSON", help='A Map containing the field field name and a list of operations to perform on the issue screen field. Note that fields included in here cannot be included in `fields`.')
    c.set_defaults(handler=_run_issues_edit, flags={'issue_id_or_key': '--issue-id-or-key', 'notify_users': '--notify-users', 'override_screen_security': '--override-screen-security', 'override_editable_flag': '--override-editable-flag', 'return_issue': '--return-issue', 'expand': '--expand', 'body.fields': '--fields', 'body.history_metadata': '--history-metadata', 'body.properties': '--properties', 'body.transition': '--transition', 'body.update': '--update'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'edit_issue', 'requires_one_of': [['--fields', '--history-metadata', '--properties', '--transition', '--update']]})
    c = g_issues_commands.add_parser('delete', parents=[common], help='Delete issue', description="Deletes an issue.\n\nAn issue cannot be deleted if it has one or more subtasks. To delete an issue\nwith subtasks, set `deleteSubtasks`. This causes the issue's subtasks to be\ndeleted with the issue.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* and *Delete issues* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project\ncontaining the issue. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.", usage='%(prog)s ISSUE_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues delete ISSUE_ID_OR_KEY --dry-run', 'codapact-jira issues delete ISSUE_ID_OR_KEY --yes']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--delete-subtasks', dest='p_delete_subtasks', choices=['true', 'false'], help="Whether the issue's subtasks are deleted when the issue is deleted. (default: false)")
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_issues_delete, flags={'issue_id_or_key': '--issue-id-or-key', 'delete_subtasks': '--delete-subtasks'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_issue'})
    c = g_issues_commands.add_parser('assign', parents=[common], help='Assign issue', description='Assigns an issue to a user. Use this operation when the calling user does not\nhave the *Edit Issues* permission but has the *Assign issue* permission for\nthe project that the issue is in.\n\nIf `name` or `accountId` is set to:\n\n* `"-1"`, the issue is assigned to the default assignee for the project. *\n`null`, the issue is set to unassigned.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse Projects* and *Assign Issues* [ project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s ISSUE_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues assign ISSUE_ID_OR_KEY --account-id ACCOUNT_ID', 'codapact-jira issues assign ISSUE_ID_OR_KEY --account-id ACCOUNT_ID --dry-run']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue to be assigned.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='The account ID of the user, which uniquely identifies the user across all Atlassian products. For example, *5b10ac8d82e05b22cc7d4ef5*. Required in requests.')
    c.add_argument('--account-type', dest='p_account_type', choices=['atlassian', 'app', 'customer', 'unknown'], help='The user account type. Can take the following values:')
    c.add_argument('--active', dest='p_active', action=argparse.BooleanOptionalAction, help='Whether the user is active.')
    c.add_argument('--app-type', dest='p_app_type', metavar='APP_TYPE', help="The app type of the user account when accountType is 'app'. Can take the following values:")
    c.add_argument('--application-roles', dest='p_application_roles', type=json_value, metavar="JSON", help='The application roles the user is assigned to. JSON object with callback, items, max_results, paging_callback, size. Schema: codapact-jira describe issues assign')
    c.add_argument('--avatar-urls', dest='p_avatar_urls', type=json_value, metavar="JSON", help='The avatars of the user. JSON object with n16_x_16, n24_x_24, n32_x_32, n48_x_48. Schema: codapact-jira describe issues assign')
    c.add_argument('--display-name', dest='p_display_name', metavar='DISPLAY_NAME', help='The display name of the user. Depending on the user’s privacy setting, this may return an alternative value.')
    c.add_argument('--email-address', dest='p_email_address', metavar='EMAIL_ADDRESS', help='The email address of the user. Depending on the user’s privacy setting, this may be returned as null.')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Expand options that include additional user details in the response.')
    c.add_argument('--groups', dest='p_groups', type=json_value, metavar="JSON", help='The groups that the user belongs to. JSON object with callback, items, max_results, paging_callback, size. Schema: codapact-jira describe issues assign')
    c.add_argument('--guest', dest='p_guest', action=argparse.BooleanOptionalAction, help='Whether the user is a guest.')
    c.add_argument('--key', dest='p_key', metavar='KEY', help='This property is no longer available and will be removed from the documentation soon. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--locale', dest='p_locale', metavar='LOCALE', help='The locale of the user. Depending on the user’s privacy setting, this may be returned as null.')
    c.add_argument('--name', dest='p_name', metavar='NAME', help='This property is no longer available and will be removed from the documentation soon. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--self', dest='p_self', metavar='SELF', help='The URL of the user.')
    c.add_argument('--time-zone', dest='p_time_zone', metavar='TIME_ZONE', help="The time zone specified in the user's profile. If the user's time zone is not visible to the current user (due to user's profile setting), or if a time zone has not been set, the instance's default time zone will be returned.")
    c.set_defaults(handler=_run_issues_assign, flags={'issue_id_or_key': '--issue-id-or-key', 'body.account_id': '--account-id', 'body.account_type': '--account-type', 'body.active': '--active', 'body.app_type': '--app-type', 'body.application_roles': '--application-roles', 'body.avatar_urls': '--avatar-urls', 'body.display_name': '--display-name', 'body.email_address': '--email-address', 'body.expand': '--expand', 'body.groups': '--groups', 'body.guest': '--guest', 'body.key': '--key', 'body.locale': '--locale', 'body.name': '--name', 'body.self': '--self', 'body.time_zone': '--time-zone'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'assign_issue', 'requires_one_of': [['--account-id', '--account-type', '--active', '--app-type', '--application-roles', '--avatar-urls', '--display-name', '--email-address', '--expand', '--groups', '--guest', '--key', '--locale', '--name', '--self', '--time-zone']]})
    c = g_issues_commands.add_parser('list-change-logs', parents=[common], help='Get changelogs', description='Returns a [paginated](#pagination) list of all changelogs for an issue sorted\nby date, starting from the oldest.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s ISSUE_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues list-change-logs ISSUE_ID_OR_KEY']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 100)')
    c.set_defaults(handler=_run_issues_list_change_logs, flags={'issue_id_or_key': '--issue-id-or-key', 'start_at': '--start-at', 'max_results': '--max-results'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_change_logs'})
    c = g_issues_commands.add_parser('list-change-logs-by-ids', parents=[common], help='Get changelogs by IDs', description='Returns changelogs for an issue specified by a list of changelog IDs.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s ISSUE_ID_OR_KEY --changelog-ids CHANGELOG_IDS [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues list-change-logs-by-ids ISSUE_ID_OR_KEY --changelog-ids CHANGELOG_IDS', 'codapact-jira issues list-change-logs-by-ids ISSUE_ID_OR_KEY --changelog-ids CHANGELOG_IDS --dry-run']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--changelog-ids', dest='p_changelog_ids', action="append", type=integer, metavar='CHANGELOG_IDS', required=True, help='The list of changelog IDs.')
    c.set_defaults(handler=_run_issues_list_change_logs_by_ids, flags={'issue_id_or_key': '--issue-id-or-key', 'body.changelog_ids': '--changelog-ids'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_change_logs_by_ids'})
    c = g_issues_commands.add_parser('get-edit-meta', parents=[common], help='Get edit issue metadata', description='Returns the edit screen fields for an issue that are visible to and editable\nby the user. Use the information to populate the requests in [Edit\nissue](#api-rest-api-3-issue-issueIdOrKey-put).\n\nThis endpoint will check for these conditions:\n\n1. Field is available on a field screen - through screen, screen scheme, issue\ntype screen scheme, and issue type scheme configuration.\n`overrideScreenSecurity=true` skips this condition. 2. Field is visible in the\n[field configuration](https://support.atlassian.com/jira-cloud-\nadministration/docs/change-a-field-configuration/).\n`overrideScreenSecurity=true` skips this condition. 3. Field is shown on the\nissue: each field has different conditions here. For example: Attachment field\nonly shows if attachments are enabled. Assignee only shows if user has\npermissions to assign the issue. 4. If a field is custom then it must have\nvalid custom field context, applicable for its project and issue type. All\nsystem fields are assumed to have context in all projects and all issue types.\n5. Issue has a project, issue type, and status defined. 6. Issue is assigned\nto a valid workflow, and the current status has assigned a workflow step.\n`overrideEditableFlag=true` skips this condition. 7. The current workflow step\nis editable. This is true by default, but [can be disabled by\nsetting](https://support.atlassian.com/jira-cloud-administration/docs/use-\nworkflow-properties/) the `jira.issue.editable` property to `false`.\n`overrideEditableFlag=true` skips this condition. 8. User has [Edit issues\npermission](https://support.atlassian.com/jira-cloud-\nadministration/docs/permissions-for-company-managed-projects/). 9. Workflow\npermissions allow editing a field. This is true by default but [can be\nmodified](https://support.atlassian.com/jira-cloud-administration/docs/use-\nworkflow-properties/) using `jira.permission.*` workflow properties.\n\nFields hidden using [Issue layout settings\npage](https://support.atlassian.com/jira-software-cloud/docs/configure-field-\nlayout-in-the-issue-view/) remain editable.\n\nConnect apps having an app user with *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg), and Forge apps acting\non behalf of users with *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg), can return additional\ndetails using:\n\n* `overrideScreenSecurity` When this flag is `true`, then this endpoint skips\nchecking if fields are available through screens, and field configuration\n(conditions 1. and 2. from the list above). * `overrideEditableFlag` When this\nflag is `true`, then this endpoint skips checking if workflow is present and\nif the current step is editable (conditions 6. and 7. from the list above).\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.\n\nNote: For any fields to be editable the user must have the *Edit issues*\n[project permission](https://confluence.atlassian.com/x/yodKLg) for the issue.', usage='%(prog)s ISSUE_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues get-edit-meta ISSUE_ID_OR_KEY']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--override-screen-security', dest='p_override_screen_security', action=argparse.BooleanOptionalAction, help='Whether hidden fields are returned. Available to Connect and Forge app users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg) and Forge apps acting on behalf of users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg). (default: False)')
    c.add_argument('--override-editable-flag', dest='p_override_editable_flag', action=argparse.BooleanOptionalAction, help='Whether non-editable fields are returned. Available to Connect and Forge app users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg) and Forge apps acting on behalf of users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg). (default: False)')
    c.set_defaults(handler=_run_issues_get_edit_meta, flags={'issue_id_or_key': '--issue-id-or-key', 'override_screen_security': '--override-screen-security', 'override_editable_flag': '--override-editable-flag'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_edit_issue_meta'})
    c = g_issues_commands.add_parser('notify', parents=[common], help='Send notification for issue', description='Creates an email notification for an issue and adds it to the mail queue.\n\n**[Permissions](#permissions) required:**\n\n* *Browse Projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s ISSUE_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues notify ISSUE_ID_OR_KEY --html-body HTML_BODY', 'codapact-jira issues notify ISSUE_ID_OR_KEY --html-body HTML_BODY --dry-run']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='ID or key of the issue that the notification is sent for.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--html-body', dest='p_html_body', metavar='HTML_BODY', help='The HTML body of the email notification for the issue.')
    c.add_argument('--restrict', dest='p_restrict', type=json_value, metavar="JSON", help='Restricts the notifications to users with the specified permissions. JSON object with group_ids, groups, permissions. Schema: codapact-jira describe issues notify')
    c.add_argument('--subject', dest='p_subject', metavar='SUBJECT', help='The subject of the email notification for the issue. If this is not specified, then the subject is set to the issue key and summary.')
    c.add_argument('--text-body', dest='p_text_body', metavar='TEXT_BODY', help='The plain text body of the email notification for the issue.')
    c.add_argument('--to', dest='p_to', type=json_value, metavar="JSON", help='The recipients of the email notification for the issue. JSON object with assignee, group_ids, groups, reporter, users, voters, watchers. Schema: codapact-jira describe issues notify')
    c.set_defaults(handler=_run_issues_notify, flags={'issue_id_or_key': '--issue-id-or-key', 'body.html_body': '--html-body', 'body.restrict': '--restrict', 'body.subject': '--subject', 'body.text_body': '--text-body', 'body.to': '--to'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'notify', 'requires_one_of': [['--html-body', '--restrict', '--subject', '--text-body', '--to']]})
    c = g_issues_commands.add_parser('list-transitions', parents=[common], help='Get transitions', description="Returns either all transitions or a transition that can be performed by the\nuser on an issue, based on the issue's status.\n\nNote, if a request is made for a transition that does not exist or cannot be\nperformed on the issue, given its status, the response will return any empty\ntransitions list.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required: A list or transition is returned only\nwhen the user has:**\n\n* *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.\n\nHowever, if the user does not have the *Transition issues* [ project\npermission](https://confluence.atlassian.com/x/yodKLg) the response will not\nlist any transitions.", usage='%(prog)s ISSUE_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues list-transitions ISSUE_ID_OR_KEY']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about transitions in the response. This parameter accepts `transitions.fields`, which returns information about the fields in the transition screen for each transition. Fields hidden from the screen are not returned. Use this information to populate the `fields` and `update` fields in [Transition issue](#api-rest-api-3-issue-issueIdOrKey-transitions-post).')
    c.add_argument('--transition-id', dest='p_transition_id', metavar='TRANSITION_ID', help='The ID of the transition.')
    c.add_argument('--skip-remote-only-condition', dest='p_skip_remote_only_condition', action=argparse.BooleanOptionalAction, help='Whether transitions with the condition *Hide From User Condition* are included in the response. Available to Connect and Forge app users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg) and Forge apps acting on behalf of users with *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg). (default: False)')
    c.add_argument('--include-unavailable-transitions', dest='p_include_unavailable_transitions', action=argparse.BooleanOptionalAction, help='Whether details of transitions that fail a condition are included in the response (default: False)')
    c.add_argument('--sort-by-ops-bar-and-status', dest='p_sort_by_ops_bar_and_status', action=argparse.BooleanOptionalAction, help='Whether the transitions are sorted by ops-bar sequence value first then category order (Todo, In Progress, Done) or only by ops-bar sequence value. (default: False)')
    c.set_defaults(handler=_run_issues_list_transitions, flags={'issue_id_or_key': '--issue-id-or-key', 'expand': '--expand', 'transition_id': '--transition-id', 'skip_remote_only_condition': '--skip-remote-only-condition', 'include_unavailable_transitions': '--include-unavailable-transitions', 'sort_by_ops_bar_and_status': '--sort-by-ops-bar-and-status'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_transitions'})
    c = g_issues_commands.add_parser('do-transition', parents=[common], help='Transition issue', description='Performs an issue transition and, if the transition has a screen, updates the\nfields from the transition screen.\n\nsortByCategory To update the fields on the transition screen, specify the\nfields in the `fields` or `update` parameters in the request body. Get details\nabout the fields using [ Get transitions](#api-rest-api-3-issue-issueIdOrKey-\ntransitions-get) with the `transitions.fields` expand.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Browse projects* and *Transition issues* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project that\nthe issue is in. * If [issue-level\nsecurity](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-\nlevel security permission to view the issue.', usage='%(prog)s ISSUE_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues do-transition ISSUE_ID_OR_KEY --fields @fields.json', 'codapact-jira issues do-transition ISSUE_ID_OR_KEY --fields @fields.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_issue_id_or_key', metavar='ISSUE_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The ID or key of the issue.')
    c.add_argument('--issue-id-or-key', dest='p_issue_id_or_key', default=argparse.SUPPRESS, metavar='ISSUE_ID_OR_KEY', help='same as ISSUE_ID_OR_KEY')
    c.add_argument('--fields', dest='p_fields', type=json_value, metavar="JSON", help='List of issue screen fields to update, specifying the sub-field to update and its value for each field. This field provides a straightforward option when setting a sub-field. When multiple sub-fields or other operations are required, use `update`. Fields included in here cannot be included in `update`.')
    c.add_argument('--history-metadata', dest='p_history_metadata', type=json_value, metavar="JSON", help='Additional issue history details. JSON object with activity_description, activity_description_key, actor, cause, description, description_key, email_description, email_description_key, extra_data, generator, type. Schema: codapact-jira describe issues do-transition')
    c.add_argument('--properties', dest='p_properties', type=json_value, metavar="JSON", help='Details of issue properties to be add or update. JSON array of objects with key, value. Schema: codapact-jira describe issues do-transition')
    c.add_argument('--transition', dest='p_transition', type=json_value, metavar="JSON", help='Details of a transition. Required when performing a transition, optional when creating or editing an issue. JSON object with expand, fields, has_screen, id, is_available, is_conditional, is_global, is_initial, looped, name, to. Schema: codapact-jira describe issues do-transition')
    c.add_argument('--update', dest='p_update', type=json_value, metavar="JSON", help='A Map containing the field field name and a list of operations to perform on the issue screen field. Note that fields included in here cannot be included in `fields`.')
    c.set_defaults(handler=_run_issues_do_transition, flags={'issue_id_or_key': '--issue-id-or-key', 'body.fields': '--fields', 'body.history_metadata': '--history-metadata', 'body.properties': '--properties', 'body.transition': '--transition', 'body.update': '--update'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'do_transition', 'requires_one_of': [['--fields', '--history-metadata', '--properties', '--transition', '--update']]})
    c = g_issues_commands.add_parser('export', parents=[common], help='Export archived issue(s)', description="Enables admins to retrieve details of all archived issues. Upon a successful\nrequest, the admin who submitted it will receive an email with a link to\ndownload a CSV file with the issue details.\n\nNote that this API only exports the values of system fields and archival-\nspecific fields (`ArchivedBy` and `ArchivedDate`). Custom fields aren't\nsupported.\n\n**[Permissions](#permissions) required:** Jira admin or site admin: [global\npermission](https://confluence.atlassian.com/x/x4dKLg)\n\n**License required:** Premium or Enterprise\n\n**Signed-in users only:** This API can't be accessed anonymously.\n\n**Rate limiting:** Only a single request can be active at any given time.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira issues export --archived-by ARCHIVED_BY', 'codapact-jira issues export --archived-by ARCHIVED_BY --dry-run']), formatter_class=RAW)
    c.add_argument('--archived-by', dest='p_archived_by', action="append", metavar='ARCHIVED_BY', help='List archived issues archived by a specified account ID.')
    c.add_argument('--archived-date-range', dest='p_archived_date_range', type=json_value, metavar="JSON", help='JSON object with date_after*, date_before* (* required). Schema: codapact-jira describe issues export')
    c.add_argument('--issue-types', dest='p_issue_types', action="append", metavar='ISSUE_TYPES', help='List archived issues with a specified issue type ID.')
    c.add_argument('--projects', dest='p_projects', action="append", metavar='PROJECTS', help='List archived issues with a specified project key.')
    c.add_argument('--reporters', dest='p_reporters', action="append", metavar='REPORTERS', help='List archived issues where the reporter is a specified account ID.')
    c.set_defaults(handler=_run_issues_export, flags={'body.archived_by': '--archived-by', 'body.archived_date_range': '--archived-date-range', 'body.issue_types': '--issue-types', 'body.projects': '--projects', 'body.reporters': '--reporters'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'export_archived_issues', 'requires_one_of': [['--archived-by', '--archived-date-range', '--issue-types', '--projects', '--reporters']]})
    g_jira_expressions = commands.add_parser('jira-expressions', help='analyse-expression, evaluate, evaluate-jsis', description="Run 'codapact-jira jira-expressions COMMAND --help' for a command's options and examples.")
    g_jira_expressions_commands = g_jira_expressions.add_subparsers(dest="g_jira_expressions", metavar="COMMAND", required=True)
    c = g_jira_expressions_commands.add_parser('analyse-expression', parents=[common], help='Analyse Jira expression', description='Analyses and validates Jira expressions.\n\nAs an experimental feature, this operation can also attempt to type-check the\nexpressions.\n\nLearn more about Jira expressions in the\n[documentation](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions/).\n\n**[Permissions](#permissions) required**: None.', usage='%(prog)s --expressions EXPRESSIONS [options]', epilog=RUNTIME.command_epilog(['codapact-jira jira-expressions analyse-expression --expressions EXPRESSIONS', 'codapact-jira jira-expressions analyse-expression --expressions EXPRESSIONS --dry-run']), formatter_class=RAW)
    c.add_argument('--check', dest='p_check', choices=['syntax', 'type', 'complexity'], help='The check to perform: (default: syntax)')
    c.add_argument('--context-variables', dest='p_context_variables', type=json_value, metavar="JSON", help='Context variables and their types. The type checker assumes that [common context variables](https://developer.atlassian.com/cloud/jira/platform/jira-expressions/#context-variables), such as `issue` or `project`, are available in context and sets their type. Use this property to override the default types or provide details of new variables.')
    c.add_argument('--expressions', dest='p_expressions', action="append", metavar='EXPRESSIONS', required=True, help='The list of Jira expressions to analyse.')
    c.set_defaults(handler=_run_jira_expressions_analyse_expression, flags={'check': '--check', 'body.context_variables': '--context-variables', 'body.expressions': '--expressions'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'analyse_expression'})
    c = g_jira_expressions_commands.add_parser('evaluate', parents=[common], help='[deprecated] Currently being removed. Evaluate Jira expression', description='Endpoint is currently being removed. [More\ndetails](https://developer.atlassian.com/changelog/#CHANGE-2046)\n\nEvaluates a Jira expression and returns its value.\n\nThis resource can be used to test Jira expressions that you plan to use\nelsewhere, or to fetch data in a flexible way. Consult the [Jira expressions\ndocumentation](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions/) for more details.\n\n#### Context variables ####\n\nThe following context variables are available to Jira expressions evaluated by\nthis resource. Their presence depends on various factors; usually you need to\nmanually request them in the context object sent in the payload, but some of\nthem are added automatically under certain conditions.\n\n* `user` ([User](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#user)): The current user. Always available and\nequal to `null` if the request is anonymous. * `app`\n([App](https://developer.atlassian.com/cloud/jira/platform/jira-expressions-\ntype-reference#app)): The [Connect\napp](https://developer.atlassian.com/cloud/jira/platform/index/#connect-apps)\nthat made the request. Available only for authenticated requests made by\nConnect Apps (read more here: [Authentication for Connect\napps](https://developer.atlassian.com/cloud/jira/platform/security-for-\nconnect-apps/)). * `issue`\n([Issue](https://developer.atlassian.com/cloud/jira/platform/jira-expressions-\ntype-reference#issue)): The current issue. Available only when the issue is\nprovided in the request context object. * `issues`\n([List](https://developer.atlassian.com/cloud/jira/platform/jira-expressions-\ntype-reference#list) of\n[Issues](https://developer.atlassian.com/cloud/jira/platform/jira-expressions-\ntype-reference#issue)): A collection of issues matching a JQL query. Available\nonly when JQL is provided in the request context object. * `project`\n([Project](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#project)): The current project. Available only when\nthe project is provided in the request context object. * `sprint`\n([Sprint](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#sprint)): The current sprint. Available only when\nthe sprint is provided in the request context object. * `board`\n([Board](https://developer.atlassian.com/cloud/jira/platform/jira-expressions-\ntype-reference#board)): The current board. Available only when the board is\nprovided in the request context object. * `serviceDesk`\n([ServiceDesk](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#servicedesk)): The current service desk. Available\nonly when the service desk is provided in the request context object. *\n`customerRequest`\n([CustomerRequest](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#customerrequest)): The current customer request.\nAvailable only when the customer request is provided in the request context\nobject.\n\nAlso, custom context variables can be passed in the request with their types.\nThose variables can be accessed by key in the Jira expression. These variable\ntypes are available for use in a custom context:\n\n* `user`: A [user](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#user) specified as an Atlassian account ID. *\n`issue`: An [issue](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#issue) specified by ID or key. All the fields of\nthe issue object are available in the Jira expression. * `json`: A JSON object\ncontaining custom content. * `list`: A JSON list of `user`, `issue`, or `json`\nvariable types.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required**: None. However, an expression may\nreturn different results for different users depending on their permissions.\nFor example, different users may see different comments on the same issue.\nPermission to access Jira Software is required to access Jira Software context\nvariables (`board` and `sprint`) or fields (for example, `issue.sprint`).', usage='%(prog)s --expression EXPRESSION [options]', epilog=RUNTIME.command_epilog(['codapact-jira jira-expressions evaluate --expression EXPRESSION', 'codapact-jira jira-expressions evaluate --expression EXPRESSION --dry-run']), formatter_class=RAW)
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information in the response. This parameter accepts `meta.complexity` that returns information about the expression complexity. For example, the number of expensive operations used by the expression and how close the expression is to reaching the [complexity limit](https://developer.atlassian.com/cloud/jira/platform/jira-expressions/#restrictions). Useful when designing and debugging your expressions.')
    c.add_argument('--context', dest='p_context', type=json_value, metavar="JSON", help='The context in which the Jira expression is evaluated. JSON object with board, custom, customer_request, issue, issues, project, service_desk, sprint. Schema: codapact-jira describe jira-expressions evaluate')
    c.add_argument('--expression', dest='p_expression', metavar='EXPRESSION', required=True, help='The Jira expression to evaluate.')
    c.set_defaults(handler=_run_jira_expressions_evaluate, flags={'expand': '--expand', 'body.context': '--context', 'body.expression': '--expression'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': True, 'operation': 'evaluate_jira_expression'})
    c = g_jira_expressions_commands.add_parser('evaluate-jsis', parents=[common], help='Evaluate Jira expression using enhanced search API', description="Evaluates a Jira expression and returns its value. The difference between this\nand `eval` is that this endpoint uses the enhanced search API when evaluating\nJQL queries. This API is eventually consistent, unlike the strongly consistent\n`eval` API. This allows for better performance and scalability. In addition,\nthis API's response for JQL evaluation is based on a scrolling view (backed by\na `nextPageToken`) instead of a paginated view (backed by `startAt` and\n`totalCount`).\n\nThis resource can be used to test Jira expressions that you plan to use\nelsewhere, or to fetch data in a flexible way. Consult the [Jira expressions\ndocumentation](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions/) for more details.\n\n#### Context variables ####\n\nThe following context variables are available to Jira expressions evaluated by\nthis resource. Their presence depends on various factors; usually you need to\nmanually request them in the context object sent in the payload, but some of\nthem are added automatically under certain conditions.\n\n* `user` ([User](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#user)): The current user. Always available and\nequal to `null` if the request is anonymous. * `app`\n([App](https://developer.atlassian.com/cloud/jira/platform/jira-expressions-\ntype-reference#app)): The [Connect\napp](https://developer.atlassian.com/cloud/jira/platform/index/#connect-apps)\nthat made the request. Available only for authenticated requests made by\nConnect apps (read more here: [Authentication for Connect\napps](https://developer.atlassian.com/cloud/jira/platform/security-for-\nconnect-apps/)). * `issue`\n([Issue](https://developer.atlassian.com/cloud/jira/platform/jira-expressions-\ntype-reference#issue)): The current issue. Available only when the issue is\nprovided in the request context object. * `issues`\n([List](https://developer.atlassian.com/cloud/jira/platform/jira-expressions-\ntype-reference#list) of\n[Issues](https://developer.atlassian.com/cloud/jira/platform/jira-expressions-\ntype-reference#issue)): A collection of issues matching a JQL query. Available\nonly when JQL is provided in the request context object. * `project`\n([Project](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#project)): The current project. Available only when\nthe project is provided in the request context object. * `sprint`\n([Sprint](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#sprint)): The current sprint. Available only when\nthe sprint is provided in the request context object. * `board`\n([Board](https://developer.atlassian.com/cloud/jira/platform/jira-expressions-\ntype-reference#board)): The current board. Available only when the board is\nprovided in the request context object. * `serviceDesk`\n([ServiceDesk](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#servicedesk)): The current service desk. Available\nonly when the service desk is provided in the request context object. *\n`customerRequest`\n([CustomerRequest](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#customerrequest)): The current customer request.\nAvailable only when the customer request is provided in the request context\nobject.\n\nIn addition, you can pass custom context variables along with their types. You\ncan then access them from the Jira expression by key. You can use the\nfollowing variables in a custom context:\n\n* `user`: A [user](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#user) specified as an Atlassian account ID. *\n`issue`: An [issue](https://developer.atlassian.com/cloud/jira/platform/jira-\nexpressions-type-reference#issue) specified by ID or key. All the fields of\nthe issue object are available in the Jira expression. * `json`: A JSON object\ncontaining custom content. * `list`: A JSON list of `user`, `issue`, or `json`\nvariable types.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required**: None. However, an expression may\nreturn different results for different users depending on their permissions.\nFor example, different users may see different comments on the same issue.\nPermission to access Jira Software is required to access Jira Software context\nvariables (`board` and `sprint`) or fields (for example, `issue.sprint`).", usage='%(prog)s --expression EXPRESSION [options]', epilog=RUNTIME.command_epilog(['codapact-jira jira-expressions evaluate-jsis --expression EXPRESSION', 'codapact-jira jira-expressions evaluate-jsis --expression EXPRESSION --dry-run']), formatter_class=RAW)
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information in the response. This parameter accepts `meta.complexity` that returns information about the expression complexity. For example, the number of expensive operations used by the expression and how close the expression is to reaching the [complexity limit](https://developer.atlassian.com/cloud/jira/platform/jira-expressions/#restrictions). Useful when designing and debugging your expressions.')
    c.add_argument('--context', dest='p_context', type=json_value, metavar="JSON", help='The context in which the Jira expression is evaluated. JSON object with board, custom, customer_request, issue, issues, project, service_desk, sprint. Schema: codapact-jira describe jira-expressions evaluate-jsis')
    c.add_argument('--expression', dest='p_expression', metavar='EXPRESSION', required=True, help='The Jira expression to evaluate.')
    c.set_defaults(handler=_run_jira_expressions_evaluate_jsis, flags={'expand': '--expand', 'body.context': '--context', 'body.expression': '--expression'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'evaluate_jsis_jira_expression'})
    g_jira_settings = commands.add_parser('jira-settings', help='get-application-property, get-configuration, list-advanced-settings, set-application-property', description="Run 'codapact-jira jira-settings COMMAND --help' for a command's options and examples.")
    g_jira_settings_commands = g_jira_settings.add_subparsers(dest="g_jira_settings", metavar="COMMAND", required=True)
    c = g_jira_settings_commands.add_parser('get-application-property', parents=[common], help='Get application property', description='Returns all application properties or an application property.\n\nIf you specify a value for the `key` parameter, then an application property\nis returned as an object (not in an array). Otherwise, an array of all\neditable application properties is returned. See [Set application\nproperty](#api-rest-api-3-application-properties-id-put) for descriptions of\neditable properties.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira jira-settings get-application-property']), formatter_class=RAW)
    c.add_argument('--key', dest='p_key', metavar='KEY', help='The key of the application property.')
    c.add_argument('--permission-level', dest='p_permission_level', metavar='PERMISSION_LEVEL', help='The permission level of all items being returned in the list.')
    c.add_argument('--key-filter', dest='p_key_filter', metavar='KEY_FILTER', help="When a `key` isn't provided, this filters the list of results by the application property `key` using a regular expression. For example, using `jira.lf.*` will return all application properties with keys that start with *jira.lf.*.")
    c.set_defaults(handler=_run_jira_settings_get_application_property, flags={'key': '--key', 'permission_level': '--permission-level', 'key_filter': '--key-filter'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_application_property'})
    c = g_jira_settings_commands.add_parser('list-advanced-settings', parents=[common], help='Get advanced settings', description='Returns the application properties that are accessible on the *Advanced\nSettings* page. To navigate to the *Advanced Settings* page in Jira, choose\nthe Jira icon > **Jira settings** > **System**, **General Configuration** and\nthen click **Advanced Settings** (in the upper right).\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira jira-settings list-advanced-settings']), formatter_class=RAW)
    c.set_defaults(handler=_run_jira_settings_list_advanced_settings, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_advanced_settings'})
    c = g_jira_settings_commands.add_parser('set-application-property', parents=[common], help='Set application property', description='Changes the value of an application property. For example, you can change the\nvalue of the `jira.clone.prefix` from its default value of *CLONE -* to *Clone\n-* if you prefer sentence case capitalization. Editable properties are\ndescribed below along with their default values.\n\n#### Advanced settings ####\n\nThe advanced settings below are also accessible in\n[Jira](https://confluence.atlassian.com/x/vYXKM).\n\n| Key | Description | Default value | | -- | -- | -- | | `jira.clone.prefix` |\nThe string of text prefixed to the title of a cloned issue. | `CLONE -` | |\n`jira.date.picker.java.format` | The date format for the Java (server-side)\ngenerated dates. This must be the same as the\n`jira.date.picker.javascript.format` format setting. | `d/MMM/yy` | |\n`jira.date.picker.javascript.format` | The date format for the JavaScript\n(client-side) generated dates. This must be the same as the\n`jira.date.picker.java.format` format setting. | `%e/%b/%y` | |\n`jira.date.time.picker.java.format` | The date format for the Java (server-\nside) generated date times. This must be the same as the\n`jira.date.time.picker.javascript.format` format setting. | `dd/MMM/yy h:mm a`\n| | `jira.date.time.picker.javascript.format` | The date format for the\nJavaScript (client-side) generated date times. This must be the same as the\n`jira.date.time.picker.java.format` format setting. | `%e/%b/%y %I:%M %p` | |\n`jira.issue.actions.order` | The default order of actions (such as *Comments*\nor *Change history*) displayed on the issue view. | `asc` | |\n`jira.view.issue.links.sort.order` | The sort order of the list of issue links\non the issue view. | `type, status, priority` | |\n`jira.comment.collapsing.minimum.hidden` | The minimum number of comments\nrequired for comment collapsing to occur. A value of `0` disables comment\ncollapsing. | `4` | | `jira.newsletter.tip.delay.days` | The number of days\nbefore a prompt to sign up to the Jira Insiders newsletter is shown. A value\nof `-1` disables this feature. | `7` |\n\n#### Look and feel ####\n\nThe settings listed below adjust the [look and\nfeel](https://confluence.atlassian.com/x/VwCLLg).\n\n| Key | Description | Default value | | -- | -- | -- | | `jira.lf.date.time` |\nThe [ time format](https://docs.oracle.com/javase/6/docs/api/index.html?java/t\next/SimpleDateFormat.html). | `h:mm a` | | `jira.lf.date.day` | The [ day form\nat](https://docs.oracle.com/javase/6/docs/api/index.html?java/text/SimpleDateF\normat.html). | `EEEE h:mm a` | | `jira.lf.date.complete` | The [ date and time\nformat](https://docs.oracle.com/javase/6/docs/api/index.html?java/text/SimpleD\nateFormat.html). | `dd/MMM/yy h:mm a` | | `jira.lf.date.dmy` | The [ date form\nat](https://docs.oracle.com/javase/6/docs/api/index.html?java/text/SimpleDateF\normat.html). | `dd/MMM/yy` | | `jira.date.time.picker.use.iso8061` | When\nenabled, sets Monday as the first day of the week in the date picker, as\nspecified by the ISO8601 standard. | `false` | | `jira.lf.logo.url` | The URL\nof the logo image file. | `/images/icon-jira-logo.png` | |\n`jira.lf.logo.show.application.title` | Controls the visibility of the\napplication title on the sidebar. | `false` | | `jira.lf.favicon.url` | The\nURL of the favicon. | `/favicon.ico` | | `jira.lf.favicon.hires.url` | The URL\nof the high-resolution favicon. | `/images/64jira.png` | |\n`jira.lf.navigation.bgcolour` | The background color of the sidebar. |\n`#0747A6` | | `jira.lf.navigation.highlightcolour` | The color of the text and\nlogo of the sidebar. | `#DEEBFF` | | `jira.lf.hero.button.base.bg.colour` |\nThe background color of the hero button. | `#3b7fc4` | | `jira.title` | The\ntext for the application title. The application title can also be set in\n*General settings*. | `Jira` | | `jira.option.globalsharing` | Whether filters\nand dashboards can be shared with anyone signed into Jira. | `true` | |\n`xflow.product.suggestions.enabled` | Whether to expose product suggestions\nfor other Atlassian products within Jira. | `true` |\n\n#### Other settings ####\n\n| Key | Description | Default value | | -- | -- | -- | |\n`jira.issuenav.criteria.autoupdate` | Whether instant updates to search\ncriteria is active. | `true` |\n\n*Note: Be careful when changing [application properties and advanced\nsettings](https://confluence.atlassian.com/x/vYXKM).*\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira jira-settings set-application-property ID --body @body.json', 'codapact-jira jira-settings set-application-property ID --body @body.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The key of the application property to update.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='JSON object with id, value. Schema: codapact-jira describe jira-settings set-application-property')
    c.set_defaults(handler=_run_jira_settings_set_application_property, flags={'id': '--id', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'set_application_property'})
    c = g_jira_settings_commands.add_parser('get-configuration', parents=[common], help='Get global settings', description='Returns the [global settings](https://confluence.atlassian.com/x/qYXKM) in\nJira. These settings determine whether optional features (for example,\nsubtasks, time tracking, and others) are enabled. If time tracking is enabled,\nthis operation also returns the time tracking configuration.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira jira-settings get-configuration']), formatter_class=RAW)
    c.set_defaults(handler=_run_jira_settings_get_configuration, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_configuration'})
    g_jql = commands.add_parser('jql', help='get-auto-complete, get-auto-complete-post, get-field-auto-complete-for-query-string, … (7 commands)', description="Run 'codapact-jira jql COMMAND --help' for a command's options and examples.")
    g_jql_commands = g_jql.add_subparsers(dest="g_jql", metavar="COMMAND", required=True)
    c = g_jql_commands.add_parser('list-audit-entries', parents=[common], help='Get invalid JQL searches', description='Returns JQL searches that need updating because Jira can no longer support\nthem. Use the entries to find affected saved filters and JQL used by apps,\nautomations, scripts, or REST integrations.\n\nEntries are ordered by creation time, newest first, and retained for three\ndays. Pass the `nextPageToken` returned in a previous response to retrieve the\nnext page. Results may be restricted to a user by external account ID.\n\n**[Permissions](#permissions) required:** *Administer Jira* global permission.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira jql list-audit-entries']), formatter_class=RAW)
    c.add_argument('--user-account-id', dest='p_user_account_id', metavar='USER_ACCOUNT_ID', help='The optional external account ID used to restrict the entries returned.')
    c.add_argument('--next-page-token', dest='p_next_page_token', metavar='NEXT_PAGE_TOKEN', help='The token returned by a previous response to retrieve the next page.')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of entries to return, from 1 to 100 and defaulting to 50.')
    c.set_defaults(handler=_run_jql_list_audit_entries, flags={'user_account_id': '--user-account-id', 'next_page_token': '--next-page-token', 'max_results': '--max-results'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_audit_entries'})
    c = g_jql_commands.add_parser('get-auto-complete', parents=[common], help='Get field reference data (GET)', description='Returns reference data for JQL searches. This is a downloadable version of the\ndocumentation provided in [Advanced searching - fields\nreference](https://confluence.atlassian.com/x/gwORLQ) and [Advanced searching\n- functions reference](https://confluence.atlassian.com/x/hgORLQ), along with\na list of JQL-reserved words. Use this information to assist with the\nprogrammatic creation of JQL queries or the validation of queries built in a\ncustom query builder.\n\nTo filter visible field details by project or collapse non-unique fields by\nfield type then [Get field reference data (POST)](#api-rest-api-3-jql-\nautocompletedata-post) can be used.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira jql get-auto-complete']), formatter_class=RAW)
    c.set_defaults(handler=_run_jql_get_auto_complete, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_auto_complete'})
    c = g_jql_commands.add_parser('get-auto-complete-post', parents=[common], help='Get field reference data (POST)', description='Returns reference data for JQL searches. This is a downloadable version of the\ndocumentation provided in [Advanced searching - fields\nreference](https://confluence.atlassian.com/x/gwORLQ) and [Advanced searching\n- functions reference](https://confluence.atlassian.com/x/hgORLQ), along with\na list of JQL-reserved words. Use this information to assist with the\nprogrammatic creation of JQL queries or the validation of queries built in a\ncustom query builder.\n\nThis operation can filter the custom fields returned by project. Invalid\nproject IDs in `projectIds` are ignored. System fields are always returned.\n\nIt can also return the collapsed field for custom fields. Collapsed fields\nenable searches to be performed across all fields with the same name and of\nthe same field type. For example, the collapsed field `Component -\nComponent[Dropdown]` enables dropdown fields `Component - cf[10061]` and\n`Component - cf[10062]` to be searched simultaneously.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira jql get-auto-complete-post --include-collapsed-fields INCLUDE_COLLAPSED_FIELDS', 'codapact-jira jql get-auto-complete-post --include-collapsed-fields INCLUDE_COLLAPSED_FIELDS --dry-run']), formatter_class=RAW)
    c.add_argument('--include-collapsed-fields', dest='p_include_collapsed_fields', action=argparse.BooleanOptionalAction, help='Include collapsed fields for fields that have non-unique names. (default: False)')
    c.add_argument('--project-ids', dest='p_project_ids', action="append", type=integer, metavar='PROJECT_IDS', help='List of project IDs used to filter the visible field details returned.')
    c.set_defaults(handler=_run_jql_get_auto_complete_post, flags={'body.include_collapsed_fields': '--include-collapsed-fields', 'body.project_ids': '--project-ids'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_auto_complete_post', 'requires_one_of': [['--include-collapsed-fields', '--project-ids']]})
    c = g_jql_commands.add_parser('get-field-auto-complete-for-query-string', parents=[common], help='Get field auto complete suggestions', description='Returns the JQL search auto complete suggestions for a field.\n\nSuggestions can be obtained by providing:\n\n* `fieldName` to get a list of all values for the field. * `fieldName` and\n`fieldValue` to get a list of values containing the text in `fieldValue`. *\n`fieldName` and `predicateName` to get a list of all predicate values for the\nfield. * `fieldName`, `predicateName`, and `predicateValue` to get a list of\npredicate values containing the text in `predicateValue`.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira jql get-field-auto-complete-for-query-string']), formatter_class=RAW)
    c.add_argument('--field-name', dest='p_field_name', metavar='FIELD_NAME', help='The name of the field.')
    c.add_argument('--field-value', dest='p_field_value', metavar='FIELD_VALUE', help='The partial field item name entered by the user.')
    c.add_argument('--predicate-name', dest='p_predicate_name', metavar='PREDICATE_NAME', help='The name of the [ CHANGED operator predicate](https://confluence.atlassian.com/x/hQORLQ#Advancedsearching-operatorsreference-CHANGEDCHANGED) for which the suggestions are generated. The valid predicate operators are *by*, *from*, and *to*.')
    c.add_argument('--predicate-value', dest='p_predicate_value', metavar='PREDICATE_VALUE', help='The partial predicate item name entered by the user.')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='EXPERIMENTAL. A hint for the maximum number of suggestions to return for each of the field and predicate values. The value is capped at 50 and may be ignored, in which case the default of 15 is used. It is subject to change and may be removed without notice.')
    c.set_defaults(handler=_run_jql_get_field_auto_complete_for_query_string, flags={'field_name': '--field-name', 'field_value': '--field-value', 'predicate_name': '--predicate-name', 'predicate_value': '--predicate-value', 'max_results': '--max-results'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_field_auto_complete_for_query_string'})
    c = g_jql_commands.add_parser('parse-queries', parents=[common], help='Parse JQL query', description='Parses and validates JQL queries.\n\nValidation is performed in context of the current user.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s --validation {strict,warn,none} --queries QUERIES [options]', epilog=RUNTIME.command_epilog(['codapact-jira jql parse-queries --validation strict --queries QUERIES', 'codapact-jira jql parse-queries --validation strict --queries QUERIES --dry-run']), formatter_class=RAW)
    c.add_argument('--validation', dest='p_validation', choices=['strict', 'warn', 'none'], required=True, help='How to validate the JQL query and treat the validation results. Validation options include: (default: strict)')
    c.add_argument('--queries', dest='p_queries', action="append", metavar='QUERIES', required=True, help='A list of queries to parse.')
    c.set_defaults(handler=_run_jql_parse_queries, flags={'validation': '--validation', 'body.queries': '--queries'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'parse_jql_queries'})
    c = g_jql_commands.add_parser('migrate-queries', parents=[common], help='Convert user identifiers to account IDs in JQL queries', description='Converts one or more JQL queries with user identifiers (username or user key)\nto equivalent JQL queries with account IDs.\n\nYou may wish to use this operation if your system stores JQL queries and you\nwant to make them GDPR-compliant. For more information about GDPR-related\nchanges, see the [migration\nguide](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-\nuser-privacy-api-migration-guide/).\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira jql migrate-queries --query-strings QUERY_STRINGS', 'codapact-jira jql migrate-queries --query-strings QUERY_STRINGS --dry-run']), formatter_class=RAW)
    c.add_argument('--query-strings', dest='p_query_strings', action="append", metavar='QUERY_STRINGS', help='A list of queries with user identifiers. Maximum of 100 queries.')
    c.set_defaults(handler=_run_jql_migrate_queries, flags={'body.query_strings': '--query-strings'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'migrate_queries', 'requires_one_of': [['--query-strings']]})
    c = g_jql_commands.add_parser('sanitise-queries', parents=[common], help='Sanitize JQL queries', description='Sanitizes one or more JQL queries by converting readable details into IDs\nwhere a user doesn\'t have permission to view the entity.\n\nFor example, if the query contains the clause *project = \'Secret project\'*,\nand a user does not have browse permission for the project "Secret project",\nthe sanitized query replaces the clause with *project = 12345"* (where 12345\nis the ID of the project). If a user has the required permission, the clause\nis not sanitized. If the account ID is null, sanitizing is performed for an\nanonymous user.\n\nNote that sanitization doesn\'t make the queries GDPR-compliant, because it\ndoesn\'t remove user identifiers (username or user key). If you need to make\nqueries GDPR-compliant, use [Convert user identifiers to account IDs in JQL\nqueries](https://developer.atlassian.com/cloud/jira/platform/rest/v3/api-\ngroup-jql/#api-rest-api-3-jql-sanitize-post).\n\nBefore sanitization each JQL query is parsed. The queries are returned in the\nsame order that they were passed.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --queries @queries.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira jql sanitise-queries --queries @queries.json', 'codapact-jira jql sanitise-queries --queries @queries.json --dry-run']), formatter_class=RAW)
    c.add_argument('--queries', dest='p_queries', type=json_value, metavar="JSON", required=True, help='The list of JQL queries to sanitize. Must contain unique values. Maximum of 20 queries. JSON array of objects with query*, account_id (* required). Schema: codapact-jira describe jql sanitise-queries')
    c.set_defaults(handler=_run_jql_sanitise_queries, flags={'body.queries': '--queries'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'sanitise_jql_queries'})
    g_jql_functions_apps = commands.add_parser('jql-functions-apps', help='get-precomputations-by-id, list-precomputations, update-precomputations', description="Run 'codapact-jira jql-functions-apps COMMAND --help' for a command's options and examples.")
    g_jql_functions_apps_commands = g_jql_functions_apps.add_subparsers(dest="g_jql_functions_apps", metavar="COMMAND", required=True)
    c = g_jql_functions_apps_commands.add_parser('list-precomputations', parents=[common], help='Get precomputations (apps)', description="Returns the list of a function's precomputations along with information about\nwhen they were created, updated, and last used. Each precomputation has a\n`value` \\- the JQL fragment to replace the custom function clause with.\n\n**[Permissions](#permissions) required:** This API is only accessible to apps\nand apps can only inspect their own functions.\n\nThe new `read:app-data:jira` OAuth scope is 100% optional now, and not using\nit won't break your app. However, we recommend adding it to your app's scope\nlist because we will eventually make it mandatory.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira jql-functions-apps list-precomputations']), formatter_class=RAW)
    c.add_argument('--function-key', dest='p_function_key', action="append", metavar='FUNCTION_KEY', help='The function key in format:')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 100)')
    c.add_argument('--order-by', dest='p_order_by', metavar='ORDER_BY', help='[Order](#ordering) the results by a field:')
    c.set_defaults(handler=_run_jql_functions_apps_list_precomputations, flags={'function_key': '--function-key', 'start_at': '--start-at', 'max_results': '--max-results', 'order_by': '--order-by'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_precomputations'})
    c = g_jql_functions_apps_commands.add_parser('update-precomputations', parents=[common], help='Update precomputations (apps)', description="Update the precomputation value of a function created by a Forge/Connect app.\n\n**[Permissions](#permissions) required:** An API for apps to update their own\nprecomputations.\n\nThe new `write:app-data:jira` OAuth scope is 100% optional now, and not using\nit won't break your app. However, we recommend adding it to your app's scope\nlist because we will eventually make it mandatory.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira jql-functions-apps update-precomputations --values @values.json', 'codapact-jira jql-functions-apps update-precomputations --values @values.json --dry-run']), formatter_class=RAW)
    c.add_argument('--skip-not-found-precomputations', dest='p_skip_not_found_precomputations', action=argparse.BooleanOptionalAction, help='(default: False)')
    c.add_argument('--values', dest='p_values', type=json_value, metavar="JSON", help='JSON array of objects with id*, error, value (* required). Schema: codapact-jira describe jql-functions-apps update-precomputations')
    c.set_defaults(handler=_run_jql_functions_apps_update_precomputations, flags={'skip_not_found_precomputations': '--skip-not-found-precomputations', 'body.values': '--values'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_precomputations', 'requires_one_of': [['--values']]})
    c = g_jql_functions_apps_commands.add_parser('get-precomputations-by-id', parents=[common], help='Get precomputations by ID (apps)', description="Returns function precomputations by IDs, along with information about when\nthey were created, updated, and last used. Each precomputation has a `value`\n\\- the JQL fragment to replace the custom function clause with.\n\n**[Permissions](#permissions) required:** This API is only accessible to apps\nand apps can only inspect their own functions.\n\nThe new `read:app-data:jira` OAuth scope is 100% optional now, and not using\nit won't break your app. However, we recommend adding it to your app's scope\nlist because we will eventually make it mandatory.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira jql-functions-apps get-precomputations-by-id --precomputation-i-ds PRECOMPUTATION_I_DS', 'codapact-jira jql-functions-apps get-precomputations-by-id --precomputation-i-ds PRECOMPUTATION_I_DS --dry-run']), formatter_class=RAW)
    c.add_argument('--order-by', dest='p_order_by', metavar='ORDER_BY', help='[Order](#ordering) the results by a field:')
    c.add_argument('--precomputation-i-ds', dest='p_precomputation_i_ds', action="append", metavar='PRECOMPUTATION_I_DS')
    c.set_defaults(handler=_run_jql_functions_apps_get_precomputations_by_id, flags={'order_by': '--order-by', 'body.precomputation_i_ds': '--precomputation-i-ds'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_precomputations_by_id', 'requires_one_of': [['--precomputation-i-ds']]})
    g_labels = commands.add_parser('labels', help='list', description="Run 'codapact-jira labels COMMAND --help' for a command's options and examples.")
    g_labels_commands = g_labels.add_subparsers(dest="g_labels", metavar="COMMAND", required=True)
    c = g_labels_commands.add_parser('list', parents=[common], help='Get all labels', description='Returns a [paginated](#pagination) list of labels.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira labels list']), formatter_class=RAW)
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 1000)')
    c.add_argument('--arg-query', dest='p_arg_query', metavar='ARG_QUERY', help='Case-insensitive prefix used to filter labels before pagination.')
    c.add_argument('--scope', dest='p_scope', metavar='SCOPE', help='RECENT\\_PROJECTS or ALL\\_BROWSEABLE\\_PROJECTS. Omitted scope retains the unbounded search. Blank or unrecognised values use ALL\\_BROWSEABLE\\_PROJECTS.')
    c.set_defaults(handler=_run_labels_list, flags={'start_at': '--start-at', 'max_results': '--max-results', 'query': '--arg-query', 'scope': '--scope'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_all_labels'})
    g_license_metrics = commands.add_parser('license-metrics', help='get-approximate-application-license-count, get-approximate-license-count, get-license', description="Run 'codapact-jira license-metrics COMMAND --help' for a command's options and examples.")
    g_license_metrics_commands = g_license_metrics.add_subparsers(dest="g_license_metrics", metavar="COMMAND", required=True)
    c = g_license_metrics_commands.add_parser('get-license', parents=[common], help='Get license', description='Returns licensing information about the Jira instance.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira license-metrics get-license']), formatter_class=RAW)
    c.set_defaults(handler=_run_license_metrics_get_license, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_license'})
    c = g_license_metrics_commands.add_parser('get-approximate-license-count', parents=[common], help='Get approximate license count', description='Returns the approximate number of user accounts across all Jira licenses. Note\nthat this information is cached with a 7-day lifecycle and could be stale at\nthe time of call.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira license-metrics get-approximate-license-count']), formatter_class=RAW)
    c.set_defaults(handler=_run_license_metrics_get_approximate_license_count, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_approximate_license_count'})
    c = g_license_metrics_commands.add_parser('get-approximate-application-license-count', parents=[common], help='Get approximate application license count', description='Returns the total approximate number of user accounts for a single Jira\nlicense. Note that this information is cached with a 7-day lifecycle and could\nbe stale at the time of call.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s APPLICATION_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira license-metrics get-approximate-application-license-count APPLICATION_KEY']), formatter_class=RAW)
    c.add_argument('p_application_key', metavar='APPLICATION_KEY', nargs='?', default=argparse.SUPPRESS, choices=['jira-core', 'jira-product-discovery', 'jira-software', 'jira-servicedesk'], help='The ID of the application, represents a specific version of Jira.')
    c.add_argument('--application-key', dest='p_application_key', default=argparse.SUPPRESS, choices=['jira-core', 'jira-product-discovery', 'jira-software', 'jira-servicedesk'], help='same as APPLICATION_KEY')
    c.set_defaults(handler=_run_license_metrics_get_approximate_application_license_count, flags={'application_key': '--application-key'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_approximate_application_license_count'})
    g_migration_of_connect_modules_to_forge = commands.add_parser('migration-of-connect-modules-to-forge', help='connect-to-forge-migration-fetch-task-resource-fetch-migration-task-get, connect-to-forge-migration-task-submission-resource-submit-task-post', description="Run 'codapact-jira migration-of-connect-modules-to-forge COMMAND --help' for a command's options and examples.")
    g_migration_of_connect_modules_to_forge_commands = g_migration_of_connect_modules_to_forge.add_subparsers(dest="g_migration_of_connect_modules_to_forge", metavar="COMMAND", required=True)
    c = g_migration_of_connect_modules_to_forge_commands.add_parser('connect-to-forge-migration-fetch-task-resource-fetch-migration-task-get', parents=[common], help='Get Connect issue field migration task', description="Returns the details of a Connect issue field's migration to Forge.\n\nWhen migrating a Connect app to Forge, [Issue\nField](https://developer.atlassian.com/cloud/jira/software/modules/issue-\nfield/) modules must be converted to [Custom\nfield](https://developer.atlassian.com/platform/forge/manifest-\nreference/modules/jira-custom-field/). When the Forge version of the app is\ninstalled, Forge creates a [background\ntask](https://developer.atlassian.com/cloud/jira/platform/rest/v3/api-group-\ntasks/#api-group-tasks) to track the migration of field data across. This\nendpoint returns the status and other details of that background task.\n\nFor more details, see [Jira modules > Jira Custom\nFields](https://developer.atlassian.com/platform/adopting-forge-from-\nconnect/migrate-jira-custom-fields/).\n\n**[Permissions](#permissions) required:** Only Connect and Forge apps can make\nthis request.", usage='%(prog)s CONNECT_KEY JIRA_ISSUE_FIELDS_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira migration-of-connect-modules-to-forge connect-to-forge-migration-fetch-task-resource-fetch-migration-task-get CONNECT_KEY JIRA_ISSUE_FIELDS_KEY']), formatter_class=RAW)
    c.add_argument('p_connect_key', metavar='CONNECT_KEY', nargs='?', default=argparse.SUPPRESS, help='The key of the Connect app that contains the Jira issue field being migrated.')
    c.add_argument('p_jira_issue_fields_key', metavar='JIRA_ISSUE_FIELDS_KEY', nargs='?', default=argparse.SUPPRESS, help='The module key of the Connect issue field being migrated.')
    c.add_argument('--connect-key', dest='p_connect_key', default=argparse.SUPPRESS, metavar='CONNECT_KEY', help='same as CONNECT_KEY')
    c.add_argument('--jira-issue-fields-key', dest='p_jira_issue_fields_key', default=argparse.SUPPRESS, metavar='JIRA_ISSUE_FIELDS_KEY', help='same as JIRA_ISSUE_FIELDS_KEY')
    c.set_defaults(handler=_run_migration_of_connect_modules_to_forge_connect_to_forge_migration_fetch_task_resource_fetch_migration_task_get, flags={'connect_key': '--connect-key', 'jira_issue_fields_key': '--jira-issue-fields-key'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'connect_to_forge_migration_fetch_task_resource_fetch_migration_task_get'})
    c = g_migration_of_connect_modules_to_forge_commands.add_parser('connect-to-forge-migration-task-submission-resource-submit-task-post', parents=[common], help='Submit Connect issue field migration task', description='Submits a request to trigger migration of connect issue field to its Forge\ncustom field counterpart.\n\nWhen migrating a Connect app to Forge, [Issue\nField](https://developer.atlassian.com/cloud/jira/software/modules/issue-\nfield/) modules must be converted to [Custom\nfield](https://developer.atlassian.com/platform/forge/manifest-\nreference/modules/jira-custom-field/) modules. This endpoint triggers the\nbackground migration of field data. Use the GET endpoint to retrieve the\nstatus and progress of the task.\n\nFor more details, see [Jira modules > Jira Custom\nFields](https://developer.atlassian.com/platform/adopting-forge-from-\nconnect/migrate-jira-custom-fields/).\n\n**[Permissions](#permissions) required:** Only Connect and Forge apps can make\nthis request.', usage='%(prog)s CONNECT_KEY JIRA_ISSUE_FIELDS_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira migration-of-connect-modules-to-forge connect-to-forge-migration-task-submission-resource-submit-task-post CONNECT_KEY JIRA_ISSUE_FIELDS_KEY', 'codapact-jira migration-of-connect-modules-to-forge connect-to-forge-migration-task-submission-resource-submit-task-post CONNECT_KEY JIRA_ISSUE_FIELDS_KEY --dry-run']), formatter_class=RAW)
    c.add_argument('p_connect_key', metavar='CONNECT_KEY', nargs='?', default=argparse.SUPPRESS, help='The key of the Connect app that contains the Jira issue field being migrated.')
    c.add_argument('p_jira_issue_fields_key', metavar='JIRA_ISSUE_FIELDS_KEY', nargs='?', default=argparse.SUPPRESS, help='The module key of the Connect issue field being migrated.')
    c.add_argument('--connect-key', dest='p_connect_key', default=argparse.SUPPRESS, metavar='CONNECT_KEY', help='same as CONNECT_KEY')
    c.add_argument('--jira-issue-fields-key', dest='p_jira_issue_fields_key', default=argparse.SUPPRESS, metavar='JIRA_ISSUE_FIELDS_KEY', help='same as JIRA_ISSUE_FIELDS_KEY')
    c.add_argument('--retrigger-completed-migration', dest='p_retrigger_completed_migration', action=argparse.BooleanOptionalAction, help='Whether to retrigger the migration if it has already completed. (default: False)')
    c.set_defaults(handler=_run_migration_of_connect_modules_to_forge_connect_to_forge_migration_task_submission_resource_submit_task_post, flags={'connect_key': '--connect-key', 'jira_issue_fields_key': '--jira-issue-fields-key', 'retrigger_completed_migration': '--retrigger-completed-migration'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'connect_to_forge_migration_task_submission_resource_submit_task_post'})
    g_myself = commands.add_parser('myself', help='get-current-user, get-locale, get-preference, … (6 commands)', description="Run 'codapact-jira myself COMMAND --help' for a command's options and examples.")
    g_myself_commands = g_myself.add_subparsers(dest="g_myself", metavar="COMMAND", required=True)
    c = g_myself_commands.add_parser('get-preference', parents=[common], help='Get preference', description='Returns the value of a preference of the current user.\n\nNote that these keys are deprecated:\n\n* *jira.user.locale* The locale of the user. By default this is not set and\nthe user takes the locale of the instance. * *jira.user.timezone* The time\nzone of the user. By default this is not set and the user takes the timezone\nof the instance.\n\nThese system preferences keys will be deprecated by 15/07/2024. You can still\nretrieve these keys, but it will not have any impact on Notification\nbehaviour.\n\n* *user.notifications.watcher* Whether the user gets notified when they are\nwatcher. * *user.notifications.assignee* Whether the user gets notified when\nthey are assignee. * *user.notifications.reporter* Whether the user gets\nnotified when they are reporter. * *user.notifications.mentions* Whether the\nuser gets notified when they are mentions.\n\nUse [ Update a user profile](https://developer.atlassian.com/cloud/admin/user-\nmanagement/rest/#api-users-account-id-manage-profile-patch) from the user\nmanagement REST API to manage timezone and locale instead.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s --key KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira myself get-preference --key KEY']), formatter_class=RAW)
    c.add_argument('--key', dest='p_key', metavar='KEY', required=True, help='The key of the preference.')
    c.set_defaults(handler=_run_myself_get_preference, flags={'key': '--key'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_preference'})
    c = g_myself_commands.add_parser('set-preference', parents=[common], help='Set preference', description="Creates a preference for the user or updates a preference's value by sending a\nplain text string. For example, `false`. An arbitrary preference can be\ncreated with the value containing up to 255 characters. In addition, the\nfollowing keys define system preferences that can be set or created:\n\n* *user.notifications.mimetype* The mime type used in notifications sent to\nthe user. Defaults to `html`. * *user.default.share.private* Whether new [\nfilters](https://confluence.atlassian.com/x/eQiiLQ) are set to private.\nDefaults to `true`. * *user.keyboard.shortcuts.disabled* Whether keyboard\nshortcuts are disabled. Defaults to `false`. * *user.autowatch.disabled*\nWhether the user automatically watches issues they create or add a comment to.\nBy default, not set: the user takes the instance autowatch setting. *\n*user.notifiy.own.changes* Whether the user gets notified of their own\nchanges.\n\nNote that these keys are deprecated:\n\n* *jira.user.locale* The locale of the user. By default, not set. The user\ntakes the instance locale. * *jira.user.timezone* The time zone of the user.\nBy default, not set. The user takes the instance timezone.\n\nThese system preferences keys will be deprecated by 15/07/2024. You can still\nuse these keys to create arbitrary preferences, but it will not have any\nimpact on Notification behaviour.\n\n* *user.notifications.watcher* Whether the user gets notified when they are\nwatcher. * *user.notifications.assignee* Whether the user gets notified when\nthey are assignee. * *user.notifications.reporter* Whether the user gets\nnotified when they are reporter. * *user.notifications.mentions* Whether the\nuser gets notified when they are mentions.\n\nUse [ Update a user profile](https://developer.atlassian.com/cloud/admin/user-\nmanagement/rest/#api-users-account-id-manage-profile-patch) from the user\nmanagement REST API to manage timezone and locale instead.\n\n**[Permissions](#permissions) required:** Permission to access Jira.", usage='%(prog)s --key KEY --body BODY [options]', epilog=RUNTIME.command_epilog(['codapact-jira myself set-preference --key KEY --body BODY', 'codapact-jira myself set-preference --key KEY --body BODY --dry-run']), formatter_class=RAW)
    c.add_argument('--key', dest='p_key', metavar='KEY', required=True, help='The key of the preference. The maximum length is 255 characters.')
    c.add_argument('--body', dest='p_body', metavar='BODY', required=True, help='The value of the preference as a plain text string. The maximum length is 255 characters.')
    c.set_defaults(handler=_run_myself_set_preference, flags={'key': '--key', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'set_preference'})
    c = g_myself_commands.add_parser('remove-preference', parents=[common], help='Delete preference', description='Deletes a preference of the user, which restores the default value of system\ndefined settings.\n\nNote that these keys are deprecated:\n\n* *jira.user.locale* The locale of the user. By default, not set. The user\ntakes the instance locale. * *jira.user.timezone* The time zone of the user.\nBy default, not set. The user takes the instance timezone.\n\nUse [ Update a user profile](https://developer.atlassian.com/cloud/admin/user-\nmanagement/rest/#api-users-account-id-manage-profile-patch) from the user\nmanagement REST API to manage timezone and locale instead.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s --key KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira myself remove-preference --key KEY --dry-run', 'codapact-jira myself remove-preference --key KEY --yes']), formatter_class=RAW)
    c.add_argument('--key', dest='p_key', metavar='KEY', required=True, help='The key of the preference.')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_myself_remove_preference, flags={'key': '--key'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'remove_preference'})
    c = g_myself_commands.add_parser('get-locale', parents=[common], help='Get locale', description="Returns the locale for the user.\n\nIf the user has no language preference set (which is the default setting) or\nthis resource is accessed anonymous, the browser locale detected by Jira is\nreturned. Jira detects the browser locale using the *Accept-Language* header\nin the request. However, if this doesn't match a locale available Jira, the\nsite default locale is returned.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira myself get-locale']), formatter_class=RAW)
    c.set_defaults(handler=_run_myself_get_locale, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_locale'})
    c = g_myself_commands.add_parser('set-locale', parents=[common], help='[deprecated] Set locale', description='Deprecated, use [ Update a user\nprofile](https://developer.atlassian.com/cloud/admin/user-\nmanagement/rest/#api-users-account-id-manage-profile-patch) from the user\nmanagement REST API instead.\n\nSets the locale of the user. The locale must be one supported by the instance\nof Jira.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira myself set-locale --locale LOCALE', 'codapact-jira myself set-locale --locale LOCALE --dry-run']), formatter_class=RAW)
    c.add_argument('--locale', dest='p_locale', metavar='LOCALE', help='The locale code. The Java the locale format is used: a two character language code (ISO 639), an underscore, and two letter country code (ISO 3166). For example, en\\_US represents a locale of English (United States). Required on create.')
    c.set_defaults(handler=_run_myself_set_locale, flags={'body.locale': '--locale'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': True, 'operation': 'set_locale', 'requires_one_of': [['--locale']]})
    c = g_myself_commands.add_parser('get-current-user', parents=[common], help='Get current user', description='Returns details for the current user.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira myself get-current-user']), formatter_class=RAW)
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information about user in the response. This parameter accepts a comma-separated list. Expand options include:')
    c.set_defaults(handler=_run_myself_get_current_user, flags={'expand': '--expand'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_current_user'})
    g_permission_schemes = commands.add_parser('permission-schemes', help='create, create-permission-grant, delete, … (9 commands)', description="Run 'codapact-jira permission-schemes COMMAND --help' for a command's options and examples.")
    g_permission_schemes_commands = g_permission_schemes.add_subparsers(dest="g_permission_schemes", metavar="COMMAND", required=True)
    c = g_permission_schemes_commands.add_parser('list', parents=[common], help='Get all permission schemes', description='Returns all permission schemes.\n\n### About permission schemes and grants ###\n\nA permission scheme is a collection of permission grants. A permission grant\nconsists of a `holder` and a `permission`.\n\n#### Holder object ####\n\nThe `holder` object contains information about the user or group being granted\nthe permission. For example, the *Administer projects* permission is granted\nto a group named *Teams in space administrators*. In this case, the type is\n`"type": "group"`, and the parameter is the group name, `"parameter": "Teams\nin space administrators"` and the value is group ID, `"value":\n"ca85fac0-d974-40ca-a615-7af99c48d24f"`.\n\nThe `holder` object is defined by the following properties:\n\n* `type` Identifies the user or group (see the list of types below). *\n`parameter` As a group\'s name can change, use of `value` is recommended. The\nvalue of this property depends on the `type`. For example, if the `type` is a\ngroup, then you need to specify the group name. * `value` The value of this\nproperty depends on the `type`. If the `type` is a group, then you need to\nspecify the group ID. For other `type` it has the same value as `parameter`\n\nThe following `types` are available. The expected values for `parameter` and\n`value` are given in parentheses (some types may not have a `parameter` or\n`value`):\n\n* `anyone` Grant for anonymous users. * `applicationRole` Grant for users with\naccess to the specified application (application name, application name). See\n[Update product access settings](https://confluence.atlassian.com/x/3YxjL) for\nmore information. * `assignee` Grant for the user currently assigned to an\nissue. * `group` Grant for the specified group (`parameter` : group name,\n`value` : group ID). * `groupCustomField` Grant for a user in the group\nselected in the specified custom field (`parameter` : custom field ID, `value`\n: custom field ID). * `projectLead` Grant for a project lead. * `projectRole`\nGrant for the specified project role (`parameter` :project role ID, `value` :\nproject role ID). * `reporter` Grant for the user who reported the issue. *\n`sd.customer.portal.only` Jira Service Desk only. Grants customers permission\nto access the customer portal but not Jira. See [Customizing Jira Service Desk\npermissions](https://confluence.atlassian.com/x/24dKLg) for more information.\n* `user` Grant for the specified user (`parameter` : user ID - historically\nthis was the userkey but that is deprecated and the account ID should be used,\n`value` : user ID). * `userCustomField` Grant for a user selected in the\nspecified custom field (`parameter` : custom field ID, `value` : custom field\nID).\n\n#### Built-in permissions ####\n\nThe [built-in Jira permissions](https://confluence.atlassian.com/x/yodKLg) are\nlisted below. Apps can also define custom permissions. See the [project permis\nsion](https://developer.atlassian.com/cloud/jira/platform/modules/project-\npermission/) and [global permission](https://developer.atlassian.com/cloud/jir\na/platform/modules/global-permission/) module documentation for more\ninformation.\n\n**Administration permissions**\n\n* `ADMINISTER_PROJECTS` * `EDIT_WORKFLOW` * `EDIT_ISSUE_LAYOUT`\n\n**Project permissions**\n\n* `BROWSE_PROJECTS` * `MANAGE_SPRINTS_PERMISSION` (Jira Software only) *\n`SERVICEDESK_AGENT` (Jira Service Desk only) * `VIEW_DEV_TOOLS` (Jira Software\nonly) * `VIEW_READONLY_WORKFLOW`\n\n**Issue permissions**\n\n* `ASSIGNABLE_USER` * `ASSIGN_ISSUES` * `CLOSE_ISSUES` * `CREATE_ISSUES` *\n`DELETE_ISSUES` * `EDIT_ISSUES` * `LINK_ISSUES` * `MODIFY_REPORTER` *\n`MOVE_ISSUES` * `RESOLVE_ISSUES` * `SCHEDULE_ISSUES` * `SET_ISSUE_SECURITY` *\n`TRANSITION_ISSUES`\n\n**Voters and watchers permissions**\n\n* `MANAGE_WATCHERS` * `VIEW_VOTERS_AND_WATCHERS`\n\n**Comments permissions**\n\n* `ADD_COMMENTS` * `DELETE_ALL_COMMENTS` * `DELETE_OWN_COMMENTS` *\n`EDIT_ALL_COMMENTS` * `EDIT_OWN_COMMENTS`\n\n**Attachments permissions**\n\n* `CREATE_ATTACHMENTS` * `DELETE_ALL_ATTACHMENTS` * `DELETE_OWN_ATTACHMENTS`\n\n**Time tracking permissions**\n\n* `DELETE_ALL_WORKLOGS` * `DELETE_OWN_WORKLOGS` * `EDIT_ALL_WORKLOGS` *\n`EDIT_OWN_WORKLOGS` * `WORK_ON_ISSUES`\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira permission-schemes list']), formatter_class=RAW)
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use expand to include additional information in the response. This parameter accepts a comma-separated list. Note that permissions are included when you specify any value. Expand options include:')
    c.set_defaults(handler=_run_permission_schemes_list, flags={'expand': '--expand'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_all_permission_schemes'})
    c = g_permission_schemes_commands.add_parser('create', parents=[common], help='Create permission scheme', description='Creates a new permission scheme. You can create a permission scheme with or\nwithout defining a set of permission grants.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira permission-schemes create --body @body.json', 'codapact-jira permission-schemes create --body @body.json --dry-run']), formatter_class=RAW)
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use expand to include additional information in the response. This parameter accepts a comma-separated list. Note that permissions are always included when you specify any value. Expand options include:')
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='The permission scheme to create. JSON object with name*, description, expand, id, permissions, scope, self (* required). Schema: codapact-jira describe permission-schemes create')
    c.set_defaults(handler=_run_permission_schemes_create, flags={'expand': '--expand', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_permission_scheme'})
    c = g_permission_schemes_commands.add_parser('get', parents=[common], help='Get permission scheme', description='Returns a permission scheme.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s SCHEME_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira permission-schemes get SCHEME_ID']), formatter_class=RAW)
    c.add_argument('p_scheme_id', metavar='SCHEME_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the permission scheme to return.')
    c.add_argument('--scheme-id', dest='p_scheme_id', default=argparse.SUPPRESS, type=integer, metavar='SCHEME_ID', help='same as SCHEME_ID')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use expand to include additional information in the response. This parameter accepts a comma-separated list. Note that permissions are included when you specify any value. Expand options include:')
    c.set_defaults(handler=_run_permission_schemes_get, flags={'scheme_id': '--scheme-id', 'expand': '--expand'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_permission_scheme'})
    c = g_permission_schemes_commands.add_parser('update', parents=[common], help='Update permission scheme', description='Updates a permission scheme. Below are some important things to note when\nusing this resource:\n\n* If a permissions list is present in the request, then it is set in the\npermission scheme, overwriting *all existing* grants. * If you want to update\nonly the name and description, then do not send a permissions list in the\nrequest. * Sending an empty list will remove all permission grants from the\npermission scheme.\n\nIf you want to add or delete a permission grant instead of updating the whole\nlist, see [Create permission grant](#api-rest-api-3-permissionscheme-schemeId-\npermission-post) or [Delete permission scheme entity](#api-rest-\napi-3-permissionscheme-schemeId-permission-permissionId-delete).\n\nSee [About permission schemes and grants](../api-group-permission-\nschemes/#about-permission-schemes-and-grants) for more details.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s SCHEME_ID --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira permission-schemes update SCHEME_ID --body @body.json', 'codapact-jira permission-schemes update SCHEME_ID --body @body.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_scheme_id', metavar='SCHEME_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the permission scheme to update.')
    c.add_argument('--scheme-id', dest='p_scheme_id', default=argparse.SUPPRESS, type=integer, metavar='SCHEME_ID', help='same as SCHEME_ID')
