    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='JSON object with name*, description, expand, id, permissions, scope, self (* required). Schema: codapact-jira describe permission-schemes update')
    c.set_defaults(handler=_run_permission_schemes_update, flags={'scheme_id': '--scheme-id', 'expand': '--expand', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_permission_scheme'})
    c = g_permission_schemes_commands.add_parser('delete', parents=[common], help='Delete permission scheme', description='Deletes a permission scheme.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s SCHEME_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira permission-schemes delete SCHEME_ID --dry-run', 'codapact-jira permission-schemes delete SCHEME_ID --yes']), formatter_class=RAW)
