    c = g_permission_schemes_commands.add_parser('create-permission-grant', parents=[common], help='Create permission grant', description='Creates a permission grant in a permission scheme.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s SCHEME_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira permission-schemes create-permission-grant SCHEME_ID --holder @holder.json', 'codapact-jira permission-schemes create-permission-grant SCHEME_ID --holder @holder.json --dry-run']), formatter_class=RAW)
