    c = g_permission_schemes_commands.add_parser('get-grant', parents=[common], help='Get permission scheme grant', description='Returns a permission grant.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s SCHEME_ID PERMISSION_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira permission-schemes get-grant SCHEME_ID PERMISSION_ID']), formatter_class=RAW)
