    c.set_defaults(handler=_run_permission_schemes_get_grant, flags={'scheme_id': '--scheme-id', 'permission_id': '--permission-id', 'expand': '--expand'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_permission_scheme_grant'})
