    c.add_argument('p_scheme_id', metavar='SCHEME_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the permission scheme to delete the permission grant from.')
    c.add_argument('p_permission_id', metavar='PERMISSION_ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the permission grant to delete.')
    c.add_argument('--scheme-id', dest='p_scheme_id', default=argparse.SUPPRESS, type=integer, metavar='SCHEME_ID', help='same as SCHEME_ID')
