    c.set_defaults(handler=_run_permission_schemes_delete_entity, flags={'scheme_id': '--scheme-id', 'permission_id': '--permission-id'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_permission_scheme_entity'})
