    g_permissions_commands = g_permissions.add_subparsers(dest="g_permissions", metavar="COMMAND", required=True)
    c = g_permissions_commands.add_parser('list-my', parents=[common], help='Get my permissions', description="Returns a list of permissions indicating which permissions the user has.\nDetails of the user's permissions can be obtained in a global, project, issue\nor comment context.\n\nThe user is reported as having a project permission:\n\n* in the global context, if the user has the project permission in any\nproject. * for a project, where the project permission is determined using\nissue data, if the user meets the permission's criteria for any issue in the\nproject. Otherwise, if the user has the project permission in the project. *\nfor an issue, where a project permission is determined using issue data, if\nthe user has the permission in the issue. Otherwise, if the user has the\nproject permission in the project containing the issue. * for a comment, where\nthe user has both the permission to browse the comment and the project\npermission for the comment's parent issue. Only the BROWSE\\_PROJECTS\npermission is supported. If a `commentId` is provided whose `permissions` does\nnot equal BROWSE\\_PROJECTS, a 400 error will be returned.\n\nThis means that users may be shown as having an issue permission (such as\nEDIT\\_ISSUES) in the global context or a project context but may not have the\npermission for any or all issues. For example, if Reporters have the\nEDIT\\_ISSUES permission a user would be shown as having this permission in the\nglobal context or the context of a project, because any user can be a\nreporter. However, if they are not the user who reported the issue queried\nthey would not have EDIT\\_ISSUES permission for that issue.\n\nFor [Jira Service Management project\npermissions](https://support.atlassian.com/jira-cloud-\nadministration/docs/customize-jira-service-management-permissions/), this will\nbe evaluated similarly to a user in the customer portal. For example, if the\nBROWSE\\_PROJECTS permission is granted to Service Project Customer - Portal\nAccess, any users with access to the customer portal will have the\nBROWSE\\_PROJECTS permission.\n\nGlobal permissions are unaffected by context.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira permissions list-my']), formatter_class=RAW)
    c.add_argument('--project-key', dest='p_project_key', metavar='PROJECT_KEY', help='The key of project. Ignored if `projectId` is provided.')
    c.add_argument('--project-id', dest='p_project_id', metavar='PROJECT_ID', help='The ID of project.')
    c.add_argument('--issue-key', dest='p_issue_key', metavar='ISSUE_KEY', help='The key of the issue. Ignored if `issueId` is provided.')
    c.add_argument('--issue-id', dest='p_issue_id', metavar='ISSUE_ID', help='The ID of the issue.')
    c.add_argument('--permissions', dest='p_permissions', metavar='PERMISSIONS', help='A list of permission keys. (Required) This parameter accepts a comma-separated list. To get the list of available permissions, use [Get all permissions](#api-rest-api-3-permissions-get).')
    c.add_argument('--project-uuid', dest='p_project_uuid', metavar='PROJECT_UUID')
    c.add_argument('--project-configuration-uuid', dest='p_project_configuration_uuid', metavar='PROJECT_CONFIGURATION_UUID')
    c.add_argument('--comment-id', dest='p_comment_id', metavar='COMMENT_ID', help='The ID of the comment.')
    c.set_defaults(handler=_run_permissions_list_my, flags={'project_key': '--project-key', 'project_id': '--project-id', 'issue_key': '--issue-key', 'issue_id': '--issue-id', 'permissions': '--permissions', 'project_uuid': '--project-uuid', 'project_configuration_uuid': '--project-configuration-uuid', 'comment_id': '--comment-id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_my_permissions'})
    c = g_permissions_commands.add_parser('list-all', parents=[common], help='Get all permissions', description='Returns all permissions, including:\n\n* global permissions. * project permissions. * global permissions added by\nplugins.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira permissions list-all']), formatter_class=RAW)
    c.set_defaults(handler=_run_permissions_list_all, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_all_permissions'})
    c = g_permissions_commands.add_parser('list-bulk', parents=[common], help='Get bulk permissions', description="Returns:\n\n* for a list of global permissions, the global permissions granted to a user.\n* for a list of project permissions and lists of projects and issues, for each\nproject permission a list of the projects and issues a user can access or\nmanipulate.\n\nIf no account ID is provided, the operation returns details for the logged in\nuser.\n\nNote that:\n\n* Invalid project and issue IDs are ignored. * A maximum of 1000 projects and\n1000 issues can be checked. * Null values in `globalPermissions`,\n`projectPermissions`, `projectPermissions.projects`, and\n`projectPermissions.issues` are ignored. * Empty strings in\n`projectPermissions.permissions` are ignored.\n\n**Deprecation notice:** The required OAuth 2.0 scopes will be updated on June\n15, 2024.\n\n* **Classic**: `read:jira-work` * **Granular**: `read:permission:jira`\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg) to check the\npermissions for other users, otherwise none. However, Connect apps can make a\ncall from the app server to the product to obtain permission details for any\nuser, without admin permission. This Connect app ability doesn't apply to\ncalls made using AP.request() in a browser.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira permissions list-bulk --account-id ACCOUNT_ID', 'codapact-jira permissions list-bulk --account-id ACCOUNT_ID --dry-run']), formatter_class=RAW)
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='The account ID of a user.')
    c.add_argument('--global-permissions', dest='p_global_permissions', action="append", metavar='GLOBAL_PERMISSIONS', help='Global permissions to look up.')
    c.add_argument('--project-permissions', dest='p_project_permissions', type=json_value, metavar="JSON", help='Project permissions with associated projects and issues to look up. JSON array of objects with permissions*, issues, projects (* required). Schema: codapact-jira describe permissions list-bulk')
    c.set_defaults(handler=_run_permissions_list_bulk, flags={'body.account_id': '--account-id', 'body.global_permissions': '--global-permissions', 'body.project_permissions': '--project-permissions'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_bulk_permissions', 'requires_one_of': [['--account-id', '--global-permissions', '--project-permissions']]})
    c = g_permissions_commands.add_parser('list-permitted-projects', parents=[common], help='Get permitted projects', description='Returns all the projects where the user is granted a list of project\npermissions.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None.', usage='%(prog)s --permissions PERMISSIONS [options]', epilog=RUNTIME.command_epilog(['codapact-jira permissions list-permitted-projects --permissions PERMISSIONS', 'codapact-jira permissions list-permitted-projects --permissions PERMISSIONS --dry-run']), formatter_class=RAW)
