    c = g_plans_commands.add_parser('create', parents=[common], help='Create plan', description='Creates a plan.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --issue-sources @issue-sources.json --name NAME --scheduling @scheduling.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira plans create --issue-sources @issue-sources.json --name NAME --scheduling @scheduling.json', 'codapact-jira plans create --issue-sources @issue-sources.json --name NAME --scheduling @scheduling.json --dry-run']), formatter_class=RAW)
