    c.add_argument('--use-group-id', dest='p_use_group_id', action=argparse.BooleanOptionalAction, help='Whether to accept group IDs instead of group names. Group names are deprecated. (default: False)')
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True)
    c.set_defaults(handler=_run_plans_update, flags={'plan_id': '--plan-id', 'use_group_id': '--use-group-id', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_plan'})
