    c.add_argument('--owner', dest='p_owner', metavar='OWNER', help='The owner of the avatar. For a system avatar the owner is null (and nothing is returned). For non-system avatars this is the appropriate identifier, such as the ID for a project or the account ID for a user.')
    c.add_argument('--urls', dest='p_urls', type=json_value, metavar="JSON", help='The list of avatar icon URLs.')
