    c = g_project_components_commands.add_parser('create-component', parents=[common], help='Create component', description='Creates a component. Use components to provide containers for issues within a\nproject. Use components to provide containers for issues within a project.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Administer projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project in\nwhich the component is created or *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-components create-component --ari ARI', 'codapact-jira project-components create-component --ari ARI --dry-run']), formatter_class=RAW)
    c.add_argument('--ari', dest='p_ari', metavar='ARI', help="Compass component's ID. Can't be updated. Not required for creating a Project Component.")
    c.add_argument('--assignee', dest='p_assignee', type=json_value, metavar="JSON", help='The details of the user associated with `assigneeType`, if any. See `realAssignee` for details of the user assigned to issues created with this component. JSON object with account_id, account_type, active, app_type, application_roles, avatar_urls, display_name, email_address, expand, groups, guest, key, ... Schema: codapact-jira describe project-components create-component')
    c.add_argument('--assignee-type', dest='p_assignee_type', choices=['PROJECT_DEFAULT', 'COMPONENT_LEAD', 'PROJECT_LEAD', 'UNASSIGNED'], help='The nominal user type used to determine the assignee for issues created with this component. See `realAssigneeType` for details on how the type of the user, and hence the user, assigned to issues is determined. Can take the following values:')
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='The description for the component. Optional when creating or updating a component.')
    c.add_argument('--id', dest='p_id', metavar='ID', help='The unique identifier for the component.')
    c.add_argument('--is-assignee-type-valid', dest='p_is_assignee_type_valid', action=argparse.BooleanOptionalAction, help='Whether a user is associated with `assigneeType`. For example, if the `assigneeType` is set to `COMPONENT_LEAD` but the component lead is not set, then `false` is returned.')
    c.add_argument('--lead', dest='p_lead', type=json_value, metavar="JSON", help="The user details for the component's lead user. JSON object with account_id, account_type, active, app_type, application_roles, avatar_urls, display_name, email_address, expand, groups, guest, key, ... Schema: codapact-jira describe project-components create-component")
    c.add_argument('--lead-account-id', dest='p_lead_account_id', metavar='LEAD_ACCOUNT_ID', help="The accountId of the component's lead user. The accountId uniquely identifies the user across all Atlassian products. For example, *5b10ac8d82e05b22cc7d4ef5*.")
    c.add_argument('--lead-user-name', dest='p_lead_user_name', metavar='LEAD_USER_NAME', help='This property is no longer available and will be removed from the documentation soon. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--metadata', dest='p_metadata', type=json_value, metavar="JSON", help="Compass component's metadata. Can't be updated. Not required for creating a Project Component.")
    c.add_argument('--name', dest='p_name', metavar='NAME', help='The unique name for the component in the project. Required when creating a component. Optional when updating a component. The maximum length is 255 characters.')
    c.add_argument('--project', dest='p_project', metavar='PROJECT', help="The key of the project the component is assigned to. Required when creating a component. Can't be updated.")
    c.add_argument('--project-id', dest='p_project_id', type=integer, metavar='PROJECT_ID', help='The ID of the project the component is assigned to.')
    c.add_argument('--real-assignee', dest='p_real_assignee', type=json_value, metavar="JSON", help='The user assigned to issues created with this component, when `assigneeType` does not identify a valid assignee. JSON object with account_id, account_type, active, app_type, application_roles, avatar_urls, display_name, email_address, expand, groups, guest, key, ... Schema: codapact-jira describe project-components create-component')
    c.add_argument('--real-assignee-type', dest='p_real_assignee_type', choices=['PROJECT_DEFAULT', 'COMPONENT_LEAD', 'PROJECT_LEAD', 'UNASSIGNED'], help='The type of the assignee that is assigned to issues created with this component, when an assignee cannot be set from the `assigneeType`. For example, `assigneeType` is set to `COMPONENT_LEAD` but no component lead is set. This property is set to one of the following values:')
    c.add_argument('--self', dest='p_self', metavar='SELF', help='The URL of the component.')
