    c = g_project_role_actors_commands.add_parser('get-for-role', parents=[common], help='Get default actors for project role', description='Returns the [default actors](#api-rest-api-3-resolution-get) for the project\nrole.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-role-actors get-for-role ID']), formatter_class=RAW)
