    c = g_project_role_actors_commands.add_parser('add-to-role', parents=[common], help='Add default actors to project role', description="Adds [default actors](#api-rest-api-3-resolution-get) to a role. You may add\ngroups or users, but you cannot add groups and users in the same request.\n\nChanging a project role's default actors does not affect project role members\nfor projects already created.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).", usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-role-actors add-to-role ID --group GROUP', 'codapact-jira project-role-actors add-to-role ID --group GROUP --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the project role. Use [Get all project roles](#api-rest-api-3-role-get) to get a list of project role IDs.')
