    g_project_roles = commands.add_parser('project-roles', help='create, delete, fully, … (9 commands)', description="Run 'codapact-jira project-roles COMMAND --help' for a command's options and examples.")
    g_project_roles_commands = g_project_roles.add_subparsers(dest="g_project_roles", metavar="COMMAND", required=True)
    c = g_project_roles_commands.add_parser('list', parents=[common], help='Get project roles for project', description='Returns a list of [project roles](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-roles/) for the project returning the name\nand self URL for each role.\n\nNote that all project roles are shared with all projects in Jira Cloud. See\n[Get all project roles](#api-rest-api-3-role-get) for more information.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Administer Projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for any project on the\nsite or *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s PROJECT_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-roles list PROJECT_ID_OR_KEY']), formatter_class=RAW)
