    c.set_defaults(handler=_run_project_roles_list, flags={'project_id_or_key': '--project-id-or-key'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_project_roles'})
    c = g_project_roles_commands.add_parser('get', parents=[common], help='Get project role for project', description="Returns a project role's details and actors associated with the project. The\nlist of actors is sorted by display name.\n\nTo check whether a user belongs to a role based on their group memberships,\nuse [Get user](#api-rest-api-3-user-get) with the `groups` expand parameter\nselected. Then check whether the user keys and groups match with the actors\nreturned for the project.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Administer Projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project or\n*Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).", usage='%(prog)s PROJECT_ID_OR_KEY ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-roles get PROJECT_ID_OR_KEY ID']), formatter_class=RAW)
    c.add_argument('p_project_id_or_key', metavar='PROJECT_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The project ID or project key (case sensitive).')
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the project role. Use [Get all project roles](#api-rest-api-3-role-get) to get a list of project role IDs.')
    c.add_argument('--project-id-or-key', dest='p_project_id_or_key', default=argparse.SUPPRESS, metavar='PROJECT_ID_OR_KEY', help='same as PROJECT_ID_OR_KEY')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
