    c.set_defaults(handler=_run_project_roles_get, flags={'project_id_or_key': '--project-id-or-key', 'id': '--id', 'exclude_inactive_users': '--exclude-inactive-users'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_project_role'})
    c = g_project_roles_commands.add_parser('list-details', parents=[common], help='Get project role details', description='Returns all [project roles](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-roles/) and the details for each role. Note\nthat the list of project roles is common to all projects.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg) or *Administer\nprojects* [project permission](https://confluence.atlassian.com/x/yodKLg) for\nthe project.', usage='%(prog)s PROJECT_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-roles list-details PROJECT_ID_OR_KEY']), formatter_class=RAW)
    c.add_argument('p_project_id_or_key', metavar='PROJECT_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The project ID or project key (case sensitive).')
    c.add_argument('--project-id-or-key', dest='p_project_id_or_key', default=argparse.SUPPRESS, metavar='PROJECT_ID_OR_KEY', help='same as PROJECT_ID_OR_KEY')
    c.add_argument('--current-member', dest='p_current_member', action=argparse.BooleanOptionalAction, help='Whether the roles should be filtered to include only those the user is assigned to. (default: False)')
    c.add_argument('--exclude-connect-addons', dest='p_exclude_connect_addons', action=argparse.BooleanOptionalAction, help='(default: False)')
    c.add_argument('--exclude-other-service-roles', dest='p_exclude_other_service_roles', action=argparse.BooleanOptionalAction, help='Do not return the default JSM company-managed space from CSM spaces, or the default CSM roles from JSM spaces. (default: False)')
    c.set_defaults(handler=_run_project_roles_list_details, flags={'project_id_or_key': '--project-id-or-key', 'current_member': '--current-member', 'exclude_connect_addons': '--exclude-connect-addons', 'exclude_other_service_roles': '--exclude-other-service-roles'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_project_role_details'})
    c = g_project_roles_commands.add_parser('list-all', parents=[common], help='Get all project roles', description="Gets a list of all project roles, complete with project role details and\ndefault actors.\n\n### About project roles ###\n\n[Project roles](https://support.atlassian.com/jira-cloud-\nadministration/docs/manage-project-roles/) are a flexible way to to associate\nusers and groups with projects. In Jira Cloud, the list of project roles is\nshared globally with all projects, but each project can have a different set\nof actors associated with it (unlike groups, which have the same membership\nthroughout all Jira applications).\n\nProject roles are used in [permission schemes](#api-rest-\napi-3-permissionscheme-get), [email notification schemes](#api-rest-\napi-3-notificationscheme-get), [issue security levels](#api-rest-\napi-3-issuesecurityschemes-get), [comment visibility](#api-rest-api-3-comment-\nlist-post), and workflow conditions.\n\n#### Members and actors ####\n\nIn the Jira REST API, a member of a project role is called an *actor*. An\n*actor* is a group or user associated with a project role.\n\nActors may be set as [default members](https://support.atlassian.com/jira-\ncloud-administration/docs/manage-project-roles/#Specifying-'default-\nmembers'-for-a-project-role) of the project role or set at the project level:\n\n* Default actors: Users and groups that are assigned to the project role for\nall newly created projects. The default actors can be removed at the project\nlevel later if desired. * Actors: Users and groups that are associated with a\nproject role for a project, which may differ from the default actors. This\nenables you to assign a user to different roles in different projects.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-roles list-all']), formatter_class=RAW)
    c.set_defaults(handler=_run_project_roles_list_all, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_all_project_roles'})
    c = g_project_roles_commands.add_parser('create', parents=[common], help='Create project role', description='Creates a new project role with no [default actors](#api-rest-\napi-3-resolution-get). You can use the [Add default actors to project\nrole](#api-rest-api-3-role-id-actors-post) operation to add default actors to\nthe project role after creating it.\n\n*Note that although a new project role is available to all projects upon\ncreation, any default actors that are associated with the project role are not\nadded to projects that existed prior to the role being created.*<\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-roles create --description DESCRIPTION', 'codapact-jira project-roles create --description DESCRIPTION --dry-run']), formatter_class=RAW)
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='A description of the project role. Required when fully updating a project role. Optional when creating or partially updating a project role.')
    c.add_argument('--name', dest='p_name', metavar='NAME', help='The name of the project role. Must be unique. Cannot begin or end with whitespace. The maximum length is 255 characters. Required when creating a project role. Optional when partially updating a project role.')
    c.set_defaults(handler=_run_project_roles_create, flags={'body.description': '--description', 'body.name': '--name'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_project_role', 'requires_one_of': [['--description', '--name']]})
    c = g_project_roles_commands.add_parser('get-by-id', parents=[common], help='Get project role by ID', description='Gets the project role details and the default actors associated with the role.\nThe list of default actors is sorted by display name.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-roles get-by-id ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the project role. Use [Get all project roles](#api-rest-api-3-role-get) to get a list of project role IDs.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
    c.set_defaults(handler=_run_project_roles_get_by_id, flags={'id': '--id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_project_role_by_id'})
    c = g_project_roles_commands.add_parser('fully', parents=[common], help='Fully update project role', description="Updates the project role's name and description. You must include both a name\nand a description in the request.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).", usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-roles fully ID --description DESCRIPTION', 'codapact-jira project-roles fully ID --description DESCRIPTION --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the project role. Use [Get all project roles](#api-rest-api-3-role-get) to get a list of project role IDs.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='A description of the project role. Required when fully updating a project role. Optional when creating or partially updating a project role.')
    c.add_argument('--name', dest='p_name', metavar='NAME', help='The name of the project role. Must be unique. Cannot begin or end with whitespace. The maximum length is 255 characters. Required when creating a project role. Optional when partially updating a project role.')
    c.set_defaults(handler=_run_project_roles_fully, flags={'id': '--id', 'body.description': '--description', 'body.name': '--name'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'fully_update_project_role', 'requires_one_of': [['--description', '--name']]})
    c = g_project_roles_commands.add_parser('partial', parents=[common], help='Partial update project role', description="Updates either the project role's name or its description.\n\nYou cannot update both the name and description at the same time using this\noperation. If you send a request with a name and a description only the name\nis updated.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).", usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-roles partial ID --description DESCRIPTION', 'codapact-jira project-roles partial ID --description DESCRIPTION --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the project role. Use [Get all project roles](#api-rest-api-3-role-get) to get a list of project role IDs.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
