    c.add_argument('--name', dest='p_name', metavar='NAME', help='The name of the project role. Must be unique. Cannot begin or end with whitespace. The maximum length is 255 characters. Required when creating a project role. Optional when partially updating a project role.')
    c.set_defaults(handler=_run_project_roles_partial, flags={'id': '--id', 'body.description': '--description', 'body.name': '--name'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'partial_update_project_role', 'requires_one_of': [['--description', '--name']]})
    c = g_project_roles_commands.add_parser('delete', parents=[common], help='Delete project role', description='Deletes a project role. You must specify a replacement project role if you\nwish to delete a project role that is in use.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-roles delete ID --dry-run', 'codapact-jira project-roles delete ID --yes']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the project role to delete. Use [Get all project roles](#api-rest-api-3-role-get) to get a list of project role IDs.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
    c.add_argument('--swap', dest='p_swap', type=integer, metavar='SWAP', help='The ID of the project role that will replace the one being deleted. The swap will attempt to swap the role in schemes (notifications, permissions, issue security), workflows, worklogs and comments.')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_project_roles_delete, flags={'id': '--id', 'swap': '--swap'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_project_role'})
    g_project_templates = commands.add_parser('project-templates', help='create-project-with-custom-template, edit-template, live-template, … (5 commands)', description="Run 'codapact-jira project-templates COMMAND --help' for a command's options and examples.")
    g_project_templates_commands = g_project_templates.add_subparsers(dest="g_project_templates", metavar="COMMAND", required=True)
    c = g_project_templates_commands.add_parser('create-project-with-custom-template', parents=[common], help='Create custom project', description='Creates a project based on a custom template provided in the request.\n\nThe request body should contain the project details and the capabilities that\ncomprise the project:\n\n* `details` \\- represents the project details settings * `template` \\-\nrepresents a list of capabilities responsible for creating specific parts of a\nproject\n\nA capability is defined as a unit of configuration for the project you want to\ncreate.\n\nThis operation is:\n\n* [asynchronous](#async). Follow the `Location` link in the response header to\ndetermine the status of the task and use [Get task](#api-rest-api-3-task-\ntaskId-get) to obtain subsequent updates.\n\n***Note: This API is only supported for Jira Enterprise edition.***\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-templates create-project-with-custom-template --details @details.json', 'codapact-jira project-templates create-project-with-custom-template --details @details.json --dry-run']), formatter_class=RAW)
    c.add_argument('--details', dest='p_details', type=json_value, metavar="JSON", help='JSON object with access_level, additional_properties, assignee_type, avatar_id, category_id, description, enable_components, key, language, lead_account_id, name, url. Schema: codapact-jira describe project-templates create-project-with-custom-template')
    c.add_argument('--template', dest='p_template', type=json_value, metavar="JSON", help='JSON object with board_features, boards, field, issue_type, notification, permission_scheme, project, role, scope, security, workflow. Schema: codapact-jira describe project-templates create-project-with-custom-template')
    c.set_defaults(handler=_run_project_templates_create_project_with_custom_template, flags={'body.details': '--details', 'body.template': '--template'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_project_with_custom_template', 'requires_one_of': [['--details', '--template']]})
    c = g_project_templates_commands.add_parser('edit-template', parents=[common], help='Edit a custom project template', description='Edit custom template\n\nThis API endpoint allows you to edit an existing customised template.\n\n***Note: Custom Templates are only supported for Jira Enterprise edition.***', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-templates edit-template --template-description TEMPLATE_DESCRIPTION', 'codapact-jira project-templates edit-template --template-description TEMPLATE_DESCRIPTION --dry-run']), formatter_class=RAW)
    c.add_argument('--template-description', dest='p_template_description', metavar='TEMPLATE_DESCRIPTION', help='The description of the template')
    c.add_argument('--template-generation-options', dest='p_template_generation_options', type=json_value, metavar="JSON", help='JSON object with enable_screen_delegated_admin_support, enable_workflow_delegated_admin_support. Schema: codapact-jira describe project-templates edit-template')
    c.add_argument('--template-key', dest='p_template_key', metavar='TEMPLATE_KEY', help='The unique identifier of the template')
