    c = g_project_versions_commands.add_parser('create-version', parents=[common], help='Create version', description='Creates a project version.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg) or *Administer\nProjects* [project permission](https://confluence.atlassian.com/x/yodKLg) for\nthe project the version is added to.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-versions create-version --approvers @approvers.json', 'codapact-jira project-versions create-version --approvers @approvers.json --dry-run']), formatter_class=RAW)
    c.add_argument('--approvers', dest='p_approvers', type=json_value, metavar="JSON", help='If the expand option `approvers` is used, returns a list containing the approvers for this version. JSON array of objects with account_id, decline_reason, description, status. Schema: codapact-jira describe project-versions create-version')
