    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='The description of the version. Optional when creating or updating a version. The maximum size is 16,384 bytes.')
    c.add_argument('--driver', dest='p_driver', metavar='DRIVER', help='The Atlassian account ID of the version driver. Optional when creating or updating a version. If the expand option `driver` is used, returns the Atlassian account ID of the driver.')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](em>#expansion) to include additional information about version in the response. This parameter accepts a comma-separated list. Expand options include:')
