    c.add_argument('--issues-status-for-fix-version', dest='p_issues_status_for_fix_version', type=json_value, metavar="JSON", help='If the expand option `issuesstatus` is used, returns the count of issues in this version for each of the status categories *to do*, *in progress*, *done*, and *unmapped*. The *unmapped* property contains a count of issues with a status other than *to do*, *in progress*, and *done*. JSON object with done, in_progress, to_do, unmapped. Schema: codapact-jira describe project-versions create-version')
    c.add_argument('--move-unfixed-issues-to', dest='p_move_unfixed_issues_to', metavar='MOVE_UNFIXED_ISSUES_TO', help='The URL of the self link to the version to which all unfixed issues are moved when a version is released. Not applicable when creating a version. Optional when updating a version.')
    c.add_argument('--name', dest='p_name', metavar='NAME', help='The unique name of the version. Required when creating a version. Optional when updating a version. The maximum length is 255 characters.')
    c.add_argument('--operations', dest='p_operations', type=json_value, metavar="JSON", help='If the expand option `operations` is used, returns the list of operations available for this version. JSON array of objects with href, icon_class, id, label, style_class, title, weight. Schema: codapact-jira describe project-versions create-version')
    c.add_argument('--overdue', dest='p_overdue', action=argparse.BooleanOptionalAction, help='Indicates that the version is overdue.')
    c.add_argument('--project', dest='p_project', metavar='PROJECT', help='Deprecated. Use `projectId`.')
    c.add_argument('--project-id', dest='p_project_id', type=integer, metavar='PROJECT_ID', help='The ID of the project to which this version is attached. Required when creating a version. Not applicable when updating a version.')
    c.add_argument('--release-date', dest='p_release_date', metavar='YYYY-MM-DD', help='The release date of the version. Expressed in ISO 8601 format (yyyy-mm-dd). Optional when creating or updating a version.')
    c.add_argument('--released', dest='p_released', action=argparse.BooleanOptionalAction, help='Indicates that the version is released. If the version is released a request to release again is ignored. Not applicable when creating a version. Optional when updating a version.')
    c.add_argument('--self', dest='p_self', metavar='SELF', help='The URL of the version.')
    c.add_argument('--start-date', dest='p_start_date', metavar='YYYY-MM-DD', help='The start date of the version. Expressed in ISO 8601 format (yyyy-mm-dd). Optional when creating or updating a version.')
    c.add_argument('--user-release-date', dest='p_user_release_date', metavar='USER_RELEASE_DATE', help="The date on which work on this version is expected to finish, expressed in the instance's *Day/Month/Year Format* date format.")
    c.add_argument('--user-start-date', dest='p_user_start_date', metavar='USER_START_DATE', help="The date on which work on this version is expected to start, expressed in the instance's *Day/Month/Year Format* date format.")
    c.set_defaults(handler=_run_project_versions_create_version, flags={'body.approvers': '--approvers', 'body.archived': '--archived', 'body.description': '--description', 'body.driver': '--driver', 'body.expand': '--expand', 'body.id': '--id', 'body.issues_status_for_fix_version': '--issues-status-for-fix-version', 'body.move_unfixed_issues_to': '--move-unfixed-issues-to', 'body.name': '--name', 'body.operations': '--operations', 'body.overdue': '--overdue', 'body.project': '--project', 'body.project_id': '--project-id', 'body.release_date': '--release-date', 'body.released': '--released', 'body.self': '--self', 'body.start_date': '--start-date', 'body.user_release_date': '--user-release-date', 'body.user_start_date': '--user-start-date'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_version', 'requires_one_of': [['--approvers', '--archived', '--description', '--driver', '--expand', '--id', '--issues-status-for-fix-version', '--move-unfixed-issues-to', '--name', '--operations', '--overdue', '--project', '--project-id', '--release-date', '--released', '--self', '--start-date', '--user-release-date', '--user-start-date']]})
    c = g_project_versions_commands.add_parser('get-version', parents=[common], help='Get version', description='Returns a project version.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project\ncontaining the version.', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-versions get-version ID']), formatter_class=RAW)
