    c.set_defaults(handler=_run_project_versions_get_version, flags={'id': '--id', 'expand': '--expand'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_version'})
    c = g_project_versions_commands.add_parser('update-version', parents=[common], help='Update version', description='Updates a project version.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg) or *Administer\nProjects* [project permission](https://confluence.atlassian.com/x/yodKLg) for\nthe project that contains the version.', usage='%(prog)s ID --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-versions update-version ID --body @body.json', 'codapact-jira project-versions update-version ID --body @body.json --dry-run']), formatter_class=RAW)
