    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='JSON object with approvers, archived, description, driver, expand, id, issues_status_for_fix_version, move_unfixed_issues_to, name, operations, overdue, project, ... Schema: codapact-jira describe project-versions update-version')
    c.set_defaults(handler=_run_project_versions_update_version, flags={'id': '--id', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_version'})
    c = g_project_versions_commands.add_parser('delete-version', parents=[common], help='[deprecated] Delete version', description='Deletes a project version.\n\nDeprecated, use [ Delete and replace version](#api-rest-api-3-version-id-\nremoveAndSwap-post) that supports swapping version values in custom fields, in\naddition to the swapping for `fixVersion` and `affectedVersion` provided in\nthis resource.\n\nAlternative versions can be provided to update issues that use the deleted\nversion in `fixVersion` or `affectedVersion`. If alternatives are not\nprovided, occurrences of `fixVersion` and `affectedVersion` that contain the\ndeleted version are cleared.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg) or *Administer\nProjects* [project permission](https://confluence.atlassian.com/x/yodKLg) for\nthe project that contains the version.', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-versions delete-version ID --dry-run', 'codapact-jira project-versions delete-version ID --yes']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the version.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.add_argument('--move-fix-issues-to', dest='p_move_fix_issues_to', metavar='MOVE_FIX_ISSUES_TO', help='The ID of the version to update `fixVersion` to when the field contains the deleted version. The replacement version must be in the same project as the version being deleted and cannot be the version being deleted.')
    c.add_argument('--move-affected-issues-to', dest='p_move_affected_issues_to', metavar='MOVE_AFFECTED_ISSUES_TO', help='The ID of the version to update `affectedVersion` to when the field contains the deleted version. The replacement version must be in the same project as the version being deleted and cannot be the version being deleted.')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_project_versions_delete_version, flags={'id': '--id', 'move_fix_issues_to': '--move-fix-issues-to', 'move_affected_issues_to': '--move-affected-issues-to'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': True, 'operation': 'delete_version'})
    c = g_project_versions_commands.add_parser('merge-versions', parents=[common], help='Merge versions', description='Merges two project versions. The merge is completed by deleting the version\nspecified in `id` and replacing any occurrences of its ID in `fixVersion` with\nthe version ID specified in `moveIssuesTo`.\n\nConsider using [ Delete and replace version](#api-rest-api-3-version-id-\nremoveAndSwap-post) instead. This resource supports swapping version values in\n`fixVersion`, `affectedVersion`, and custom fields.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg) or *Administer\nProjects* [project permission](https://confluence.atlassian.com/x/yodKLg) for\nthe project that contains the version.', usage='%(prog)s ID MOVE_ISSUES_TO [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-versions merge-versions ID MOVE_ISSUES_TO', 'codapact-jira project-versions merge-versions ID MOVE_ISSUES_TO --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the version to delete.')
    c.add_argument('p_move_issues_to', metavar='MOVE_ISSUES_TO', nargs='?', default=argparse.SUPPRESS, help='The ID of the version to merge into.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.add_argument('--move-issues-to', dest='p_move_issues_to', default=argparse.SUPPRESS, metavar='MOVE_ISSUES_TO', help='same as MOVE_ISSUES_TO')
    c.set_defaults(handler=_run_project_versions_merge_versions, flags={'id': '--id', 'move_issues_to': '--move-issues-to'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'merge_versions'})
    c = g_project_versions_commands.add_parser('move-version', parents=[common], help='Move version', description="Modifies the version's sequence within the project, which affects the display\norder of the versions in Jira.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse projects* project permission\nfor the project that contains the version.", usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-versions move-version ID --after AFTER', 'codapact-jira project-versions move-version ID --after AFTER --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the version to be moved.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.add_argument('--after', dest='p_after', metavar='AFTER', help='The URL (self link) of the version after which to place the moved version. Cannot be used with `position`.')
    c.add_argument('--position', dest='p_position', choices=['Earlier', 'Later', 'First', 'Last'], help='An absolute position in which to place the moved version. Cannot be used with `after`.')
    c.set_defaults(handler=_run_project_versions_move_version, flags={'id': '--id', 'body.after': '--after', 'body.position': '--position'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'move_version', 'requires_one_of': [['--after', '--position']]})
    c = g_project_versions_commands.add_parser('list-version-related-issues', parents=[common], help="Get version's related issues count", description='Returns the following counts for a version:\n\n* Number of issues where the `fixVersion` is set to the version. * Number of\nissues where the `affectedVersion` is set to the version. * Number of issues\nwhere a version custom field is set to the version.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse projects* project permission\nfor the project that contains the version.', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-versions list-version-related-issues ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the version.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.set_defaults(handler=_run_project_versions_list_version_related_issues, flags={'id': '--id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_version_related_issues'})
    c = g_project_versions_commands.add_parser('get-related-work', parents=[common], help='Get related work', description='Returns related work items for the given version id.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project\ncontaining the version.', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-versions get-related-work ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the version.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.set_defaults(handler=_run_project_versions_get_related_work, flags={'id': '--id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_related_work'})
    c = g_project_versions_commands.add_parser('update-related-work', parents=[common], help='Update related work', description="Updates the given related work. You can only update generic link related works\nvia Rest APIs. Any archived version related works can't be edited.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Resolve issues:* and *Edit issues*\n[Managing project\npermissions](https://confluence.atlassian.com/adminjiraserver/managing-\nproject-permissions-938847145.html) for the project that contains the version.", usage='%(prog)s ID --category CATEGORY [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-versions update-related-work ID --category CATEGORY', 'codapact-jira project-versions update-related-work ID --category CATEGORY --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the version to update the related work on. For the related work id, pass it to the input JSON.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.add_argument('--category', dest='p_category', metavar='CATEGORY', required=True, help='The category of the related work')
    c.add_argument('--issue-id', dest='p_issue_id', type=integer, metavar='ISSUE_ID', help='The ID of the issue associated with the related work (if there is one). Cannot be updated via the Rest API.')
    c.add_argument('--related-work-id', dest='p_related_work_id', metavar='RELATED_WORK_ID', help='The id of the related work. For the native release note related work item, this will be null, and Rest API does not support updating it.')
    c.add_argument('--title', dest='p_title', metavar='TITLE', help='The title of the related work')
    c.add_argument('--url', dest='p_url', metavar='URL', help='The URL of the related work. Will be null for the native release note related work item, but is otherwise required.')
    c.set_defaults(handler=_run_project_versions_update_related_work, flags={'id': '--id', 'body.category': '--category', 'body.issue_id': '--issue-id', 'body.related_work_id': '--related-work-id', 'body.title': '--title', 'body.url': '--url'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_related_work'})
    c = g_project_versions_commands.add_parser('create-related-work', parents=[common], help='Create related work', description='Creates a related work for the given version. You can only create a generic\nlink type of related works via this API. relatedWorkId will be auto-generated\nUUID, that does not need to be provided.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Resolve issues:* and *Edit issues*\n[Managing project\npermissions](https://confluence.atlassian.com/adminjiraserver/managing-\nproject-permissions-938847145.html) for the project that contains the version.', usage='%(prog)s ID --category CATEGORY [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-versions create-related-work ID --category CATEGORY', 'codapact-jira project-versions create-related-work ID --category CATEGORY --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS)
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.add_argument('--category', dest='p_category', metavar='CATEGORY', required=True, help='The category of the related work')
    c.add_argument('--issue-id', dest='p_issue_id', type=integer, metavar='ISSUE_ID', help='The ID of the issue associated with the related work (if there is one). Cannot be updated via the Rest API.')
    c.add_argument('--related-work-id', dest='p_related_work_id', metavar='RELATED_WORK_ID', help='The id of the related work. For the native release note related work item, this will be null, and Rest API does not support updating it.')
    c.add_argument('--title', dest='p_title', metavar='TITLE', help='The title of the related work')
    c.add_argument('--url', dest='p_url', metavar='URL', help='The URL of the related work. Will be null for the native release note related work item, but is otherwise required.')
    c.set_defaults(handler=_run_project_versions_create_related_work, flags={'id': '--id', 'body.category': '--category', 'body.issue_id': '--issue-id', 'body.related_work_id': '--related-work-id', 'body.title': '--title', 'body.url': '--url'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_related_work'})
    c = g_project_versions_commands.add_parser('delete-and-replace-version', parents=[common], help='Delete and replace version', description='Deletes a project version.\n\nAlternative versions can be provided to update issues that use the deleted\nversion in `fixVersion`, `affectedVersion`, or any version picker custom\nfields. If alternatives are not provided, occurrences of `fixVersion`,\n`affectedVersion`, and any version picker custom field, that contain the\ndeleted version, are cleared. Any replacement version must be in the same\nproject as the version being deleted and cannot be the version being deleted.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg) or *Administer\nProjects* [project permission](https://confluence.atlassian.com/x/yodKLg) for\nthe project that contains the version.', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-versions delete-and-replace-version ID --custom-field-replacement-list @custom-field-replacement-list.json --dry-run', 'codapact-jira project-versions delete-and-replace-version ID --custom-field-replacement-list @custom-field-replacement-list.json --yes']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the version.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.add_argument('--custom-field-replacement-list', dest='p_custom_field_replacement_list', type=json_value, metavar="JSON", help='An array of custom field IDs (`customFieldId`) and version IDs (`moveTo`) to update when the fields contain the deleted version. JSON array of objects with custom_field_id, move_to. Schema: codapact-jira describe project-versions delete-and-replace-version')
    c.add_argument('--move-affected-issues-to', dest='p_move_affected_issues_to', type=integer, metavar='MOVE_AFFECTED_ISSUES_TO', help='The ID of the version to update `affectedVersion` to when the field contains the deleted version.')
    c.add_argument('--move-fix-issues-to', dest='p_move_fix_issues_to', type=integer, metavar='MOVE_FIX_ISSUES_TO', help='The ID of the version to update `fixVersion` to when the field contains the deleted version.')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_project_versions_delete_and_replace_version, flags={'id': '--id', 'body.custom_field_replacement_list': '--custom-field-replacement-list', 'body.move_affected_issues_to': '--move-affected-issues-to', 'body.move_fix_issues_to': '--move-fix-issues-to'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_and_replace_version', 'requires_one_of': [['--custom-field-replacement-list', '--move-affected-issues-to', '--move-fix-issues-to']]})
    c = g_project_versions_commands.add_parser('list-version-unresolved-issues', parents=[common], help="Get version's unresolved issues count", description='Returns counts of the issues and unresolved issues for the project version.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse projects* project permission\nfor the project that contains the version.', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-versions list-version-unresolved-issues ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the version.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, metavar='ID', help='same as ID')
    c.set_defaults(handler=_run_project_versions_list_version_unresolved_issues, flags={'id': '--id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_version_unresolved_issues'})
    c = g_project_versions_commands.add_parser('delete-related-work', parents=[common], help='Delete related work', description='Deletes the given related work for the given version.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Resolve issues:* and *Edit issues*\n[Managing project\npermissions](https://confluence.atlassian.com/adminjiraserver/managing-\nproject-permissions-938847145.html) for the project that contains the version.', usage='%(prog)s VERSION_ID RELATED_WORK_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira project-versions delete-related-work VERSION_ID RELATED_WORK_ID --dry-run', 'codapact-jira project-versions delete-related-work VERSION_ID RELATED_WORK_ID --yes']), formatter_class=RAW)
    c.add_argument('p_version_id', metavar='VERSION_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the version that the target related work belongs to.')
    c.add_argument('p_related_work_id', metavar='RELATED_WORK_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the related work to delete.')
    c.add_argument('--version-id', dest='p_version_id', default=argparse.SUPPRESS, metavar='VERSION_ID', help='same as VERSION_ID')
    c.add_argument('--related-work-id', dest='p_related_work_id', default=argparse.SUPPRESS, metavar='RELATED_WORK_ID', help='same as RELATED_WORK_ID')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_project_versions_delete_related_work, flags={'version_id': '--version-id', 'related_work_id': '--related-work-id'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_related_work'})
    g_projects = commands.add_parser('projects', help='archive, create, delete, … (13 commands)', description="Run 'codapact-jira projects COMMAND --help' for a command's options and examples.")
    g_projects_commands = g_projects.add_subparsers(dest="g_projects", metavar="COMMAND", required=True)
    c = g_projects_commands.add_parser('list', parents=[common], help='[deprecated] Get all projects', description='Returns all projects visible to the user. Deprecated, use [ Get projects\npaginated](#api-rest-api-3-project-search-get) that supports search and\npagination.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** Projects are returned only where the\nuser has *Browse Projects* or *Administer projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira projects list']), formatter_class=RAW)
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information in the response. This parameter accepts a comma-separated list. Expanded options include:')
    c.add_argument('--recent', dest='p_recent', type=integer, metavar='RECENT', help="Returns the user's most recently accessed projects. You may specify the number of results to return up to a maximum of 20. If access is anonymous, then the recently accessed projects are based on the current HTTP session.")
    c.add_argument('--properties', dest='p_properties', action="append", metavar='PROPERTIES', help='A list of project properties to return for the project. This parameter accepts a comma-separated list.')
    c.set_defaults(handler=_run_projects_list, flags={'expand': '--expand', 'recent': '--recent', 'properties': '--properties'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': True, 'operation': 'get_all_projects'})
    c = g_projects_commands.add_parser('create', parents=[common], help='Create project', description='Creates a project based on a project type template, as shown in the following\ntable:\n\n| Project Type Key | Project Template Key | |--|--| | `business` |\n`com.atlassian.jira-core-project-templates:jira-core-simplified-content-\nmanagement`, `com.atlassian.jira-core-project-templates:jira-core-simplified-\ndocument-approval`, `com.atlassian.jira-core-project-templates:jira-core-\nsimplified-lead-tracking`, `com.atlassian.jira-core-project-templates:jira-\ncore-simplified-process-control`, `com.atlassian.jira-core-project-\ntemplates:jira-core-simplified-procurement`, `com.atlassian.jira-core-project-\ntemplates:jira-core-simplified-project-management`, `com.atlassian.jira-core-\nproject-templates:jira-core-simplified-recruitment`, `com.atlassian.jira-core-\nproject-templates:jira-core-simplified-task-tracking` | | `service_desk` |\n`com.atlassian.servicedesk:simplified-it-service-management`,\n`com.atlassian.servicedesk:simplified-external-service-desk`,\n`com.atlassian.servicedesk:simplified-hr-service-desk`,\n`com.atlassian.servicedesk:simplified-facilities-service-desk`,\n`com.atlassian.servicedesk:simplified-legal-service-desk`,\n`com.atlassian.servicedesk:simplified-analytics-service-desk`,\n`com.atlassian.servicedesk:simplified-marketing-service-desk`,\n`com.atlassian.servicedesk:simplified-design-service-desk`,\n`com.atlassian.servicedesk:simplified-sales-service-desk`,\n`com.atlassian.servicedesk:simplified-finance-service-desk`,\n`com.atlassian.servicedesk:company-managed-blank-service-project`,\n`com.atlassian.servicedesk:company-managed-general-service-project`,\n`com.atlassian.servicedesk:team-managed-general-service-project`,\n`com.atlassian.servicedesk:next-gen-it-service-desk`,\n`com.atlassian.servicedesk:next-gen-hr-service-desk`,\n`com.atlassian.servicedesk:next-gen-legal-service-desk`,\n`com.atlassian.servicedesk:next-gen-marketing-service-desk`,\n`com.atlassian.servicedesk:next-gen-facilities-service-desk`,\n`com.atlassian.servicedesk:next-gen-analytics-service-desk`,\n`com.atlassian.servicedesk:next-gen-finance-service-desk`,\n`com.atlassian.servicedesk:next-gen-design-service-desk`,\n`com.atlassian.servicedesk:next-gen-sales-service-desk` | | `software` |\n`com.pyxis.greenhopper.jira:gh-simplified-agility-kanban`,\n`com.pyxis.greenhopper.jira:gh-simplified-agility-scrum`,\n`com.pyxis.greenhopper.jira:gh-simplified-basic`,\n`com.pyxis.greenhopper.jira:gh-simplified-kanban-classic`,\n`com.pyxis.greenhopper.jira:gh-simplified-scrum-classic` | |\n`customer_service` | `com.atlassian.jcs:customer-service-management` | The\nproject types are available according to the installed Jira features as\nfollows:\n\n* Jira Core, the default, enables `business` projects. * Jira Service\nManagement enables `service_desk` projects. * Jira Software enables `software`\nprojects. * Jira Customer Service enables `customer_service` projects.\n\nTo determine which features are installed, go to **Jira settings** > **Apps**\n> **Manage apps** and review the System Apps list. To add Jira Software or\nJira Service Management into a JIRA instance, use **Jira settings** > **Apps**\n> **Finding new apps**. For more information, see [ Managing add-\nons](https://confluence.atlassian.com/x/S31NLg).\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --key KEY --name NAME [options]', epilog=RUNTIME.command_epilog(['codapact-jira projects create --key KEY --name NAME', 'codapact-jira projects create --key KEY --name NAME --dry-run']), formatter_class=RAW)
    c.add_argument('--assignee-type', dest='p_assignee_type', choices=['PROJECT_LEAD', 'UNASSIGNED'], help='The default assignee when creating issues for this project.')
    c.add_argument('--avatar-id', dest='p_avatar_id', type=integer, metavar='AVATAR_ID', help="An integer value for the project's avatar.")
    c.add_argument('--category-id', dest='p_category_id', type=integer, metavar='CATEGORY_ID', help="The ID of the project's category. A complete list of category IDs is found using the [Get all project categories](#api-rest-api-3-projectCategory-get) operation.")
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='A brief description of the project.')
    c.add_argument('--field-configuration-scheme', dest='p_field_configuration_scheme', type=integer, metavar='FIELD_CONFIGURATION_SCHEME', help='Deprecated use [fieldScheme](https://developer.atlassian.com/cloud/jira/platform/rest/v3/api-group-field-schemes/#api-group-field-schemes) instead. The ID of the field configuration scheme for the project. Use the [Get all field configuration schemes](#api-rest-api-3-fieldconfigurationscheme-get) operation to get a list of field configuration scheme IDs. If you specify the field configuration scheme you cannot specify the project template key.')
    c.add_argument('--field-scheme', dest='p_field_scheme', type=integer, metavar='FIELD_SCHEME', help='The ID of the field scheme for the project. Use the [Get field schemes](#api-rest-api-3-config-fieldschemes-get) operation to get a list of field scheme IDs. If you specify the field scheme you cannot specify the project template key.')
    c.add_argument('--issue-security-scheme', dest='p_issue_security_scheme', type=integer, metavar='ISSUE_SECURITY_SCHEME', help='The ID of the issue security scheme for the project, which enables you to control who can and cannot view issues. Use the [Get issue security schemes](#api-rest-api-3-issuesecurityschemes-get) resource to get all issue security scheme IDs.')
    c.add_argument('--issue-type-scheme', dest='p_issue_type_scheme', type=integer, metavar='ISSUE_TYPE_SCHEME', help='The ID of the issue type scheme for the project. Use the [Get all issue type schemes](#api-rest-api-3-issuetypescheme-get) operation to get a list of issue type scheme IDs. If you specify the issue type scheme you cannot specify the project template key.')
    c.add_argument('--issue-type-screen-scheme', dest='p_issue_type_screen_scheme', type=integer, metavar='ISSUE_TYPE_SCREEN_SCHEME', help='The ID of the issue type screen scheme for the project. Use the [Get all issue type screen schemes](#api-rest-api-3-issuetypescreenscheme-get) operation to get a list of issue type screen scheme IDs. If you specify the issue type screen scheme you cannot specify the project template key.')
    c.add_argument('--key', dest='p_key', metavar='KEY', required=True, help='Project keys must be unique and start with an uppercase letter followed by one or more uppercase alphanumeric characters. The maximum length is 10 characters.')
    c.add_argument('--lead', dest='p_lead', metavar='LEAD', help='This parameter is deprecated because of privacy changes. Use `leadAccountId` instead. See the [migration guide](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details. The user name of the project lead. Either `lead` or `leadAccountId` must be set when creating a project. Cannot be provided with `leadAccountId`.')
    c.add_argument('--lead-account-id', dest='p_lead_account_id', metavar='LEAD_ACCOUNT_ID', help='The account ID of the project lead. Either `lead` or `leadAccountId` must be set when creating a project. Cannot be provided with `lead`.')
    c.add_argument('--name', dest='p_name', metavar='NAME', required=True, help='The name of the project.')
    c.add_argument('--notification-scheme', dest='p_notification_scheme', type=integer, metavar='NOTIFICATION_SCHEME', help='The ID of the notification scheme for the project. Use the [Get notification schemes](#api-rest-api-3-notificationscheme-get) resource to get a list of notification scheme IDs.')
    c.add_argument('--permission-scheme', dest='p_permission_scheme', type=integer, metavar='PERMISSION_SCHEME', help='The ID of the permission scheme for the project. Use the [Get all permission schemes](#api-rest-api-3-permissionscheme-get) resource to see a list of all permission scheme IDs.')
    c.add_argument('--project-template-key', dest='p_project_template_key', choices=['com.pyxis.greenhopper.jira:gh-simplified-agility-kanban', 'com.pyxis.greenhopper.jira:gh-simplified-agility-scrum', 'com.pyxis.greenhopper.jira:gh-simplified-basic', 'com.pyxis.greenhopper.jira:gh-simplified-kanban-classic', 'com.pyxis.greenhopper.jira:gh-simplified-scrum-classic', 'com.pyxis.greenhopper.jira:gh-cross-team-template', 'com.pyxis.greenhopper.jira:gh-cross-team-planning-template', 'com.atlassian.servicedesk:simplified-it-service-management', 'com.atlassian.servicedesk:simplified-it-service-management-basic', 'com.atlassian.servicedesk:simplified-it-service-management-operations', 'com.atlassian.servicedesk:simplified-internal-service-desk', 'com.atlassian.servicedesk:simplified-external-service-desk', 'com.atlassian.servicedesk:simplified-hr-service-desk', 'com.atlassian.servicedesk:simplified-facilities-service-desk', 'com.atlassian.servicedesk:simplified-legal-service-desk', 'com.atlassian.servicedesk:simplified-marketing-service-desk', 'com.atlassian.servicedesk:simplified-finance-service-desk', 'com.atlassian.servicedesk:simplified-analytics-service-desk', 'com.atlassian.servicedesk:simplified-design-service-desk', 'com.atlassian.servicedesk:simplified-sales-service-desk', 'com.atlassian.servicedesk:simplified-halp-service-desk', 'com.atlassian.servicedesk:next-gen-it-service-desk', 'com.atlassian.servicedesk:next-gen-hr-service-desk', 'com.atlassian.servicedesk:next-gen-legal-service-desk', 'com.atlassian.servicedesk:next-gen-marketing-service-desk', 'com.atlassian.servicedesk:next-gen-facilities-service-desk', 'com.atlassian.servicedesk:next-gen-analytics-service-desk', 'com.atlassian.servicedesk:next-gen-finance-service-desk', 'com.atlassian.servicedesk:next-gen-design-service-desk', 'com.atlassian.servicedesk:next-gen-sales-service-desk', 'com.atlassian.servicedesk:company-managed-blank-service-project', 'com.atlassian.servicedesk:company-managed-general-service-project', 'com.atlassian.servicedesk:team-managed-general-service-project', 'com.atlassian.jira-core-project-templates:jira-core-simplified-content-management', 'com.atlassian.jira-core-project-templates:jira-core-simplified-document-approval', 'com.atlassian.jira-core-project-templates:jira-core-simplified-lead-tracking', 'com.atlassian.jira-core-project-templates:jira-core-simplified-process-control', 'com.atlassian.jira-core-project-templates:jira-core-simplified-procurement', 'com.atlassian.jira-core-project-templates:jira-core-simplified-project-management', 'com.atlassian.jira-core-project-templates:jira-core-simplified-recruitment', 'com.atlassian.jira-core-project-templates:jira-core-simplified-task-', 'com.atlassian.jcs:customer-service-management'], help='A predefined configuration for a project. The type of the `projectTemplateKey` must match with the type of the `projectTypeKey`.')
