    c = g_projects_commands.add_parser('get-recent', parents=[common], help='Get recent projects', description='Returns a list of up to 20 projects recently viewed by the user that are still\nvisible to the user.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** Projects are returned only where the\nuser has one of:\n\n* *Browse Projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project. *\n*Administer Projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project. *\n*Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira projects get-recent']), formatter_class=RAW)
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information in the response. This parameter accepts a comma-separated list. Expanded options include:')
