    c.set_defaults(handler=_run_projects_get_recent, flags={'expand': '--expand', 'properties': '--properties'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_recent'})
    c = g_projects_commands.add_parser('search', parents=[common], help='Get projects paginated', description='Returns a [paginated](#pagination) list of projects visible to the user.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** Projects are returned only where the\nuser has one of:\n\n* *Browse Projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project. *\n*Administer Projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project. *\n*Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira projects search']), formatter_class=RAW)
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. Must be less than or equal to 100. If a value greater than 100 is provided, the `maxResults` parameter will default to 100. (default: 50)')
    c.add_argument('--order-by', dest='p_order_by', choices=['category', '-category', '+category', 'key', '-key', '+key', 'name', '-name', '+name', 'owner', '-owner', '+owner', 'issueCount', '-issueCount', '+issueCount', 'lastIssueUpdatedDate', '-lastIssueUpdatedDate', '+lastIssueUpdatedDate', 'archivedDate', '+archivedDate', '-archivedDate', 'deletedDate', '+deletedDate', '-deletedDate'], help='[Order](#ordering) the results by a field. (default: key)')
    c.add_argument('--id', dest='p_id', action="append", type=integer, metavar='ID', help='The project IDs to filter the results by. To include multiple IDs, provide an ampersand-separated list. For example, `id=10000&id=10001`. Up to 50 project IDs can be provided.')
    c.add_argument('--keys', dest='p_keys', action="append", metavar='KEYS', help='The project keys to filter the results by. To include multiple keys, provide an ampersand-separated list. For example, `keys=PA&keys=PB`. Up to 50 project keys can be provided.')
    c.add_argument('--arg-query', dest='p_arg_query', metavar='ARG_QUERY', help='Filter the results using a literal string. Projects with a matching `key` or `name` are returned (case insensitive).')
    c.add_argument('--type-key', dest='p_type_key', metavar='TYPE_KEY', help='Orders results by the [project type](https://confluence.atlassian.com/x/GwiiLQ#Jiraapplicationsoverview-Productfeaturesandprojecttypes). This parameter accepts a comma-separated list. Valid values are `business`, `service_desk`, and `software`.')
    c.add_argument('--category-id', dest='p_category_id', type=integer, metavar='CATEGORY_ID', help="The ID of the project's category. A complete list of category IDs is found using the [Get all project categories](#api-rest-api-3-projectCategory-get) operation.")
    c.add_argument('--action', dest='p_action', choices=['view', 'browse', 'edit', 'create'], help='Filter results by projects for which the user can: (default: view)')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information in the response. This parameter accepts a comma-separated list. Expanded options include:')
    c.add_argument('--status', dest='p_status', action="append", choices=['live', 'archived', 'deleted'], help='EXPERIMENTAL. Filter results by project status:')
    c.add_argument('--properties', dest='p_properties', type=json_value, metavar="JSON", help='EXPERIMENTAL. A list of project properties to return for the project. This parameter accepts a comma-separated list.')
    c.add_argument('--property-query', dest='p_property_query', metavar='PROPERTY_QUERY', help='EXPERIMENTAL. A query string used to search properties. The query string cannot be specified using a JSON object. For example, to search for the value of `nested` from `{"something":{"nested":1,"other":2}}` use `[thepropertykey].something.nested=1`. Note that the propertyQuery key is enclosed in square brackets to enable searching where the propertyQuery key includes dot (.) or equals (=) characters. Note that `thepropertykey` is only returned when included in `properties`.')
    c.set_defaults(handler=_run_projects_search, flags={'start_at': '--start-at', 'max_results': '--max-results', 'order_by': '--order-by', 'id': '--id', 'keys': '--keys', 'query': '--arg-query', 'type_key': '--type-key', 'category_id': '--category-id', 'action': '--action', 'expand': '--expand', 'status': '--status', 'properties': '--properties', 'property_query': '--property-query'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'search_projects'})
    c = g_projects_commands.add_parser('get', parents=[common], help='Get project', description='Returns the [project details](https://confluence.atlassian.com/x/ahLpNw) for a\nproject.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project.', usage='%(prog)s PROJECT_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira projects get PROJECT_ID_OR_KEY']), formatter_class=RAW)
    c.add_argument('p_project_id_or_key', metavar='PROJECT_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The project ID or project key (case sensitive).')
    c.add_argument('--project-id-or-key', dest='p_project_id_or_key', default=argparse.SUPPRESS, metavar='PROJECT_ID_OR_KEY', help='same as PROJECT_ID_OR_KEY')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information in the response. This parameter accepts a comma-separated list. Note that the project description, issue types, and project lead are included in all responses by default. Expand options include:')
    c.add_argument('--properties', dest='p_properties', action="append", metavar='PROPERTIES', help='A list of project properties to return for the project. This parameter accepts a comma-separated list. Note that only the properties named here are returned in `properties` in the response; that object is empty when this parameter is omitted.')
    c.set_defaults(handler=_run_projects_get, flags={'project_id_or_key': '--project-id-or-key', 'expand': '--expand', 'properties': '--properties'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_project'})
    c = g_projects_commands.add_parser('update', parents=[common], help='Update project', description='Updates the [project details](https://confluence.atlassian.com/x/ahLpNw) of a\nproject.\n\nAll parameters are optional in the body of the request. Schemes will only be\nupdated if they are included in the request, any omitted schemes will be left\nunchanged.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg). is only needed when\nchanging the schemes or project key. Otherwise you will only need *Administer\nProjects* [project permission](https://confluence.atlassian.com/x/yodKLg)', usage='%(prog)s PROJECT_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira projects update PROJECT_ID_OR_KEY --assignee-type PROJECT_LEAD', 'codapact-jira projects update PROJECT_ID_OR_KEY --assignee-type PROJECT_LEAD --dry-run']), formatter_class=RAW)
    c.add_argument('p_project_id_or_key', metavar='PROJECT_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The project ID or project key (case sensitive).')
    c.add_argument('--project-id-or-key', dest='p_project_id_or_key', default=argparse.SUPPRESS, metavar='PROJECT_ID_OR_KEY', help='same as PROJECT_ID_OR_KEY')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information in the response. This parameter accepts a comma-separated list. Note that the project description, issue types, and project lead are included in all responses by default. Expand options include:')
    c.add_argument('--assignee-type', dest='p_assignee_type', choices=['PROJECT_LEAD', 'UNASSIGNED'], help='The default assignee when creating issues for this project.')
    c.add_argument('--avatar-id', dest='p_avatar_id', type=integer, metavar='AVATAR_ID', help="An integer value for the project's avatar.")
    c.add_argument('--category-id', dest='p_category_id', type=integer, metavar='CATEGORY_ID', help="The ID of the project's category. A complete list of category IDs is found using the [Get all project categories](#api-rest-api-3-projectCategory-get) operation. To remove the project category from the project, set the value to `-1.`")
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='A brief description of the project.')
    c.add_argument('--issue-security-scheme', dest='p_issue_security_scheme', type=integer, metavar='ISSUE_SECURITY_SCHEME', help='The ID of the issue security scheme for the project, which enables you to control who can and cannot view issues. Use the [Get issue security schemes](#api-rest-api-3-issuesecurityschemes-get) resource to get all issue security scheme IDs.')
    c.add_argument('--key', dest='p_key', metavar='KEY', help='Project keys must be unique and start with an uppercase letter followed by one or more uppercase alphanumeric characters. The maximum length is 10 characters.')
    c.add_argument('--lead', dest='p_lead', metavar='LEAD', help='This parameter is deprecated because of privacy changes. Use `leadAccountId` instead. See the [migration guide](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details. The user name of the project lead. Cannot be provided with `leadAccountId`.')
    c.add_argument('--lead-account-id', dest='p_lead_account_id', metavar='LEAD_ACCOUNT_ID', help='The account ID of the project lead. Cannot be provided with `lead`.')
    c.add_argument('--name', dest='p_name', metavar='NAME', help='The name of the project.')
    c.add_argument('--notification-scheme', dest='p_notification_scheme', type=integer, metavar='NOTIFICATION_SCHEME', help='The ID of the notification scheme for the project. Use the [Get notification schemes](#api-rest-api-3-notificationscheme-get) resource to get a list of notification scheme IDs.')
    c.add_argument('--permission-scheme', dest='p_permission_scheme', type=integer, metavar='PERMISSION_SCHEME', help='The ID of the permission scheme for the project. Use the [Get all permission schemes](#api-rest-api-3-permissionscheme-get) resource to see a list of all permission scheme IDs.')
    c.add_argument('--released-project-keys', dest='p_released_project_keys', action="append", metavar='RELEASED_PROJECT_KEYS', help='Previous project keys to be released from the current project. Released keys must belong to the current project and not contain the current project key')
    c.add_argument('--url', dest='p_url', metavar='URL', help='A link to information about this project, such as project documentation')
    c.set_defaults(handler=_run_projects_update, flags={'project_id_or_key': '--project-id-or-key', 'expand': '--expand', 'body.assignee_type': '--assignee-type', 'body.avatar_id': '--avatar-id', 'body.category_id': '--category-id', 'body.description': '--description', 'body.issue_security_scheme': '--issue-security-scheme', 'body.key': '--key', 'body.lead': '--lead', 'body.lead_account_id': '--lead-account-id', 'body.name': '--name', 'body.notification_scheme': '--notification-scheme', 'body.permission_scheme': '--permission-scheme', 'body.released_project_keys': '--released-project-keys', 'body.url': '--url'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_project', 'requires_one_of': [['--assignee-type', '--avatar-id', '--category-id', '--description', '--issue-security-scheme', '--key', '--lead', '--lead-account-id', '--name', '--notification-scheme', '--permission-scheme', '--released-project-keys', '--url']]})
    c = g_projects_commands.add_parser('delete', parents=[common], help='Delete project', description="Deletes a project.\n\nYou can't delete a project if it's archived. To delete an archived project,\nrestore the project and then delete it. To restore a project, use the Jira UI.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).", usage='%(prog)s PROJECT_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira projects delete PROJECT_ID_OR_KEY --dry-run', 'codapact-jira projects delete PROJECT_ID_OR_KEY --yes']), formatter_class=RAW)
    c.add_argument('p_project_id_or_key', metavar='PROJECT_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The project ID or project key (case sensitive).')
    c.add_argument('--project-id-or-key', dest='p_project_id_or_key', default=argparse.SUPPRESS, metavar='PROJECT_ID_OR_KEY', help='same as PROJECT_ID_OR_KEY')
    c.add_argument('--enable-undo', dest='p_enable_undo', action=argparse.BooleanOptionalAction, help='Whether this project is placed in the Jira recycle bin where it will be available for restoration. (default: True)')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_projects_delete, flags={'project_id_or_key': '--project-id-or-key', 'enable_undo': '--enable-undo'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_project'})
    c = g_projects_commands.add_parser('archive', parents=[common], help='Archive project', description="Archives a project. You can't delete a project if it's archived. To delete an\narchived project, restore the project and then delete it. To restore a\nproject, use the Jira UI.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).", usage='%(prog)s PROJECT_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira projects archive PROJECT_ID_OR_KEY', 'codapact-jira projects archive PROJECT_ID_OR_KEY --dry-run']), formatter_class=RAW)
    c.add_argument('p_project_id_or_key', metavar='PROJECT_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The project ID or project key (case sensitive).')
    c.add_argument('--project-id-or-key', dest='p_project_id_or_key', default=argparse.SUPPRESS, metavar='PROJECT_ID_OR_KEY', help='same as PROJECT_ID_OR_KEY')
    c.set_defaults(handler=_run_projects_archive, flags={'project_id_or_key': '--project-id-or-key'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'archive_project'})
    c = g_projects_commands.add_parser('delete-asynchronously', parents=[common], help='Delete project asynchronously', description='Deletes a project asynchronously.\n\nThis operation is:\n\n* transactional, that is, if part of the delete fails the project is not\ndeleted. * [asynchronous](#async). Follow the `location` link in the response\nto determine the status of the task and use [Get task](#api-rest-api-3-task-\ntaskId-get) to obtain subsequent updates.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s PROJECT_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira projects delete-asynchronously PROJECT_ID_OR_KEY --dry-run', 'codapact-jira projects delete-asynchronously PROJECT_ID_OR_KEY --yes']), formatter_class=RAW)
    c.add_argument('p_project_id_or_key', metavar='PROJECT_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The project ID or project key (case sensitive).')
    c.add_argument('--project-id-or-key', dest='p_project_id_or_key', default=argparse.SUPPRESS, metavar='PROJECT_ID_OR_KEY', help='same as PROJECT_ID_OR_KEY')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_projects_delete_asynchronously, flags={'project_id_or_key': '--project-id-or-key'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_project_asynchronously'})
    c = g_projects_commands.add_parser('restore', parents=[common], help='Restore deleted or archived project', description='Restores a project that has been archived or placed in the Jira recycle bin.\n\n**[Permissions](#permissions) required:**\n\n* *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg)for Company managed\nprojects. * *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg) or *Administer\nprojects* [project permission](https://confluence.atlassian.com/x/yodKLg) for\nthe project for Team managed projects.', usage='%(prog)s PROJECT_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira projects restore PROJECT_ID_OR_KEY', 'codapact-jira projects restore PROJECT_ID_OR_KEY --dry-run']), formatter_class=RAW)
    c.add_argument('p_project_id_or_key', metavar='PROJECT_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The project ID or project key (case sensitive).')
