    c = g_projects_commands.add_parser('list-all-statuses', parents=[common], help='Get all statuses for project', description='Returns the valid statuses for a project. The statuses are grouped by issue\ntype, as each project has a set of valid issue types and each issue type has a\nset of valid statuses.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse Projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for the project.', usage='%(prog)s PROJECT_ID_OR_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira projects list-all-statuses PROJECT_ID_OR_KEY']), formatter_class=RAW)
    c.add_argument('p_project_id_or_key', metavar='PROJECT_ID_OR_KEY', nargs='?', default=argparse.SUPPRESS, help='The project ID or project key (case sensitive).')
