    c.set_defaults(handler=_run_time_tracking_list_available_implementations, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_available_time_tracking_implementations'})
    c = g_time_tracking_commands.add_parser('get-shared-configuration', parents=[common], help='Get time tracking settings', description='Returns the time tracking settings. This includes settings such as the time\nformat, default time unit, and others. For more information, see [Configuring\ntime tracking](https://confluence.atlassian.com/x/qoXKM).\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira time-tracking get-shared-configuration']), formatter_class=RAW)
    c.set_defaults(handler=_run_time_tracking_get_shared_configuration, flags={}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_shared_time_tracking_configuration'})
    c = g_time_tracking_commands.add_parser('set-shared-configuration', parents=[common], help='Set time tracking settings', description='Sets the time tracking settings.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --default-unit {minute,hour,day,week} --time-format {pretty,days,hours} --working-days-per-week WORKING_DAYS_PER_WEEK --working-hours-per-day WORKING_HOURS_PER_DAY [options]', epilog=RUNTIME.command_epilog(['codapact-jira time-tracking set-shared-configuration --default-unit minute --time-format pretty --working-days-per-week WORKING_DAYS_PER_WEEK --working-hours-per-day WORKING_HOURS_PER_DAY', 'codapact-jira time-tracking set-shared-configuration --default-unit minute --time-format pretty --working-days-per-week WORKING_DAYS_PER_WEEK --working-hours-per-day WORKING_HOURS_PER_DAY --dry-run']), formatter_class=RAW)
    c.add_argument('--default-unit', dest='p_default_unit', choices=['minute', 'hour', 'day', 'week'], required=True, help='The default unit of time applied to logged time.')
    c.add_argument('--time-format', dest='p_time_format', choices=['pretty', 'days', 'hours'], required=True, help="The format that will appear on an issue's *Time Spent* field.")
    c.add_argument('--working-days-per-week', dest='p_working_days_per_week', type=number, metavar='WORKING_DAYS_PER_WEEK', required=True, help='The number of days in a working week.')
    c.add_argument('--working-hours-per-day', dest='p_working_hours_per_day', type=number, metavar='WORKING_HOURS_PER_DAY', required=True, help='The number of hours in a working day.')
    c.set_defaults(handler=_run_time_tracking_set_shared_configuration, flags={'body.default_unit': '--default-unit', 'body.time_format': '--time-format', 'body.working_days_per_week': '--working-days-per-week', 'body.working_hours_per_day': '--working-hours-per-day'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'set_shared_time_tracking_configuration'})
    g_ui_modifications_apps = commands.add_parser('ui-modifications-apps', help='create-ui-modification, delete-ui-modification, list-ui-modifications, update-ui-modification', description="Run 'codapact-jira ui-modifications-apps COMMAND --help' for a command's options and examples.")
    g_ui_modifications_apps_commands = g_ui_modifications_apps.add_subparsers(dest="g_ui_modifications_apps", metavar="COMMAND", required=True)
    c = g_ui_modifications_apps_commands.add_parser('list-ui-modifications', parents=[common], help='Get UI modifications', description="Gets UI modifications. UI modifications can only be retrieved by Forge apps.\n\n**[Permissions](#permissions) required:** None.\n\nThe new `read:app-data:jira` OAuth scope is 100% optional now, and not using\nit won't break your app. However, we recommend adding it to your app's scope\nlist because we will eventually make it mandatory.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira ui-modifications-apps list-ui-modifications']), formatter_class=RAW)
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use expand to include additional information in the response. This parameter accepts a comma-separated list. Expand options include:')
    c.set_defaults(handler=_run_ui_modifications_apps_list_ui_modifications, flags={'start_at': '--start-at', 'max_results': '--max-results', 'expand': '--expand'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_ui_modifications'})
    c = g_ui_modifications_apps_commands.add_parser('create-ui-modification', parents=[common], help='Create UI modification', description="Creates a UI modification. UI modification can only be created by Forge apps.\n\nEach app can define up to 3000 UI modifications. Each UI modification can\ndefine up to 1000 contexts. The same context can be assigned to maximum 100 UI\nmodifications.\n\n**Context types:**\n\n* **Jira contexts:** For Jira view types, use `projectId` and `issueTypeId`.\nOne field can act as a wildcard. Supported Jira views: * `GIC` \\- Jira global\nissue create * `IssueView` \\- Jira issue view * `IssueTransition` \\- Jira\nissue transition * **Jira Service Management contexts:** For Jira Service\nManagement view types, use `portalId` and `requestTypeId`. Wildcards are not\nsupported. Supported JSM views: * `JSMRequestCreate` \\- Jira Service\nManagement request create portal view * **Agent view contexts:** For Agent\nview types, use `projectId` and `issueTypeId` like Jira contexts, and\noptionally set `requestTypeId`. `portalId` must not be set. One of\n`projectId`, `issueTypeId`, or `viewType` can act as a wildcard. Supported\nAgent views: * `GICAgentView` \\- Agent view variant of Jira global issue\ncreate * `IssueViewAgentView` \\- Agent view variant of Jira issue view *\n`IssueTransitionAgentView` \\- Agent view variant of Jira issue transition\n\n**[Permissions](#permissions) required:**\n\n* *None* if the UI modification is created without contexts. * *Browse\nprojects* [project permission](https://confluence.atlassian.com/x/yodKLg) for\none or more projects, if the UI modification is created with contexts.\n\nThe new `write:app-data:jira` OAuth scope is 100% optional now, and not using\nit won't break your app. However, we recommend adding it to your app's scope\nlist because we will eventually make it mandatory.", usage='%(prog)s --name NAME [options]', epilog=RUNTIME.command_epilog(['codapact-jira ui-modifications-apps create-ui-modification --name NAME', 'codapact-jira ui-modifications-apps create-ui-modification --name NAME --dry-run']), formatter_class=RAW)
    c.add_argument('--contexts', dest='p_contexts', type=json_value, metavar="JSON", help='List of contexts of the UI modification. The maximum number of contexts is 1000. JSON array of objects with id, is_available, issue_type_id, portal_id, project_id, request_type_id, view_type. Schema: codapact-jira describe ui-modifications-apps create-ui-modification')
    c.add_argument('--data', dest='p_data', metavar='DATA', help='The data of the UI modification. The maximum size of the data is 50000 characters.')
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='The description of the UI modification. The maximum length is 255 characters.')
    c.add_argument('--name', dest='p_name', metavar='NAME', required=True, help='The name of the UI modification. The maximum length is 255 characters.')
    c.set_defaults(handler=_run_ui_modifications_apps_create_ui_modification, flags={'body.contexts': '--contexts', 'body.data': '--data', 'body.description': '--description', 'body.name': '--name'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_ui_modification'})
    c = g_ui_modifications_apps_commands.add_parser('update-ui-modification', parents=[common], help='Update UI modification', description="Updates a UI modification. UI modification can only be updated by Forge apps.\n\nEach UI modification can define up to 1000 contexts. The same context can be\nassigned to maximum 100 UI modifications.\n\n**Context types:**\n\n* **Jira contexts:** For Jira view types, use `projectId` and `issueTypeId`.\nOne field can act as a wildcard. Supported Jira views: * `GIC` \\- Jira global\nissue create * `IssueView` \\- Jira issue view * `IssueTransition` \\- Jira\nissue transition * **Jira Service Management contexts:** For Jira Service\nManagement view types, use `portalId` and `requestTypeId`. Wildcards are not\nsupported. Supported JSM views: * `JSMRequestCreate` \\- Jira Service\nManagement request create portal view * **Agent view contexts:** For Agent\nview types, use `projectId` and `issueTypeId` like Jira contexts, and\noptionally set `requestTypeId`. `portalId` must not be set. One of\n`projectId`, `issueTypeId`, or `viewType` can act as a wildcard. Supported\nAgent views: * `GICAgentView` \\- Agent view variant of Jira global issue\ncreate * `IssueViewAgentView` \\- Agent view variant of Jira issue view *\n`IssueTransitionAgentView` \\- Agent view variant of Jira issue transition\n\n**[Permissions](#permissions) required:**\n\n* *None* if the UI modification is created without contexts. * *Browse\nprojects* [project permission](https://confluence.atlassian.com/x/yodKLg) for\none or more projects, if the UI modification is created with contexts.\n\nThe new `write:app-data:jira` OAuth scope is 100% optional now, and not using\nit won't break your app. However, we recommend adding it to your app's scope\nlist because we will eventually make it mandatory.", usage='%(prog)s UI_MODIFICATION_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira ui-modifications-apps update-ui-modification UI_MODIFICATION_ID --contexts @contexts.json', 'codapact-jira ui-modifications-apps update-ui-modification UI_MODIFICATION_ID --contexts @contexts.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_ui_modification_id', metavar='UI_MODIFICATION_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the UI modification.')
    c.add_argument('--ui-modification-id', dest='p_ui_modification_id', default=argparse.SUPPRESS, metavar='UI_MODIFICATION_ID', help='same as UI_MODIFICATION_ID')
    c.add_argument('--contexts', dest='p_contexts', type=json_value, metavar="JSON", help='List of contexts of the UI modification. The maximum number of contexts is 1000. If provided, replaces all existing contexts. JSON array of objects with id, is_available, issue_type_id, portal_id, project_id, request_type_id, view_type. Schema: codapact-jira describe ui-modifications-apps update-ui-modification')
    c.add_argument('--data', dest='p_data', metavar='DATA', help='The data of the UI modification. The maximum size of the data is 50000 characters.')
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='The description of the UI modification. The maximum length is 255 characters.')
    c.add_argument('--name', dest='p_name', metavar='NAME', help='The name of the UI modification. The maximum length is 255 characters.')
    c.set_defaults(handler=_run_ui_modifications_apps_update_ui_modification, flags={'ui_modification_id': '--ui-modification-id', 'body.contexts': '--contexts', 'body.data': '--data', 'body.description': '--description', 'body.name': '--name'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_ui_modification', 'requires_one_of': [['--contexts', '--data', '--description', '--name']]})
    c = g_ui_modifications_apps_commands.add_parser('delete-ui-modification', parents=[common], help='Delete UI modification', description="Deletes a UI modification. All the contexts that belong to the UI modification\nare deleted too. UI modification can only be deleted by Forge apps.\n\n**[Permissions](#permissions) required:** None.\n\nThe new `write:app-data:jira` OAuth scope is 100% optional now, and not using\nit won't break your app. However, we recommend adding it to your app's scope\nlist because we will eventually make it mandatory.", usage='%(prog)s UI_MODIFICATION_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira ui-modifications-apps delete-ui-modification UI_MODIFICATION_ID --dry-run', 'codapact-jira ui-modifications-apps delete-ui-modification UI_MODIFICATION_ID --yes']), formatter_class=RAW)
    c.add_argument('p_ui_modification_id', metavar='UI_MODIFICATION_ID', nargs='?', default=argparse.SUPPRESS, help='The ID of the UI modification.')
    c.add_argument('--ui-modification-id', dest='p_ui_modification_id', default=argparse.SUPPRESS, metavar='UI_MODIFICATION_ID', help='same as UI_MODIFICATION_ID')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_ui_modifications_apps_delete_ui_modification, flags={'ui_modification_id': '--ui-modification-id'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_ui_modification'})
