    g_user_properties_commands = g_user_properties.add_subparsers(dest="g_user_properties", metavar="COMMAND", required=True)
    c = g_user_properties_commands.add_parser('list-keys', parents=[common], help='Get user property keys', description="Returns the keys of all properties for a user.\n\nNote: This operation does not access the [user\nproperties](https://confluence.atlassian.com/x/8YxjL) created and maintained\nin Jira.\n\n**[Permissions](#permissions) required:**\n\n* *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg), to access the property\nkeys on any user. * Access to Jira, to access the calling user's property\nkeys.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira user-properties list-keys']), formatter_class=RAW)
