    c.set_defaults(handler=_run_user_properties_list_keys, flags={'account_id': '--account-id', 'user_key': '--user-key', 'username': '--username'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_user_property_keys'})
    c = g_user_properties_commands.add_parser('get', parents=[common], help='Get user property', description="Returns the value of a user's property. If no property key is provided [Get\nuser property keys](#api-rest-api-3-user-properties-get) is called.\n\nNote: This operation does not access the [user\nproperties](https://confluence.atlassian.com/x/8YxjL) created and maintained\nin Jira.\n\n**[Permissions](#permissions) required:**\n\n* *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg), to get a property from\nany user. * Access to Jira, to get a property from the calling user's record.", usage='%(prog)s PROPERTY_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira user-properties get PROPERTY_KEY']), formatter_class=RAW)
    c.add_argument('p_property_key', metavar='PROPERTY_KEY', nargs='?', default=argparse.SUPPRESS, help="The key of the user's property.")
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='The account ID of the user, which uniquely identifies the user across all Atlassian products. For example, *5b10ac8d82e05b22cc7d4ef5*.')
    c.add_argument('--user-key', dest='p_user_key', metavar='USER_KEY', help='This parameter is no longer available and will be removed from the documentation soon. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--username', dest='p_username', metavar='USERNAME', help='This parameter is no longer available and will be removed from the documentation soon. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--property-key', dest='p_property_key', default=argparse.SUPPRESS, metavar='PROPERTY_KEY', help='same as PROPERTY_KEY')
    c.set_defaults(handler=_run_user_properties_get, flags={'account_id': '--account-id', 'user_key': '--user-key', 'username': '--username', 'property_key': '--property-key'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_user_property'})
    c = g_user_properties_commands.add_parser('set', parents=[common], help='Set user property', description="Sets the value of a user's property. Use this resource to store custom data\nagainst a user.\n\nNote: This operation does not access the [user\nproperties](https://confluence.atlassian.com/x/8YxjL) created and maintained\nin Jira.\n\n**[Permissions](#permissions) required:**\n\n* *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg), to set a property on\nany user. * Access to Jira, to set a property on the calling user's record.", usage='%(prog)s PROPERTY_KEY --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira user-properties set PROPERTY_KEY --body @body.json', 'codapact-jira user-properties set PROPERTY_KEY --body @body.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_property_key', metavar='PROPERTY_KEY', nargs='?', default=argparse.SUPPRESS, help="The key of the user's property. The maximum length is 255 characters.")
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='The account ID of the user, which uniquely identifies the user across all Atlassian products. For example, *5b10ac8d82e05b22cc7d4ef5*.')
    c.add_argument('--user-key', dest='p_user_key', metavar='USER_KEY', help='This parameter is no longer available and will be removed from the documentation soon. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--username', dest='p_username', metavar='USERNAME', help='This parameter is no longer available and will be removed from the documentation soon. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--property-key', dest='p_property_key', default=argparse.SUPPRESS, metavar='PROPERTY_KEY', help='same as PROPERTY_KEY')
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='The value of the property. The value has to be a valid, non-empty [JSON](https://tools.ietf.org/html/rfc4627) value. The maximum length of the property value is 32768 bytes.')
    c.set_defaults(handler=_run_user_properties_set, flags={'account_id': '--account-id', 'user_key': '--user-key', 'username': '--username', 'property_key': '--property-key', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'set_user_property'})
    c = g_user_properties_commands.add_parser('delete', parents=[common], help='Delete user property', description="Deletes a property from a user.\n\nNote: This operation does not access the [user\nproperties](https://confluence.atlassian.com/x/8YxjL) created and maintained\nin Jira.\n\n**[Permissions](#permissions) required:**\n\n* *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg), to delete a property\nfrom any user. * Access to Jira, to delete a property from the calling user's\nrecord.", usage='%(prog)s PROPERTY_KEY [options]', epilog=RUNTIME.command_epilog(['codapact-jira user-properties delete PROPERTY_KEY --dry-run', 'codapact-jira user-properties delete PROPERTY_KEY --yes']), formatter_class=RAW)
    c.add_argument('p_property_key', metavar='PROPERTY_KEY', nargs='?', default=argparse.SUPPRESS, help="The key of the user's property.")
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='The account ID of the user, which uniquely identifies the user across all Atlassian products. For example, *5b10ac8d82e05b22cc7d4ef5*.')
    c.add_argument('--user-key', dest='p_user_key', metavar='USER_KEY', help='This parameter is no longer available and will be removed from the documentation soon. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--username', dest='p_username', metavar='USERNAME', help='This parameter is no longer available and will be removed from the documentation soon. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--property-key', dest='p_property_key', default=argparse.SUPPRESS, metavar='PROPERTY_KEY', help='same as PROPERTY_KEY')
