    g_user_search = commands.add_parser('user-search', help='find-assignable-users, find-bulk-assignable-users, find-user-keys-by-query, … (8 commands)', description="Run 'codapact-jira user-search COMMAND --help' for a command's options and examples.")
    g_user_search_commands = g_user_search.add_subparsers(dest="g_user_search", metavar="COMMAND", required=True)
    c = g_user_search_commands.add_parser('find-bulk-assignable-users', parents=[common], help='Find users assignable to projects', description="Returns a list of users who can be assigned issues in one or more projects.\nThe list may be restricted to users whose attributes match a string.\n\nThis operation takes the users in the range defined by `startAt` and\n`maxResults`, up to the thousandth user, and then returns only the users from\nthat range that can be assigned issues in the projects. This means the\noperation usually returns fewer users than specified in `maxResults`. To get\nall the users who can be assigned issues in the projects, use [Get all\nusers](#api-rest-api-3-users-search-get) and filter the records in your code.\n\nPrivacy controls are applied to the response based on the users' preferences.\nThis could mean, for example, that the user's email address is hidden. See the\n[Profile visibility\noverview](https://developer.atlassian.com/cloud/jira/platform/profile-\nvisibility/) for more details.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse Projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for each project\nspecified in `projectKeys`.", usage='%(prog)s --project-keys PROJECT_KEYS [options]', epilog=RUNTIME.command_epilog(['codapact-jira user-search find-bulk-assignable-users --project-keys PROJECT_KEYS']), formatter_class=RAW)
    c.add_argument('--arg-query', dest='p_arg_query', metavar='ARG_QUERY', help="A query string that is matched against user attributes, such as `displayName` and `emailAddress`, to find relevant users. The string can match the prefix of the attribute's value. For example, *query=john* matches a user with a `displayName` of *John Smith* and a user with an `emailAddress` of *johnson@example.com*. Required, unless `accountId` is specified.")
    c.add_argument('--username', dest='p_username', metavar='USERNAME', help='This parameter is no longer available. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='A query string that is matched exactly against user `accountId`. Required, unless `query` is specified.')
    c.add_argument('--project-keys', dest='p_project_keys', metavar='PROJECT_KEYS', required=True, help='A list of project keys (case sensitive). This parameter accepts a comma-separated list.')
