    c = g_user_search_commands.add_parser('find-assignable-users', parents=[common], help='Find users assignable to issues', description="Returns a list of users that can be assigned to an issue. Use this operation\nto find the list of users who can be assigned to:\n\n* a new issue, by providing the `projectKeyOrId`. * an updated issue, by\nproviding the `issueKey` or `issueId`. * to an issue during a transition\n(workflow action), by providing the `issueKey` or `issueId` and the transition\nid in `actionDescriptorId`. You can obtain the IDs of an issue's valid\ntransitions using the `transitions` option in the `expand` parameter of [ Get\nissue](#api-rest-api-3-issue-issueIdOrKey-get).\n\nIn all these cases, you can pass an account ID to determine if a user can be\nassigned to an issue. The user is returned in the response if they can be\nassigned to the issue or issue transition.\n\nThis operation takes the users in the range defined by `startAt` and\n`maxResults`, up to the thousandth user, and then returns only the users from\nthat range that can be assigned the issue. This means the operation usually\nreturns fewer users than specified in `maxResults`. To get all the users who\ncan be assigned the issue, use [Get all users](#api-rest-api-3-users-search-\nget) and filter the records in your code.\n\nPrivacy controls are applied to the response based on the users' preferences.\nThis could mean, for example, that the user's email address is hidden. See the\n[Profile visibility\noverview](https://developer.atlassian.com/cloud/jira/platform/profile-\nvisibility/) for more details.\n\n**[Permissions](#permissions) required:** *Browse users and groups* [global\npermission](https://confluence.atlassian.com/x/x4dKLg) or *Assign issues*\n[project permission](https://confluence.atlassian.com/x/yodKLg)", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira user-search find-assignable-users']), formatter_class=RAW)
    c.add_argument('--arg-query', dest='p_arg_query', metavar='ARG_QUERY', help="A query string that is matched against user attributes, such as `displayName`, and `emailAddress`, to find relevant users. The string can match the prefix of the attribute's value. For example, *query=john* matches a user with a `displayName` of *John Smith* and a user with an `emailAddress` of *johnson@example.com*. Required, unless `username` or `accountId` is specified.")
    c.add_argument('--session-id', dest='p_session_id', metavar='SESSION_ID', help='The sessionId of this request. SessionId is the same until the assignee is set.')
    c.add_argument('--username', dest='p_username', metavar='USERNAME', help='This parameter is no longer available. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='A query string that is matched exactly against user `accountId`. Required, unless `query` is specified.')
    c.add_argument('--project', dest='p_project', metavar='PROJECT', help='The project ID or project key (case sensitive). Required, unless `issueKey` or `issueId` is specified.')
    c.add_argument('--issue-key', dest='p_issue_key', metavar='ISSUE_KEY', help='The key of the issue. Required, unless `issueId` or `project` is specified.')
    c.add_argument('--issue-id', dest='p_issue_id', metavar='ISSUE_ID', help='The ID of the issue. Required, unless `issueKey` or `project` is specified.')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return. This operation may return less than the maximum number of items even if more are available. The operation fetches users up to the maximum and then, from the fetched users, returns only the users that can be assigned to the issue. (default: 50)')
    c.add_argument('--action-descriptor-id', dest='p_action_descriptor_id', type=integer, metavar='ACTION_DESCRIPTOR_ID', help='The ID of the transition.')
    c.add_argument('--recommend', dest='p_recommend', action=argparse.BooleanOptionalAction, help='(default: False)')
    c.add_argument('--account-type', dest='p_account_type', action="append", metavar='ACCOUNT_TYPE')
    c.add_argument('--app-type', dest='p_app_type', action="append", metavar='APP_TYPE')
    c.set_defaults(handler=_run_user_search_find_assignable_users, flags={'query': '--arg-query', 'session_id': '--session-id', 'username': '--username', 'account_id': '--account-id', 'project': '--project', 'issue_key': '--issue-key', 'issue_id': '--issue-id', 'start_at': '--start-at', 'max_results': '--max-results', 'action_descriptor_id': '--action-descriptor-id', 'recommend': '--recommend', 'account_type': '--account-type', 'app_type': '--app-type'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'find_assignable_users'})
    c = g_user_search_commands.add_parser('find-users-with-all-permissions', parents=[common], help='Find users with permissions', description="Returns a list of users who fulfill these criteria:\n\n* their user attributes match a search string. * they have a set of\npermissions for a project or issue.\n\nIf no search string is provided, a list of all users with the permissions is\nreturned.\n\nThis operation takes the users in the range defined by `startAt` and\n`maxResults`, up to the thousandth user, and then returns only the users from\nthat range that match the search string and have permission for the project or\nissue. This means the operation usually returns fewer users than specified in\n`maxResults`. To get all the users who match the search string and have\npermission for the project or issue, use [Get all users](#api-rest-\napi-3-users-search-get) and filter the records in your code.\n\nPrivacy controls are applied to the response based on the users' preferences.\nThis could mean, for example, that the user's email address is hidden. See the\n[Profile visibility\noverview](https://developer.atlassian.com/cloud/jira/platform/profile-\nvisibility/) for more details.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:**\n\n* *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg), to get users for any\nproject. * *Administer Projects* [project\npermission](https://confluence.atlassian.com/x/yodKLg) for a project, to get\nusers for that project.", usage='%(prog)s --permissions PERMISSIONS [options]', epilog=RUNTIME.command_epilog(['codapact-jira user-search find-users-with-all-permissions --permissions PERMISSIONS']), formatter_class=RAW)
    c.add_argument('--arg-query', dest='p_arg_query', metavar='ARG_QUERY', help="A query string that is matched against user attributes, such as `displayName` and `emailAddress`, to find relevant users. The string can match the prefix of the attribute's value. For example, *query=john* matches a user with a `displayName` of *John Smith* and a user with an `emailAddress` of *johnson@example.com*. Required, unless `accountId` is specified.")
    c.add_argument('--username', dest='p_username', metavar='USERNAME', help='This parameter is no longer available. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='A query string that is matched exactly against user `accountId`. Required, unless `query` is specified.')
    c.add_argument('--permissions', dest='p_permissions', metavar='PERMISSIONS', required=True, help='A comma separated list of permissions. Permissions can be specified as any:')
    c.add_argument('--issue-key', dest='p_issue_key', metavar='ISSUE_KEY', help='The issue key for the issue.')
    c.add_argument('--project-key', dest='p_project_key', metavar='PROJECT_KEY', help='The project key for the project (case sensitive).')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
