    c.set_defaults(handler=_run_user_search_find_users_with_all_permissions, flags={'query': '--arg-query', 'username': '--username', 'account_id': '--account-id', 'permissions': '--permissions', 'issue_key': '--issue-key', 'project_key': '--project-key', 'start_at': '--start-at', 'max_results': '--max-results'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'find_users_with_all_permissions'})
    c = g_user_search_commands.add_parser('find-users-for-picker', parents=[common], help='Find users for picker', description="Returns a list of users whose attributes match the query term. The returned\nobject includes the `html` field where the matched query term is highlighted\nwith the HTML strong tag. A list of account IDs can be provided to exclude\nusers from the results.\n\nThis operation takes the users in the range defined by `maxResults`, up to the\nthousandth user, and then returns only the users from that range that match\nthe query term. This means the operation usually returns fewer users than\nspecified in `maxResults`. To get all the users who match the query term, use\n[Get all users](#api-rest-api-3-users-search-get) and filter the records in\nyour code.\n\nPrivacy controls are applied to the response based on the users' preferences.\nThis could mean, for example, that the user's email address is hidden. See the\n[Profile visibility\noverview](https://developer.atlassian.com/cloud/jira/platform/profile-\nvisibility/) for more details.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse users and groups* [global\npermission](https://confluence.atlassian.com/x/x4dKLg). Anonymous calls and\ncalls by users without the required permission return search results for an\nexact name match only.", usage='%(prog)s --arg-query ARG_QUERY [options]', epilog=RUNTIME.command_epilog(['codapact-jira user-search find-users-for-picker --arg-query ARG_QUERY']), formatter_class=RAW)
    c.add_argument('--arg-query', dest='p_arg_query', metavar='ARG_QUERY', required=True, help="A query string that is matched against user attributes, such as `displayName`, and `emailAddress`, to find relevant users. The string can match the prefix of the attribute's value. For example, *query=john* matches a user with a `displayName` of *John Smith* and a user with an `emailAddress` of *johnson@example.com*.")
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return. The total number of matched users is returned in `total`. (default: 50)')
