    c = g_user_search_commands.add_parser('find-users', parents=[common], help='Find users', description="Returns a list of active users that match the search string and property.\n\nThis operation first applies a filter to match the search string and property,\nand then takes the filtered users in the range defined by `startAt` and\n`maxResults`, up to the thousandth user. To get all the users who match the\nsearch string and property, use [Get all users](#api-rest-api-3-users-search-\nget) and filter the records in your code.\n\nThis operation can be accessed anonymously.\n\nPrivacy controls are applied to the response based on the users' preferences.\nThis could mean, for example, that the user's email address is hidden. See the\n[Profile visibility\noverview](https://developer.atlassian.com/cloud/jira/platform/profile-\nvisibility/) for more details.\n\n**[Permissions](#permissions) required:** *Browse users and groups* [global\npermission](https://confluence.atlassian.com/x/x4dKLg). Anonymous calls or\ncalls by users without the required permission return empty search results.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira user-search find-users']), formatter_class=RAW)
    c.add_argument('--arg-query', dest='p_arg_query', metavar='ARG_QUERY', help="A query string that is matched against user attributes ( `displayName`, and `emailAddress`) to find relevant users. The string can match the prefix of the attribute's value. For example, *query=john* matches a user with a `displayName` of *John Smith* and a user with an `emailAddress` of *johnson@example.com*. Required, unless `accountId` or `property` is specified.")
    c.add_argument('--username', dest='p_username', metavar='USERNAME')
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='A query string that is matched exactly against a user `accountId`. Required, unless `query` or `property` is specified.')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of filtered results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.add_argument('--property', dest='p_property', metavar='PROPERTY', help='A query string used to search properties. Property keys are specified by path, so property keys containing dot (.) or equals (=) characters cannot be used. The query string cannot be specified using a JSON object. Example: To search for the value of `nested` from `{"something":{"nested":1,"other":2}}` use `thepropertykey.something.nested=1`. Required, unless `accountId` or `query` is specified.')
    c.set_defaults(handler=_run_user_search_find_users, flags={'query': '--arg-query', 'username': '--username', 'account_id': '--account-id', 'start_at': '--start-at', 'max_results': '--max-results', 'property': '--property'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'find_users'})
    c = g_user_search_commands.add_parser('find-users-by-query', parents=[common], help='Find users by query', description='Finds users with a structured query and returns a [paginated](#pagination)\nlist of user details.\n\nThis operation takes the users in the range defined by `startAt` and\n`maxResults`, up to the thousandth user, and then returns only the users from\nthat range that match the structured query. This means the operation usually\nreturns fewer users than specified in `maxResults`. To get all the users who\nmatch the structured query, use [Get all users](#api-rest-api-3-users-search-\nget) and filter the records in your code.\n\n**[Permissions](#permissions) required:** *Browse users and groups* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).\n\nThe query statements are:\n\n* `is assignee of PROJ` Returns the users that are assignees of at least one\nissue in project *PROJ*. * `is assignee of (PROJ-1, PROJ-2)` Returns users\nthat are assignees on the issues *PROJ-1* or *PROJ-2*. * `is reporter of\n(PROJ-1, PROJ-2)` Returns users that are reporters on the issues *PROJ-1* or\n*PROJ-2*. * `is watcher of (PROJ-1, PROJ-2)` Returns users that are watchers\non the issues *PROJ-1* or *PROJ-2*. * `is voter of (PROJ-1, PROJ-2)` Returns\nusers that are voters on the issues *PROJ-1* or *PROJ-2*. * `is commenter of\n(PROJ-1, PROJ-2)` Returns users that have posted a comment on the issues\n*PROJ-1* or *PROJ-2*. * `is transitioner of (PROJ-1, PROJ-2)` Returns users\nthat have performed a transition on issues *PROJ-1* or *PROJ-2*. *\n`[propertyKey].entity.property.path is "property value"` Returns users with\nthe entity property value. For example, if user property `location` is set to\nvalue `{"office": {"country": "AU", "city": "Sydney"}}`, then it\'s possible to\nuse `[location].office.city is "Sydney"` to match the user.\n\nThe list of issues can be extended as needed, as in *(PROJ-1, PROJ-2, ...\nPROJ-n)*. Statements can be combined using the `AND` and `OR` operators to\nform more complex queries. For example:\n\n`is assignee of PROJ AND [propertyKey].entity.property.path is "property\nvalue"`', usage='%(prog)s --arg-query ARG_QUERY [options]', epilog=RUNTIME.command_epilog(['codapact-jira user-search find-users-by-query --arg-query ARG_QUERY']), formatter_class=RAW)
    c.add_argument('--arg-query', dest='p_arg_query', metavar='ARG_QUERY', required=True, help='The search query.')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 100)')
    c.set_defaults(handler=_run_user_search_find_users_by_query, flags={'query': '--arg-query', 'start_at': '--start-at', 'max_results': '--max-results'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'find_users_by_query'})
    c = g_user_search_commands.add_parser('find-user-keys-by-query', parents=[common], help='Find user keys by query', description='Finds users with a structured query and returns a [paginated](#pagination)\nlist of user keys.\n\nThis operation takes the users in the range defined by `startAt` and\n`maxResults`, up to the thousandth user, and then returns only the users from\nthat range that match the structured query. This means the operation usually\nreturns fewer users than specified in `maxResults`. To get all the users who\nmatch the structured query, use [Get all users](#api-rest-api-3-users-search-\nget) and filter the records in your code.\n\n**[Permissions](#permissions) required:** *Browse users and groups* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).\n\nThe query statements are:\n\n* `is assignee of PROJ` Returns the users that are assignees of at least one\nissue in project *PROJ*. * `is assignee of (PROJ-1, PROJ-2)` Returns users\nthat are assignees on the issues *PROJ-1* or *PROJ-2*. * `is reporter of\n(PROJ-1, PROJ-2)` Returns users that are reporters on the issues *PROJ-1* or\n*PROJ-2*. * `is watcher of (PROJ-1, PROJ-2)` Returns users that are watchers\non the issues *PROJ-1* or *PROJ-2*. * `is voter of (PROJ-1, PROJ-2)` Returns\nusers that are voters on the issues *PROJ-1* or *PROJ-2*. * `is commenter of\n(PROJ-1, PROJ-2)` Returns users that have posted a comment on the issues\n*PROJ-1* or *PROJ-2*. * `is transitioner of (PROJ-1, PROJ-2)` Returns users\nthat have performed a transition on issues *PROJ-1* or *PROJ-2*. *\n`[propertyKey].entity.property.path is "property value"` Returns users with\nthe entity property value. For example, if user property `location` is set to\nvalue `{"office": {"country": "AU", "city": "Sydney"}}`, then it\'s possible to\nuse `[location].office.city is "Sydney"` to match the user.\n\nThe list of issues can be extended as needed, as in *(PROJ-1, PROJ-2, ...\nPROJ-n)*. Statements can be combined using the `AND` and `OR` operators to\nform more complex queries. For example:\n\n`is assignee of PROJ AND [propertyKey].entity.property.path is "property\nvalue"`', usage='%(prog)s --arg-query ARG_QUERY [options]', epilog=RUNTIME.command_epilog(['codapact-jira user-search find-user-keys-by-query --arg-query ARG_QUERY']), formatter_class=RAW)
    c.add_argument('--arg-query', dest='p_arg_query', metavar='ARG_QUERY', required=True, help='The search query.')
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-result', dest='p_max_result', type=integer, metavar='MAX_RESULT', help='The maximum number of items to return per page. (default: 100)')
    c.set_defaults(handler=_run_user_search_find_user_keys_by_query, flags={'query': '--arg-query', 'start_at': '--start-at', 'max_result': '--max-result'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'find_user_keys_by_query'})
    c = g_user_search_commands.add_parser('find-users-with-browse-permission', parents=[common], help='Find users with browse permission', description="Returns a list of users who fulfill these criteria:\n\n* their user attributes match a search string. * they have permission to\nbrowse issues.\n\nUse this resource to find users who can browse:\n\n* an issue, by providing the `issueKey`. * any issue in a project, by\nproviding the `projectKey`.\n\nThis operation takes the users in the range defined by `startAt` and\n`maxResults`, up to the thousandth user, and then returns only the users from\nthat range that match the search string and have permission to browse issues.\nThis means the operation usually returns fewer users than specified in\n`maxResults`. To get all the users who match the search string and have\npermission to browse issues, use [Get all users](#api-rest-api-3-users-search-\nget) and filter the records in your code.\n\nPrivacy controls are applied to the response based on the users' preferences.\nThis could mean, for example, that the user's email address is hidden. See the\n[Profile visibility\noverview](https://developer.atlassian.com/cloud/jira/platform/profile-\nvisibility/) for more details.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse users and groups* [global\npermission](https://confluence.atlassian.com/x/x4dKLg). Anonymous calls and\ncalls by users without the required permission return empty search results.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira user-search find-users-with-browse-permission']), formatter_class=RAW)
