    c = g_users_commands.add_parser('get', parents=[common], help='Get user', description="Returns a user.\n\nPrivacy controls are applied to the response based on the user's preferences.\nThis could mean, for example, that the user's email address is hidden. See the\n[Profile visibility\noverview](https://developer.atlassian.com/cloud/jira/platform/profile-\nvisibility/) for more details.\n\n**[Permissions](#permissions) required:** *Browse users and groups* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira users get']), formatter_class=RAW)
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='The account ID of the user, which uniquely identifies the user across all Atlassian products. For example, *5b10ac8d82e05b22cc7d4ef5*. Required.')
    c.add_argument('--username', dest='p_username', metavar='USERNAME', help='This parameter is no longer available. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide) for details.')
    c.add_argument('--key', dest='p_key', metavar='KEY', help='This parameter is no longer available. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide) for details.')
