    c.add_argument('--display-name', dest='p_display_name', metavar='DISPLAY_NAME', help='This property is no longer available. If the user has an Atlassian account, their display name is not changed. If the user does not have an Atlassian account, they are sent an email asking them set up an account.')
    c.add_argument('--email-address', dest='p_email_address', metavar='EMAIL_ADDRESS', required=True, help='The email address for the user.')
    c.add_argument('--key', dest='p_key', metavar='KEY', help='This property is no longer available. See the [migration guide](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--name', dest='p_name', metavar='NAME', help='This property is no longer available. See the [migration guide](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--password', dest='p_password', metavar='PASSWORD', help='This property is no longer available. If the user has an Atlassian account, their password is not changed. If the user does not have an Atlassian account, they are sent an email asking them set up an account.')
    c.add_argument('--products', dest='p_products', action="append", metavar='PRODUCTS', required=True, help='Products the new user has access to. Valid products are: jira-core, jira-servicedesk, jira-product-discovery, jira-software. To create a user without product access, set this field to be an empty array.')
    c.add_argument('--self', dest='p_self', metavar='SELF', help='The URL of the user.')
    c.set_defaults(handler=_run_users_create, flags={'body.application_keys': '--application-keys', 'body.display_name': '--display-name', 'body.email_address': '--email-address', 'body.key': '--key', 'body.name': '--name', 'body.password': '--password', 'body.products': '--products', 'body.self': '--self'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_user'})
    c = g_users_commands.add_parser('remove', parents=[common], help='Delete user', description="Deletes a user. If the operation completes successfully then the user is\nremoved from Jira's user base. This operation does not delete the user's\nAtlassian account.\n\n**[Permissions](#permissions) required:** Site administration (that is,\nmembership of the *site-admin*\n[group](https://confluence.atlassian.com/x/24xjL)).", usage='%(prog)s --account-id ACCOUNT_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira users remove --account-id ACCOUNT_ID --dry-run', 'codapact-jira users remove --account-id ACCOUNT_ID --yes']), formatter_class=RAW)
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', required=True, help='The account ID of the user, which uniquely identifies the user across all Atlassian products. For example, *5b10ac8d82e05b22cc7d4ef5*.')
    c.add_argument('--username', dest='p_username', metavar='USERNAME', help='This parameter is no longer available. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    c.add_argument('--key', dest='p_key', metavar='KEY', help='This parameter is no longer available. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
