    c = g_users_commands.add_parser('bulk', parents=[common], help='Bulk get users', description='Returns a [paginated](#pagination) list of the users specified by one or more\naccount IDs.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s --account-id ACCOUNT_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira users bulk --account-id ACCOUNT_ID']), formatter_class=RAW)
