    c.set_defaults(handler=_run_users_bulk, flags={'start_at': '--start-at', 'max_results': '--max-results', 'username': '--username', 'key': '--key', 'account_id': '--account-id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'bulk_get_users'})
    c = g_users_commands.add_parser('bulk-get-migration', parents=[common], help='Get account IDs for users', description='Returns the account IDs for the users specified in the `key` or `username`\nparameters. Note that multiple `key` or `username` parameters can be\nspecified.\n\n**[Permissions](#permissions) required:** Permission to access Jira.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira users bulk-get-migration']), formatter_class=RAW)
