    c = g_users_commands.add_parser('list-default-columns', parents=[common], help='Get user default columns', description="Returns the default [issue table\ncolumns](https://confluence.atlassian.com/x/XYdKLg) for the user. If\n`accountId` is not passed in the request, the calling user's details are\nreturned.\n\n**[Permissions](#permissions) required:**\n\n* *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLgl), to get the column\ndetails for any user. * Permission to access Jira, to get the calling user's\ncolumn details.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira users list-default-columns']), formatter_class=RAW)
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='The account ID of the user, which uniquely identifies the user across all Atlassian products. For example, *5b10ac8d82e05b22cc7d4ef5*.')
    c.add_argument('--username', dest='p_username', metavar='USERNAME', help='This parameter is no longer available See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
