    c = g_users_commands.add_parser('reset-columns', parents=[common], help='Reset user default columns', description="Resets the default [ issue table\ncolumns](https://confluence.atlassian.com/x/XYdKLg) for the user to the system\ndefault. If `accountId` is not passed, the calling user's default columns are\nreset.\n\n**[Permissions](#permissions) required:**\n\n* *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg), to set the columns on\nany user. * Permission to access Jira, to set the calling user's columns.", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira users reset-columns --dry-run', 'codapact-jira users reset-columns --yes']), formatter_class=RAW)
    c.add_argument('--account-id', dest='p_account_id', metavar='ACCOUNT_ID', help='The account ID of the user, which uniquely identifies the user across all Atlassian products. For example, *5b10ac8d82e05b22cc7d4ef5*.')
    c.add_argument('--username', dest='p_username', metavar='USERNAME', help='This parameter is no longer available. See the [deprecation notice](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/) for details.')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_users_reset_columns, flags={'account_id': '--account-id', 'username': '--username'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'reset_user_columns'})
