    c = g_users_commands.add_parser('get-email-bulk', parents=[common], help='Get user email bulk', description="Returns a user's email address regardless of the user's profile visibility\nsettings. For Connect apps, this API is only available to apps approved by\nAtlassian, according to these\n[guidelines](https://community.developer.atlassian.com/t/guidelines-for-\nrequesting-access-to-email-address/27603). For Forge apps, this API only\nsupports access via asApp() requests.", usage='%(prog)s --account-id ACCOUNT_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira users get-email-bulk --account-id ACCOUNT_ID']), formatter_class=RAW)
    c.add_argument('--account-id', dest='p_account_id', action="append", metavar='ACCOUNT_ID', required=True, help='The account IDs of the users for which emails are required. An `accountId` is an identifier that uniquely identifies the user across all Atlassian products. For example, `5b10ac8d82e05b22cc7d4ef5`. Note, this should be treated as an opaque identifier (that is, do not assume any structure in the value).')
    c.set_defaults(handler=_run_users_get_email_bulk, flags={'account_id': '--account-id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_user_email_bulk'})
