    c = g_webhooks_commands.add_parser('register', parents=[common], help='Register dynamic webhooks', description='Registers webhooks.\n\n**NOTE:** for non-public OAuth apps, webhooks are delivered only if there is a\nmatch between the app owner and the user who registered a dynamic webhook.\n\n**[Permissions](#permissions) required:** Only\n[Connect](https://developer.atlassian.com/cloud/jira/platform/#connect-apps)\nand [OAuth\n2.0](https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps)\napps can use this operation.', usage='%(prog)s --url URL --webhooks @webhooks.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira webhooks register --url URL --webhooks @webhooks.json', 'codapact-jira webhooks register --url URL --webhooks @webhooks.json --dry-run']), formatter_class=RAW)
    c.add_argument('--url', dest='p_url', metavar='URL', required=True, help='The URL that specifies where to send the webhooks. This URL must use the same base URL as the Connect app. Only a single URL per app is allowed to be registered.')
