    c = g_webhooks_commands.add_parser('delete', parents=[common], help='Delete webhooks by ID', description='Removes webhooks by ID. Only webhooks registered by the calling app are\nremoved. If webhooks created by other apps are specified, they are ignored.\n\n**[Permissions](#permissions) required:** Only\n[Connect](https://developer.atlassian.com/cloud/jira/platform/#connect-apps)\nand [OAuth\n2.0](https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps)\napps can use this operation.', usage='%(prog)s --webhook-ids WEBHOOK_IDS [options]', epilog=RUNTIME.command_epilog(['codapact-jira webhooks delete --webhook-ids WEBHOOK_IDS --dry-run', 'codapact-jira webhooks delete --webhook-ids WEBHOOK_IDS --yes']), formatter_class=RAW)
