    c = g_webhooks_commands.add_parser('list', parents=[common], help='Get failed webhooks', description='Returns webhooks that have recently failed to be delivered to the requesting\napp after the maximum number of retries.\n\nAfter 72 hours the failure may no longer be returned by this operation.\n\nThe oldest failure is returned first.\n\nThis method uses a cursor-based pagination. To request the next page use the\nfailure time of the last webhook on the list as the `failedAfter` value or use\nthe URL provided in `next`.\n\n**[Permissions](#permissions) required:** Only [Connect\napps](https://developer.atlassian.com/cloud/jira/platform/index/#connect-apps)\ncan use this operation.', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira webhooks list']), formatter_class=RAW)
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of webhooks to return per page. If obeying the maxResults directive would result in records with the same failure time being split across pages, the directive is ignored and all records with the same failure time included on the page.')
