    c = g_webhooks_commands.add_parser('refresh', parents=[common], help='Extend webhook life', description='Extends the life of webhook. Webhooks registered through the REST API expire\nafter 30 days. Call this operation to keep them alive.\n\nUnrecognized webhook IDs (those that are not found or belong to other apps)\nare ignored.\n\n**[Permissions](#permissions) required:** Only\n[Connect](https://developer.atlassian.com/cloud/jira/platform/#connect-apps)\nand [OAuth\n2.0](https://developer.atlassian.com/cloud/jira/platform/oauth-2-3lo-apps)\napps can use this operation.', usage='%(prog)s --webhook-ids WEBHOOK_IDS [options]', epilog=RUNTIME.command_epilog(['codapact-jira webhooks refresh --webhook-ids WEBHOOK_IDS', 'codapact-jira webhooks refresh --webhook-ids WEBHOOK_IDS --dry-run']), formatter_class=RAW)
    c.add_argument('--webhook-ids', dest='p_webhook_ids', action="append", type=integer, metavar='WEBHOOK_IDS', required=True, help='A list of webhook IDs.')
