    c = g_workflow_scheme_project_associations_commands.add_parser('list', parents=[common], help='Get workflow scheme project associations', description='Returns a list of the workflow schemes associated with a list of projects.\nEach returned workflow scheme includes a list of the requested projects\nassociated with it. Any team-managed or non-existent projects in the request\nare ignored and no errors are returned.\n\nIf the project is associated with the `Default Workflow Scheme` no ID is\nreturned. This is because the way the `Default Workflow Scheme` is stored\nmeans it has no ID.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --project-id PROJECT_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-scheme-project-associations list --project-id PROJECT_ID']), formatter_class=RAW)
    c.add_argument('--project-id', dest='p_project_id', action="append", type=integer, metavar='PROJECT_ID', required=True, help='The ID of a project to return the workflow schemes for. To include multiple projects, provide an ampersand-Jim: oneseparated list. For example, `projectId=10000&projectId=10001`.')
    c.set_defaults(handler=_run_workflow_scheme_project_associations_list, flags={'project_id': '--project-id'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_workflow_scheme_project_associations'})
    c = g_workflow_scheme_project_associations_commands.add_parser('assign-scheme-to-project', parents=[common], help='Assign workflow scheme to project', description='Assigns a workflow scheme to a project. This operation is performed only when\nthere are no issues in the project.\n\nWorkflow schemes can only be assigned to classic projects.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s --project-id PROJECT_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-scheme-project-associations assign-scheme-to-project --project-id PROJECT_ID', 'codapact-jira workflow-scheme-project-associations assign-scheme-to-project --project-id PROJECT_ID --dry-run']), formatter_class=RAW)
    c.add_argument('--project-id', dest='p_project_id', metavar='PROJECT_ID', required=True, help='The ID of the project.')
    c.add_argument('--workflow-scheme-id', dest='p_workflow_scheme_id', metavar='WORKFLOW_SCHEME_ID', help='The ID of the workflow scheme. If the workflow scheme ID is `null`, the operation assigns the default workflow scheme.')
    c.set_defaults(handler=_run_workflow_scheme_project_associations_assign_scheme_to_project, flags={'body.project_id': '--project-id', 'body.workflow_scheme_id': '--workflow-scheme-id'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'assign_scheme_to_project'})
    g_workflow_schemes = commands.add_parser('workflow-schemes', help='create, delete, delete-default-workflow, … (19 commands)', description="Run 'codapact-jira workflow-schemes COMMAND --help' for a command's options and examples.")
    g_workflow_schemes_commands = g_workflow_schemes.add_subparsers(dest="g_workflow_schemes", metavar="COMMAND", required=True)
    c = g_workflow_schemes_commands.add_parser('list', parents=[common], help='Get all workflow schemes', description='Returns a [paginated](#pagination) list of all workflow schemes, not including\ndraft workflow schemes.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-schemes list']), formatter_class=RAW)
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 50)')
    c.set_defaults(handler=_run_workflow_schemes_list, flags={'start_at': '--start-at', 'max_results': '--max-results'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_all_workflow_schemes'})
    c = g_workflow_schemes_commands.add_parser('create', parents=[common], help='Create workflow scheme', description='Creates a workflow scheme.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-schemes create --default-workflow DEFAULT_WORKFLOW', 'codapact-jira workflow-schemes create --default-workflow DEFAULT_WORKFLOW --dry-run']), formatter_class=RAW)
    c.add_argument('--default-workflow', dest='p_default_workflow', metavar='DEFAULT_WORKFLOW', help='The name of the default workflow for the workflow scheme. The default workflow has *All Unassigned Issue Types* assigned to it in Jira. If `defaultWorkflow` is not specified when creating a workflow scheme, it is set to *Jira Workflow (jira)*.')
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', help='The description of the workflow scheme.')
    c.add_argument('--draft', dest='p_draft', action=argparse.BooleanOptionalAction, help='Whether the workflow scheme is a draft or not.')
    c.add_argument('--id', dest='p_id', type=integer, metavar='ID', help='The ID of the workflow scheme.')
    c.add_argument('--issue-type-mappings', dest='p_issue_type_mappings', type=json_value, metavar="JSON", help='The issue type to workflow mappings, where each mapping is an issue type ID and workflow name pair. Note that an issue type can only be mapped to one workflow in a workflow scheme.')
    c.add_argument('--issue-types', dest='p_issue_types', type=json_value, metavar="JSON", help='The issue types available in Jira.')
    c.add_argument('--last-modified', dest='p_last_modified', metavar='LAST_MODIFIED', help='The date-time that the draft workflow scheme was last modified. A modification is a change to the issue type-project mappings only. This property does not apply to non-draft workflows.')
    c.add_argument('--last-modified-user', dest='p_last_modified_user', type=json_value, metavar="JSON", help='The user that last modified the draft workflow scheme. A modification is a change to the issue type-project mappings only. This property does not apply to non-draft workflows. JSON object with account_id, account_type, active, app_type, application_roles, avatar_urls, display_name, email_address, expand, groups, guest, key, ... Schema: codapact-jira describe workflow-schemes create')
    c.add_argument('--name', dest='p_name', metavar='NAME', help='The name of the workflow scheme. The name must be unique. The maximum length is 255 characters. Required when creating a workflow scheme.')
    c.add_argument('--original-default-workflow', dest='p_original_default_workflow', metavar='ORIGINAL_DEFAULT_WORKFLOW', help='For draft workflow schemes, this property is the name of the default workflow for the original workflow scheme. The default workflow has *All Unassigned Issue Types* assigned to it in Jira.')
    c.add_argument('--original-issue-type-mappings', dest='p_original_issue_type_mappings', type=json_value, metavar="JSON", help='For draft workflow schemes, this property is the issue type to workflow mappings for the original workflow scheme, where each mapping is an issue type ID and workflow name pair. Note that an issue type can only be mapped to one workflow in a workflow scheme.')
    c.add_argument('--self', dest='p_self', metavar='SELF')
    c.add_argument('--update-draft-if-needed', dest='p_update_draft_if_needed', action=argparse.BooleanOptionalAction, help='Whether to create or update a draft workflow scheme when updating an active workflow scheme. An active workflow scheme is a workflow scheme that is used by at least one project. The following examples show how this property works:')
    c.set_defaults(handler=_run_workflow_schemes_create, flags={'body.default_workflow': '--default-workflow', 'body.description': '--description', 'body.draft': '--draft', 'body.id': '--id', 'body.issue_type_mappings': '--issue-type-mappings', 'body.issue_types': '--issue-types', 'body.last_modified': '--last-modified', 'body.last_modified_user': '--last-modified-user', 'body.name': '--name', 'body.original_default_workflow': '--original-default-workflow', 'body.original_issue_type_mappings': '--original-issue-type-mappings', 'body.self': '--self', 'body.update_draft_if_needed': '--update-draft-if-needed'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'create_workflow_scheme', 'requires_one_of': [['--default-workflow', '--description', '--draft', '--id', '--issue-type-mappings', '--issue-types', '--last-modified', '--last-modified-user', '--name', '--original-default-workflow', '--original-issue-type-mappings', '--self', '--update-draft-if-needed']]})
    c = g_workflow_schemes_commands.add_parser('switch-for-project', parents=[common], help='Switch workflow scheme for project', description="Switches a workflow scheme for a project.\n\nWorkflow schemes can only be assigned to classic projects.\n\n**Calculating required mappings:** If statuses from the current workflow\nscheme won't exist in the target workflow scheme, you must provide\n`mappingsByIssueTypeOverride` to specify how issues with those statuses should\nbe migrated. Use [the required workflow scheme mappings API](#api-rest-\napi-3-workflowscheme-update-mappings-post) to determine which statuses and\nissue types require mappings.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).", usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-schemes switch-for-project --mappings-by-issue-type-override @mappings-by-issue-type-override.json', 'codapact-jira workflow-schemes switch-for-project --mappings-by-issue-type-override @mappings-by-issue-type-override.json --dry-run']), formatter_class=RAW)
    c.add_argument('--mappings-by-issue-type-override', dest='p_mappings_by_issue_type_override', type=json_value, metavar="JSON", help="The mappings for migrating issues from old statuses to new statuses when switching from one workflow scheme to another. This field is required if any statuses in the current project's workflows would no longer exist in the target workflow scheme. Each mapping defines how to update issues from an old status to the corresponding new status in the issue’s new workflow. JSON array of objects with issue_type_id, status_mappings. Schema: codapact-jira describe workflow-schemes switch-for-project")
    c.add_argument('--project-id', dest='p_project_id', metavar='PROJECT_ID', help='The ID of the project to switch the workflow scheme for')
    c.add_argument('--target-scheme-id', dest='p_target_scheme_id', metavar='TARGET_SCHEME_ID', help='The ID of the target workflow scheme to switch to')
    c.set_defaults(handler=_run_workflow_schemes_switch_for_project, flags={'body.mappings_by_issue_type_override': '--mappings-by-issue-type-override', 'body.project_id': '--project-id', 'body.target_scheme_id': '--target-scheme-id'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'switch_workflow_scheme_for_project', 'requires_one_of': [['--mappings-by-issue-type-override', '--project-id', '--target-scheme-id']]})
    c = g_workflow_schemes_commands.add_parser('read', parents=[common], help='Bulk get workflow schemes', description='Returns a list of workflow schemes by providing workflow scheme IDs or project\nIDs.\n\n**[Permissions](#permissions) required:**\n\n* *Administer Jira* global permission to access all, including project-scoped,\nworkflow schemes * *Administer projects* project permissions to access\nproject-scoped workflow schemes', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-schemes read --project-ids PROJECT_IDS', 'codapact-jira workflow-schemes read --project-ids PROJECT_IDS --dry-run']), formatter_class=RAW)
    c.add_argument('--project-ids', dest='p_project_ids', action="append", metavar='PROJECT_IDS', help='The list of project IDs to query.')
    c.add_argument('--workflow-scheme-ids', dest='p_workflow_scheme_ids', action="append", metavar='WORKFLOW_SCHEME_IDS', help='The list of workflow scheme IDs to query.')
    c.set_defaults(handler=_run_workflow_schemes_read, flags={'body.project_ids': '--project-ids', 'body.workflow_scheme_ids': '--workflow-scheme-ids'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'read_workflow_schemes', 'requires_one_of': [['--project-ids', '--workflow-scheme-ids']]})
    c = g_workflow_schemes_commands.add_parser('update-schemes', parents=[common], help='Update workflow scheme', description="Updates company-managed and team-managed project workflow schemes. This API\ndoesn't have a concept of draft, so any changes made to a workflow scheme are\nimmediately available. When changing the available statuses for issue types,\nan [asynchronous task](#async) migrates the issues as defined in the provided\nmappings.\n\n**[Permissions](#permissions) required:**\n\n* *Administer Jira* project permission to update all, including global-scoped,\nworkflow schemes. * *Administer projects* project permission to update\nproject-scoped workflow schemes.", usage='%(prog)s --description DESCRIPTION --id ID --name NAME --arg-version @arg-version.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-schemes update-schemes --description DESCRIPTION --id ID --name NAME --arg-version @arg-version.json', 'codapact-jira workflow-schemes update-schemes --description DESCRIPTION --id ID --name NAME --arg-version @arg-version.json --dry-run']), formatter_class=RAW)
    c.add_argument('--default-workflow-id', dest='p_default_workflow_id', metavar='DEFAULT_WORKFLOW_ID', help="The ID of the workflow for issue types without having a mapping defined in this workflow scheme. Only used in global-scoped workflow schemes. If the `defaultWorkflowId` isn't specified, this is set to *Jira Workflow (jira)*.")
    c.add_argument('--description', dest='p_description', metavar='DESCRIPTION', required=True, help='The new description for this workflow scheme.')
    c.add_argument('--id', dest='p_id', metavar='ID', required=True, help='The ID of this workflow scheme.')
    c.add_argument('--name', dest='p_name', metavar='NAME', required=True, help='The new name for this workflow scheme.')
    c.add_argument('--status-mappings-by-issue-type-override', dest='p_status_mappings_by_issue_type_override', type=json_value, metavar="JSON", help="Overrides, for the selected issue types, any status mappings provided in `statusMappingsByWorkflows`. Status mappings are required when the new workflow for an issue type doesn't contain all statuses that the old workflow has. Status mappings can be provided by a combination of `statusMappingsByWorkflows` and `statusMappingsByIssueTypeOverride`. JSON array of objects with issue_type_id, status_mappings. Schema: codapact-jira describe workflow-schemes update-schemes")
    c.add_argument('--status-mappings-by-workflows', dest='p_status_mappings_by_workflows', type=json_value, metavar="JSON", help="The status mappings by workflows. Status mappings are required when the new workflow for an issue type doesn't contain all statuses that the old workflow has. Status mappings can be provided by a combination of `statusMappingsByWorkflows` and `statusMappingsByIssueTypeOverride`. JSON array of objects with new_workflow_id*, old_workflow_id*, status_mappings* (* required). Schema: codapact-jira describe workflow-schemes update-schemes")
    c.add_argument('--arg-version', dest='p_arg_version', type=json_value, metavar="JSON", required=True, help='JSON object with id, version_number. Schema: codapact-jira describe workflow-schemes update-schemes')
    c.add_argument('--workflows-for-issue-types', dest='p_workflows_for_issue_types', type=json_value, metavar="JSON", help='Mappings from workflows to issue types. JSON array of objects with issue_type_ids*, workflow_id* (* required). Schema: codapact-jira describe workflow-schemes update-schemes')
    c.set_defaults(handler=_run_workflow_schemes_update_schemes, flags={'body.default_workflow_id': '--default-workflow-id', 'body.description': '--description', 'body.id': '--id', 'body.name': '--name', 'body.status_mappings_by_issue_type_override': '--status-mappings-by-issue-type-override', 'body.status_mappings_by_workflows': '--status-mappings-by-workflows', 'body.version': '--arg-version', 'body.workflows_for_issue_types': '--workflows-for-issue-types'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_schemes'})
    c = g_workflow_schemes_commands.add_parser('list-required-mappings', parents=[common], help='Get required status mappings for workflow scheme update', description='Gets the required status mappings for the desired changes to a workflow\nscheme. The results are provided per issue type and workflow. When updating a\nworkflow scheme, status mappings can be provided per issue type, per workflow,\nor both.\n\n**[Permissions](#permissions) required:**\n\n* *Administer Jira* permission to update all, including global-scoped,\nworkflow schemes. * *Administer projects* project permission to update\nproject-scoped workflow schemes.', usage='%(prog)s --id ID --workflows-for-issue-types @workflows-for-issue-types.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-schemes list-required-mappings --id ID --workflows-for-issue-types @workflows-for-issue-types.json', 'codapact-jira workflow-schemes list-required-mappings --id ID --workflows-for-issue-types @workflows-for-issue-types.json --dry-run']), formatter_class=RAW)
    c.add_argument('--default-workflow-id', dest='p_default_workflow_id', metavar='DEFAULT_WORKFLOW_ID', help="The ID of the new default workflow for this workflow scheme. Only used in global-scoped workflow schemes. If it isn't specified, is set to *Jira Workflow (jira)*.")
    c.add_argument('--id', dest='p_id', metavar='ID', required=True, help='The ID of the workflow scheme.')
    c.add_argument('--workflows-for-issue-types', dest='p_workflows_for_issue_types', type=json_value, metavar="JSON", required=True, help='The new workflow to issue type mappings for this workflow scheme. JSON array of objects with issue_type_ids*, workflow_id* (* required). Schema: codapact-jira describe workflow-schemes list-required-mappings')
    c.set_defaults(handler=_run_workflow_schemes_list_required_mappings, flags={'body.default_workflow_id': '--default-workflow-id', 'body.id': '--id', 'body.workflows_for_issue_types': '--workflows-for-issue-types'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_required_workflow_scheme_mappings'})
    c = g_workflow_schemes_commands.add_parser('get', parents=[common], help='Get workflow scheme', description='Returns a workflow scheme.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-schemes get ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the workflow scheme. Find this ID by editing the desired workflow scheme in Jira. The ID is shown in the URL as `schemeId`. For example, *schemeId=10301*.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
    c.add_argument('--return-draft-if-exists', dest='p_return_draft_if_exists', action=argparse.BooleanOptionalAction, help="Returns the workflow scheme's draft rather than scheme itself, if set to true. If the workflow scheme does not have a draft, then the workflow scheme is returned. (default: False)")
    c.set_defaults(handler=_run_workflow_schemes_get, flags={'id': '--id', 'return_draft_if_exists': '--return-draft-if-exists'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_workflow_scheme'})
    c = g_workflow_schemes_commands.add_parser('update', parents=[common], help='Classic update workflow scheme', description='Updates a company-manged project workflow scheme, including the name, default\nworkflow, issue type to project mappings, and more. If the workflow scheme is\nactive (that is, being used by at least one project), then a draft workflow\nscheme is created or updated instead, provided that `updateDraftIfNeeded` is\nset to `true`.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID --body @body.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-schemes update ID --body @body.json', 'codapact-jira workflow-schemes update ID --body @body.json --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the workflow scheme. Find this ID by editing the desired workflow scheme in Jira. The ID is shown in the URL as `schemeId`. For example, *schemeId=10301*.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
    c.add_argument('--body', dest='p_body', type=json_value, metavar="JSON", required=True, help='JSON object with default_workflow, description, draft, id, issue_type_mappings, issue_types, last_modified, last_modified_user, name, original_default_workflow, original_issue_type_mappings, self, ... Schema: codapact-jira describe workflow-schemes update')
    c.set_defaults(handler=_run_workflow_schemes_update, flags={'id': '--id', 'body': '--body'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_workflow_scheme'})
    c = g_workflow_schemes_commands.add_parser('delete', parents=[common], help='Delete workflow scheme', description='Deletes a workflow scheme. Note that a workflow scheme cannot be deleted if it\nis active (that is, being used by at least one project).\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-schemes delete ID --dry-run', 'codapact-jira workflow-schemes delete ID --yes']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the workflow scheme. Find this ID by editing the desired workflow scheme in Jira. The ID is shown in the URL as `schemeId`. For example, *schemeId=10301*.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_workflow_schemes_delete, flags={'id': '--id'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_workflow_scheme'})
    c = g_workflow_schemes_commands.add_parser('get-default-workflow', parents=[common], help='Get default workflow', description='Returns the default workflow for a workflow scheme. The default workflow is\nthe workflow that is assigned any issue types that have not been mapped to any\nother workflow. The default workflow has *All Unassigned Issue Types* listed\nin its issue types for the workflow scheme in Jira.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-schemes get-default-workflow ID']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the workflow scheme.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
    c.add_argument('--return-draft-if-exists', dest='p_return_draft_if_exists', action=argparse.BooleanOptionalAction, help="Set to `true` to return the default workflow for the workflow scheme's draft rather than scheme itself. If the workflow scheme does not have a draft, then the default workflow for the workflow scheme is returned. (default: False)")
    c.set_defaults(handler=_run_workflow_schemes_get_default_workflow, flags={'id': '--id', 'return_draft_if_exists': '--return-draft-if-exists'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_default_workflow'})
    c = g_workflow_schemes_commands.add_parser('update-default-workflow', parents=[common], help='Update default workflow', description='Sets the default workflow for a workflow scheme.\n\nNote that active workflow schemes cannot be edited. If the workflow scheme is\nactive, set `updateDraftIfNeeded` to `true` in the request object and a draft\nworkflow scheme is created or updated with the new default workflow. The draft\nworkflow scheme can be published in Jira.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ID --workflow WORKFLOW [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-schemes update-default-workflow ID --workflow WORKFLOW', 'codapact-jira workflow-schemes update-default-workflow ID --workflow WORKFLOW --dry-run']), formatter_class=RAW)
    c.add_argument('p_id', metavar='ID', nargs='?', default=argparse.SUPPRESS, type=integer, help='The ID of the workflow scheme.')
    c.add_argument('--id', dest='p_id', default=argparse.SUPPRESS, type=integer, metavar='ID', help='same as ID')
    c.add_argument('--update-draft-if-needed', dest='p_update_draft_if_needed', action=argparse.BooleanOptionalAction, help='Whether a draft workflow scheme is created or updated when updating an active workflow scheme. The draft is updated with the new default workflow. Defaults to `false`.')
    c.add_argument('--workflow', dest='p_workflow', metavar='WORKFLOW', required=True, help='The name of the workflow to set as the default workflow.')
