    c.add_argument('--update-draft-if-needed', dest='p_update_draft_if_needed', action=argparse.BooleanOptionalAction, help='Whether a draft workflow scheme is created or updated when updating an active workflow scheme. The draft is updated with the new workflow-issue types mapping. Defaults to `false`.')
    c.add_argument('--workflow', dest='p_workflow', metavar='WORKFLOW', help='The name of the workflow. Optional if updating the workflow-issue types mapping.')
    c.set_defaults(handler=_run_workflow_schemes_update_workflow_mapping, flags={'id': '--id', 'workflow_name': '--workflow-name', 'body.default_mapping': '--default-mapping', 'body.issue_types': '--issue-types', 'body.update_draft_if_needed': '--update-draft-if-needed', 'body.workflow': '--workflow'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_workflow_mapping', 'requires_one_of': [['--default-mapping', '--issue-types', '--update-draft-if-needed', '--workflow']]})
