    g_workflow_transition_rules = commands.add_parser('workflow-transition-rules', help='delete-configurations, list-configurations, update-configurations', description="Run 'codapact-jira workflow-transition-rules COMMAND --help' for a command's options and examples.")
    g_workflow_transition_rules_commands = g_workflow_transition_rules.add_subparsers(dest="g_workflow_transition_rules", metavar="COMMAND", required=True)
    c = g_workflow_transition_rules_commands.add_parser('list-configurations', parents=[common], help='Get workflow transition rule configurations', description='Returns a [paginated](#pagination) list of workflows with transition rules.\nThe workflows can be filtered to return only those containing workflow\ntransition rules:\n\n* of one or more transition rule types, such as [workflow post functions](http\ns://developer.atlassian.com/cloud/jira/platform/modules/workflow-post-\nfunction/). * matching one or more transition rule keys.\n\nOnly workflows containing transition rules created by the calling\n[Connect](https://developer.atlassian.com/cloud/jira/platform/index/#connect-\napps) or\n[Forge](https://developer.atlassian.com/cloud/jira/platform/index/#forge-apps)\napp are returned.\n\nDue to server-side optimizations, workflows with an empty list of rules may be\nreturned; these workflows can be ignored.\n\n**[Permissions](#permissions) required:** Only\n[Connect](https://developer.atlassian.com/cloud/jira/platform/index/#connect-\napps) or\n[Forge](https://developer.atlassian.com/cloud/jira/platform/index/#forge-apps)\napps can use this operation.', usage='%(prog)s --types TYPES [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-transition-rules list-configurations --types TYPES']), formatter_class=RAW)
    c.add_argument('--start-at', dest='p_start_at', type=integer, metavar='START_AT', help='The index of the first item to return in a page of results (page offset). (default: 0)')
    c.add_argument('--max-results', dest='p_max_results', type=integer, metavar='MAX_RESULTS', help='The maximum number of items to return per page. (default: 10)')
    c.add_argument('--types', dest='p_types', action="append", choices=['postfunction', 'condition', 'validator'], required=True, help='The types of the transition rules to return.')
    c.add_argument('--keys', dest='p_keys', action="append", metavar='KEYS', help='The transition rule class keys, as defined in the Connect or the Forge app descriptor, of the transition rules to return.')
    c.add_argument('--workflow-names', dest='p_workflow_names', action="append", metavar='WORKFLOW_NAMES', help='The list of workflow names to filter by.')
    c.add_argument('--with-tags', dest='p_with_tags', action="append", metavar='WITH_TAGS', help='The list of `tags` to filter by.')
    c.add_argument('--draft', dest='p_draft', action=argparse.BooleanOptionalAction, help="**Deprecated:** Whether draft or published workflows are returned. If not provided, both workflow types are returned. The 'draft' parameter will be removed from this API on [November 2, 2026](https://developer.atlassian.com/cloud/jira/platform/changelog/#CHANGE-3147).")
    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information in the response. This parameter accepts `transition`, which, for each rule, returns information about the transition the rule is assigned to.')
    c.set_defaults(handler=_run_workflow_transition_rules_list_configurations, flags={'start_at': '--start-at', 'max_results': '--max-results', 'types': '--types', 'keys': '--keys', 'workflow_names': '--workflow-names', 'with_tags': '--with-tags', 'draft': '--draft', 'expand': '--expand'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'get_workflow_transition_rule_configurations'})
    c = g_workflow_transition_rules_commands.add_parser('update-configurations', parents=[common], help='Update workflow transition rule configurations', description='Updates configuration of workflow transition rules. The following rule types\nare supported:\n\n* [post functions](https://developer.atlassian.com/cloud/jira/platform/modules\n/workflow-post-function/) * [conditions](https://developer.atlassian.com/cloud\n/jira/platform/modules/workflow-condition/) * [validators](https://developer.a\ntlassian.com/cloud/jira/platform/modules/workflow-validator/)\n\nOnly rules created by the calling\n[Connect](https://developer.atlassian.com/cloud/jira/platform/index/#connect-\napps) or\n[Forge](https://developer.atlassian.com/cloud/jira/platform/index/#forge-apps)\napp can be updated.\n\nTo assist with app migration, this operation can be used to:\n\n* Disable a rule. * Add a `tag`. Use this to filter rules in the [Get workflow\ntransition rule configurations](https://developer.atlassian.com/cloud/jira/pla\ntform/rest/v3/api-group-workflow-transition-rules/#api-rest-api-3-workflow-\nrule-config-get).\n\nRules are enabled if the `disabled` parameter is not provided.\n\n**Note:** The `draft` parameter in the request body WorkflowId is deprecated\nand will be removed from this API on [November 2, 2026](https://developer.atla\nssian.com/cloud/jira/platform/changelog/#CHANGE-3147).\n\n**[Permissions](#permissions) required:** Only\n[Connect](https://developer.atlassian.com/cloud/jira/platform/index/#connect-\napps) or\n[Forge](https://developer.atlassian.com/cloud/jira/platform/index/#forge-apps)\napps can use this operation.', usage='%(prog)s --workflows @workflows.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-transition-rules update-configurations --workflows @workflows.json', 'codapact-jira workflow-transition-rules update-configurations --workflows @workflows.json --dry-run']), formatter_class=RAW)
    c.add_argument('--workflows', dest='p_workflows', type=json_value, metavar="JSON", required=True, help='The list of workflows with transition rules to update. JSON array of objects with workflow_id*, conditions, post_functions, validators (* required). Schema: codapact-jira describe workflow-transition-rules update-configurations')
    c.set_defaults(handler=_run_workflow_transition_rules_update_configurations, flags={'body.workflows': '--workflows'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'update_workflow_transition_rule_configurations'})
    c = g_workflow_transition_rules_commands.add_parser('delete-configurations', parents=[common], help='Delete workflow transition rule configurations', description='Deletes workflow transition rules from one or more workflows. These rule types\nare supported:\n\n* [post functions](https://developer.atlassian.com/cloud/jira/platform/modules\n/workflow-post-function/) * [conditions](https://developer.atlassian.com/cloud\n/jira/platform/modules/workflow-condition/) * [validators](https://developer.a\ntlassian.com/cloud/jira/platform/modules/workflow-validator/)\n\nOnly rules created by the calling Connect app can be deleted.\n\n**Note:** The `draft` parameter in the request body WorkflowId is deprecated\nand will be removed from this API on [November 2, 2026](https://developer.atla\nssian.com/cloud/jira/platform/changelog/#CHANGE-3147).\n\n**[Permissions](#permissions) required:** Only Connect apps can use this\noperation.', usage='%(prog)s --workflows @workflows.json [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflow-transition-rules delete-configurations --workflows @workflows.json --dry-run', 'codapact-jira workflow-transition-rules delete-configurations --workflows @workflows.json --yes']), formatter_class=RAW)
    c.add_argument('--workflows', dest='p_workflows', type=json_value, metavar="JSON", required=True, help='The list of workflows with transition rules to delete. JSON array of objects with workflow_id*, workflow_rule_ids* (* required). Schema: codapact-jira describe workflow-transition-rules delete-configurations')
    RUNTIME.add_confirm_option(c)
    c.set_defaults(handler=_run_workflow_transition_rules_delete_configurations, flags={'body.workflows': '--workflows'}, meta={'read_only': False, 'destructive': True, 'paginated': False, 'deprecated': False, 'operation': 'delete_workflow_transition_rule_configurations'})
    g_workflows = commands.add_parser('workflows', help='capabilities, copy, create, … (17 commands)', description="Run 'codapact-jira workflows COMMAND --help' for a command's options and examples.")
    g_workflows_commands = g_workflows.add_subparsers(dest="g_workflows", metavar="COMMAND", required=True)
    c = g_workflows_commands.add_parser('read-from-history', parents=[common], help='Read workflow version from history', description='Returns a workflow and related statuses for a specified workflow id and\nversion number.\n\n**Note:** Stored workflow data expires after 60 days. Additionally, no data\nfrom before the 30th of October 2025 is available.\n\n**[Permissions](#permissions) required:**\n\n* *Administer Jira* global permission to access all, including project-scoped,\nworkflows * At least one of the *Administer projects* and *View (read-only)\nworkflow* project permissions to access project-scoped workflows', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflows read-from-history --arg-version ARG_VERSION', 'codapact-jira workflows read-from-history --arg-version ARG_VERSION --dry-run']), formatter_class=RAW)
    c.add_argument('--arg-version', dest='p_arg_version', type=integer, metavar='ARG_VERSION')
    c.add_argument('--workflow-id', dest='p_workflow_id', metavar='WORKFLOW_ID')
    c.set_defaults(handler=_run_workflows_read_from_history, flags={'body.version': '--arg-version', 'body.workflow_id': '--workflow-id'}, meta={'read_only': False, 'destructive': False, 'paginated': False, 'deprecated': False, 'operation': 'read_workflow_from_history', 'requires_one_of': [['--arg-version', '--workflow-id']]})
    c = g_workflows_commands.add_parser('list-history', parents=[common], help='List workflow history entries', description='Returns a list of workflow history entries for a specified workflow id.\n\n**Note:** Stored workflow data expires after 60 days. Additionally, no data\nfrom before the 30th of October 2025 is available.\n\n**[Permissions](#permissions) required:**\n\n* *Administer Jira* global permission to access all, including project-scoped,\nworkflows * At least one of the *Administer projects* and *View (read-only)\nworkflow* project permissions to access project-scoped workflows', usage='%(prog)s [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflows list-history --workflow-id WORKFLOW_ID', 'codapact-jira workflows list-history --workflow-id WORKFLOW_ID --dry-run']), formatter_class=RAW)
