    c.add_argument('--expand', dest='p_expand', metavar='EXPAND', help='Use [expand](#expansion) to include additional information in the response. This parameter accepts a comma-separated list. Expand options include:')
    c.add_argument('--query-string', dest='p_query_string', metavar='QUERY_STRING', help='String used to perform a case-insensitive partial match with workflow name.')
    c.add_argument('--order-by', dest='p_order_by', choices=['name', '-name', '+name', 'created', '-created', '+created', 'updated', '+updated', '-updated'], help='[Order](#ordering) the results by a field:')
    c.add_argument('--is-active', dest='p_is_active', action=argparse.BooleanOptionalAction, help='Filters active and inactive workflows.')
    c.set_defaults(handler=_run_workflows_get_paginated, flags={'start_at': '--start-at', 'max_results': '--max-results', 'workflow_name': '--workflow-name', 'expand': '--expand', 'query_string': '--query-string', 'order_by': '--order-by', 'is_active': '--is-active'}, meta={'read_only': True, 'destructive': False, 'paginated': False, 'deprecated': True, 'operation': 'get_workflows_paginated'})
    c = g_workflows_commands.add_parser('delete', parents=[common], help='Delete inactive workflow', description='Deletes a workflow.\n\nThe workflow cannot be deleted if it is:\n\n* an active workflow. * a system workflow. * associated with any workflow\nscheme. * associated with any draft workflow scheme.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global\npermission](https://confluence.atlassian.com/x/x4dKLg).', usage='%(prog)s ENTITY_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflows delete ENTITY_ID --dry-run', 'codapact-jira workflows delete ENTITY_ID --yes']), formatter_class=RAW)
