    c = g_workflows_commands.add_parser('list-project-issue-type-usages', parents=[common], help='Get issue types in a project that are using a given workflow', description='Returns a page of issue types using a given workflow within a project.', usage='%(prog)s WORKFLOW_ID PROJECT_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflows list-project-issue-type-usages WORKFLOW_ID PROJECT_ID']), formatter_class=RAW)
