    c = g_workflows_commands.add_parser('get-scheme-usages-for-workflow', parents=[common], help='Get workflow schemes which are using a given workflow', description='Returns a page of workflow schemes using a given workflow.', usage='%(prog)s WORKFLOW_ID [options]', epilog=RUNTIME.command_epilog(['codapact-jira workflows get-scheme-usages-for-workflow WORKFLOW_ID']), formatter_class=RAW)
    c.add_argument('p_workflow_id', metavar='WORKFLOW_ID', nargs='?', default=argparse.SUPPRESS, help='The workflow ID')
    c.add_argument('--workflow-id', dest='p_workflow_id', default=argparse.SUPPRESS, metavar='WORKFLOW_ID', help='same as WORKFLOW_ID')
